      box: { x: round(card.x + box.w * 0.025), y: round(card.y + box.h * 0.055), w: round(card.w), h: round(card.h) },
      style: { fill: "#DCEFEF", stroke: "none", strokeWidthPt: 0, radiusRatio: 0.05 },
