function filterTextBoxesClaimedByCoverEngineCore(textBoxes = [], active = false) {
  if (!active) return textBoxes || [];
  const detector = "cover-engine-core-native-label";
  const nativeLabels = (textBoxes || []).filter((item) => item?.source?.detector === detector && item?.box);
  if (nativeLabels.length === 0) return textBoxes || [];
  return (textBoxes || []).filter((item) => {
    if (item?.source?.detector === detector || !item?.box) return true;
    const key = normalizeTextKey(item.text);
    if (!key) return true;
    return !nativeLabels.some((native) => {
      if (normalizeTextKey(native.text) !== key) return false;
      const smallerArea = Math.min(boxArea(item.box), boxArea(native.box));
      return smallerArea > 0 && intersectionArea(item.box, native.box) / smallerArea >= 0.72;
    });
  });
}


function detectCoverAxis(sourceImage, slideSize, regionPt) {
  if (!sourceImage?.rgba) return null;
  const region = ptToPxBox(regionPt, sourceImage, slideSize, 0);
  const components = detectColorComponents(sourceImage, {
    region,
    stride: 2,
    minAreaPx: 1200,
    predicate: (r, g, b, a) => a > 0 && g >= 125 && g - r >= 45 && g - b >= 18
  });
  const component = components.slice().sort((a, b) => b.areaPx - a.areaPx)[0];
  return component ? pxToPtBox(component, sourceImage, slideSize, 0) : null;
}

function detectCoverAvatarBox(sourceImage, slideSize) {
  if (!sourceImage?.rgba) return null;
  const components = detectColorComponents(sourceImage, {
    stride: 2,
    minAreaPx: 900,
    predicate: (r, g, b, a) => a > 0 && r >= 220 && g >= 45 && g <= 145 && b <= 75
  });
  const component = components
    .filter((item) => item.x >= sourceImage.width * 0.72 && item.y <= sourceImage.height * 0.25)
    .sort((a, b) => b.areaPx - a.areaPx)[0];
  return component ? pxToPtBox(component, sourceImage, slideSize, 1) : null;
}

function normalizeCoverEngineCoreChromeTextBoxes(textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  const avatar = detectCoverAvatarBox(sourceImage, slideSize);
  for (const textBox of textBoxes || []) {
    const text = String(textBox?.text || "").trim();
    if (text === "PM Portal Skills 引擎") {
      textBox.font = { ...(textBox.font || {}), family: "DengXian", sizePt: 39, color: "#06345E", weight: "regular", align: "left", opacity: 1 };
    } else if (text === "AI原生产品交付基座") {
      textBox.font = { ...(textBox.font || {}), family: "DengXian", sizePt: 27, color: "#0B355B", weight: "regular", align: "left", opacity: 1 };
    } else if (text === "YH" && avatar) {
      textBox.box = roundedBox({ x: avatar.x, y: avatar.y + avatar.h * 0.22, w: avatar.w, h: avatar.h * 0.56 });
      textBox.font = { ...(textBox.font || {}), family: "Microsoft YaHei", sizePt: 22, color: "#FFFFFF", weight: "regular", align: "center", valign: "middle", opacity: 1 };
      textBox.source = { ...(textBox.source || {}), evidenceBox: textBox.box, detector: "cover-engine-core-native-avatar-label", layerSourceId: "cover-engine-core-page-chrome" };
      Object.assign(textBox.source, coverEngineComponent("avatar", "label"));
    }
  }
}

function coverEngineComponent(group, part) {
  return coverEngineComponentFromRegistry(group, part);
}


function detectCoverCardBox(sourceImage, slideSize, evidenceBox, graphicBox) {
  if (!sourceImage?.rgba || !evidenceBox || !graphicBox) return null;
  const sx = sourceImage.width / slideSize.widthPt;
  const sy = sourceImage.height / slideSize.heightPt;
  const centerX = Math.round((evidenceBox.x + evidenceBox.w / 2) * sx);
  const centerY = Math.round((evidenceBox.y + evidenceBox.h / 2) * sy);
  const graphic = ptToPxBox(expandPtBox(graphicBox, slideSize, 12, 12), sourceImage, slideSize, 0);
  const radiusX = Math.max(90, Math.round(graphic.w * 0.27));
  const radiusY = Math.max(120, Math.round(graphic.h * 0.26));
  const region = {
    x: clamp(centerX - radiusX, graphic.x, graphic.x + graphic.w - 1),
    y: clamp(centerY - radiusY, graphic.y, graphic.y + graphic.h - 1),
    w: 1,
    h: 1
  };
  const right = clamp(centerX + radiusX, region.x + 1, graphic.x + graphic.w);
  const bottom = clamp(centerY + radiusY, region.y + 1, graphic.y + graphic.h);
  region.w = right - region.x;
  region.h = bottom - region.y;
  const leftColumnCounts = [];
  const rightColumnCounts = [];
  for (let x = region.x; x < right; x += 1) {
    let leftCount = 0;
    let rightCount = 0;
    for (let y = region.y; y < bottom; y += 1) {
      if (!isCoverCardBluePixel(pixel(sourceImage, x, y))) continue;
      if (isCoverCardInteriorPixel(pixel(sourceImage, clamp(x + 8, 0, sourceImage.width - 1), y))) leftCount += 1;
      if (isCoverCardInteriorPixel(pixel(sourceImage, clamp(x - 8, 0, sourceImage.width - 1), y))) rightCount += 1;
    }
    leftColumnCounts.push(leftCount);
    rightColumnCounts.push(rightCount);
  }
  const verticalThreshold = Math.max(24, Math.floor(region.h * 0.16));
  const leftBand = projectionBands(leftColumnCounts, verticalThreshold, region.x)
    .filter((band) => band.center < centerX)
    .sort((a, b) => b.center - a.center)[0];
  const rightBand = projectionBands(rightColumnCounts, verticalThreshold, region.x)
    .filter((band) => band.center > centerX)
    .sort((a, b) => a.center - b.center)[0];
  if (!leftBand || !rightBand || rightBand.start - leftBand.end < 70) return null;
  const left = leftBand.start;
  const edgeRight = rightBand.end;
  const topRowCounts = [];
  const bottomRowCounts = [];
  for (let y = region.y; y < bottom; y += 1) {
    let topCount = 0;
    let bottomCount = 0;
    for (let x = left; x <= edgeRight; x += 1) {
      if (!isCoverCardBluePixel(pixel(sourceImage, x, y))) continue;
      if (isCoverCardInteriorPixel(pixel(sourceImage, x, clamp(y + 8, 0, sourceImage.height - 1)))) topCount += 1;
      if (isCoverCardInteriorPixel(pixel(sourceImage, x, clamp(y - 8, 0, sourceImage.height - 1)))) bottomCount += 1;
    }
    topRowCounts.push(topCount);
    bottomRowCounts.push(bottomCount);
  }
  const horizontalThreshold = Math.max(24, Math.floor((edgeRight - left + 1) * 0.24));
  const topBand = projectionBands(topRowCounts, horizontalThreshold, region.y)
    .filter((band) => band.center < centerY)
    .sort((a, b) => b.center - a.center)[0];
  const bottomBand = projectionBands(bottomRowCounts, horizontalThreshold, region.y)
    .filter((band) => band.center > centerY)
    .sort((a, b) => a.center - b.center)[0];
  if (!topBand || !bottomBand || bottomBand.start - topBand.end < 80) return null;
  return pxToPtBox({
    x: left,
    y: topBand.start,
    w: edgeRight - left + 1,
    h: bottomBand.end - topBand.start + 1
  }, sourceImage, slideSize, 0);
}

function projectionBands(counts, threshold, offset = 0) {
  const bands = [];
  let start = -1;
  let maxCount = 0;
  for (let index = 0; index <= counts.length; index += 1) {
    const count = index < counts.length ? counts[index] : 0;
    if (count >= threshold) {
      if (start < 0) start = index;
      maxCount = Math.max(maxCount, count);
      continue;
    }
    if (start < 0) continue;
    const end = index - 1;
    bands.push({
      start: start + offset,
      end: end + offset,
      center: (start + end) / 2 + offset,
      maxCount
    });
    start = -1;
    maxCount = 0;
  }
  return bands;
}

function isCoverCardBluePixel(color) {
  return color.a >= 128
    && color.r <= 105
    && color.g >= 55
    && color.g <= 175
    && color.b >= 135
    && color.b - color.r >= 65
    && color.b - color.g >= 25;
}

function isCoverCardInteriorPixel(color) {
  return color.a >= 128
    && color.r >= 232
    && color.g >= 232
    && color.b >= 232
    && Math.max(color.r, color.g, color.b) - Math.min(color.r, color.g, color.b) <= 12;
}

function createSkillChainOverviewShapes(images = [], textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  const shapes = [];
  for (const image of images || []) {
    const evidenceTextBoxes = skillChainOverviewEvidenceTextBoxes(image, textBoxes, slideSize);
    if (!shouldObjectifySkillChainOverview(image, evidenceTextBoxes)) continue;
    const overview = inferSkillChainOverview(image, evidenceTextBoxes, slideSize);
    if (!overview) continue;
    const nativeTextBoxes = annotateSkillChainOverviewComponentTextBoxes(overview.textBoxes, image);
    normalizeSkillChainOverviewChromeTextBoxes(textBoxes);
    image.source = {
      ...(image.source || {}),
      layer: {
        ...(image.source?.layer || {}),
        layerType: "diagram-zone",
        nativeConfidence: Math.max(0.62, Number(image.source?.layer?.nativeConfidence || 0)),
        editBenefit: Math.max(0.24, Number(image.source?.layer?.editBenefit || 0)),
        recommendedAction: "split-native-with-residual-crop"
      },
      skillChainOverviewObjectified: true,
      objectifiedSkillChainCards: overview.cards.length,
      objectifiedSkillChainConnectors: overview.connectors.length,
      objectifiedSkillChainDecorations: overview.decorations.length,
      objectifiedSkillChainDocumentPreview: overview.documentPreviewObjectified === true,
      objectifiedSkillChainMaterialCloud: overview.materialCloudObjectified === true,
      skillChainOverviewNativeTextBoxes: nativeTextBoxes,
      skillChainResidualBoxes: overview.residualCrops,
      dropErasedResidualAfterNativeRebuild: overview.residualCrops.length === 0 ? true : image.source?.dropErasedResidualAfterNativeRebuild,
      nonEditableReason: overview.residualCrops.length === 0
        ? `${image.source?.nonEditableReason || image.source?.reason || "diagram underlay"}; rebuilt the complete skill chain, including input materials and output document, as native components`
        : `${image.source?.nonEditableReason || image.source?.reason || "diagram underlay"}; rebuilt skill chain stage cards and route lines natively while preserving input materials and output document as local fidelity crops`
    };
    for (let index = 0; index < overview.decorations.length; index += 1) {
      const decoration = overview.decorations[index];
      const component = skillChainOverviewDecorationComponent(image, decoration);
      shapes.push({
        id: `${image.id || "skill-chain-overview"}-native-decoration-${index}`,
        type: decoration.type,
        box: decoration.box,
        style: decoration.style,
        source: {
          editable: true,
          nativeRebuild: true,
          detector: decoration.detector,
          layerSourceId: image.id || null,
          role: decoration.role || "skill-chain-decoration",
          decorationIndex: index,
          ...component
        }
      });
    }
    for (let index = 0; index < overview.cards.length; index += 1) {
      const card = overview.cards[index];
      const component = skillChainOverviewComponent(image, `stage-${index}`, "skill-chain-stage");
      const baseSource = {
        editable: true,
        nativeRebuild: true,
        layerSourceId: image.id || null,
        label: card.label,
        role: "skill-chain-stage",
        ...component,
        nativeComponentRole: "body"
      };
      shapes.push({
        id: `${image.id || "skill-chain-overview"}-native-card-body-${index}`,
        type: "hexagon",
        box: card.box,
        style: {
          fill: card.fill,
          gradient: card.gradient,
          stroke: card.stroke,
          strokeWidthPt: 1.2,
          shadow: {
            color: "#000000",
            alpha: 0.10,
            blurPt: 7,
            distancePt: 2,
            angle: 45
          }
        },
        source: {
          ...baseSource,
          detector: "skill-chain-overview-native-card-body",
          cardIndex: index
        }
      });
    }
    for (let index = 0; index < overview.connectors.length; index += 1) {
      const connector = overview.connectors[index];
      const component = skillChainOverviewComponent(image, "stage-routing", "skill-chain-routing");
      shapes.push({
        id: `${image.id || "skill-chain-overview"}-native-connector-${index}`,
        type: connector.type || "line",
        box: connector.box,
        style: connector.type === "rightArrow"
          ? { fill: connector.stroke, stroke: connector.stroke, strokeWidthPt: 0.8 }
          : { stroke: connector.stroke, strokeWidthPt: connector.strokeWidthPt, connectorType: "straight", endArrow: connector.endArrow },
        source: {
          editable: true,
          nativeRebuild: true,
          detector: "skill-chain-overview-native-connector",
          layerSourceId: image.id || null,
          connectorIndex: index,
          ...component,
          nativeComponentRole: `connector-${index}`
        }
      });
    }
  }
  return shapes;
}

function skillChainOverviewComponent(image = {}, role = "component", archetype = "skill-chain-overview") {
  const base = safeComponentToken(image.id || "skill-chain-overview");
  const safeRole = safeComponentToken(role);
  const groupId = `${base}-skill-chain-${safeRole}`;
  return {
    nativeComponentInstance: true,
    nativeComponentGroupId: groupId,
    nativeComponentArchetype: archetype,
    componentOwnerId: groupId,
    componentOwnerKind: archetype
  };
}

function skillChainOverviewDecorationComponent(image = {}, decoration = {}) {
  const detector = String(decoration.detector || "");
  const role = String(decoration.role || "");
  if (/native-rail-(?:bg|line)$/.test(detector)) {
    return { ...skillChainOverviewComponent(image, "rail", "skill-chain-rail"), nativeComponentRole: role || "rail" };
  }
  if (detector === "skill-chain-overview-native-side-route") {
    const side = role === "output-route" ? "output-routing" : "input-routing";
    return { ...skillChainOverviewComponent(image, side, "skill-chain-routing"), nativeComponentRole: role || side };
  }
  if (detector === "skill-chain-overview-native-material-cloud") {
    return { ...skillChainOverviewComponent(image, "input-materials", "material-cloud"), nativeComponentRole: role || "fragment" };
  }
  if (detector === "skill-chain-overview-native-document-preview") {
    return { ...skillChainOverviewComponent(image, "output-document", "document-preview"), nativeComponentRole: role || "document-part" };
  }
  return skillChainOverviewComponent(image, `decoration-${safeComponentToken(role || detector)}`, "skill-chain-decoration");
}

function annotateSkillChainOverviewComponentTextBoxes(textBoxes = [], image = {}) {
  return (textBoxes || []).map((textBox) => {
    const role = String(textBox?.source?.role || "");
    const stageIndex = Number(textBox?.source?.stageIndex);
    const component = role === "stage-label" && Number.isInteger(stageIndex)
      ? skillChainOverviewComponent(image, `stage-${stageIndex}`, "skill-chain-stage")
      : skillChainOverviewComponent(image, "rail", "skill-chain-rail");
    return {
      ...textBox,
      style: { ...(textBox.style || {}), nativeComponentGroupId: component.nativeComponentGroupId },
      source: {
        ...(textBox.source || {}),
        layerSourceId: image.id || null,
        ...component,
        nativeComponentRole: role === "stage-label" ? "label" : "title"
      }
    };
  });
}

function createPageLevelSkillChainOverviewObjects(page = {}, textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage) return { shapes: [], textBoxes: [] };
  const candidate = inferPageLevelSkillChainOverviewCandidate(page, textBoxes, slideSize);
  if (!candidate) return { shapes: [], textBoxes: [] };
  const syntheticImage = {
    id: `page-${page.pageIndex ?? 0}-skill-chain-overview`,
    box: candidate.box,
    source: {
      detector: "sparse-diagram-graphic-underlay-crop",
      // The end illustrations are source-faithful crops; only the rail and stage flow
      // are reliable enough for native reconstruction.
      skillChainOverviewPreserveVisualAtomsAsNative: false,
      layer: {
        layerType: "diagram-zone",
        recommendedAction: "split-native-with-residual-crop",
        diagramUnderstanding: {
          archetype: "flow-card-chain",
          confidence: 0.92
        }
      }
    }
  };
  const shapes = createSkillChainOverviewShapes([syntheticImage], textBoxes, sourceImage, slideSize);
  if (shapes.length === 0 || syntheticImage.source?.skillChainOverviewObjectified !== true) {
    return { shapes: [], textBoxes: [] };
  }
  if (syntheticImage.source.skillChainOverviewPreserveVisualAtomsAsNative === true) {
    for (const item of candidate.residuals) {
      item.source = {
        ...(item.source || {}),
        pageLevelSkillChainResidualDrop: true,
        nonEditableReason: `${item.source?.nonEditableReason || item.source?.reason || "split skill-chain residual"}; page-level AI Skills workflow rebuilt natively`
      };
    }
  }
  const residualSourceIds = candidate.residuals.map((item) => item.id).filter(Boolean);
  return {
    shapes: shapes.map((shape) => ({
      ...shape,
      source: {
        ...(shape.source || {}),
        pageLevelSkillChainObjectified: true,
        residualSourceIds
      }
    })),
    textBoxes: (syntheticImage.source.skillChainOverviewNativeTextBoxes || []).map((textBox, index) => ({
      ...textBox,
      id: textBox.id || `${syntheticImage.id}-native-label-${index}`,
      source: {
        ...(textBox.source || {}),
        pageLevelSkillChainObjectified: true,
        residualSourceIds
      }
    }))
  };
}

function inferPageLevelSkillChainOverviewCandidate(page = {}, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const byText = new Map((textBoxes || [])
    .filter((item) => item?.box)
    .map((item) => [String(item.text || "").trim(), item.box]));
  const required = ["Skills Engine", "需求理解", "原型/高仿", "PRD生成", "智能评审"];
  if (required.some((label) => !byText.has(label))) return null;
  const residuals = (page.images || []).filter((item) => {
    const detector = String(item?.source?.detector || "");
    if (!/^(?:foreground-graphic-crop|split-wide-residual-crop|sparse-diagram-graphic-underlay-crop)$/.test(detector)) return false;
    const layer = item.source?.layer || {};
    return layer.layerType === "diagram-zone" || /diagram|flow|chain/.test(String(item.source?.expressionSubtype || item.source?.nonEditableReason || ""));
  });
  if (residuals.length < 2) return null;
  const labelBox = unionPtBoxes(required.map((label) => byText.get(label)));
  const residualBox = unionPtBoxes(residuals.map((item) => item.box).filter(Boolean));
  if (!labelBox || !residualBox) return null;
  const box = expandPtBox({
    x: Math.min(residualBox.x, labelBox.x - 230),
    y: Math.min(residualBox.y, byText.get("Skills Engine").y - 32),
    w: Math.max(residualBox.x + residualBox.w, labelBox.x + labelBox.w + 210) - Math.min(residualBox.x, labelBox.x - 230),
    h: Math.max(residualBox.y + residualBox.h, labelBox.y + labelBox.h + 118) - Math.min(residualBox.y, byText.get("Skills Engine").y - 32)
  }, slideSize, 0, 0);
  if (box.w < 760 || box.h < 180) return null;
  return { box, residuals };
}

function shouldObjectifySkillChainOverview(image, textBoxes = []) {
  const box = image?.box || {};
  if (image?.source?.detector !== "sparse-diagram-graphic-underlay-crop") return false;
  if (!box.w || !box.h || box.w < 760 || box.h < 180) return false;
  const labels = new Set((textBoxes || [])
    .filter((item) => item?.box && boxCenterInside(item.box, expandPtBox(box, DEFAULT_SLIDE, 10, 10)))
    .map((item) => String(item.text || "").trim()));
  return labels.has("Skills Engine")
    && labels.has("需求理解")
    && labels.has("原型/高仿")
    && labels.has("PRD生成")
    && labels.has("智能评审");
}

function skillChainOverviewEvidenceTextBoxes(image = {}, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  const expanded = box?.w && box?.h ? expandPtBox(box, slideSize, 10, 10) : null;
  const items = [...(textBoxes || [])];
  const nodes = [
    image.source?.diagramUnderstanding?.nodes,
    image.source?.layer?.diagramUnderstanding?.nodes
  ];
  for (const nodeSet of nodes) {
    if (!Array.isArray(nodeSet)) continue;
    for (const node of nodeSet) {
      const text = String(node?.text || "").trim();
      if (!text || !node?.box) continue;
      if (expanded && !boxCenterInside(node.box, expanded)) continue;
      if (items.some((item) => String(item?.text || "").trim() === text && skillChainSameBox(item.box, node.box, 0.5))) continue;
      items.push({
        id: node.sourceTextBoxId || `${image.id || "skill-chain-overview"}-semantic-node-${items.length}`,
        text,
        box: node.box,
        source: {
          editable: true,
          nativeRebuild: true,
          detector: "skill-chain-overview-semantic-node",
          semanticTextSource: true,
          semanticNodeId: node.id || ""
        }
      });
    }
  }
  return items;
}

function skillChainSameBox(a = {}, b = {}, tolerance = 0.5) {
  return ["x", "y", "w", "h"].every((key) =>
    Math.abs(Number(a?.[key] || 0) - Number(b?.[key] || 0)) <= tolerance
  );
}

function inferSkillChainOverview(image, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const box = image.box;
  // The material cloud and document preview are illustrations, not semantic flow
  // primitives. Preserve them unless a verified component implementation opts in.
  const preserveVisualAtomsAsNative = image?.source?.skillChainOverviewPreserveVisualAtomsAsNative === true;
  const byText = new Map((textBoxes || [])
    .filter((item) => item?.box && boxCenterInside(item.box, expandPtBox(box, slideSize, 10, 10)))
    .map((item) => [String(item.text || "").trim(), item.box]));
  const stages = ["需求理解", "原型/高仿", "PRD生成", "智能评审"];
  const stageBoxes = stages.map((label) => {
    const textBox = byText.get(label);
    if (!textBox) return null;
    return {
      label,
      box: expandPtBox({
        x: textBox.x - 16,
        y: textBox.y - 49,
        w: Math.max(100, textBox.w + 32),
        h: 112
      }, slideSize, 0, 0)
    };
  });
  if (stageBoxes.some((item) => !item)) return null;
  const engine = byText.get("Skills Engine");
  if (!engine) return null;
  const first = stageBoxes[0].box;
  const last = stageBoxes[stageBoxes.length - 1].box;
  const midY = first.y + first.h / 2;
  const connectors = [];
  const leftCloud = expandPtBox({
    x: box.x,
    y: Math.max(box.y, first.y - 52),
    w: Math.max(120, first.x - box.x - 64),
    h: Math.min(box.h, first.y + first.h + 58 - Math.max(box.y, first.y - 52))
  }, slideSize, 0, 0);
  const engineCore = expandPtBox({
    x: engine.x - 42,
    y: engine.y + 26,
    w: Math.max(130, engine.w + 62),
    h: Math.max(92, first.y + first.h - engine.y - 14)
  }, slideSize, 0, 0);
  const documentPreview = expandPtBox({
    x: last.x + last.w + 70,
    y: first.y - 20,
    w: Math.max(104, box.x + box.w - (last.x + last.w) - 70),
    h: Math.min(164, box.y + box.h - (first.y - 20) - 8)
  }, slideSize, 0, 0);
  for (let index = 0; index < stageBoxes.length - 1; index += 1) {
    const current = stageBoxes[index].box;
    const next = stageBoxes[index + 1].box;
    connectors.push({
      type: "rightArrow",
      box: {
        x: round(current.x + current.w - 2),
        y: round(midY - 11),
        w: round(Math.max(18, next.x - current.x - current.w + 5)),
        h: 22
      },
      stroke: index === 2 ? "#F27A14" : "#28A263",
      strokeWidthPt: 0.8
    });
  }
  const fills = ["#1D75BB", "#28A263", "#34AE5A", "#F07916"];
  const strokes = ["#0B4F91", "#16804A", "#1E8C4A", "#C85C08"];
  const gradientFaces = [
    ["#2C86CC", "#1764AA"],
    ["#39B56A", "#229655"],
    ["#43BE6A", "#259B4C"],
    ["#FF9224", "#ED6D09"]
  ];
  return {
    residualCrops: preserveVisualAtomsAsNative ? [] : [
      { name: "input-materials", box: leftCloud },
      { name: "output-document", box: documentPreview }
    ],
    decorations: [
      ...skillChainOverviewDecorations({ box, leftCloud, engineCore, documentPreview, first, last, engine, midY }, slideSize),
      ...(preserveVisualAtomsAsNative ? skillChainOverviewMaterialCloudShapes(leftCloud, slideSize) : []),
      ...(preserveVisualAtomsAsNative ? skillChainOverviewDocumentPreviewShapes(documentPreview, slideSize) : [])
    ],
    documentPreviewObjectified: preserveVisualAtomsAsNative,
    materialCloudObjectified: preserveVisualAtomsAsNative,
    textBoxes: skillChainOverviewTextBoxes(engine, stageBoxes),
    cards: stageBoxes.map((item, index) => ({
      ...item,
      fill: fills[index],
      stroke: strokes[index],
      gradient: {
        type: "linear",
        angleDeg: 0,
        stops: [
          { position: 0, color: gradientFaces[index][0] },
          { position: 0.49, color: gradientFaces[index][0] },
          { position: 0.51, color: gradientFaces[index][1] },
          { position: 1, color: gradientFaces[index][1] }
        ]
      }
    })),
    connectors: connectors.filter((connector) => Math.abs(connector.box.w) + Math.abs(connector.box.h) > 3)
  };
}

function skillChainOverviewTextBoxes(engineBox, stageBoxes = []) {
  const labels = [{
    text: "Skills Engine",
    box: {
      x: round(engineBox.x - 24),
      y: round(engineBox.y),
      w: round(engineBox.w + 48),
      h: round(engineBox.h)
    },
    font: {
      family: "Microsoft YaHei",
      sizePt: 18,
      color: "#111111",
      opacity: 1,
      weight: "bold",
      align: "center",
      valign: "middle"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "skill-chain-overview-native-label",
      role: "engine-title"
    }
  }];
  for (let stageIndex = 0; stageIndex < stageBoxes.length; stageIndex += 1) {
    const stage = stageBoxes[stageIndex];
    const textBox = {
      x: stage.box.x + stage.box.w * 0.06,
      y: stage.box.y + stage.box.h * 0.32,
      w: stage.box.w * 0.88,
      h: stage.box.h * 0.32
    };
    labels.push({
      text: stage.label,
      box: {
        x: round(textBox.x),
        y: round(textBox.y),
        w: round(textBox.w),
        h: round(textBox.h)
      },
      font: {
        family: "Microsoft YaHei",
        sizePt: 17,
        color: "#FFFFFF",
        opacity: 1,
        weight: "regular",
        align: "center",
        valign: "middle"
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "skill-chain-overview-native-label",
        role: "stage-label",
        stageIndex
      }
    });
  }
  return labels;
}

function normalizeSkillChainOverviewChromeTextBoxes(textBoxes = []) {
  for (const textBox of textBoxes || []) {
    const text = String(textBox?.text || "");
    if (/破局重构.*全链路.*A[Iil1\/]*\s*Skills.*工作流/i.test(text)) {
      textBox.text = "破局重构：全链路 AI Skills 工作流";
      textBox.source = { ...(textBox.source || {}), semanticCorrection: "skill-chain-overview-title" };
      continue;
    }
    if (/单点对话.*链式编排.*深度介入产研/.test(text)) {
      textBox.text = "从“单点对话”走向“链式编排”，让AI深度介入产研发生的标准顺序。";
      textBox.source = { ...(textBox.source || {}), semanticCorrection: "skill-chain-overview-subtitle" };
    }
  }
}

function skillChainOverviewDecorations(layout, slideSize = DEFAULT_SLIDE) {
  const { box, leftCloud, documentPreview, first, last, engine, midY } = layout;
  const decorations = [];
  const railX = Math.max(box.x + box.w * 0.24, first.x - 42);
  const railRight = Math.min(box.x + box.w - 118, last.x + last.w + 52);
  const railW = Math.max(80, railRight - railX);
  const railTop = Math.max(box.y + 34, engine.y + 34);
  const railBottom = Math.min(box.y + box.h - 8, first.y + first.h + 20);
  decorations.push({
    type: "rect",
    box: expandPtBox({ x: railX, y: railTop, w: railW, h: railBottom - railTop }, slideSize, 0, 0),
    style: { fill: "#F2F4F6", stroke: "none", strokeWidthPt: 0 },
    detector: "skill-chain-overview-native-rail-bg",
    role: "rail-background"
  });
  for (const y of [railTop - 8, railBottom - 12, railBottom - 3]) {
    decorations.push({
      type: "rect",
      box: expandPtBox({ x: railX - 12, y, w: railW + 24, h: 4.2 }, slideSize, 0, 0),
      style: { fill: "#AEB7BF", stroke: "none", strokeWidthPt: 0 },
      detector: "skill-chain-overview-native-rail-line",
      role: "rail-line"
    });
  }
  for (const offset of [-28, 0, 28]) {
    decorations.push({
      type: "line",
      box: lineBox(
        { x: leftCloud.x + leftCloud.w + 8, y: midY + offset * 0.72 },
        { x: first.x - 8, y: midY + offset * 0.28 }
      ),
      style: { stroke: "#AEB7BF", strokeWidthPt: 1.2, connectorType: "straight", endArrow: "triangle" },
      detector: "skill-chain-overview-native-side-route",
      role: "input-route"
    });
    decorations.push({
      type: "line",
      box: lineBox(
        { x: last.x + last.w + 8, y: midY + offset * 0.28 },
        { x: documentPreview.x - 8, y: midY + offset * 0.72 }
      ),
      style: { stroke: "#AEB7BF", strokeWidthPt: 1.2, connectorType: "straight", endArrow: "triangle" },
      detector: "skill-chain-overview-native-side-route",
      role: "output-route"
    });
  }
  return decorations;
}

function skillChainOverviewMaterialCloudShapes(materialCloud, slideSize = DEFAULT_SLIDE) {
  const b = materialCloud;
  const fill = "#D8DDE2";
  const stroke = "#AEB6BE";
  const baseStyle = {
    fill,
    stroke,
    strokeWidthPt: 1.1,
    shadow: { color: "#000000", alpha: 0.10, blurPt: 2.5, distancePt: 0.9, angle: 45 }
  };
  const pieces = [
    { role: "fragment-rect", type: "rect", x: 0.51, y: 0.02, w: 0.39, h: 0.29, rotation: -18 },
    { role: "fragment-rect", type: "rect", x: 0.31, y: 0.33, w: 0.38, h: 0.18, rotation: -7 },
    { role: "fragment-rect", type: "rect", x: 0.73, y: 0.25, w: 0.42, h: 0.34, rotation: 13 },
    { role: "fragment-rect", type: "rect", x: 0.02, y: 0.46, w: 0.16, h: 0.46, rotation: -13 },
    { role: "fragment-triangle", type: "triangle", x: 0.48, y: 0.53, w: 0.34, h: 0.34, rotation: 45 },
    { role: "fragment-hexagon", type: "hexagon", x: 0.25, y: 0.72, w: 0.31, h: 0.34, rotation: -10 },
    { role: "fragment-hexagon", type: "hexagon", x: 0.72, y: 0.69, w: 0.33, h: 0.33, rotation: 15 },
    { role: "fragment-rect", type: "rect", x: 0.44, y: 1.05, w: 0.43, h: 0.22, rotation: -19 },
    { role: "fragment-rect", type: "rect", x: 0.02, y: 1.05, w: 0.34, h: 0.15, rotation: 9 }
  ];
  return pieces.map((piece) => ({
    type: piece.type,
    box: expandPtBox({
      x: b.x + b.w * piece.x,
      y: b.y + b.h * piece.y,
      w: b.w * piece.w,
      h: b.h * piece.h
    }, slideSize, 0, 0),
    style: {
      ...baseStyle,
      rotation: piece.rotation
    },
    detector: "skill-chain-overview-native-material-cloud",
    role: piece.role
  }));
}

function skillChainOverviewDocumentPreviewShapes(documentPreview, slideSize = DEFAULT_SLIDE) {
  const b = documentPreview;
  const shapes = [];
  const addRect = (role, box, fill, stroke = "none", strokeWidthPt = 0, extraStyle = {}) => {
    shapes.push({
      type: "rect",
      box: expandPtBox(box, slideSize, 0, 0),
      style: {
        fill,
        stroke,
        strokeWidthPt,
        ...extraStyle
      },
      detector: "skill-chain-overview-native-document-preview",
      role
    });
  };
  addRect("document-paper", {
    x: b.x + b.w * 0.08,
    y: b.y + b.h * 0.02,
    w: b.w * 0.86,
    h: b.h * 0.96
  }, "#FFFFFF", "#C7CDD3", 1.2, {
    shadow: { color: "#000000", alpha: 0.12, blurPt: 5, distancePt: 1.4, angle: 45 }
  });
  addRect("document-side-tab", {
    x: b.x,
    y: b.y + b.h * 0.68,
    w: b.w * 0.22,
    h: b.h * 0.28
  }, "#FFFFFF", "#D3D8DD", 0.8);
  addRect("document-tab-line", {
    x: b.x + b.w * 0.05,
    y: b.y + b.h * 0.83,
    w: b.w * 0.16,
    h: 1.1
  }, "#AEB6BE");
  const lineColor = "#AEB7BF";
  const textLines = [
    [0.24, 0.18, 0.38, 0.075],
    [0.24, 0.34, 0.75, 0.030],
    [0.24, 0.41, 0.75, 0.030],
    [0.24, 0.48, 0.75, 0.030],
    [0.24, 0.55, 0.61, 0.030],
    [0.24, 0.72, 0.30, 0.030],
    [0.24, 0.79, 0.45, 0.030],
    [0.24, 0.86, 0.45, 0.030],
    [0.24, 0.93, 0.33, 0.030],
    [0.66, 0.73, 0.30, 0.030],
    [0.66, 0.80, 0.30, 0.030],
    [0.66, 0.87, 0.24, 0.030]
  ];
  for (const [x, y, w, h] of textLines) {
    addRect("document-text-line", {
      x: b.x + b.w * x,
      y: b.y + b.h * y,
      w: b.w * w,
      h: Math.max(1.2, b.h * h)
    }, lineColor);
  }
  addRect("document-image-placeholder", {
    x: b.x + b.w * 0.24,
    y: b.y + b.h * 0.70,
    w: b.w * 0.37,
    h: b.h * 0.38
  }, "#D9DDE1", "#D2D7DC", 0.7);
  addRect("document-image-placeholder", {
    x: b.x + b.w * 0.67,
    y: b.y + b.h * 0.74,
    w: b.w * 0.30,
    h: b.h * 0.30
  }, "#D9DDE1", "#D2D7DC", 0.7);
  return shapes;
}

function createLinearProcessDiagramShapes(images = [], textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage) return [];
  const shapes = [];
  for (const image of images || []) {
    if (!shouldObjectifyLinearProcessDiagram(image)) continue;
    const process = inferLinearProcessDiagram(image, textBoxes, slideSize);
    if (!process) continue;
    image.source = {
      ...(image.source || {}),
      linearProcessObjectified: true,
      objectifiedLinearProcessStages: process.stages.length,
      objectifiedLinearProcessConnectors: process.connectors.length,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "diagram underlay"}; rebuilt linear process stages and connectors natively while preserving residual artwork`
    };
    for (let index = 0; index < process.stages.length; index += 1) {
      const stage = process.stages[index];
      shapes.push({
        id: `${image.id || "linear-process"}-native-stage-${index}`,
        type: "roundRect",
        box: stage.box,
        style: {
          fill: stage.fill,
          stroke: stage.stroke,
          strokeWidthPt: 1.3,
          radiusRatio: 0.11,
          shadow: {
            color: "#000000",
            alpha: 0.08,
            blurPt: 6,
            distancePt: 1.5,
            angle: 45
          }
        },
        source: {
          editable: true,
          nativeRebuild: true,
          detector: "linear-process-native-stage",
          layerSourceId: image.id || null,
          stageIndex: index,
          label: stage.label,
          confidence: process.confidence
        }
      });
    }
    for (let index = 0; index < process.connectors.length; index += 1) {
      const connector = process.connectors[index];
      shapes.push({
        id: `${image.id || "linear-process"}-native-connector-${index}`,
        type: "line",
        box: connector.box,
        style: {
          stroke: connector.stroke,
          strokeWidthPt: connector.strokeWidthPt,
          connectorType: "straight",
          endArrow: "triangle"
        },
        source: {
          editable: true,
          nativeRebuild: true,
          detector: "linear-process-native-connector",
          layerSourceId: image.id || null,
          connectorIndex: index,
          confidence: process.confidence
        }
      });
    }
  }
  return shapes;
}

function createProductCollaborationChallengeObjects(images = [], rawTextBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE, options = {}) {
  if (!sourceImage) return { shapes: [], textBoxes: [], images: [] };
  const target = (images || []).find((image) => shouldObjectifyProductCollaborationChallenge(image, rawTextBoxes, slideSize));
  if (!target) return { shapes: [], textBoxes: [], images: [] };
  const semanticSignatureVerified = shouldObjectifyProductCollaborationChallenge(target, rawTextBoxes, slideSize);
  // Recognizing a complete diagram is not proof that primitive reconstruction is faithful.
  // Keep the source visual unit unless a caller deliberately opts into the approximation path.
  if (options.allowNativeApproximation !== true) {
    protectProductCollaborationChallengeCrop(target);
    const protectedCrops = createProductCollaborationProtectedCrops(target, sourceImage, slideSize, options);
    if (protectedCrops.length > 0) {
      target.source = {
        ...(target.source || {}),
        productCollaborationChallengeObjectified: true,
        productCollaborationChallengeProtectedSplit: true
      };
    }
    return { shapes: [], textBoxes: [], images: protectedCrops };
  }
  const layout = inferProductCollaborationChallengeLayout(target, rawTextBoxes, slideSize);
  const blindBoxCrop = createProductCollaborationBlindBoxCrop(target, layout.blindBox, sourceImage, slideSize, options);
  target.source = {
    ...(target.source || {}),
    productCollaborationChallengeObjectified: true,
    productCollaborationChallengeAutoApproved: undefined,
    productCollaborationChallengeSemanticSignatureVerified: semanticSignatureVerified || undefined,
    objectifiedProductChallengeCards: layout.inputCards.length,
    objectifiedProductChallengeWarnings: layout.warningCenters.length,
    productCollaborationChallengeNativeTextBoxes: layout.textBoxes,
    dropErasedResidualAfterNativeRebuild: true,
    nonEditableReason: `${target.source?.nonEditableReason || target.source?.reason || "collaboration challenge crop"}; rebuilt fragmented inputs, warning flow, callouts, blind-box output, and bottom banner natively`
  };
  const source = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    componentOwnerId: "product-collaboration-challenge-native-component",
    componentOwnerKind: "product-collaboration-challenge",
    layerSourceId: target.id || null,
    confidence: layout.confidence,
    ...extra
  });
  const shapes = [
    ...layout.inputCards.map((card, index) => ({
      id: `${target.id || "product-challenge"}-input-card-${index}`,
      type: "rect",
      box: card.box,
      style: {
        fill: "#276CC4",
        stroke: "#1455A4",
        strokeWidthPt: 1.2,
        rotation: card.rotation,
        shadow: { color: "#000000", alpha: 0.18, blurPt: 6, distancePt: 2, angle: 45 }
      },
      source: source("product-collaboration-challenge-input-card", { cardIndex: index, label: card.label })
    })),
    ...layout.callouts.map((callout, index) => ({
      id: `${target.id || "product-challenge"}-callout-${index}`,
      type: "roundRect",
      box: callout,
      style: {
        fill: "#F16922",
        stroke: "#C84B12",
        strokeWidthPt: 1,
        radiusRatio: 0.08,
        shadow: { color: "#000000", alpha: 0.12, blurPt: 5, distancePt: 1.5, angle: 45 }
      },
      source: source("product-collaboration-challenge-callout", { calloutIndex: index })
    })),
    ...layout.calloutPointers.map((pointer, index) => ({
      id: `${target.id || "product-challenge"}-callout-pointer-${index}`,
      type: "freeform",
      box: pointer.box,
      points: pointer.points,
      style: { fill: "#F16922", stroke: "#C84B12", strokeWidthPt: 1 },
      source: source("product-collaboration-challenge-callout-pointer", { pointerIndex: index })
    })),
    ...layout.flowLines.map((line, index) => ({
      id: `${target.id || "product-challenge"}-flow-line-${index}`,
      type: "freeform",
      box: line.box,
      points: line.points,
      style: { fill: "none", stroke: "#2E73BF", strokeWidthPt: 2.2, lineCap: "round" },
      source: source("product-collaboration-challenge-zigzag-flow", { lineIndex: index })
    })),
    ...layout.warningCenters.flatMap((center, index) =>
      productCollaborationWarningShapes(target, center, index, slideSize, source)
    ),
    ...layout.sparkLines.map((line, index) => ({
      id: `${target.id || "product-challenge"}-spark-${index}`,
      type: "line",
      box: line.box,
      style: { stroke: "#F16922", strokeWidthPt: 2, connectorType: "straight" },
      source: source("product-collaboration-challenge-warning-spark", { sparkIndex: index })
    })),
    ...(blindBoxCrop ? [] : productCollaborationBlindBoxShapes(target, layout.blindBox, slideSize, source)),
    {
      id: `${target.id || "product-challenge"}-bottom-banner`,
      type: "roundRect",
      box: layout.bottomBanner,
      style: {
        fill: "#286ACF",
        stroke: "#1558B5",
        strokeWidthPt: 1,
        radiusRatio: 0.035,
        shadow: { color: "#000000", alpha: 0.08, blurPt: 4, distancePt: 1.2, angle: 45 }
      },
      source: source("product-collaboration-challenge-bottom-banner")
    }
  ];
  return {
    shapes,
    textBoxes: productCollaborationChallengeTextBoxes(target, rawTextBoxes, layout.inputCards, layout.callouts, layout.bottomBanner, {
      preserveBlindBoxCrop: Boolean(blindBoxCrop)
    }),
    images: blindBoxCrop ? [blindBoxCrop] : []
  };
}

function dropFalseTableLayersClaimedByPortalPlatform(items = [], portalPlatformActive = false) {
  if (portalPlatformActive !== true) return Array.isArray(items) ? items : [];
  const falseTableDetectors = new Set([
    "table-zone-native-cell-fill",
    "table-zone-native-grid-line",
    "table-zone-semantic-native-visible-label"
  ]);
  return (Array.isArray(items) ? items : []).filter((item) =>
    !falseTableDetectors.has(String(item?.source?.detector || "")));
}

function shouldAutoAllowProductCollaborationChallengeNativeApproximation(image = {}) {
  if (isFidelityFirstMinimumVisualUnit(image)) return false;
  const source = image.source || {};
  const layer = source.layer || {};
  const strategy = source.componentRenderStrategy || layer.componentRenderStrategy || {};
  const mode = String(strategy.mode || "");
  const visualAtoms = Array.isArray(layer.visualAtoms) ? layer.visualAtoms : [];
  const nativeConfidence = Number(layer.nativeConfidence ?? source.nativeConfidence ?? 0);
  const editBenefit = Number(layer.editBenefit ?? source.editBenefit ?? 0);
  const hasStructureStrategy = /plugin-component-template|native-visual-atom-rebuild|native-matrix/.test(mode);
  const strongVisualEvidence = visualAtoms.length >= 10 || nativeConfidence >= 0.65 || editBenefit >= 0.85;
  return hasStructureStrategy && strongVisualEvidence;
}

function inferProductCollaborationChallengeLayout(image, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const b = image.box || {};
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const sx = (n) => b.x + b.w * n;
  const sy = (n) => b.y + b.h * n;
  const sw = (n) => b.w * n;
  const sh = (n) => b.h * n;
  const inputCards = [
    { label: "飞书需求", x: 0.055, y: 0.055, w: 0.122, h: 0.155, rotation: -8 },
    { label: "会议截图", x: 0.125, y: 0.205, w: 0.125, h: 0.155, rotation: 8 },
    { label: "口头反馈", x: 0.035, y: 0.350, w: 0.125, h: 0.155, rotation: -7 },
    { label: "过期旧 PRD", x: 0.135, y: 0.505, w: 0.135, h: 0.155, rotation: 7 }
  ].map((card) => ({
    ...card,
    box: constrainPtBox({ x: sx(card.x), y: sy(card.y), w: sw(card.w), h: sh(card.h) }, bounds)
  }));
  const callouts = [
    { x: 0.340, y: -0.018, w: 0.360, h: 0.090 },
    { x: 0.390, y: 0.720, w: 0.395, h: 0.095 },
    { x: 0.460, y: 0.145, w: 0.380, h: 0.090 }
  ].map((box) => constrainPtBox({ x: sx(box.x), y: sy(box.y), w: sw(box.w), h: sh(box.h) }, bounds));
  const calloutPointers = [
    productChallengePointerBox(callouts[0], { x: sx(0.55), y: sy(0.23) }),
    productChallengePointerBox(callouts[1], { x: sx(0.53), y: sy(0.60) }),
    productChallengePointerBox(callouts[2], { x: sx(0.66), y: sy(0.43) })
  ];
  const flowLines = [
    productChallengePolylineBox([
      [0.31, 0.42], [0.38, 0.42], [0.44, 0.36], [0.48, 0.42], [0.54, 0.42], [0.59, 0.34]
    ], b),
    productChallengePolylineBox([
      [0.31, 0.42], [0.39, 0.58], [0.48, 0.61], [0.54, 0.58], [0.61, 0.62], [0.68, 0.53]
    ], b),
    productChallengePolylineBox([
      [0.60, 0.42], [0.67, 0.42], [0.73, 0.34], [0.77, 0.42], [0.84, 0.42]
    ], b),
    productChallengePolylineBox([
      [0.70, 0.58], [0.77, 0.51], [0.84, 0.53]
    ], b)
  ];
  const warningCenters = [
    { x: sx(0.34), y: sy(0.42), size: sw(0.038) },
    { x: sx(0.43), y: sy(0.31), size: sw(0.042) },
    { x: sx(0.53), y: sy(0.42), size: sw(0.060), big: true },
    { x: sx(0.53), y: sy(0.66), size: sw(0.052), big: true },
    { x: sx(0.62), y: sy(0.40), size: sw(0.038) },
    { x: sx(0.66), y: sy(0.60), size: sw(0.040) },
    { x: sx(0.78), y: sy(0.42), size: sw(0.038) }
  ];
  const sparkLines = warningCenters
    .filter((center) => center.big)
    .flatMap((center, index) => productChallengeSparkLines(center, index));
  const blindBox = constrainPtBox({ x: sx(0.835), y: sy(0.26), w: sw(0.135), h: sh(0.300) }, bounds);
  const bottomBanner = constrainPtBox({ x: slideSize.widthPt * 0.03, y: slideSize.heightPt * 0.868, w: slideSize.widthPt * 0.94, h: slideSize.heightPt * 0.085 }, bounds);
  return {
    inputCards,
    callouts,
    calloutPointers,
    flowLines,
    warningCenters,
    sparkLines,
    blindBox,
    bottomBanner,
    textBoxes: productCollaborationChallengeTextBoxes(image, rawTextBoxes, inputCards, callouts, bottomBanner),
    confidence: 0.86
  };
}

function productChallengePointerBox(callout, tip) {
  const left = Math.min(callout.x + callout.w * 0.35, tip.x);
  const top = Math.min(callout.y + callout.h * 0.85, tip.y);
  const right = Math.max(callout.x + callout.w * 0.55, tip.x);
  const bottom = Math.max(callout.y + callout.h * 0.85, tip.y);
  const box = { x: round(left), y: round(top), w: round(right - left), h: round(Math.max(8, bottom - top)) };
  return {
    box,
    points: [
      { x: 0.20, y: 0 },
      { x: 0.46, y: 0 },
      { x: 1, y: 1 },
      { x: 0.34, y: 0.38 }
    ]
  };
}

function productChallengePolylineBox(points, baseBox) {
  const abs = points.map(([x, y]) => ({ x: baseBox.x + baseBox.w * x, y: baseBox.y + baseBox.h * y }));
  const minX = Math.min(...abs.map((p) => p.x));
  const minY = Math.min(...abs.map((p) => p.y));
  const maxX = Math.max(...abs.map((p) => p.x));
  const maxY = Math.max(...abs.map((p) => p.y));
  return {
    box: { x: round(minX), y: round(minY), w: round(maxX - minX), h: round(maxY - minY || 1) },
    points: abs.map((p) => ({
      x: (p.x - minX) / Math.max(1, maxX - minX),
      y: (p.y - minY) / Math.max(1, maxY - minY)
    }))
  };
}

function productCollaborationWarningShapes(target, center, index, slideSize, source) {
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  return comparisonWarningShapes({ x: center.x, y: center.y }, bounds).map((shape, partIndex) => ({
    id: `${target.id || "product-challenge"}-warning-${index}-${partIndex}`,
    ...shape,
    box: partIndex === 0
      ? constrainPtBox({ x: center.x - center.size / 2, y: center.y - center.size / 2, w: center.size, h: center.size }, bounds)
      : shape.box,
    source: source("product-collaboration-challenge-warning", { warningIndex: index, warningPart: shape.statusKind })
  }));
}

function productChallengeSparkLines(center, groupIndex) {
  const offsets = [
    [-22, -18, -10, -8], [18, -18, 8, -8], [-24, 0, -10, 0], [24, 0, 10, 0], [-18, 18, -8, 8], [18, 18, 8, 8]
  ];
  return offsets.map(([x1, y1, x2, y2], index) => ({
    box: lineBox({ x: center.x + x1, y: center.y + y1 }, { x: center.x + x2, y: center.y + y2 }),
    groupIndex,
    index
  }));
}

function productCollaborationBlindBoxShapes(target, box, slideSize, source) {
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  return [
    { id: "box-body", type: "rect", box: { x: box.x + box.w * 0.12, y: box.y + box.h * 0.35, w: box.w * 0.76, h: box.h * 0.48 }, fill: "#C9D4E3", stroke: "#AAB8C9" },
    { id: "box-left-flap", type: "freeform", box: { x: box.x, y: box.y + box.h * 0.24, w: box.w * 0.56, h: box.h * 0.30 }, fill: "#E4EAF2", stroke: "#B7C3D1", points: [{ x: 0.15, y: 0.25 }, { x: 1, y: 0 }, { x: 0.78, y: 1 }, { x: 0, y: 0.70 }] },
    { id: "box-right-flap", type: "freeform", box: { x: box.x + box.w * 0.44, y: box.y + box.h * 0.24, w: box.w * 0.56, h: box.h * 0.30 }, fill: "#D9E1EC", stroke: "#B7C3D1", points: [{ x: 0, y: 0 }, { x: 0.85, y: 0.25 }, { x: 1, y: 0.70 }, { x: 0.22, y: 1 }] },
    { id: "box-question", type: "textBackplate", box: { x: box.x + box.w * 0.38, y: box.y - box.h * 0.02, w: box.w * 0.25, h: box.h * 0.38 }, fill: "none", stroke: "none" }
  ].map((shape) => ({
    id: `${target.id || "product-challenge"}-${shape.id}`,
    type: shape.type === "textBackplate" ? "rect" : shape.type,
    box: constrainPtBox(shape.box, bounds),
    ...(shape.points ? { points: shape.points } : {}),
    style: {
      fill: shape.fill,
      stroke: shape.stroke,
      strokeWidthPt: shape.stroke === "none" ? 0 : 1,
      opacity: shape.id === "box-question" ? 0 : 1
    },
    source: source("product-collaboration-challenge-blind-box", { boxPart: shape.id })
  }));
}

function createProductCollaborationBlindBoxCrop(target, box, sourceImage, slideSize, options = {}) {
  if (!sourceImage || !options.assetDir) return null;
  ensureDir(options.assetDir);
  const paddedBox = expandPtBox(box, slideSize, 3, 3);
  const pxBox = ptToPxBox(paddedBox, sourceImage, slideSize, 0);
  const crop = cropPng(sourceImage, pxBox);
  const base = safeIdentifier(`${options.deckName || "deck"}-p${String(Number(options.pageIndex || 0) + 1).padStart(2, "0")}-${target.id || "product-challenge"}-blind-box`, "product-challenge-blind-box");
  const file = path.join(options.assetDir, `${base}.png`);
  writePng(file, crop);
  return {
    id: `${target.id || "product-challenge"}-blind-box-crop`,
    type: "fidelity-crop",
    assetPath: path.relative(options.irDir || options.assetDir, file).replace(/\\/g, "/"),
    box: pxToPtBox(pxBox, sourceImage, slideSize, 0),
    source: {
      editable: false,
      nativeRebuild: true,
      detector: "product-collaboration-challenge-blind-box-crop",
      expressionForm: "icon-or-illustration",
      expressionSubtype: "blind-box-illustration",
      recommendedAction: "preserve-local-crop",
      protectedMinimumUnit: true,
      intentionalMinimumUnitCrop: true,
      nonEditableReason: "complex blind-box illustration retained as a local fidelity crop while the surrounding collaboration flow is rebuilt natively"
    }
  };
}

function productCollaborationChallengeTextBoxes(image, rawTextBoxes = [], inputCards = [], callouts = [], bottomBanner, options = {}) {
  const b = image.box || {};
  const inside = (rawTextBoxes || []).filter((item) => {
    const box = item?.box || {};
    const cx = Number(box.x || 0) + Number(box.w || 0) / 2;
    const cy = Number(box.y || 0) + Number(box.h || 0) / 2;
    return cx >= b.x - 8 && cx <= b.x + b.w + 8 && cy >= b.y - 8 && cy <= b.y + b.h + 8;
  });
  const rawByLabel = new Map(inside.map((item) => [normalizeMatrixLabel(item.text), item]));
  const result = [];
  for (let index = 0; index < inputCards.length; index += 1) {
    const card = inputCards[index];
    const text = card.label;
    result.push(productChallengeTextBox(image, text, {
      x: card.box.x + card.box.w * 0.12,
      y: card.box.y + card.box.h * 0.34,
      w: card.box.w * 0.76,
      h: card.box.h * 0.30
    }, "input-card", index, { color: "#FFFFFF", sizePt: 15.5, weight: "bold", align: "center", rotation: card.rotation }));
  }
  const calloutTexts = [
    "协作断层：文档分散，查找与核对成本极高",
    "版本漂移：规则散落，同功能增量极易互相覆盖",
    "评审低效：依赖人工经验，风险往往暴露太晚"
  ];
  calloutTexts.forEach((text, index) => {
    const box = callouts[index];
    result.push(productChallengeTextBox(image, text, {
      x: box.x + box.w * 0.08,
      y: box.y + box.h * 0.23,
      w: box.w * 0.86,
      h: box.h * 0.50
    }, "callout", index, { color: "#FFFFFF", sizePt: index === 2 ? 12.4 : 13.2, weight: "bold" }));
  });
  [
    ["碎片化输入（飞书需求、会议截图、口头反馈、过期旧PRD）", { x: b.x + b.w * 0.02, y: b.y + b.h * 0.722, w: b.w * 0.23, h: b.h * 0.11 }],
    ["盲盒式交付（交付标准完全依赖个人经验，质量极不稳定）", { x: b.x + b.w * 0.78, y: b.y + b.h * 0.724, w: b.w * 0.20, h: b.h * 0.12 }]
  ].forEach(([text, box], index) => {
    result.push(productChallengeTextBox(image, text, box, "caption", index, { color: "#202936", sizePt: 13.6, weight: "bold", align: "left" }));
  });
  const bottomRaw = rawByLabel.get(normalizeMatrixLabel("核心矛盾：瓶颈已不是“缺工具”，而是缺乏一条贯穿需求、文档、原型和评审的标准化资产链路"));
  result.push(productChallengeTextBox(image, bottomRaw?.text || "核心矛盾：瓶颈已不是“缺工具”，而是缺乏一条贯穿需求、文档、原型和评审的标准化资产链路。", {
    x: bottomBanner.x + bottomBanner.w * 0.025,
    y: bottomBanner.y + bottomBanner.h * 0.20,
    w: bottomBanner.w * 0.95,
    h: bottomBanner.h * 0.58
  }, "bottom-banner", 0, { color: "#FFFFFF", sizePt: 17, weight: "bold", align: "left" }));
  if (options.preserveBlindBoxCrop !== true) {
    result.push(productChallengeTextBox(image, "?", { x: b.x + b.w * 0.875, y: b.y + b.h * 0.22, w: b.w * 0.08, h: b.h * 0.18 }, "question", 0, { color: "#9BAABE", sizePt: 58, weight: "bold", align: "center" }));
  }
  return result;
}

function productChallengeTextBox(image, text, box, role, index, font = {}) {
  return {
    id: `${image.id || "product-challenge"}-native-text-${role}-${index}`,
    text,
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(box.w),
      h: round(box.h)
    },
    font: {
      family: "Microsoft YaHei",
      sizePt: font.sizePt || 14,
      color: font.color || "#111827",
      opacity: 1,
      weight: font.weight || "regular",
      align: font.align || "center",
      valign: "middle"
    },
    style: {
      fit: "shrink",
      rotation: font.rotation || 0,
      marginLeftPt: 0,
      marginRightPt: 0,
      marginTopPt: 0,
      marginBottomPt: 0
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "product-collaboration-challenge-native-text",
      componentOwnerId: "product-collaboration-challenge-native-component",
      componentOwnerKind: "product-collaboration-challenge",
      layerSourceId: image.id || null,
      role,
      confidence: 0.86
    }
  };
}

function createProcessWithScreenshotsFlowObjects(images = [], sourceImage = null, slideSize = DEFAULT_SLIDE, options = {}) {
  const shapes = [];
  const textBoxes = [];
  const fidelityImages = [];
  for (const image of images || []) {
    if (image?.source?.standardizedFourLayerArchitectureObjectified === true) continue;
    if (!shouldObjectifyProcessWithScreenshotsFlow(image)) continue;
    const layout = inferProcessWithScreenshotsFlowLayout(image, slideSize);
    if (!layout) continue;
    const stageCrops = layout.productWorkflowIconProcess === true
      ? createProductWorkflowStageMinimumUnitCrops({
        image,
        layout,
        sourceImage,
        slideSize,
        assetDir: options.assetDir,
        irDir: options.irDir,
        deckName: options.deckName,
        pageIndex: options.pageIndex
      })
      : [];
    const stageCropsPreserved = stageCrops.length === 4;
    const fullyObjectified = isProcessWithScreenshotsFlowFullyObjectified(layout);
    image.source = {
      ...(image.source || {}),
      processWithScreenshotsFlowObjectified: true,
      processWithScreenshotsLeftIllustrationObjectified: layout.leftIllustrationShapes.length > 0,
      processWithScreenshotsChaosCoreObjectified: layout.leftIllustrationShapes.length >= 35,
      processWithScreenshotsFullyObjectified: fullyObjectified,
      productWorkflowIconProcessObjectified: layout.productWorkflowIconProcess === true,
      productWorkflowStageCropsPreserved: stageCropsPreserved,
      productWorkflowStageCropCount: stageCrops.length,
      productWorkflowEndpointObjectified: layout.productWorkflowEndpointShapes?.length > 0,
      objectifiedProcessFlowCards: layout.cards.length,
      objectifiedProcessFlowConnectors: layout.connectors.length,
      objectifiedProcessLeftIllustrationShapes: layout.leftIllustrationShapes.length,
      objectifiedProductWorkflowEndpointShapes: layout.productWorkflowEndpointShapes?.length || 0,
      processWithScreenshotsNativeTextBoxes: layout.textBoxes,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "process diagram underlay"}; rebuilt process flow and left-side work-chaos illustration as native editable objects while preserving screenshot-like notes`
    };
    shapes.push(...layout.leftIllustrationShapes);
    shapes.push(...(layout.productWorkflowEndpointShapes || []));
    shapes.push(...layout.connectors.map((connector, index) => ({
      id: `${image.id || "process-screenshots"}-native-connector-${index}`,
      type: "line",
      box: connector.box,
      style: {
        stroke: "#24A867",
        strokeWidthPt: connector.strokeWidthPt,
        connectorType: "straight",
        endArrow: connector.endArrow || undefined,
        lineCap: "round"
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "process-screenshots-native-connector",
        layerSourceId: image.id || null,
        connectorIndex: index,
        confidence: layout.confidence
      }
    })));
    const nativeCards = stageCropsPreserved
      ? layout.cards.filter((card) => card.role === "bottom-banner")
      : layout.cards;
    shapes.push(...nativeCards.map((card, index) => ({
      id: `${image.id || "process-screenshots"}-native-card-${index}`,
      type: card.type || "roundRect",
      box: card.box,
      style: {
        fill: card.fill,
        stroke: card.stroke,
        strokeWidthPt: card.strokeWidthPt,
        radiusRatio: card.type === "rect" || card.type === "hexagon" ? undefined : 0.11,
        shadow: card.noShadow ? undefined : {
          color: "#000000",
          alpha: card.primary ? 0.13 : 0.08,
          blurPt: card.primary ? 9 : 5,
          distancePt: card.primary ? 2 : 1,
          angle: 45
        }
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "process-screenshots-native-card",
        layerSourceId: image.id || null,
        cardRole: card.role,
        cardIndex: index,
        confidence: layout.confidence
      }
    })));
    if (!stageCropsPreserved) {
      shapes.push(...layout.icons.flatMap((icon, index) =>
        processWithScreenshotsIconShapes(image, icon, index, layout.confidence)
      ));
    }
    fidelityImages.push(...stageCrops);
    textBoxes.push(...layout.textBoxes);
  }
  return { shapes, textBoxes, images: fidelityImages };
}

function createProductWorkflowStageMinimumUnitCrops({ image = {}, layout = {}, sourceImage = null, slideSize = DEFAULT_SLIDE, assetDir = null, irDir = null, deckName = "deck", pageIndex = 0 } = {}) {
  if (!sourceImage || !assetDir || !irDir || layout.productWorkflowIconProcess !== true) return [];
  const stages = (layout.cards || []).filter((card) => card.role !== "bottom-banner");
  if (stages.length !== 4 || stages.some((stage) => !stage.box?.w || !stage.box?.h)) return [];
  ensureDir(assetDir);
  return stages.map((stage, index) => {
    const cropBox = roundedBox(expandPtBox(stage.box, slideSize, 2.5, 2.5));
    const file = path.join(assetDir, `${safeIdentifier(deckName, "deck")}-page-${String(Number(pageIndex || 0) + 1).padStart(3, "0")}-workflow-stage-${String(index + 1).padStart(2, "0")}.png`);
    writePng(file, cropPng(sourceImage, ptToPxBox(cropBox, sourceImage, slideSize, 0)));
    const stageLayer = splitResidualLayerSource(image.source?.layer, cropBox, "product-workflow-stage-minimum-unit-crop");
    return {
      id: `${image.id || "product-workflow"}-stage-${index + 1}-crop`,
      type: "fidelity-crop",
      assetPath: path.relative(irDir, file).replace(/\\/g, "/"),
      box: cropBox,
      source: {
        ...(image.source || {}),
        editable: false,
        detector: "product-workflow-stage-minimum-unit-crop",
        parentDetector: image.source?.detector || null,
        parentImageId: image.id || null,
        layer: stageLayer ? {
          ...stageLayer,
          layerType: "illustration-zone",
          expressionForm: "icon-or-illustration",
          expressionSubtype: "decorated-process-node",
          recommendedAction: "preserve-stage-node-as-minimum-unit-crop"
        } : stageLayer,
        expressionForm: "icon-or-illustration",
        expressionSubtype: "decorated-process-node",
        recommendedAction: "preserve-stage-node-as-minimum-unit-crop",
        intentionalMinimumUnitCrop: true,
        protectedMinimumUnit: true,
        skipVisualAtomRebuild: true,
        productWorkflowStageRole: stage.role,
        productWorkflowStageIndex: index,
        nonEditableReason: "rounded hexagon and embedded pictorial icon form one visually indivisible process-node asset"
      }
    };
  });
}

function isProcessWithScreenshotsFlowFullyObjectified(layout = {}) {
  const cards = Array.isArray(layout.cards) ? layout.cards.length : 0;
  const connectors = Array.isArray(layout.connectors) ? layout.connectors.length : 0;
  const leftIllustrationShapes = Array.isArray(layout.leftIllustrationShapes) ? layout.leftIllustrationShapes.length : 0;
  const textBoxes = Array.isArray(layout.textBoxes) ? layout.textBoxes.length : 0;
  return cards >= 4 && connectors >= 5 && leftIllustrationShapes >= 35 && textBoxes >= 8;
}

function shouldObjectifyProcessWithScreenshotsFlow(image) {
  if (!shouldSplitProcessWithScreenshotsLayer(image)) return false;
  const box = image?.box || {};
  if (Number(box.w || 0) < 720 || Number(box.h || 0) < 260) return false;
  return true;
}

function createToolGapPlatformDiagramObjects(images = [], rawTextBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage) return { shapes: [], textBoxes: [] };
  const target = (images || []).find((image) => shouldObjectifyToolGapPlatformDiagram(image, rawTextBoxes, slideSize));
  if (!target) return { shapes: [], textBoxes: [] };
  const layout = inferToolGapPlatformDiagramLayout(target, rawTextBoxes, slideSize);
  if (!layout) return { shapes: [], textBoxes: [] };
  target.source = {
    ...(target.source || {}),
    toolGapPlatformObjectified: true,
    objectifiedToolGapRows: layout.rowBands.length,
    objectifiedToolGapIcons: layout.iconShapes.length,
    objectifiedToolGapConnectors: layout.connectorShapes.length,
    toolGapPlatformNativeTextBoxes: layout.textBoxes.length,
    toolGapPlatformTextEraseBoxes: layout.textBoxes.map((item) => item.box).filter(Boolean),
    nonEditableReason: `${target.source?.nonEditableReason || target.source?.reason || "mixed diagram crop"}; rebuilt tool-gap comparison table, status row, and PM Portal flow as native editable objects`
  };
  const source = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    layerSourceId: target.id || null,
    confidence: layout.confidence,
    ...extra
  });
  const shapes = [
    ...layout.rowBands.flatMap((band, index) => [
      {
        id: `${target.id || "tool-gap"}-native-row-${index}`,
        type: "rect",
        box: band.box,
        style: {
          fill: band.fill,
          stroke: "#BFC8D2",
          strokeWidthPt: 0.9
        },
        source: source("tool-gap-platform-native-row", { rowIndex: index })
      },
      {
        id: `${target.id || "tool-gap"}-native-left-label-${index}`,
        type: "rect",
        box: band.labelBox,
        style: {
          fill: "#EEF3F8",
          stroke: "#BFC8D2",
          strokeWidthPt: 0.8
        },
        source: source("tool-gap-platform-native-label-cell", { rowIndex: index })
      }
    ]),
    ...layout.columnDividers.map((line, index) => ({
      id: `${target.id || "tool-gap"}-native-divider-${index}`,
      type: "line",
      box: line.box,
      style: {
        stroke: "#C9D2DC",
        strokeWidthPt: line.strokeWidthPt,
        connectorType: "straight"
      },
      source: source("tool-gap-platform-native-divider", { dividerIndex: index })
    })),
    ...layout.connectorShapes.map((line, index) => ({
      id: `${target.id || "tool-gap"}-native-connector-${index}`,
      type: "line",
      box: line.box,
      style: {
        stroke: line.stroke,
        strokeWidthPt: line.strokeWidthPt,
        connectorType: "straight",
        endArrow: line.endArrow,
        lineCap: "round"
      },
      source: source("tool-gap-platform-native-connector", { connectorIndex: index })
    })),
    ...layout.loopShapes.map((shape, index) => ({
      id: `${target.id || "tool-gap"}-native-loop-${index}`,
      type: shape.type,
      box: shape.box,
      style: shape.style,
      source: source("tool-gap-platform-native-loop", { loopIndex: index, loopRole: shape.role })
    })),
    ...layout.iconShapes.map((shape, index) => ({
      id: `${target.id || "tool-gap"}-native-icon-${index}`,
      type: shape.type,
      box: shape.box,
      style: shape.style,
      source: source("tool-gap-platform-native-icon", { iconIndex: index, iconRole: shape.role })
    }))
  ];
  return { shapes, textBoxes: layout.textBoxes };
}

function shouldObjectifyToolGapPlatformDiagram(image, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const source = image?.source || {};
  const box = image?.box || {};
  if (source.toolGapPlatformObjectified === true) return false;
  if (source.detector !== "mixed-diagram-graphic-underlay-crop") return false;
  if (Number(box.w || 0) < slideSize.widthPt * 0.72 || Number(box.h || 0) < slideSize.heightPt * 0.56) return false;
  const allText = (textBoxes || []).map((item) => String(item.text || "")).join(" ");
  return /跨越工具孤岛/.test(allText)
    && /传统协作模式/.test(allText)
    && /普通AI工具/.test(allText)
    && /PM\s*Portal/i.test(allText)
    && /Platform/i.test(allText);
}

function inferToolGapPlatformDiagramLayout(image, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const b = image.box || {};
  if (!b.w || !b.h) return null;
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const sx = (n) => b.x + b.w * n;
  const sy = (n) => b.y + b.h * n;
  const sw = (n) => b.w * n;
  const sh = (n) => b.h * n;
  const rowBands = [
    { role: "manual", box: { x: b.x, y: sy(0.01), w: b.w, h: sh(0.24) }, fill: "#F6FAFD" },
    { role: "ai-tool", box: { x: b.x, y: sy(0.34), w: b.w, h: sh(0.21) }, fill: "#F7FAFD" },
    { role: "platform", box: { x: b.x, y: sy(0.68), w: b.w, h: sh(0.27) }, fill: "#F7FAFD" }
  ].map((row) => ({
    ...row,
    box: constrainPtBox(row.box, bounds),
    labelBox: constrainPtBox({ x: row.box.x, y: row.box.y, w: sw(0.16), h: row.box.h }, bounds)
  }));
  const columnDividers = [
    { x: sx(0.16), y1: sy(0.01), y2: sy(0.95), strokeWidthPt: 0.9 },
    { x: sx(0.76), y1: sy(0.01), y2: sy(0.95), strokeWidthPt: 0.9 },
    { x: sx(0.49), y1: sy(0.01), y2: sy(0.28), strokeWidthPt: 0.7 }
  ].map((line) => ({
    ...line,
    box: lineBox({ x: line.x, y: line.y1 }, { x: line.x, y: line.y2 })
  }));
  const connectorShapes = [
    { from: [0.22, 0.18], to: [0.32, 0.18], stroke: "#F28C24", strokeWidthPt: 1.7, endArrow: "triangle" },
    { from: [0.43, 0.18], to: [0.53, 0.18], stroke: "#F28C24", strokeWidthPt: 1.7, endArrow: "triangle" },
    { from: [0.64, 0.18], to: [0.72, 0.18], stroke: "#F28C24", strokeWidthPt: 1.7, endArrow: "triangle" },
    { from: [0.28, 0.47], to: [0.75, 0.47], stroke: "#B7BEC7", strokeWidthPt: 1.5, endArrow: "triangle" },
    { from: [0.30, 0.78], to: [0.73, 0.78], stroke: "#1478B8", strokeWidthPt: 3.0, endArrow: "triangle" },
    { from: [0.58, 0.79], to: [0.73, 0.79], stroke: "#22A76B", strokeWidthPt: 3.0, endArrow: "triangle" }
  ].map((line) => ({
    ...line,
    box: lineBox({ x: sx(line.from[0]), y: sy(line.from[1]) }, { x: sx(line.to[0]), y: sy(line.to[1]) })
  }));
  const loopShapes = [
    { role: "left-loop", type: "ellipse", box: { x: sx(0.21), y: sy(0.72), w: sw(0.27), h: sh(0.17) }, stroke: "#1478B8" },
    { role: "right-loop", type: "ellipse", box: { x: sx(0.43), y: sy(0.72), w: sw(0.27), h: sh(0.17) }, stroke: "#1478B8" },
    { role: "platform-chip-left", type: "roundRect", box: { x: sx(0.25), y: sy(0.735), w: sw(0.13), h: sh(0.055) }, fill: "#E8F3FE", stroke: "#1478B8" },
    { role: "platform-chip-right", type: "roundRect", box: { x: sx(0.51), y: sy(0.735), w: sw(0.13), h: sh(0.055) }, fill: "#E8F9F1", stroke: "#22A76B" }
  ].map((shape) => ({
    ...shape,
    box: constrainPtBox(shape.box, bounds),
    style: {
      fill: shape.fill || "none",
      stroke: shape.stroke,
      strokeWidthPt: shape.type === "ellipse" ? 3.2 : 1.1,
      radiusRatio: shape.type === "roundRect" ? 0.25 : undefined
    }
  }));
  const iconShapes = [
    ...toolGapDocumentIconCluster(b, bounds),
    ...toolGapAiStatusIconCluster(b, bounds),
    ...toolGapPlatformIconCluster(b, bounds)
  ];
  const textBoxes = toolGapPlatformNativeTextBoxes(image, rawTextBoxes);
  return {
    rowBands,
    columnDividers,
    connectorShapes,
    loopShapes,
    iconShapes,
    textBoxes,
    confidence: 0.82
  };
}

function toolGapDocumentIconCluster(b, bounds) {
  const positions = [
    [0.215, 0.095, "#F3A33A", "doc"],
    [0.355, 0.095, "#F3A33A", "prototype"],
    [0.555, 0.095, "#F3A33A", "review"]
  ];
  return positions.flatMap(([x, y, color, role], index) => {
    const box = constrainPtBox({ x: b.x + b.w * x, y: b.y + b.h * y, w: b.w * 0.05, h: b.h * 0.095 }, bounds);
    return [
      {
        role: `${role}-paper`,
        type: "rect",
        box,
        style: { fill: "#FFFFFF", stroke: color, strokeWidthPt: 1.2 }
      },
      {
        role: `${role}-fold`,
        type: "triangle",
        box: constrainPtBox({ x: box.x + box.w * 0.62, y: box.y, w: box.w * 0.38, h: box.h * 0.30 }, bounds),
        style: { fill: "#FFE1B9", stroke: color, strokeWidthPt: 0.7, rotation: 45 }
      },
      {
        role: `${role}-line-${index}`,
        type: "rect",
        box: constrainPtBox({ x: box.x + box.w * 0.18, y: box.y + box.h * 0.58, w: box.w * 0.58, h: 1.6 }, bounds),
        style: { fill: color, stroke: color, strokeWidthPt: 0 }
      }
    ];
  });
}

function toolGapAiStatusIconCluster(b, bounds) {
  const icons = [
    { role: "chat-a", type: "roundRect", x: 0.22, y: 0.42, w: 0.060, h: 0.060, fill: "#B5BBC3", stroke: "#8C949E" },
    { role: "chat-b", type: "roundRect", x: 0.30, y: 0.42, w: 0.060, h: 0.060, fill: "#B5BBC3", stroke: "#8C949E" },
    { role: "check-a", type: "ellipse", x: 0.405, y: 0.42, w: 0.045, h: 0.060, fill: "#2EAD67", stroke: "#2EAD67" },
    { role: "warning-a", type: "triangle", x: 0.500, y: 0.42, w: 0.050, h: 0.065, fill: "#F4A42C", stroke: "#E18716" },
    { role: "warning-b", type: "triangle", x: 0.595, y: 0.42, w: 0.050, h: 0.065, fill: "#F4A42C", stroke: "#E18716" },
    { role: "warning-c", type: "triangle", x: 0.690, y: 0.42, w: 0.050, h: 0.065, fill: "#F4A42C", stroke: "#E18716" }
  ];
  return icons.flatMap((icon) => {
    const box = constrainPtBox({ x: b.x + b.w * icon.x, y: b.y + b.h * icon.y, w: b.w * icon.w, h: b.h * icon.h }, bounds);
    const base = {
      role: icon.role,
      type: icon.type,
      box,
      style: {
        fill: icon.fill,
        stroke: icon.stroke,
        strokeWidthPt: 0.8,
        radiusRatio: icon.type === "roundRect" ? 0.22 : undefined
      }
    };
    if (!icon.role.startsWith("check")) return [base];
    return [
      base,
      {
        role: `${icon.role}-tick`,
        type: "line",
        box: lineBox({ x: box.x + box.w * 0.28, y: box.y + box.h * 0.55 }, { x: box.x + box.w * 0.46, y: box.y + box.h * 0.72 }),
        style: { stroke: "#FFFFFF", strokeWidthPt: 1.2, connectorType: "straight" }
      },
      {
        role: `${icon.role}-tick-long`,
        type: "line",
        box: lineBox({ x: box.x + box.w * 0.45, y: box.y + box.h * 0.72 }, { x: box.x + box.w * 0.76, y: box.y + box.h * 0.33 }),
        style: { stroke: "#FFFFFF", strokeWidthPt: 1.2, connectorType: "straight" }
      }
    ];
  });
}

function toolGapPlatformIconCluster(b, bounds) {
  const search = constrainPtBox({ x: b.x + b.w * 0.238, y: b.y + b.h * 0.730, w: b.w * 0.055, h: b.h * 0.100 }, bounds);
  const catalog = constrainPtBox({ x: b.x + b.w * 0.552, y: b.y + b.h * 0.728, w: b.w * 0.052, h: b.h * 0.098 }, bounds);
  return [
    { role: "search-tile", type: "roundRect", box: search, style: { fill: "#E8F3FE", stroke: "#1478B8", strokeWidthPt: 1, radiusRatio: 0.12 } },
    { role: "search-lens", type: "ellipse", box: constrainPtBox({ x: search.x + search.w * 0.24, y: search.y + search.h * 0.22, w: search.w * 0.36, h: search.h * 0.36 }, bounds), style: { fill: "none", stroke: "#1478B8", strokeWidthPt: 1.5 } },
    { role: "search-handle", type: "line", box: lineBox({ x: search.x + search.w * 0.58, y: search.y + search.h * 0.58 }, { x: search.x + search.w * 0.78, y: search.y + search.h * 0.78 }), style: { stroke: "#1478B8", strokeWidthPt: 1.5, connectorType: "straight" } },
    { role: "catalog-tile", type: "roundRect", box: catalog, style: { fill: "#E8F9F1", stroke: "#22A76B", strokeWidthPt: 1, radiusRatio: 0.12 } },
    { role: "catalog-line-a", type: "rect", box: constrainPtBox({ x: catalog.x + catalog.w * 0.22, y: catalog.y + catalog.h * 0.28, w: catalog.w * 0.56, h: 1.8 }, bounds), style: { fill: "#22A76B", stroke: "#22A76B", strokeWidthPt: 0 } },
    { role: "catalog-line-b", type: "rect", box: constrainPtBox({ x: catalog.x + catalog.w * 0.22, y: catalog.y + catalog.h * 0.50, w: catalog.w * 0.56, h: 1.8 }, bounds), style: { fill: "#22A76B", stroke: "#22A76B", strokeWidthPt: 0 } },
    { role: "catalog-line-c", type: "rect", box: constrainPtBox({ x: catalog.x + catalog.w * 0.22, y: catalog.y + catalog.h * 0.72, w: catalog.w * 0.45, h: 1.8 }, bounds), style: { fill: "#22A76B", stroke: "#22A76B", strokeWidthPt: 0 } }
  ];
}

function toolGapPlatformNativeTextBoxes(image, rawTextBoxes = []) {
  const b = image.box || {};
  const candidates = (rawTextBoxes || []).filter((item) => {
    const box = item?.box || {};
    const cx = Number(box.x || 0) + Number(box.w || 0) / 2;
    const cy = Number(box.y || 0) + Number(box.h || 0) / 2;
    return cx >= b.x - 2 && cx <= b.x + b.w + 2 && cy >= b.y - 2 && cy <= b.y + b.h + 2;
  });
  return candidates.map((item, index) => {
    const text = String(item.text || "");
    const sizePt = Number(item.font?.sizePt || item.fontSizePt || 12);
    return {
      id: `${image.id || "tool-gap"}-native-text-${index}`,
      text,
      box: item.box,
      font: {
        family: /[\u4e00-\u9fa5]/.test(text) ? "Microsoft YaHei" : "Aptos",
        sizePt,
        color: item.font?.color || "#111827",
        weight: item.font?.weight || (/^(?:深|PM Portal|Platform)$/i.test(text.trim()) ? "bold" : "regular"),
        align: item.font?.align || "center",
        valign: "middle",
        opacity: 1
      },
      style: {
        visibility: "visible",
        opacity: 1,
        marginLeftPt: 0,
        marginRightPt: 0,
        marginTopPt: 0,
        marginBottomPt: 0,
        fit: "shrink"
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "tool-gap-platform-native-text",
        layerSourceId: image.id || null,
        confidence: 0.82
      }
    };
  });
}

function createStackedArchitectureDiagramObjects(images = [], textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage) return { shapes: [], textBoxes: [] };
  const foundationNetwork = createFoundationCapabilityNetworkObjects(images, textBoxes, slideSize);
  if (foundationNetwork.shapes.length > 0) return foundationNetwork;
  const standardizedFourLayer = createStandardizedFourLayerArchitectureObjects(images, textBoxes, sourceImage, slideSize);
  if (standardizedFourLayer.shapes.length > 0) return standardizedFourLayer;
  const target = (images || []).find((image) => shouldObjectifyStackedArchitectureDiagram(image, textBoxes));
  if (!target) return { shapes: [], textBoxes: [] };
  const layout = inferStackedArchitectureLayout(target, slideSize);
  target.source = {
    ...(target.source || {}),
    stackedArchitectureObjectified: true,
    objectifiedStackedArchitectureBlocks: layout.layers.length,
    objectifiedStackedArchitectureArrows: layout.arrows.length,
    dropErasedResidualAfterNativeRebuild: true,
    nonEditableReason: `${target.source?.nonEditableReason || target.source?.reason || "architecture stack crop"}; rebuilt stacked architecture blocks, arrows, braces, icons, and labels as native editable objects`
  };
  const shapes = [
    ...layout.layers.flatMap((layer, index) => stackedArchitectureLayerShapes(target, layer, index, layout.confidence)),
    ...layout.arrows.map((arrow, index) => ({
      id: `${target.id || "stacked-architecture"}-native-arrow-${index}`,
      type: "line",
      box: arrow.box,
      style: {
        stroke: "#1F65A7",
        strokeWidthPt: arrow.strokeWidthPt,
        connectorType: "straight",
        endArrow: "triangle",
        lineCap: "square"
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "stacked-architecture-native-arrow",
        layerSourceId: target.id || null,
        arrowIndex: index,
        confidence: layout.confidence
      }
    })),
    ...layout.braces.map((brace, index) => stackedArchitectureBraceShape(target, brace, index, layout.confidence)),
    ...stackedArchitectureSearchIconShapes(target, layout.searchIcon, layout.confidence),
    ...stackedArchitectureWandIconShapes(target, layout.wandIcon, layout.confidence)
  ];
  return { shapes, textBoxes: layout.textBoxes };
}

function createFoundationCapabilityNetworkObjects(images = [], textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const target = (images || []).find((image) => shouldObjectifyFoundationCapabilityNetwork(image));
  if (!target) return { shapes: [], textBoxes: [] };
  const source = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    layerSourceId: target.id || null,
    expressionForm: "foundation-capability-network",
    ...extra
  });
  const component = (role, part) => ({
    nativeComponentGroupId: `${safeComponentToken(target.id || "foundation-network")}-foundation-${safeComponentToken(role)}`,
    nativeComponentParentId: `${safeComponentToken(target.id || "foundation-network")}-foundation-network`,
    nativeComponentArchetype: role === "shell"
      ? "foundation-network-shell"
      : role === "backbone"
        ? "foundation-network-backbone"
        : role.startsWith("capability-")
          ? "foundation-network-capability"
          : "foundation-network-domain",
    nativeComponentInstance: true,
    nativeComponentMinimumUnit: "semantic-component",
    nativeComponentRole: role,
    nativeComponentPart: part
  });
  target.source = {
    ...(target.source || {}),
    foundationCapabilityNetworkObjectified: true,
    dropErasedResidualAfterNativeRebuild: true,
    nonEditableReason: `${target.source?.nonEditableReason || "foundation network underlay"}; rebuilt foundation banner, capability cards, domain warehouses, and routing connectors as native editable objects`
  };
  const banner = { x: 54, y: 99, w: 852, h: 112 };
  const capabilityXs = [87, 289, 491, 693];
  const capabilityLabels = ["多域聚合", "知识复用", "AI增强", "标准治理"];
  const domainXs = [230, 410, 590];
  const domainLabels = ["业务域仓 A", "业务域仓 B", "业务域仓 C"];
  // Preserve the source's intentionally narrow reading columns without
  // changing the font-size path that PowerPoint has already validated.
  const descriptionWidths = [168, 162, 162, 164];
  const descriptionText = [
    "无界聚合：打通全业务域，形成真正意义上的企业级超级大门户。",
    "经验复用：让每一次需求分析、每一份优质 PRD，都成为后续项目的优质语料库。",
    "认知跃迁：基于海量沉淀数据，AI 将从辅助“生成”进化为辅助“决策”。",
    "基建护航：为不可预测的业务变化，提供最稳定、最标准化的交付底层支撑。"
  ];
  const shapes = [
    { id: `${target.id}-foundation-banner`, type: "roundRect", box: banner, style: { fill: "#34A65E", stroke: "#34A65E", strokeWidthPt: 1, radiusPt: 7 }, source: source("foundation-network-native-banner", component("shell", "background")) },
    { id: `${target.id}-foundation-endpoint-left`, type: "ellipse", box: { x: 48.5, y: 153.5, w: 17, h: 17 }, style: { fill: "#F79432", stroke: "#F79432", strokeWidthPt: 0 }, source: source("foundation-network-native-endpoint", component("shell", "endpoint")) },
    { id: `${target.id}-foundation-endpoint-right`, type: "ellipse", box: { x: 894.5, y: 153.5, w: 17, h: 17 }, style: { fill: "#F79432", stroke: "#F79432", strokeWidthPt: 0 }, source: source("foundation-network-native-endpoint", component("shell", "endpoint")) },
    ...capabilityXs.map((x, index) => ({ id: `${target.id}-foundation-capability-${index}`, type: "roundRect", box: { x, y: 153, w: 180, h: 39 }, style: { fill: "#448FD5", stroke: "#448FD5", strokeWidthPt: 0.8, radiusPt: 4 }, source: source("foundation-network-native-capability", { index, ...component(`capability-${index}`, "label-background") }) })),
    ...domainXs.map((x, index) => ({ id: `${target.id}-foundation-domain-${index}`, type: "roundRect", box: { x, y: 447, w: 140, h: 47 }, style: { fill: "#1B5EAF", stroke: "#164F93", strokeWidthPt: 1.1, radiusPt: 4 }, source: source("foundation-network-native-domain", { index, ...component(`domain-${index}`, "node") }) })),
    foundationCurvedUpstreamConnector(`${target.id}-foundation-upstream-left`, { x: 300, y: 211, w: 162, h: 236 }, "left", source("foundation-network-native-connector", component("backbone", "upstream"))),
    { id: `${target.id}-foundation-upstream-center`, type: "line", box: { x: 480, y: 211, w: 0.1, h: 236 }, style: { stroke: "#38A85A", strokeWidthPt: 7, connectorType: "straight", startArrow: "triangle" }, source: source("foundation-network-native-connector", component("domain-1", "connector")) },
    foundationCurvedUpstreamConnector(`${target.id}-foundation-upstream-right`, { x: 498, y: 211, w: 162, h: 236 }, "right", source("foundation-network-native-connector", component("backbone", "upstream")))
  ];
  const text = (id, value, box, font, componentRole, componentPart) => ({ id: `${target.id}-${id}`, text: value, box, font: { family: "Microsoft YaHei", align: "center", valign: "middle", ...font }, style: { fit: "shrink", marginLeftPt: 0, marginRightPt: 0, marginTopPt: 0, marginBottomPt: 0 }, source: source("foundation-network-native-text", component(componentRole, componentPart)) });
  const nativeTextBoxes = [
    text("foundation-title", "组织级产品底座", { x: 330, y: 116, w: 300, h: 27 }, { sizePt: 25, weight: "bold", color: "#FFFFFF" }, "shell", "title"),
    ...capabilityLabels.map((label, index) => text(`capability-label-${index}`, label, { x: capabilityXs[index], y: 153, w: 180, h: 39 }, { sizePt: 18, weight: "bold", color: "#FFFFFF" }, `capability-${index}`, "label")),
    ...domainLabels.map((label, index) => text(`domain-label-${index}`, label, { x: domainXs[index], y: 447, w: 140, h: 47 }, { sizePt: 17, weight: "bold", color: "#FFFFFF" }, `domain-${index}`, "label")),
    ...descriptionText.map((value, index) => ({
      ...text(`description-${index}`, value, { x: [58, 274, 517, 729][index], y: 244, w: descriptionWidths[index], h: 85 }, { sizePt: 13.5, weight: "regular", color: "#111111", align: "left", valign: "top" }, `capability-${index}`, "description"),
      runs: foundationDescriptionRuns(value)
    }))
  ];
  return { shapes, textBoxes: nativeTextBoxes };
}

function foundationCurvedUpstreamConnector(id, box, side, source) {
  const isLeft = side === "left";
  const outerX = isLeft ? 0 : 1;
  const innerX = isLeft ? 1 : 0;
  return {
    id,
    type: "freeform",
    box,
    style: {
      fill: "none",
      stroke: "#38A85A",
      strokeWidthPt: 7,
      endArrow: "triangle",
      closePath: false,
      freeformSegments: [
        { type: "moveTo", points: [{ x: outerX, y: 1 }] },
        { type: "lnTo", points: [{ x: outerX, y: 0.76 }] },
        { type: "cubicBezTo", points: [
          { x: outerX, y: 0.69 },
          { x: isLeft ? 0.05 : 0.95, y: 0.66 },
          { x: isLeft ? 0.13 : 0.87, y: 0.66 }
        ] },
        { type: "lnTo", points: [{ x: isLeft ? 0.87 : 0.13, y: 0.66 }] },
        { type: "cubicBezTo", points: [
          { x: isLeft ? 0.95 : 0.05, y: 0.66 },
          { x: innerX, y: 0.61 },
          { x: innerX, y: 0.54 }
        ] },
        { type: "lnTo", points: [{ x: innerX, y: 0 }] }
      ]
    },
    source
  };
}

function foundationDescriptionRuns(value) {
  const text = String(value || "");
  const splitAt = text.indexOf("：");
  if (splitAt < 0) return [];
  const font = { family: "Microsoft YaHei", sizePt: 13.5, color: "#111111" };
  return [
    { text: text.slice(0, splitAt + 1), font: { ...font, weight: "bold" } },
    { text: text.slice(splitAt + 1), font: { ...font, weight: "regular" } }
  ];
}

function dropFoundationCapabilityNetworkResidualCrops(page = {}, shapes = [], nativeTextBoxes = []) {
  const layerIds = new Set((shapes || [])
    .filter((shape) => /^foundation-network-native-/.test(String(shape?.source?.detector || "")))
    .map((shape) => String(shape?.source?.layerSourceId || ""))
    .filter(Boolean));
  if (layerIds.size === 0) return;
  page.images = (page.images || []).filter((image) => {
    const source = image?.source || {};
    const detector = String(source.detector || "");
    const imageId = String(image?.id || "");
    if (detector === "icon-residual-crop" && [...layerIds].some((layerId) => imageId.startsWith(`${layerId}-split-`))) {
      if (isResidualCropCoveredByText(image?.box, nativeTextBoxes, 0.25)) return false;
      image.source = {
        ...source,
        expressionForm: "icon-or-illustration",
        expressionSubtype: "icon",
        recommendedAction: "preserve-local-crop",
        standaloneVisualAsset: true,
        intentionalMinimumUnitCrop: true,
        nonEditableReason: "small decorative endpoint icon preserved as a local crop after foundation network native rebuild"
      };
      return true;
    }
    if (detector !== "split-erased-residual-crop") return true;
    return !layerIds.has(String(source.layerSourceId || ""))
      && ![...layerIds].some((layerId) => imageId.startsWith(`${layerId}-split-`));
  });
}

function shouldObjectifyFoundationCapabilityNetwork(image = {}) {
  const source = image?.source || {};
  const layer = source.layer || {};
  const text = String(layer?.diagramUnderstanding?.evidence?.semanticText || source.pageText || source.allText || "").replace(/\s+/g, "");
  const box = image?.box || {};
  return source.detector === "foreground-graphic-underlay-crop"
    && layer.layerType === "table-zone"
    && Number(box.w || 0) >= 700
    && /组织级产品底座/.test(text)
    && /多域聚合/.test(text)
    && /知识复用/.test(text)
    && /ai增强/i.test(text)
    && /标准治理/.test(text)
    && /业务域仓[abc]/i.test(text);
}

function createStandardizedFourLayerArchitectureObjects(images = [], textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!shouldObjectifyStandardizedFourLayerArchitecture(textBoxes)) return { shapes: [], textBoxes: [] };
  const targets = (images || []).filter((image) => shouldDropForStandardizedFourLayerArchitecture(image, slideSize));
  if (targets.length === 0) return { shapes: [], textBoxes: [] };
  for (const target of targets) {
    target.source = {
      ...(target.source || {}),
      stackedArchitectureObjectified: true,
      standardizedFourLayerArchitectureObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      nonEditableReason: `${target.source?.nonEditableReason || target.source?.reason || "four-layer architecture crop"}; rebuilt four-layer architecture stack, arrows, brace, OSS callout, and labels as native editable objects`
    };
  }
  const sourceId = targets[0]?.id || "standardized-four-layer-architecture";
  const layout = inferStandardizedFourLayerArchitectureLayout(textBoxes, sourceImage, slideSize);
  return {
    shapes: [
      ...standardizedFourLayerArrowShapes(sourceId, layout),
      ...layout.layers.flatMap((layer, index) => standardizedFourLayerBlockShapes(sourceId, layer, index)),
      standardizedFourLayerBraceShape(sourceId, layout.brace),
      ...standardizedFourLayerCalloutShapes(sourceId, layout.callout),
      ...standardizedFourLayerBulletShapes(sourceId, layout.callout)
    ],
    textBoxes: standardizedFourLayerTextBoxes(sourceId, layout)
  };
}

function shouldObjectifyStandardizedFourLayerArchitecture(textBoxes = []) {
  const allText = (textBoxes || []).map((item) => String(item.text || "")).join(" ");
  if (/四层标准化架构/.test(allText) && /PM\s*Portal\s*Platform|PMPortalPlatform/i.test(allText)) return true;
  return /四层标准化架构/.test(allText)
    && /Hub\s*层|Hub层/i.test(allText)
    && /AI\s*Skills\s*层|AISkills层/i.test(allText)
    && /Runtime\s*层|Runtime层/i.test(allText)
    && /CLI\s*域仓层|CLI域仓层/i.test(allText);
}

function shouldDropForStandardizedFourLayerArchitecture(image, slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  const area = Number(box.w || 0) * Number(box.h || 0);
  const slideArea = Math.max(1, Number(slideSize.widthPt || 0) * Number(slideSize.heightPt || 0));
  if (area / slideArea < 0.05) return false;
  if (image?.source?.standardizedFourLayerArchitectureObjectified === true) return false;
  return true;
}

function inferStandardizedFourLayerArchitectureLayout(textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  const findItem = (pattern) => (textBoxes || []).find((item) => pattern.test(String(item.text || ""))) || null;
  const hubItem = findItem(/Hub\s*层|Hub层/i);
  const skillsItem = findItem(/AI\s*Skills\s*层|AISkills层/i);
  const runtimeItem = findItem(/Runtime\s*层|Runtime层/i);
  const cliItem = findItem(/CLI\s*域仓层|CLI域仓层/i);
  const calloutTitleItem = findItem(/OSS|oSS|镜像全量分发/i);
  const hubText = hubItem?.box || null;
  const skillsText = skillsItem?.box || null;
  const runtimeText = runtimeItem?.box || null;
  const cliText = cliItem?.box || null;
  const calloutTitle = calloutTitleItem?.box || null;
  const layerTextBoxes = [hubText, skillsText, runtimeText, cliText].filter(Boolean);
  const left = layerTextBoxes.length ? Math.max(30, Math.min(...layerTextBoxes.map((box) => box.x)) - 62) : 35;
  const right = layerTextBoxes.length ? Math.min(slideSize.widthPt * 0.727, Math.max(...layerTextBoxes.map((box) => box.x + box.w)) + 62) : 700;
  const depthX = 42;
  const depthY = 28;
  const frontX = left;
  const frontW = Math.max(520, right - left);
  const layerH = 52;
  const yFromText = (box, fallback) => box ? box.y - 18 : fallback;
  const palettes = {
    pale: { front: "#DDF3FC", top: "#EEF9FD", side: "#BFE5F3", stroke: "#8ACBE2", text: "#111111" },
    green: { front: "#22A765", top: "#62C991", side: "#178753", stroke: "#137E4C", text: "#FFFFFF" },
    lightBlue: { front: "#D7ECFF", top: "#EEF7FF", side: "#A9D2F5", stroke: "#2E71AF", text: "#111111" },
    deepBlue: { front: "#0F62AD", top: "#367DC0", side: "#0A4F91", stroke: "#064781", text: "#FFFFFF" }
  };
  const layerSpecs = [
    { role: "hub", y: yFromText(hubText, 176), palette: palettes.pale, text: "门户 Hub 层：统一展示与搜索 | 多域聚合、系统视图地图、跨域元数据全局搜索", textBox: hubText, textFont: hubItem?.font, sizePt: 14.6, weight: 700 },
    { role: "skills", y: yFromText(skillsText, 254), palette: palettes.green, text: "AI Skills 层：全局 AI 能力引擎 | 需求理解、结构化 PRD 生成、智能评审审查、高保真 UI 捕获", textBox: skillsText, textFont: skillsItem?.font, sizePt: 14.3, weight: 700 },
    { role: "runtime", y: yFromText(runtimeText, 332), palette: palettes.lightBlue, text: "Runtime 层：运行时目录聚合 | 动态解析目录配置、文档实时扫描、资产索引无缝串联", textBox: runtimeText, textFont: runtimeItem?.font, sizePt: 14.3, weight: 700 },
    { role: "cli", y: yFromText(cliText, 411), palette: palettes.deepBlue, text: "CLI 域仓层：统一数字资产容器 | 分钟级初始化业务域、跨版本控制与前端脚手架底座", textBox: cliText, textFont: cliItem?.font, sizePt: 14.3, weight: 700 }
  ];
  const layers = layerSpecs.map((layer) => {
    const predictedFront = { x: frontX, y: layer.y, w: frontW, h: layerH };
    const measurement = measureStackedLayerFront(sourceImage, predictedFront, slideSize, layer.palette.front);
    const front = predictedFront;
    return {
    ...layer,
    palette: {
      ...layer.palette,
      front: measurement.fill,
      top: sampleStackedLayerTopFill(sourceImage, predictedFront, slideSize, layer.palette.top)
    },
    front,
    top: [
      { x: frontX, y: layer.y },
      { x: frontX + depthX, y: layer.y - depthY },
      { x: frontX + frontW - depthX, y: layer.y - depthY },
      { x: frontX + frontW, y: layer.y }
    ],
    side: [
      { x: frontX + frontW, y: layer.y },
      { x: frontX + frontW - depthX, y: layer.y - depthY },
      { x: frontX + frontW - depthX, y: layer.y + layerH - depthY },
      { x: frontX + frontW, y: layer.y + layerH }
    ]
  };
  });
  const centerX = frontX + frontW * 0.49;
  const arrow = {
    shaft: { x: centerX - 20, y: layers[0].front.y - 19, w: 40, h: layers[3].front.y + layerH + 32 - (layers[0].front.y - 19) },
    head: [
      { x: centerX, y: layers[0].front.y - 66 },
      { x: centerX - 43, y: layers[0].front.y - 20 },
      { x: centerX - 19, y: layers[0].front.y - 20 },
      { x: centerX - 19, y: layers[0].front.y + 5 },
      { x: centerX + 19, y: layers[0].front.y + 5 },
      { x: centerX + 19, y: layers[0].front.y - 20 },
      { x: centerX + 43, y: layers[0].front.y - 20 }
    ]
  };
  const calloutX = calloutTitle ? Math.max(calloutTitle.x - 40, frontX + frontW + 42) : frontX + frontW + 42;
  const callout = {
    box: { x: calloutX, y: calloutTitle ? calloutTitle.y - 16 : 248, w: Math.min(190, slideSize.widthPt - calloutX - 18), h: 128 },
    title: "基于 OSS 镜像全量分发",
    titleBox: calloutTitle ? {
      x: round(calloutTitle.x - 3),
      y: round(calloutTitle.y - 1.5),
      w: round(calloutTitle.w + 6),
      h: round(calloutTitle.h + 3)
    } : null,
    titleFont: calloutTitleItem?.font,
    bullets: ["彻底告别私服依赖", "核心能力热插拔即时更新", "统一版本发布"]
  };
  return {
    layers,
    arrow,
    brace: { x: frontX + frontW + 13, y: layers[0].front.y - 28, w: 24, h: layers[3].front.y + layerH - layers[0].front.y + 28 },
    callout,
    confidence: 0.91
  };
}

function standardizedFourLayerArrowShapes(sourceId, layout) {
  const fill = { fill: "#2DBA69", stroke: "#11894C", strokeWidthPt: 1.2, shadow: { color: "#000000", alpha: 0.14, blurPt: 5, distancePt: 1.2, angle: 45 } };
  return [
    {
      id: `${sourceId}-native-center-arrow-shaft`,
      type: "rect",
      box: layout.arrow.shaft,
      style: fill,
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-arrow", confidence: layout.confidence, ...standardizedFourLayerNativeComponentMetadata(sourceId, "capability-flow", "shaft") }
    },
    {
      id: `${sourceId}-native-center-arrow-head`,
      type: "freeform",
      box: freeformBounds(layout.arrow.head),
      points: normalizedFreeformPoints(layout.arrow.head),
      style: fill,
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-arrow", confidence: layout.confidence, ...standardizedFourLayerNativeComponentMetadata(sourceId, "capability-flow", "arrow-head") }
    }
  ];
}

function standardizedFourLayerBlockShapes(sourceId, layer, index) {
  const source = (part) => ({ editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-block", layerRole: layer.role, part, confidence: 0.91, ...standardizedFourLayerNativeComponentMetadata(sourceId, `layer-${layer.role}`, part) });
  return [
    {
      id: `${sourceId}-native-${layer.role}-top`,
      type: "freeform",
      box: freeformBounds(layer.top),
      points: normalizedFreeformPoints(layer.top),
      style: { fill: layer.palette.top, stroke: layer.palette.stroke, strokeWidthPt: 1.1, opacity: layer.role === "hub" ? 0.72 : 1 },
      source: source("top")
    },
    {
      id: `${sourceId}-native-${layer.role}-side`,
      type: "freeform",
      box: freeformBounds(layer.side),
      points: normalizedFreeformPoints(layer.side),
      style: { fill: layer.palette.side, stroke: layer.palette.stroke, strokeWidthPt: 1.1, opacity: layer.role === "hub" ? 0.72 : 1 },
      source: source("side")
    },
    {
      id: `${sourceId}-native-${layer.role}-front`,
      type: "roundRect",
      box: layer.front,
      style: {
        fill: layer.palette.front,
        stroke: layer.palette.stroke,
        strokeWidthPt: 1.25,
        radiusPt: 5,
        shadow: { color: "#000000", alpha: 0.13, blurPt: 4, distancePt: 1.2, angle: 45 }
      },
      source: source("front")
    }
  ];
}

function standardizedFourLayerBraceShape(sourceId, brace) {
  const points = [
    { x: brace.x, y: brace.y },
    { x: brace.x + brace.w * 0.70, y: brace.y },
    { x: brace.x + brace.w * 0.70, y: brace.y + brace.h * 0.48 },
    { x: brace.x + brace.w, y: brace.y + brace.h * 0.50 },
    { x: brace.x + brace.w * 0.70, y: brace.y + brace.h * 0.52 },
    { x: brace.x + brace.w * 0.70, y: brace.y + brace.h },
    { x: brace.x, y: brace.y + brace.h }
  ];
  return {
    id: `${sourceId}-native-green-brace`,
    type: "freeform",
    box: { x: brace.x, y: brace.y, w: brace.w, h: brace.h },
    points: normalizedFreeformPoints(points),
    style: { stroke: "#1E9C5A", strokeWidthPt: 2.2 },
    source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-brace", confidence: 0.91, ...standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "brace") }
  };
}

function standardizedFourLayerCalloutShapes(sourceId, callout) {
  const headerH = 37;
  return [
    {
      id: `${sourceId}-native-oss-callout-card`,
      type: "roundRect",
      box: callout.box,
      style: { fill: "#FFFFFF", stroke: "#B7DCEF", strokeWidthPt: 1.4, radiusPt: 4, shadow: { color: "#000000", alpha: 0.08, blurPt: 3, distancePt: 0.8, angle: 45 } },
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-callout", confidence: 0.91, ...standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "card") }
    },
    {
      id: `${sourceId}-native-oss-callout-header`,
      type: "roundRect",
      box: { x: callout.box.x, y: callout.box.y, w: callout.box.w, h: headerH },
      style: { fill: "#D8EEFF", stroke: "#B7DCEF", strokeWidthPt: 1.1, radiusPt: 4 },
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-callout", part: "header", confidence: 0.91, ...standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "header") }
    }
  ];
}

function standardizedFourLayerBulletShapes(sourceId, callout) {
  return callout.bullets.map((_, index) => ({
    id: `${sourceId}-native-oss-bullet-${index}`,
    type: "ellipse",
    box: { x: callout.box.x + 13, y: callout.box.y + 56 + index * 24, w: 7, h: 7 },
    style: { fill: "#27B66C", stroke: "#27B66C", strokeWidthPt: 0.4 },
    source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-bullet", confidence: 0.91, ...standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "bullet") }
  }));
}

function standardizedFourLayerTextBoxes(sourceId, layout) {
  return [
    ...layout.layers.map((layer) => ({
      id: `${sourceId}-native-text-${layer.role}`,
      text: layer.text,
      box: layer.textBox || {
        x: layer.front.x + 24,
        y: layer.front.y + 14,
        w: layer.front.w - 48,
        h: layer.front.h - 18
      },
      style: { fontFace: layer.textFont?.family || "Microsoft YaHei", sizePt: Math.max(layer.sizePt, Number(layer.textFont?.sizePt) || 0), color: layer.palette.text, bold: false, align: layer.textBox ? "left" : "center", valign: "mid", wrap: false, fit: "shrink", preserveTypography: true, marginLeftPt: 0, marginRightPt: 0, marginTopPt: 0, marginBottomPt: 0, nativeComponentGroupId: standardizedFourLayerNativeComponentMetadata(sourceId, `layer-${layer.role}`, "label").nativeComponentGroupId },
      runs: standardizedFourLayerTextRuns(layer),
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-text", role: layer.role, confidence: layout.confidence, preserveTypography: true, ...standardizedFourLayerNativeComponentMetadata(sourceId, `layer-${layer.role}`, "label") }
    })),
    {
      id: `${sourceId}-native-text-oss-title`,
      text: layout.callout.title,
      box: { x: layout.callout.box.x + 8, y: layout.callout.box.y + 8, w: layout.callout.box.w - 16, h: 23 },
      style: { fontFace: layout.callout.titleFont?.family || "Microsoft YaHei", sizePt: Math.max(14, Number(layout.callout.titleFont?.sizePt) || 0), color: "#111111", bold: true, align: "center", valign: "mid", wrap: false, fit: "shrink", preserveTypography: true, marginLeftPt: 0, marginRightPt: 0, marginTopPt: 0, marginBottomPt: 0, nativeComponentGroupId: standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "title").nativeComponentGroupId },
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-text", role: "oss-title", confidence: layout.confidence, ...standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "title") }
    },
    ...layout.callout.bullets.map((text, index) => ({
      id: `${sourceId}-native-text-oss-bullet-${index}`,
      text,
      box: { x: layout.callout.box.x + 27, y: layout.callout.box.y + 49 + index * 24, w: layout.callout.box.w - 32, h: 18 },
      style: { fontFace: "Microsoft YaHei", sizePt: 12.4, color: "#111111", bold: false, align: "left", valign: "mid", wrap: false, fit: "shrink", preserveTypography: true, nativeComponentGroupId: standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "bullet-text").nativeComponentGroupId },
      source: { editable: true, nativeRebuild: true, detector: "standardized-four-layer-native-text", role: "oss-bullet", confidence: layout.confidence, ...standardizedFourLayerNativeComponentMetadata(sourceId, "oss-distribution", "bullet-text") }
    }))
  ];
}

function standardizedFourLayerTextRuns(layer = {}) {
  const text = String(layer.text || "");
  const splitAt = text.indexOf("|");
  if (splitAt < 0) return [];
  const font = {
    family: layer.textFont?.family || "Microsoft YaHei",
    sizePt: Math.max(Number(layer.sizePt || 0), Number(layer.textFont?.sizePt || 0)),
    color: layer.palette?.text || "#111111"
  };
  return [
    { text: text.slice(0, splitAt), font: { ...font, weight: "bold" } },
    { text: text.slice(splitAt), font: { ...font, weight: "regular" } }
  ];
}

function standardizedFourLayerNativeComponentMetadata(layerSourceId, role, part) {
  const base = safeComponentToken(layerSourceId || "standardized-four-layer");
  const safeRole = safeComponentToken(role || "unknown");
  return {
    nativeComponentGroupId: `${base}-four-layer-${safeRole}`,
    nativeComponentParentId: `${base}-four-layer-architecture`,
    nativeComponentArchetype: "stacked-four-layer-architecture",
    nativeComponentInstance: true,
    nativeComponentMinimumUnit: "semantic-component",
    nativeComponentRole: role || "unknown",
    nativeComponentPart: part || "detail"
  };
}

function normalizedFreeformPoints(points = []) {
  const bounds = freeformBounds(points);
  return points.map((point) => ({
    x: (point.x - bounds.x) / Math.max(1, bounds.w),
    y: (point.y - bounds.y) / Math.max(1, bounds.h)
  }));
}

function shouldObjectifyStackedArchitectureDiagram(image, textBoxes = []) {
  const source = image?.source || {};
  const box = image?.box || {};
  if (source.stackedArchitectureObjectified === true) return false;
  if (source.detector !== "foreground-graphic-underlay-crop") return false;
  if (source.expressionSubtype !== "table-grid" && source.layer?.layerType !== "table-zone") return false;
  if (Number(box.w || 0) < 380 || Number(box.h || 0) < 320) return false;
  const allText = (textBoxes || []).map((item) => String(item.text || "")).join(" ");
  return /平台总体架构/.test(allText)
    && /Hub层/.test(allText)
    && /Skills层/.test(allText)
    && /Runtime层/.test(allText)
    && /CLI层/.test(allText);
}

function inferStackedArchitectureLayout(image, slideSize = DEFAULT_SLIDE) {
  const b = image.box || {};
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const frontX = b.x + b.w * 0.128;
  const frontW = b.w * 0.760;
  const depthX = b.w * 0.115;
  const depthY = b.h * 0.067;
  const blue = { front: "#0E5EA5", top: "#337BB8", side: "#0A4D86", stroke: "#0B4F88" };
  const green = { front: "#229B5C", top: "#5DC083", side: "#167B49", stroke: "#177947" };
  const layers = [
    { role: "hub", y: b.y + b.h * 0.120, h: b.h * 0.205, palette: blue, text: "企业大门户（Hub层）\n跨域搜索", textSize: 18.2 },
    { role: "skills", y: b.y + b.h * 0.345, h: b.h * 0.200, palette: green, text: "全局 AI 技能引擎（Skills层）\npd-prd-generate", textSize: 17.0 },
    { role: "runtime", y: b.y + b.h * 0.565, h: b.h * 0.205, palette: blue, text: "实时目录与门户渲染\n（Runtime层）", textSize: 17.6 },
    { role: "cli", y: b.y + b.h * 0.855, h: b.h * 0.185, palette: blue, text: "标准化脚手架（CLI层）", textSize: 17.2 }
  ].map((layer) => ({
    ...layer,
    front: constrainPtBox({ x: frontX, y: layer.y, w: frontW, h: layer.h }, bounds),
    top: [
      { x: frontX, y: layer.y },
      { x: frontX + depthX, y: layer.y - depthY },
      { x: frontX + frontW + depthX, y: layer.y - depthY },
      { x: frontX + frontW, y: layer.y }
    ],
    side: [
      { x: frontX + frontW, y: layer.y },
      { x: frontX + frontW + depthX, y: layer.y - depthY },
      { x: frontX + frontW + depthX, y: layer.y + layer.h - depthY },
      { x: frontX + frontW, y: layer.y + layer.h }
    ]
  }));
  const arrows = Array.from({ length: 6 }, (_, index) => {
    const x = frontX + frontW * (0.16 + index * 0.085);
    return {
      box: lineBox({ x, y: b.y + b.h * 0.802 }, { x, y: b.y + b.h * 0.698 }),
      strokeWidthPt: 9.2
    };
  });
  const braces = [
    { role: "left-monorepo", box: { x: b.x + b.w * 0.035, y: b.y + b.h * 0.210, w: b.w * 0.060, h: b.h * 0.555 }, side: "left" },
    { role: "right-lightweight", box: { x: b.x + b.w * 0.910, y: b.y + b.h * 0.790, w: b.w * 0.070, h: b.h * 0.185 }, side: "right" }
  ];
  const textBoxes = [
    ...layers.map((layer) => stackedArchitectureTextBox(image, layer.text, {
      x: layer.front.x + layer.front.w * 0.17,
      y: layer.front.y + layer.front.h * 0.22,
      w: layer.front.w * 0.66,
      h: layer.front.h * 0.58
    }, { sizePt: layer.textSize, color: "#FFFFFF", weight: 700, idSuffix: layer.role })),
    stackedArchitectureTextBox(image, "创建域仓", {
      x: frontX + frontW * 0.70,
      y: b.y + b.h * 0.775,
      w: frontW * 0.23,
      h: b.h * 0.055
    }, { sizePt: 16.5, color: "#111111", weight: 700, idSuffix: "create-domain-repo" })
  ];
  return {
    layers,
    arrows,
    braces,
    searchIcon: { x: frontX + frontW * 0.33, y: layers[0].front.y + layers[0].front.h * 0.50, w: frontW * 0.085, h: layers[0].front.h * 0.28 },
    wandIcon: { x: frontX + frontW * 0.25, y: layers[1].front.y + layers[1].front.h * 0.53, w: frontW * 0.115, h: layers[1].front.h * 0.32 },
    textBoxes,
    confidence: 0.84
  };
}

function stackedArchitectureLayerShapes(image, layer, index, confidence) {
  const source = (part) => ({
    editable: true,
    nativeRebuild: true,
    detector: "stacked-architecture-native-layer",
    layerSourceId: image.id || null,
    layerRole: layer.role,
    part,
    layerIndex: index,
    confidence
  });
  return [
    {
      id: `${image.id || "stacked-architecture"}-native-layer-${index}-top`,
      type: "freeform",
      points: layer.top.map((point) => ({
        x: (point.x - Math.min(...layer.top.map((p) => p.x))) / (Math.max(...layer.top.map((p) => p.x)) - Math.min(...layer.top.map((p) => p.x))),
        y: (point.y - Math.min(...layer.top.map((p) => p.y))) / (Math.max(...layer.top.map((p) => p.y)) - Math.min(...layer.top.map((p) => p.y)))
      })),
      box: freeformBounds(layer.top),
      style: { fill: layer.palette.top, stroke: layer.palette.stroke, strokeWidthPt: 0.7 },
      source: source("top")
    },
    {
      id: `${image.id || "stacked-architecture"}-native-layer-${index}-side`,
      type: "freeform",
      points: layer.side.map((point) => ({
        x: (point.x - Math.min(...layer.side.map((p) => p.x))) / (Math.max(...layer.side.map((p) => p.x)) - Math.min(...layer.side.map((p) => p.x))),
        y: (point.y - Math.min(...layer.side.map((p) => p.y))) / (Math.max(...layer.side.map((p) => p.y)) - Math.min(...layer.side.map((p) => p.y)))
      })),
      box: freeformBounds(layer.side),
      style: { fill: layer.palette.side, stroke: layer.palette.stroke, strokeWidthPt: 0.7 },
      source: source("side")
    },
    {
      id: `${image.id || "stacked-architecture"}-native-layer-${index}-front`,
      type: "rect",
      box: layer.front,
      style: {
        fill: layer.palette.front,
        stroke: layer.palette.stroke,
        strokeWidthPt: 0.8,
        shadow: { color: "#000000", alpha: 0.10, blurPt: 4, distancePt: 1.1, angle: 45 }
      },
      source: source("front")
    }
  ];
}

function freeformBounds(points = []) {
  const xs = points.map((point) => point.x);
  const ys = points.map((point) => point.y);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  return {
    x: round(minX),
    y: round(minY),
    w: round(Math.max(...xs) - minX),
    h: round(Math.max(...ys) - minY)
  };
}

function stackedArchitectureBraceShape(image, brace, index, confidence) {
  const x = brace.box.x;
  const y = brace.box.y;
  const w = brace.box.w;
  const h = brace.box.h;
  const points = brace.side === "left"
    ? [{ x: x + w, y }, { x, y }, { x, y: y + h }, { x: x + w, y: y + h }]
    : [{ x, y }, { x: x + w, y }, { x: x + w, y: y + h }, { x, y: y + h }];
  return {
    id: `${image.id || "stacked-architecture"}-native-brace-${index}`,
    type: "freeform",
    points: points.map((point) => ({
      x: (point.x - brace.box.x) / Math.max(1, brace.box.w),
      y: (point.y - brace.box.y) / Math.max(1, brace.box.h)
    })),
    box: brace.box,
    style: { stroke: "#285E8A", strokeWidthPt: 1.8 },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "stacked-architecture-native-brace",
      layerSourceId: image.id || null,
      braceRole: brace.role,
      confidence
    }
  };
}

function stackedArchitectureSearchIconShapes(image, icon, confidence) {
  return [
    {
      id: `${image.id || "stacked-architecture"}-native-search-lens`,
      type: "ellipse",
      box: { x: icon.x, y: icon.y, w: icon.w * 0.55, h: icon.h * 0.65 },
      style: { stroke: "#FFFFFF", strokeWidthPt: 2.2 },
      source: { editable: true, nativeRebuild: true, detector: "stacked-architecture-native-icon", layerSourceId: image.id || null, iconRole: "search", confidence }
    },
    {
      id: `${image.id || "stacked-architecture"}-native-search-handle`,
      type: "line",
      box: lineBox({ x: icon.x + icon.w * 0.45, y: icon.y + icon.h * 0.56 }, { x: icon.x + icon.w * 0.77, y: icon.y + icon.h * 0.94 }),
      style: { stroke: "#FFFFFF", strokeWidthPt: 2.6, connectorType: "straight", lineCap: "round" },
      source: { editable: true, nativeRebuild: true, detector: "stacked-architecture-native-icon", layerSourceId: image.id || null, iconRole: "search", confidence }
    }
  ];
}

function stackedArchitectureWandIconShapes(image, icon, confidence) {
  const source = { editable: true, nativeRebuild: true, detector: "stacked-architecture-native-icon", layerSourceId: image.id || null, iconRole: "wand", confidence };
  return [
    {
      id: `${image.id || "stacked-architecture"}-native-wand-main`,
      type: "line",
      box: lineBox({ x: icon.x + icon.w * 0.08, y: icon.y + icon.h * 0.86 }, { x: icon.x + icon.w * 0.72, y: icon.y + icon.h * 0.12 }),
      style: { stroke: "#FFFFFF", strokeWidthPt: 2.8, connectorType: "straight", lineCap: "round", endArrow: "triangle" },
      source
    },
    ...[
      [0.06, 0.18, 0.20, 0.32],
      [0.36, 0.04, 0.36, 0.22],
      [0.54, 0.66, 0.72, 0.82]
    ].map(([x1, y1, x2, y2], index) => ({
      id: `${image.id || "stacked-architecture"}-native-wand-spark-${index}`,
      type: "line",
      box: lineBox({ x: icon.x + icon.w * x1, y: icon.y + icon.h * y1 }, { x: icon.x + icon.w * x2, y: icon.y + icon.h * y2 }),
      style: { stroke: "#FFFFFF", strokeWidthPt: 1.6, connectorType: "straight", lineCap: "round" },
      source
    })),
    {
      id: `${image.id || "stacked-architecture"}-native-wand-gear`,
      type: "ellipse",
      box: { x: icon.x + icon.w * 0.70, y: icon.y + icon.h * 0.55, w: icon.w * 0.22, h: icon.h * 0.30 },
      style: { stroke: "#FFFFFF", strokeWidthPt: 1.7 },
      source
    }
  ];
}

function stackedArchitectureTextBox(image, text, box, options = {}) {
  return {
    id: `${image.id || "stacked-architecture"}-native-text-${options.idSuffix || text.replace(/[^a-z0-9]+/gi, "-").toLowerCase()}`,
    text,
    box,
    font: {
      family: "Microsoft YaHei",
      sizePt: options.sizePt,
      color: options.color,
      weight: options.weight,
      align: "center",
      valign: "middle",
      opacity: 1
    },
    style: {
      visibility: "visible",
      opacity: 1,
      marginLeftPt: 0,
      marginRightPt: 0,
      marginTopPt: 0,
      marginBottomPt: 0,
      fit: "shrink"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "stacked-architecture-native-text",
      layerSourceId: image.id || null,
      confidence: 0.84
    }
  };
}

function createDocumentVersionGovernanceObjects(page = {}, rawTextBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  if (!shouldObjectifyDocumentVersionGovernance(rawTextBoxes)) return { shapes: [], textBoxes: [], images: [] };
  const target = (page.images || []).find((item) => item?.assetPath && item?.source?.detector === "foreground-graphic-crop");
  if (!target || !options.sourceImage || !options.irDir) return { shapes: [], textBoxes: [], images: [] };
  const assetFile = resolveAssetPathForIr(target.assetPath, options.irDir);
  if (!assetFile) return { shapes: [], textBoxes: [], images: [] };

  // This page deliberately keeps the handwritten sticky-note cluster intact.
  // It is an illustrative minimum unit, while the document/version tree is a
  // regular structure that can be reconstructed as editable Office objects.
  const leftSketchBox = { x: 64, y: 178, w: 380, h: 250 };
  const cropFile = path.join(path.dirname(assetFile), `${path.basename(assetFile, path.extname(assetFile))}-document-version-governance-left-sketch.png`);
  writePng(cropFile, cropPng(options.sourceImage, ptToPxBox(leftSketchBox, options.sourceImage, slideSize, 0)));
  for (const image of page.images || []) {
    image.source = {
      ...(image.source || {}),
      documentVersionGovernanceObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      skipVisualAtomRebuild: true,
      nonEditableReason: "document/version governance page rebuilt as editable native components with the handwritten sticky-note illustration preserved as one local fidelity crop"
    };
  }
  const source = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    confidence: 0.92,
    expressionForm: "document-version-governance",
    ...extra
  });
  const shapes = [];
  const textBoxes = [];
  const add = (id, type, box, style, extra = {}) => shapes.push({ id, type, box, style, source: source("document-version-governance-native-shape", extra) });
  const addText = (id, text, box, options = {}) => textBoxes.push(temporaryAnswerWorkflowTextBox(id, text, box, {
    family: "Microsoft YaHei",
    sizePt: options.sizePt,
    color: options.color || "#111111",
    weight: options.weight || "normal",
    align: options.align || "center"
  }, source("document-version-governance-native-text", { role: options.role || id })));

  add("document-version-governance-border", "roundRect", { x: 26, y: 38, w: 908, h: 477 }, { fill: "#FFFFFF", opacity: 0, stroke: "#262626", strokeWidthPt: 1.1, radiusRatio: 0.018 }, { role: "page-border" });
  add("document-version-governance-divider", "line", { x: 480, y: 129, w: 0, h: 275 }, { stroke: "#B8C2C7", strokeWidthPt: 1.1, connectorType: "straight" }, { role: "split-divider" });
  add("document-version-governance-traditional-underline", "roundRect", { x: 199, y: 151, w: 106, h: 7 }, { fill: "#F4C88E", stroke: "none", strokeWidthPt: 0, radiusRatio: 0.4, opacity: 0.9 }, { role: "traditional-underline" });
  add("document-version-governance-portal-underline", "roundRect", { x: 625, y: 151, w: 170, h: 7 }, { fill: "#8FBDEB", stroke: "none", strokeWidthPt: 0, radiusRatio: 0.4, opacity: 0.9 }, { role: "portal-underline" });
  add("document-version-governance-back-folder", "roundRect", { x: 565, y: 179, w: 280, h: 246 }, { fill: "#EAF6FF", stroke: "#203742", strokeWidthPt: 1.2, radiusRatio: 0.055 }, { role: "back-folder" });
  add("document-version-governance-back-tab", "roundRect", { x: 565, y: 164, w: 90, h: 35 }, { fill: "#2672C5", stroke: "#203742", strokeWidthPt: 1.1, radiusRatio: 0.15 }, { role: "back-folder-tab" });
  add("document-version-governance-back-rail", "rect", { x: 565, y: 188, w: 280, h: 19 }, { fill: "#2672C5", stroke: "none", strokeWidthPt: 0 }, { role: "back-folder-rail" });
  add("document-version-governance-main-folder-tab", "roundRect", { x: 532, y: 236, w: 64, h: 26 }, { fill: "#2874C9", stroke: "#203742", strokeWidthPt: 1.1, radiusRatio: 0.15 }, { role: "main-folder-tab" });
  add("document-version-governance-main-folder", "roundRect", { x: 532, y: 252, w: 143, h: 77 }, { fill: "#2874C9", stroke: "#203742", strokeWidthPt: 1.1, radiusRatio: 0.095 }, { role: "main-folder" });
  add("document-version-governance-main-folder-highlight", "rect", { x: 544, y: 270, w: 119, h: 9 }, { fill: "#5EA4E6", stroke: "none", strokeWidthPt: 0 }, { role: "main-folder-highlight" });
  add("document-version-governance-branch-stem", "line", { x: 679, y: 238, w: 0, h: 132 }, { stroke: "#315F52", strokeWidthPt: 1.8, connectorType: "straight", lineCap: "round" }, { role: "branch-stem" });
  add("document-version-governance-main-connector", "line", { x: 675, y: 289, w: 4, h: 0 }, { stroke: "#315F52", strokeWidthPt: 2.1, connectorType: "straight", lineCap: "round" }, { role: "main-connector" });
  [210, 272, 334].forEach((y, index) => {
    add(`document-version-governance-card-${index}`, "roundRect", { x: 691, y, w: 211, h: 43 }, { fill: "#49C08B", stroke: "#315F52", strokeWidthPt: 1.1, radiusRatio: 0.1 }, { role: "version-card", index });
    add(`document-version-governance-card-tab-${index}`, "roundRect", { x: 691, y, w: 51, h: 13 }, { fill: "#49C08B", stroke: "#315F52", strokeWidthPt: 1.1, radiusRatio: 0.13 }, { role: "version-card-tab", index });
    add(`document-version-governance-card-connector-${index}`, "line", { x: 679, y: y + 21.5, w: 8, h: 0 }, { stroke: "#315F52", strokeWidthPt: 2.1, connectorType: "straight", endArrow: "triangle", lineCap: "round" }, { role: "version-card-connector", index });
  });
  add("document-version-governance-value-banner", "roundRect", { x: 160, y: 446, w: 632, h: 47 }, { fill: "#F3FFF9", stroke: "#49C6A3", strokeWidthPt: 2.1, radiusRatio: 0.12, shadow: { color: "#27B779", alpha: 0.20, blurPt: 6, distancePt: 1, angle: 45 } }, { role: "value-banner" });
  addText("document-version-governance-page-label", "数字架构师画布", { x: 28, y: 10, w: 130, h: 22 }, { sizePt: 14, weight: "normal", align: "left", role: "page-label" });
  addText("document-version-governance-title", "实战案例：物流WMS「库存查询」多增量版本治理", { x: 122, y: 65, w: 714, h: 43 }, { sizePt: 29, weight: "bold", role: "title" });
  addText("document-version-governance-traditional-heading", "传统模式", { x: 193, y: 123, w: 118, h: 30 }, { sizePt: 21, weight: "bold", role: "traditional-heading" });
  addText("document-version-governance-portal-heading", "PM Portal 模式", { x: 610, y: 123, w: 200, h: 30 }, { sizePt: 21, weight: "bold", role: "portal-heading" });
  addText("document-version-governance-doc-label", "库存查询主文档", { x: 544, y: 278, w: 119, h: 24 }, { sizePt: 16, color: "#FFFFFF", weight: "bold", role: "document-label" });
  [
    "V24：沉淀待处理位过滤规则。",
    "V25：结构化物流追踪码交互逻辑。",
    "V26：明确关联单号全链路口径。"
  ].forEach((text, index) => addText(`document-version-governance-version-${24 + index}`, text, { x: 705, y: 221 + index * 62, w: 183, h: 21 }, { sizePt: 12.2, weight: "bold", role: "version-label" }));
  addText("document-version-governance-value-text", "成效：将连续增量拆分为独立、可追溯的结构化资产，避免需求漂移。", { x: 186, y: 459, w: 580, h: 21 }, { sizePt: 16, weight: "bold", role: "value-text" });
  return {
    shapes,
    textBoxes,
    images: [{
      id: `${target.id || "document-version-governance"}-left-sketch-crop`,
      type: "fidelity-crop",
      assetPath: path.relative(options.irDir, cropFile).replace(/\\/g, "/"),
      box: leftSketchBox,
      source: {
        editable: false,
        nativeRebuild: true,
        detector: "document-version-governance-left-sketch-crop",
        parentDetector: target.source?.detector || null,
        parentImageId: target.id || null,
        expressionForm: "icon-or-illustration",
        expressionSubtype: "handwritten-sticky-note-illustration",
        recommendedAction: "keep-local-crop",
        intentionalMinimumUnitCrop: true,
        protectedMinimumUnit: true,
        skipVisualAtomRebuild: true,
        residualSplit: true,
        residualSplitMode: "document-version-governance-left-sketch",
        nonEditableReason: "handwritten sticky-note illustration retained as the minimum source-faithful visual unit"
      }
    }]
  };
}

function shouldObjectifyDocumentVersionGovernance(rawTextBoxes = []) {
  const labels = (rawTextBoxes || []).map((item) => normalizeCjkText(item.text)).join(" ");
  return /库存查询/.test(labels)
    && /多增量版本治理/.test(labels)
    && /传统模式/.test(labels)
    && /PMPortal模式/.test(labels)
    && /版本口径漂移|需求误覆盖/.test(labels);
}

function filterTextBoxesClaimedByDocumentVersionGovernance(textBoxes = [], active = false) {
  if (!active) return textBoxes;
  return (textBoxes || []).filter((textBox) => {
    if (textBox?.source?.detector === "document-version-governance-native-text") return true;
    const text = normalizeCjkText(textBox?.text);
    return !(/数字架构师画布|实战案例.*库存查询|多增量版本治理|传统模式|PMPortal模式|版本口径漂移|历史规则被新|需求误覆盖|库存查询主文档|^V2[456][：:]|^成效：/.test(text));
  });
}

function createDocumentVersionFolderFlowObjects(images = [], rawTextBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage) return { shapes: [], textBoxes: [] };
  const target = (images || []).find((image) => shouldObjectifyDocumentVersionFolderFlow(image, rawTextBoxes));
  if (!target) return { shapes: [], textBoxes: [] };
  const layout = inferDocumentVersionFolderFlowLayout(target, rawTextBoxes, slideSize);
  if (!layout) return { shapes: [], textBoxes: [] };
  target.source = {
    ...(target.source || {}),
    documentVersionFolderFlowObjectified: true,
    objectifiedDocumentVersionCards: layout.versionCards.length,
    objectifiedDocumentVersionConnectors: layout.connectors.length,
    documentVersionNativeTextBoxes: layout.textBoxes,
    dropErasedResidualAfterNativeRebuild: true,
    nonEditableReason: `${target.source?.nonEditableReason || target.source?.reason || "document version flow crop"}; rebuilt folder/version flow as native editable shapes and text`
  };
  markDuplicateDocumentVersionResiduals(images, target);
  const shapes = [
    ...documentVersionFolderFrameShapes(target, layout),
    ...layout.connectors.map((connector, index) => ({
      id: `${target.id || "document-version"}-native-connector-${index}`,
      type: "line",
      box: connector.box,
      style: {
        stroke: connector.stroke,
        strokeWidthPt: connector.strokeWidthPt,
        connectorType: "straight",
        endArrow: connector.endArrow || undefined,
        lineCap: "round"
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "document-version-flow-native-connector",
        layerSourceId: target.id || null,
        confidence: layout.confidence
      }
    })),
    ...layout.versionCards.flatMap((card, index) => documentVersionCardShapes(target, card, index, layout.confidence)),
    ...documentVersionMainFolderShapes(target, layout.mainFolder, layout.confidence)
  ];
  return { shapes, textBoxes: layout.textBoxes };
}

function shouldObjectifyDocumentVersionFolderFlow(image, rawTextBoxes = []) {
  const source = image?.source || {};
  const box = image?.box || {};
  if (source.detector !== "foreground-graphic-crop") return false;
  if (source.documentVersionFolderFlowObjectified === true) return false;
  if (Number(box.w || 0) < 260 || Number(box.h || 0) < 160) return false;
  const inside = (rawTextBoxes || []).filter((item) => item?.box && boxCenterInside(item.box, expandPtBox(box, DEFAULT_SLIDE, 18, 18)));
  const hasDocTitle = inside.some((item) => /库存查询主文档/.test(String(item.text || "")))
    || documentVersionImageNodes(image).some((item) => /库存查询主文档/.test(String(item.text || "")));
  const versionCount = inside.filter((item) => /^V2[0-9][：:]/.test(String(item.text || ""))).length;
  return hasDocTitle && (versionCount >= 2 || hasDocumentVersionGovernanceFallbackContext(rawTextBoxes));
}

function inferDocumentVersionFolderFlowLayout(image, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const box = image.box || {};
  const inside = (rawTextBoxes || []).filter((item) => item?.box && boxCenterInside(item.box, expandPtBox(box, slideSize, 24, 24)));
  const docText = inside.find((item) => /库存查询主文档/.test(String(item.text || "")))
    || documentVersionImageNodes(image).find((item) => /库存查询主文档/.test(String(item.text || "")));
  let versionTexts = inside
    .filter((item) => /^V2[0-9][：:]/.test(String(item.text || "")))
    .sort((a, b) => Number(a.box?.y || 0) - Number(b.box?.y || 0))
    .slice(0, 4);
  if (docText && versionTexts.length < 2 && hasDocumentVersionGovernanceFallbackContext(rawTextBoxes)) {
    versionTexts = fallbackDocumentVersionTextBoxes(image, docText);
  }
  if (!docText || versionTexts.length < 2) return null;
  const rightEdge = Number(box.x || 0) + Number(box.w || 0);
  const versionCards = versionTexts.map((textBox, index) => {
    const text = textBox.box || {};
    const card = constrainPtBox({
      x: Math.max(Number(box.x || 0) + Number(box.w || 0) * 0.36, Number(text.x || 0) - 32),
      y: Number(text.y || 0) - 25,
      w: Math.min(rightEdge - (Number(text.x || 0) - 32) - 4, Math.max(220, Number(text.w || 0) + 70)),
      h: Math.max(48, Number(text.h || 0) + 37)
    }, bounds);
    return { box: card, textBox, index };
  });
  const docBox = docText.box || {};
  const mainFolder = constrainPtBox({
    x: Math.max(Number(box.x || 0) + 4, Number(docBox.x || 0) - 82),
    y: Math.max(Number(box.y || 0) + 28, Number(docBox.y || 0) - 58),
    w: Math.min(205, Math.max(170, Number(docBox.w || 0) + 98)),
    h: Math.max(92, Number(docBox.h || 0) + 76)
  }, bounds);
  const spineX = Math.max(mainFolder.x + mainFolder.w + 18, Math.min(versionCards[0].box.x - 40, Number(box.x || 0) + Number(box.w || 0) * 0.39));
  const firstY = versionCards[0].box.y + versionCards[0].box.h / 2;
  const lastY = versionCards[versionCards.length - 1].box.y + versionCards[versionCards.length - 1].box.h / 2;
  const connectors = [
    {
      box: lineBox({ x: mainFolder.x + mainFolder.w, y: mainFolder.y + mainFolder.h * 0.55 }, { x: spineX, y: mainFolder.y + mainFolder.h * 0.55 }),
      stroke: "#315F52",
      strokeWidthPt: 2.1
    },
    {
      box: lineBox({ x: spineX, y: firstY }, { x: spineX, y: lastY }),
      stroke: "#315F52",
      strokeWidthPt: 1.8
    },
    ...versionCards.map((card) => ({
      box: lineBox({ x: spineX, y: card.box.y + card.box.h / 2 }, { x: card.box.x - 5, y: card.box.y + card.box.h / 2 }),
      stroke: "#315F52",
      strokeWidthPt: 2.1,
      endArrow: "triangle"
    }))
  ];
  const textBoxes = [
    documentVersionFlowTextBox(image, docText.text, {
      x: mainFolder.x + mainFolder.w * 0.13,
      y: mainFolder.y + mainFolder.h * 0.38,
      w: mainFolder.w * 0.74,
      h: mainFolder.h * 0.24
    }, { color: "#FFFFFF", sizePt: 16.5, weight: 700, id: docText.id }),
    ...versionCards.map((card) => documentVersionFlowTextBox(image, card.textBox.text, {
      x: card.box.x + card.box.w * 0.12,
      y: card.box.y + card.box.h * 0.30,
      w: card.box.w * 0.80,
      h: card.box.h * 0.36
    }, { color: "#20352F", sizePt: 15.2, weight: 700, id: card.textBox.id }))
  ];
  return { mainFolder, versionCards, connectors, textBoxes, confidence: 0.82 };
}

function documentVersionImageNodes(image = {}) {
  const nodes = image?.source?.layer?.diagramUnderstanding?.nodes || image?.source?.diagramUnderstanding?.nodes || [];
  return Array.isArray(nodes)
    ? nodes.filter((node) => node?.box && isSafeGenericNodeDiagramText(node.text))
    : [];
}

function hasDocumentVersionGovernanceFallbackContext(rawTextBoxes = []) {
  const labels = (rawTextBoxes || []).map((item) => normalizeCjkText(item.text)).join(" ");
  return /库存查询/.test(labels)
    && /多增量版本治理/.test(labels)
    && /版本口径漂移|需求误覆盖|避免需求漂移/.test(labels);
}

function fallbackDocumentVersionTextBoxes(image = {}, docText = {}) {
  const box = image.box || {};
  const docCenterY = Number(docText.box?.y || 0) + Number(docText.box?.h || 0) / 2;
  const startX = Number(box.x || 0) + Number(box.w || 0) * 0.50;
  const startY = Math.max(Number(box.y || 0) + Number(box.h || 0) * 0.16, docCenterY - Number(box.h || 0) * 0.28);
  const rowGap = Number(box.h || 0) * 0.245;
  return [
    "V24：沉淀待处理位过滤规则。",
    "V25：结构化物流追踪码交互逻辑。",
    "V26：明确关联单号全链路口径。"
  ].map((text, index) => ({
    id: `${image.id || "document-version"}-fallback-v${24 + index}`,
    text,
    box: {
      x: round(startX),
      y: round(startY + index * rowGap),
      w: round(Number(box.w || 0) * 0.43),
      h: 14
    },
    source: {
      fallbackSemanticText: true,
      reason: "document-version-governance-page-context"
    }
  }));
}

function documentVersionFolderFrameShapes(image, layout) {
  const box = image.box || {};
  const headerH = Math.max(22, Number(box.h || 0) * 0.12);
  const tabW = Math.min(130, Number(box.w || 0) * 0.34);
  return [
    {
      id: `${image.id || "document-version"}-native-back-folder-body`,
      type: "roundRect",
      box: { x: round(box.x), y: round(box.y + headerH * 0.55), w: round(box.w), h: round(box.h - headerH * 0.55) },
      style: {
        fill: "#EAF6FF",
        stroke: "#203742",
        strokeWidthPt: 1.2,
        radiusRatio: 0.055
      },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-folder-frame", layerSourceId: image.id || null, confidence: layout.confidence }
    },
    {
      id: `${image.id || "document-version"}-native-back-folder-tab`,
      type: "roundRect",
      box: { x: round(box.x), y: round(box.y), w: round(tabW), h: round(headerH) },
      style: {
        fill: "#2672C5",
        stroke: "#203742",
        strokeWidthPt: 1.2,
        radiusRatio: 0.14
      },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-folder-tab", layerSourceId: image.id || null, confidence: layout.confidence }
    },
    {
      id: `${image.id || "document-version"}-native-back-folder-rail`,
      type: "rect",
      box: { x: round(box.x), y: round(box.y + headerH * 0.62), w: round(box.w), h: round(headerH * 0.48) },
      style: { fill: "#2672C5", stroke: "none", strokeWidthPt: 0 },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-folder-rail", layerSourceId: image.id || null, confidence: layout.confidence }
    }
  ];
}

function documentVersionMainFolderShapes(image, folder, confidence) {
  return [
    {
      id: `${image.id || "document-version"}-native-main-folder-tab`,
      type: "roundRect",
      box: { x: folder.x, y: folder.y, w: round(folder.w * 0.43), h: round(folder.h * 0.28) },
      style: { fill: "#2874C9", stroke: "#203742", strokeWidthPt: 1.1, radiusRatio: 0.15 },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-main-folder", layerSourceId: image.id || null, part: "tab", confidence }
    },
    {
      id: `${image.id || "document-version"}-native-main-folder-body`,
      type: "roundRect",
      box: { x: folder.x, y: round(folder.y + folder.h * 0.20), w: folder.w, h: round(folder.h * 0.80) },
      style: { fill: "#2874C9", stroke: "#203742", strokeWidthPt: 1.1, radiusRatio: 0.095 },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-main-folder", layerSourceId: image.id || null, part: "body", confidence }
    },
    {
      id: `${image.id || "document-version"}-native-main-folder-highlight`,
      type: "rect",
      box: { x: round(folder.x + folder.w * 0.08), y: round(folder.y + folder.h * 0.30), w: round(folder.w * 0.84), h: round(folder.h * 0.10) },
      style: { fill: "#5EA4E6", stroke: "none", strokeWidthPt: 0 },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-main-folder", layerSourceId: image.id || null, part: "highlight", confidence }
    }
  ];
}

function documentVersionCardShapes(image, card, index, confidence) {
  return [
    {
      id: `${image.id || "document-version"}-native-version-card-${index}`,
      type: "roundRect",
      box: card.box,
      style: { fill: "#49C08B", stroke: "#315F52", strokeWidthPt: 1.1, radiusRatio: 0.10 },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-version-card", layerSourceId: image.id || null, cardIndex: index, confidence }
    },
    {
      id: `${image.id || "document-version"}-native-version-card-tab-${index}`,
      type: "roundRect",
      box: { x: card.box.x, y: card.box.y, w: round(card.box.w * 0.24), h: round(card.box.h * 0.28) },
      style: { fill: "#49C08B", stroke: "#315F52", strokeWidthPt: 1.1, radiusRatio: 0.13 },
      source: { editable: true, nativeRebuild: true, detector: "document-version-flow-native-version-tab", layerSourceId: image.id || null, cardIndex: index, confidence }
    }
  ];
}

function documentVersionFlowTextBox(image, text, box, options = {}) {
  return {
    id: `${image.id || "document-version"}-native-text-${options.id || String(text || "").replace(/[^a-z0-9]+/gi, "-").toLowerCase()}`,
    text,
    box,
    font: {
      family: "Microsoft YaHei",
      sizePt: options.sizePt,
      color: options.color,
      weight: options.weight,
      align: "center",
      valign: "middle",
      opacity: 1
    },
    style: {
      visibility: "visible",
      opacity: 1,
      marginLeftPt: 0,
      marginRightPt: 0,
      marginTopPt: 0,
      marginBottomPt: 0,
      fit: "shrink"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "document-version-flow-native-text",
      layerSourceId: image.id || null
    }
  };
}

function markDuplicateDocumentVersionResiduals(images = [], target) {
  for (const image of images || []) {
    if (image === target || !image?.box) continue;
    const detector = image.source?.detector;
    if (detector === "foreground-graphic-crop" && (
      image.source?.stickyNoteClusterObjectified === true
      || shouldTreatAsDocumentVersionMixedParentCrop(image, target)
    )) {
      if (ptBoxOverlapAreaRatio(image.box, target.box) < 0.20) continue;
      image.source = {
        ...(image.source || {}),
        stickyNoteClusterObjectified: true,
        documentVersionNativePeerBox: target.box,
        nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "mixed document-version parent crop"}; split to preserve sketch/sticky residuals after native folder-flow reconstruction`
      };
      continue;
    }
    if (detector !== "sticky-note-adjacent-residual-crop") continue;
    if (ptBoxOverlapAreaRatio(image.box, target.box) < 0.45) continue;
    image.source = {
      ...(image.source || {}),
      documentVersionDuplicateResidual: true,
      dropErasedResidualAfterNativeRebuild: true,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "residual crop"}; duplicate of native rebuilt document version flow`
    };
  }
}

function splitDocumentVersionMixedParentResidualCrop(image, residual, assetFile, irDir) {
  const parent = image.box || {};
  const peer = image.source?.documentVersionNativePeerBox || null;
  if (!peer || !parent.w || !parent.h) return [];
  const leftEdge = Number(parent.x || 0);
  const topEdge = Number(parent.y || 0);
  const peerLeft = Number(peer.x || 0);
  const peerBottom = Number(peer.y || 0) + Number(peer.h || 0);
  const keepBox = constrainPtBox({
    x: leftEdge,
    y: topEdge,
    w: Math.max(0, peerLeft - leftEdge - 8),
    h: Math.min(Number(parent.h || 0), Math.max(120, peerBottom - topEdge + 4))
  }, parent);
  if (keepBox.w < 120 || keepBox.h < 90) return [];
  const localBox = slidePtBoxToLocalPxBox(keepBox, parent, residual);
  if (localBox.w < 32 || localBox.h < 32) return [];
  const crop = cropPng(residual, localBox);
  const outDir = path.dirname(assetFile);
  const base = path.basename(assetFile, path.extname(assetFile));
  const file = path.join(outDir, `${base}-document-version-sketch-residual.png`);
  writePng(file, crop);
  const slideBox = localPxBoxToSlidePt(localBox, residual, parent);
  return [{
    id: `${image.id || "document-version"}-sketch-residual`,
    type: "fidelity-crop",
    assetPath: path.relative(irDir || outDir, file).replace(/\\/g, "/"),
    box: slideBox,
    source: reclassifyImageSource(image.source || {}, slideBox, {
      layer: splitResidualLayerSource(image.source?.layer, slideBox, "document-version-sketch-residual-crop"),
      detector: "document-version-sketch-residual-crop",
      parentDetector: image.source?.detector || null,
      parentImageId: image.id || null,
      residualSplit: true,
      residualSplitMode: "document-version-left-sketch",
      residualSplitIndex: 0,
      residualSplitCount: 1,
      originalCropBox: parent,
      nonEditableReason: "left sticky/sketch illustration preserved after native document-version folder flow reconstruction"
    })
  }];
}

function shouldTreatAsDocumentVersionMixedParentCrop(image = {}, target = {}) {
  const box = image.box || {};
  const targetBox = target.box || {};
  if (!box.w || !box.h || !targetBox.w || !targetBox.h) return false;
  if (image.source?.documentVersionFolderFlowObjectified === true) return false;
  const layer = image.source?.layer || {};
  if (layer.layerType && layer.layerType !== "diagram-zone") return false;
  const imageArea = Number(box.w || 0) * Number(box.h || 0);
  const targetArea = Number(targetBox.w || 0) * Number(targetBox.h || 0);
  if (imageArea < targetArea * 1.6) return false;
  if (Number(box.x || 0) > Number(targetBox.x || 0) - 120) return false;
  if (Number(box.x || 0) + Number(box.w || 0) < Number(targetBox.x || 0) + Number(targetBox.w || 0) * 0.68) return false;
  const overlap = ptBoxOverlapAreaRatio(box, targetBox);
  if (overlap < 0.45) return false;
  const atoms = Array.isArray(layer.visualAtoms) ? layer.visualAtoms : [];
  return atoms.length >= 12 || /complex-graphic|movable-crop|folder|version/.test(String(image.source?.reason || image.source?.nonEditableReason || ""));
}

function inferProcessWithScreenshotsFlowLayout(image, slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  if (!box.w || !box.h) return null;
  if (isProductWorkflowIconProcess(image)) {
    return inferProductWorkflowIconProcessLayout(image, slideSize);
  }
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const center = constrainPtBox({
    x: box.x + box.w * 0.535,
    y: box.y + box.h * 0.292,
    w: box.w * 0.242,
    h: box.h * 0.250
  }, bounds);
  const cards = [
    { role: "decision-maker", primary: true, box: center, fill: "#18A460", stroke: "#128A51", strokeWidthPt: 1.3 },
    { role: "prompting", box: constrainPtBox({ x: box.x + box.w * 0.755, y: box.y + box.h * 0.082, w: box.w * 0.230, h: box.h * 0.188 }, bounds), fill: "#DDF3E8", stroke: "#2CB877", strokeWidthPt: 1.0 },
    { role: "document-generation", box: constrainPtBox({ x: box.x + box.w * 0.755, y: box.y + box.h * 0.352, w: box.w * 0.230, h: box.h * 0.188 }, bounds), fill: "#DDF3E8", stroke: "#2CB877", strokeWidthPt: 1.0 },
    { role: "rule-extraction", box: constrainPtBox({ x: box.x + box.w * 0.755, y: box.y + box.h * 0.622, w: box.w * 0.230, h: box.h * 0.188 }, bounds), fill: "#DDF3E8", stroke: "#2CB877", strokeWidthPt: 1.0 }
  ];
  const rightCards = cards.slice(1);
  const hubX = center.x + center.w * 0.88;
  const hubY = center.y + center.h * 0.50;
  const midCard = rightCards[1].box;
  const connectors = [
    {
      box: lineBox({ x: hubX, y: hubY }, { x: hubX, y: rightCards[0].box.y + rightCards[0].box.h * 0.5 }),
      strokeWidthPt: 5.2
    },
    {
      box: lineBox({ x: hubX, y: rightCards[0].box.y + rightCards[0].box.h * 0.5 }, { x: rightCards[0].box.x - 7, y: rightCards[0].box.y + rightCards[0].box.h * 0.5 }),
      strokeWidthPt: 5.2,
      endArrow: "triangle"
    },
    {
      box: lineBox({ x: center.x + center.w + 4, y: midCard.y + midCard.h * 0.5 }, { x: midCard.x - 7, y: midCard.y + midCard.h * 0.5 }),
      strokeWidthPt: 5.2,
      endArrow: "triangle"
    },
    {
      box: lineBox({ x: hubX, y: hubY }, { x: hubX, y: rightCards[2].box.y + rightCards[2].box.h * 0.5 }),
      strokeWidthPt: 5.2
    },
    {
      box: lineBox({ x: hubX, y: rightCards[2].box.y + rightCards[2].box.h * 0.5 }, { x: rightCards[2].box.x - 7, y: rightCards[2].box.y + rightCards[2].box.h * 0.5 }),
      strokeWidthPt: 5.2,
      endArrow: "triangle"
    }
  ];
  const textBoxes = [
    processFlowTextBox(image, "决策者/火车头", {
      x: center.x + center.w * 0.12,
      y: center.y + center.h * 0.35,
      w: center.w * 0.76,
      h: center.h * 0.30
    }, { color: "#FFFFFF", sizePt: 14.5, weight: 700 }),
    processFlowTextBox(image, "Prompting", cardLabelBox(rightCards[0].box), { color: "#2A7050", sizePt: 11.5, weight: 700 }),
    processFlowTextBox(image, "Document\nGeneration", cardLabelBox(rightCards[1].box), { color: "#2A7050", sizePt: 10.6, weight: 700 }),
    processFlowTextBox(image, "Rule Extraction", cardLabelBox(rightCards[2].box), { color: "#2A7050", sizePt: 11.2, weight: 700 })
  ];
  const left = constrainPtBox({
    x: box.x,
    y: box.y,
    w: box.w * 0.47,
    h: box.h * 0.82
  }, bounds);
  const leftIllustration = inferProcessWithScreenshotsLeftIllustrationLayout(image, left, bounds);
  textBoxes.push(...leftIllustration.textBoxes);
  textBoxes.push(
    processFlowTextBox(image, "传统模式：管理“确定性”，深陷排版与格式\n的重复劳动。", {
      x: box.x + box.w * 0.020,
      y: box.y + box.h * 0.842,
      w: box.w * 0.425,
      h: box.h * 0.130
    }, { color: "#111111", sizePt: 17.0, weight: 700, align: "left", idSuffix: "left-explanation" }),
    processFlowTextBox(image, "AI原生模式：管理“不确定性”，专注需求洞\n察、系统边界与商业落地。", {
      x: box.x + box.w * 0.570,
      y: box.y + box.h * 0.842,
      w: box.w * 0.400,
      h: box.h * 0.130
    }, { color: "#111111", sizePt: 17.0, weight: 700, align: "left", idSuffix: "right-explanation" })
  );
  const icons = rightCards.map((card, index) => ({
    role: cards[index + 1].role,
    box: {
      x: card.box.x + card.box.w * 0.08,
      y: card.box.y + card.box.h * 0.22,
      w: card.box.w * 0.20,
      h: card.box.h * 0.46
    }
  }));
  return { cards, connectors, icons, textBoxes, leftIllustrationShapes: leftIllustration.shapes, confidence: 0.78 };
}

function isProductWorkflowIconProcess(image = {}) {
  const source = image.source || {};
  const reason = `${source.reason || ""} ${source.nonEditableReason || ""}`.toLowerCase();
  return source.detector === "screenshot-process-underlay-crop"
    && /product-workflow-icon-process/.test(reason);
}

function inferProductWorkflowIconProcessLayout(image, slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  if (!box.w || !box.h) return null;
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const sx = (n) => box.x + box.w * n;
  const sy = (n) => box.y + box.h * n;
  const sw = (n) => box.w * n;
  const sh = (n) => box.h * n;
  const cards = [
    { role: "requirement-understanding", label: "需求理解", detail: "(把杂乱变结构化)", cx: 0.291, icon: "search" },
    { role: "prd-generation", label: "PRD 生成", detail: "(把重复变标准化)", cx: 0.433, icon: "document" },
    { role: "smart-review", label: "智能评审", detail: "(会后补救变前置拦截)", cx: 0.563, icon: "radar" },
    { role: "prototype-generation", label: "原型生成", detail: "(文字变可验证交互)", cx: 0.717, icon: "prototype" }
  ].map((stage) => ({
    ...stage,
    type: "hexagon",
    primary: true,
    box: constrainPtBox({
      x: sx(stage.cx) - sw(0.060),
      y: sy(0.100),
      w: sw(0.108),
      h: sh(0.320)
    }, bounds),
    fill: "#0867B8",
    stroke: "#045B9F",
    strokeWidthPt: 1.4,
    noShadow: true
  }));
  const nodeMidY = cards[0].box.y + cards[0].box.h * 0.50;
  const connectors = [
    { box: lineBox({ x: sx(0.18), y: nodeMidY }, { x: cards[0].box.x, y: nodeMidY }), strokeWidthPt: 8.0 },
    ...cards.slice(0, -1).map((card, index) => ({
      box: lineBox(
        { x: card.box.x + card.box.w, y: nodeMidY },
        { x: cards[index + 1].box.x, y: nodeMidY }
      ),
      strokeWidthPt: 8.0
    })),
    { box: lineBox({ x: cards[cards.length - 1].box.x + cards[cards.length - 1].box.w, y: nodeMidY }, { x: sx(0.86), y: nodeMidY }), strokeWidthPt: 8.0 }
  ];
  const branchConnectors = [];
  const icons = cards.map((card) => ({
    role: card.icon,
    box: {
      x: card.box.x + card.box.w * 0.23,
      y: card.box.y + card.box.h * 0.22,
      w: card.box.w * 0.54,
      h: card.box.h * 0.50
    }
  }));
  const textBoxes = [
    ...cards.flatMap((card) => [
      processFlowTextBox(image, card.label, {
        x: card.box.x - sw(0.028),
        y: sy(0.500),
        w: card.box.w + sw(0.056),
        h: sh(0.072)
      }, { color: "#111111", sizePt: 18.5, weight: 700, idSuffix: `${card.role}-label` }),
      processFlowTextBox(image, card.detail, {
        x: card.box.x - sw(0.047),
        y: sy(0.570),
        w: card.box.w + sw(0.094),
        h: sh(0.060)
      }, { color: "#111111", sizePt: 12.8, weight: 400, idSuffix: `${card.role}-detail` })
    ]),
    processFlowTextBox(image, "混沌的输入", { x: sx(0.035), y: sy(0.690), w: sw(0.135), h: sh(0.085) }, { color: "#111111", sizePt: 20.5, weight: 700, idSuffix: "left-input-label" }),
    processFlowTextBox(image, "标准资产输出", { x: sx(0.875), y: sy(0.690), w: sw(0.125), h: sh(0.085) }, { color: "#111111", sizePt: 19.5, weight: 700, idSuffix: "right-output-label" }),
    processFlowTextBox(image, "底层对接分布式域仓，将全链路产出化为可检索、可复用的产品知识网络", {
      x: 0,
      y: sy(0.835),
      w: DEFAULT_SLIDE.widthPt,
      h: sh(0.120)
    }, { color: "#FFFFFF", sizePt: 21.5, weight: 700, idSuffix: "bottom-banner-text" })
  ];
  const banner = {
    type: "rect",
    role: "bottom-banner",
    box: constrainPtBox({ x: 0, y: sy(0.822), w: DEFAULT_SLIDE.widthPt, h: sh(0.145) }, bounds),
    fill: "#0867B8",
    stroke: "#0867B8",
    strokeWidthPt: 0
  };
  return {
    cards: [banner, ...cards],
    connectors: [...branchConnectors, ...connectors],
    icons,
    textBoxes,
    leftIllustrationShapes: [],
    productWorkflowEndpointShapes: [],
    confidence: 0.82,
    productWorkflowIconProcess: true
  };
}

