function visualAtomArcArrowSegmentShapes(image, atom, index, understanding = {}) {
  if (!atom?.box) return null;
  const parentBox = atom.donutParentBox || atom.box;
  const angles = normalizedDonutSegmentAngles(atom, index, 1);
  const color = atom.color || "#38BDF8";
  const baseSource = {
    editable: true,
    nativeRebuild: true,
    detector: "visual-atom-native-arc-arrow-segment",
    layerSourceId: image.id || null,
    layerType: image.source?.layer?.layerType || "diagram-zone",
    atomId: atom.id,
    atomKind: atom.kind,
    shapeHint: atom.shapeHint || null,
    confidence: atom.density ?? null,
    startDeg: angles.startDeg,
    endDeg: angles.endDeg
  };
  const arc = {
    id: `${image.id || "layer"}-visual-atom-arc-arrow-segment-${index}`,
    type: "freeform",
    box: parentBox,
    points: donutSegmentFreeformPoints(angles.startDeg, angles.endDeg, Number(atom.holeRatio || 0.62)),
    style: {
      fill: color,
      stroke: color,
      strokeWidthPt: 0
    },
    source: { ...baseSource, part: "arc" }
  };
  if (atom.arcArrowHead !== true) return arc;
  return [
    arc,
    {
      id: `${image.id || "layer"}-visual-atom-arc-arrow-head-${index}`,
      type: "freeform",
      box: arcArrowHeadBox(parentBox, angles.endDeg),
      points: [
        { x: 1.0, y: 0.5 },
        { x: 0.0, y: 0.0 },
        { x: 0.0, y: 1.0 }
      ],
      style: {
        fill: color,
        stroke: color,
        strokeWidthPt: 0,
        rotation: round(Number(angles.endDeg || 0))
      },
      source: { ...baseSource, part: "arrowhead" }
    }
  ];
}

function arcArrowHeadBox(parentBox = {}, angleDeg = 0) {
  const size = Math.max(10, Math.min(28, Math.max(Number(parentBox.w || 0), Number(parentBox.h || 0)) * 0.16));
  const radius = Math.max(Number(parentBox.w || 0), Number(parentBox.h || 0)) * 0.48;
  const point = pointOnBoxCircle(parentBox, angleDeg, radius);
  return {
    x: round(point.x - size / 2),
    y: round(point.y - size / 2),
    w: round(size),
    h: round(size)
  };
}

function pointOnBoxCircle(box = {}, deg = 0, radius = 0) {
  const radians = normalizeDegrees(deg) * Math.PI / 180;
  return {
    x: Number(box.x || 0) + Number(box.w || 0) / 2 + Math.cos(radians) * radius,
    y: Number(box.y || 0) + Number(box.h || 0) / 2 + Math.sin(radians) * radius
  };
}

function visualAtomCycleArrowShape(image, atom, index) {
  if (!atom?.box) return null;
  const box = visualAtomCycleArrowOfficeBox(image, atom);
  return {
    id: `${image.id || "layer"}-visual-atom-cycle-arrow-${index}`,
    type: "circularArrow",
    box,
    style: {
      fill: atom.color || "#60A5FA",
      stroke: atom.color || "#60A5FA",
      strokeWidthPt: 0
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "visual-atom-native-cycle-arrow",
      layerSourceId: image.id || null,
      layerType: image.source?.layer?.layerType || "diagram-zone",
      atomId: atom.id,
      atomKind: atom.kind,
      shapeHint: atom.shapeHint || null,
      confidence: atom.density ?? null
    }
  };
}

function visualAtomCycleArrowOfficeBox(image = {}, atom = {}) {
  const box = atom.box || {};
  const layerType = String(image?.source?.layer?.layerType || "");
  const confidence = Number(atom.density ?? 1);
  const largeIllustrationAtom = layerType === "illustration-zone"
    && confidence < 0.5
    && Math.max(Number(box.w || 0), Number(box.h || 0)) >= 120;
  if (!largeIllustrationAtom) return box;
  const shrinkX = Number(box.w || 0) * 0.16;
  const shrinkY = Number(box.h || 0) * 0.14;
  return {
    x: round(Number(box.x || 0) + shrinkX),
    y: round(Number(box.y || 0) + shrinkY),
    w: round(Number(box.w || 0) - shrinkX * 2),
    h: round(Number(box.h || 0) - shrinkY * 2)
  };
}

function visualAtomConnectorShape(image, atom, index, understanding = {}) {
  if (!atom?.box) return null;
  const box = atom.box;
  const endpoints = atom.lineEndpoints?.from && atom.lineEndpoints?.to ? atom.lineEndpoints : null;
  const horizontal = Number(box.w || 0) >= Number(box.h || 0);
  const isArrow = atom.kind === "connector-arrow-candidate" || /^arrow-/.test(String(atom.shapeHint || ""));
  const visualConnector = Array.isArray(understanding.visualConnectors)
    ? understanding.visualConnectors.find((item) => item.atomId === atom.id)
    : null;
  return {
    id: `${image.id || "layer"}-visual-atom-connector-${index}`,
    type: "line",
    box: endpoints
      ? {
        x: Number(endpoints.from.x || 0),
        y: Number(endpoints.from.y || 0),
        w: Number(endpoints.to.x || 0) - Number(endpoints.from.x || 0),
        h: Number(endpoints.to.y || 0) - Number(endpoints.from.y || 0)
      }
      : horizontal
        ? { x: box.x, y: box.y + box.h / 2, w: box.w, h: 0 }
        : { x: box.x + box.w / 2, y: box.y, w: 0, h: box.h },
    style: {
      stroke: atom.color || "#6B7280",
      strokeWidthPt: Math.max(1, Math.min(4, horizontal ? Number(box.h || 1) : Number(box.w || 1))),
      connectorType: "straight",
      ...(isArrow ? { endArrow: "triangle" } : {})
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "visual-atom-native-connector",
      layerSourceId: image.id || null,
      layerType: image.source?.layer?.layerType || "diagram-zone",
      atomId: atom.id,
      atomKind: atom.kind,
      shapeHint: atom.shapeHint || null,
      confidence: atom.density ?? null,
      axis: endpoints ? "diagonal" : horizontal ? "horizontal" : "vertical",
      fromAtomId: visualConnector?.fromAtomId || atom.fromAtomId || null,
      toAtomId: visualConnector?.toAtomId || atom.toAtomId || null,
      visualConnectorId: visualConnector?.id || null
    }
  };
}

function visualAtomReturnLoopShapes(image, atom, index) {
  if (!atom?.box) return [];
  const box = atom.box;
  const color = atom.color || "#55B98D";
  const strokeWidth = Math.max(1.5, Math.min(3.5, Number(box.h || 0) * 0.045));
  const x1 = Number(box.x || 0) + Number(box.w || 0) * 0.18;
  const x2 = Number(box.x || 0) + Number(box.w || 0) * 0.88;
  const y1 = Number(box.y || 0) + Number(box.h || 0) * 0.28;
  const y2 = Number(box.y || 0) + Number(box.h || 0) * 0.78;
  const prefix = `${image.id || "layer"}-visual-atom-return-loop-${index}`;
  const source = (segment) => ({
    editable: true,
    nativeRebuild: true,
    detector: "visual-atom-native-connector",
    layerSourceId: image.id || null,
    layerType: image.source?.layer?.layerType || "diagram-zone",
    atomId: atom.id,
    atomKind: atom.kind,
    shapeHint: atom.shapeHint || "return-loop",
    confidence: atom.density ?? null,
    axis: segment,
    promotedFrom: atom.promotedFrom || null
  });
  return [
    {
      id: `${prefix}-top`,
      type: "line",
      box: { x: round(x2), y: round(y1), w: round(x1 - x2), h: 0 },
      style: { stroke: color, strokeWidthPt: strokeWidth, connectorType: "straight", startArrow: "triangle" },
      source: source("return-loop-top")
    },
    {
      id: `${prefix}-right`,
      type: "line",
      box: { x: round(x2), y: round(y1), w: 0, h: round(y2 - y1) },
      style: { stroke: color, strokeWidthPt: strokeWidth, connectorType: "straight" },
      source: source("return-loop-right")
    },
    {
      id: `${prefix}-bottom`,
      type: "line",
      box: { x: round(x1), y: round(y2), w: round(x2 - x1), h: 0 },
      style: { stroke: color, strokeWidthPt: strokeWidth, connectorType: "straight" },
      source: source("return-loop-bottom")
    }
  ];
}

function shouldObjectifyLayerConnectors(image) {
  const layer = image?.source?.layer || {};
  return image?.source?.containerObjectified === true
    && layer.layerType === "diagram-zone"
    && (layer.recommendedAction === "attempt-native-reconstruction" || layer.recommendedAction === "split-native-with-residual-crop");
}

function inferLayerContainers(image, textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!image?.box || !sourceImage) return [];
  const candidates = (textBoxes || [])
    .filter((textBox) => isContainerCandidateTextBox(textBox, image.box))
    .map((textBox) => inferTextBoxContainer(image.box, textBox, sourceImage, slideSize))
    .filter(Boolean)
    .sort((a, b) => (b.confidence - a.confidence) || (b.box.w * b.box.h - a.box.w * a.box.h));
  const accepted = [];
  for (const candidate of candidates) {
    if (accepted.some((item) => ptBoxOverlapAreaRatio(item.box, candidate.box) > 0.68)) continue;
    accepted.push(candidate);
    if (accepted.length >= 18) break;
  }
  return accepted.sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
}

function inferLayerConnectors(image, containers = [], sourceImage = null, slideSize = DEFAULT_SLIDE) {
  if (!image?.box || !sourceImage || !Array.isArray(containers) || containers.length < 2) return [];
  const candidates = [];
  const sorted = containers
    .filter((shape) => shape?.box && boxCenterInside(shape.box, image.box))
    .sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
  for (let i = 0; i < sorted.length; i += 1) {
    for (let j = i + 1; j < sorted.length; j += 1) {
      const candidate = inferConnectorBetweenContainers(sorted[i], sorted[j], sourceImage, slideSize);
      if (!candidate) continue;
      if (candidates.some((item) => connectorBoxesNear(item.box, candidate.box))) continue;
      candidates.push(candidate);
    }
  }
  return candidates
    .sort((a, b) => (b.confidence - a.confidence) || (a.box.y - b.box.y) || (a.box.x - b.box.x))
    .slice(0, 12)
    .sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
}

function inferConnectorBetweenContainers(a, b, sourceImage, slideSize) {
  const aBox = a.box || {};
  const bBox = b.box || {};
  const aCx = Number(aBox.x || 0) + Number(aBox.w || 0) / 2;
  const bCx = Number(bBox.x || 0) + Number(bBox.w || 0) / 2;
  const aCy = Number(aBox.y || 0) + Number(aBox.h || 0) / 2;
  const bCy = Number(bBox.y || 0) + Number(bBox.h || 0) / 2;
  const horizontal = Math.abs(aCy - bCy) <= Math.max(16, Math.min(Number(aBox.h || 0), Number(bBox.h || 0)) * 0.42);
  const vertical = Math.abs(aCx - bCx) <= Math.max(16, Math.min(Number(aBox.w || 0), Number(bBox.w || 0)) * 0.25);
  if (horizontal) {
    const left = aCx <= bCx ? a : b;
    const right = left === a ? b : a;
    const gap = Number(right.box.x || 0) - (Number(left.box.x || 0) + Number(left.box.w || 0));
    if (gap < 6 || gap > 260) return null;
    const y = round((Number(left.box.y || 0) + Number(left.box.h || 0) / 2 + Number(right.box.y || 0) + Number(right.box.h || 0) / 2) / 2);
    const probe = { x: Number(left.box.x || 0) + Number(left.box.w || 0), y: y - 6, w: gap, h: 12 };
    const ink = sampleConnectorInk(sourceImage, probe, slideSize);
    if (!ink) return null;
    return {
      axis: "horizontal",
      box: { x: round(probe.x + 2), y, w: round(Math.max(1, gap - 4)), h: 0 },
      stroke: ink.stroke,
      strokeWidthPt: ink.strokeWidthPt,
      confidence: ink.confidence,
      from: left.id || null,
      to: right.id || null
    };
  }
  if (vertical) {
    const top = aCy <= bCy ? a : b;
    const bottom = top === a ? b : a;
    const gap = Number(bottom.box.y || 0) - (Number(top.box.y || 0) + Number(top.box.h || 0));
    if (gap < 6 || gap > 220) return null;
    const x = round((Number(top.box.x || 0) + Number(top.box.w || 0) / 2 + Number(bottom.box.x || 0) + Number(bottom.box.w || 0) / 2) / 2);
    const probe = { x: x - 6, y: Number(top.box.y || 0) + Number(top.box.h || 0), w: 12, h: gap };
    const ink = sampleConnectorInk(sourceImage, probe, slideSize);
    if (!ink) return null;
    return {
      axis: "vertical",
      box: { x, y: round(probe.y + 2), w: 0, h: round(Math.max(1, gap - 4)) },
      stroke: ink.stroke,
      strokeWidthPt: ink.strokeWidthPt,
      confidence: ink.confidence,
      from: top.id || null,
      to: bottom.id || null
    };
  }
  return null;
}

function sampleConnectorInk(image, ptProbeBox, slideSize) {
  const pxBox = ptToPxBox(ptProbeBox, image, slideSize, 1);
  const background = sampleMaskBackgroundColor(image, pxBox);
  const ink = [];
  const total = Math.max(1, pxBox.w * pxBox.h);
  for (let y = pxBox.y; y < pxBox.y + pxBox.h; y += 1) {
    for (let x = pxBox.x; x < pxBox.x + pxBox.w; x += 1) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      if (colorDistance(color, background) >= 34 && luma(color) < 245) ink.push(color);
    }
  }
  const ratio = ink.length / total;
  if (ink.length < 6 || ratio < 0.035) return null;
  const averaged = averageColor(ink);
  return {
    stroke: rgbToHex(averaged),
    strokeWidthPt: round(clamp(Math.sqrt(ratio) * 4.5, 0.65, 2.5)),
    confidence: round(clamp(0.56 + ratio * 2.4 + colorDistance(averaged, background) / 420, 0.56, 0.94))
  };
}

function connectorBoxesNear(a, b) {
  return Math.abs(Number(a.x || 0) - Number(b.x || 0)) <= 4
    && Math.abs(Number(a.y || 0) - Number(b.y || 0)) <= 4
    && Math.abs(Number(a.w || 0) - Number(b.w || 0)) <= 6
    && Math.abs(Number(a.h || 0) - Number(b.h || 0)) <= 6;
}

function isContainerCandidateTextBox(textBox, imageBox) {
  const text = String(textBox?.text || "").trim();
  const box = textBox?.box || {};
  if (text.length < 2) return false;
  if (/^[+\-—–·•|/\\]+$/.test(text)) return false;
  if (Number(box.w || 0) < 26 || Number(box.h || 0) < 8) return false;
  if (Number(box.w || 0) > Number(imageBox.w || 0) * 0.92) return false;
  if (Number(box.h || 0) > Number(imageBox.h || 0) * 0.35) return false;
  return true;
}

function inferTextBoxContainer(imageBox, textBox, sourceImage, slideSize) {
  const textBoxWidth = Number(textBox?.box?.w || 0);
  const textBoxHeight = Number(textBox?.box?.h || 0);
  const base = expandPtBox(
    textBox.box,
    slideSize,
    Math.max(18, Math.min(38, textBoxWidth * 0.35)),
    Math.max(10, Math.min(22, textBoxHeight * 0.9))
  );
  const box = constrainPtBox(base, imageBox);
  if (box.w < 46 || box.h < 18) return null;
  const pxBox = ptToPxBox(box, sourceImage, slideSize, 0);
  const innerColor = dominantRegionColor(sourceImage, pxBox, 2);
  const outsideColor = sampleMaskBackgroundColor(sourceImage, pxBox);
  const contrast = colorDistance(innerColor, outsideColor);
  const innerSat = saturation(innerColor);
  const outsideSat = saturation(outsideColor);
  const hasVisibleFill = contrast >= 18 || innerSat >= outsideSat + 0.10 || luma(innerColor) < luma(outsideColor) - 18;
  if (!hasVisibleFill) return null;
  const isLightCard = luma(innerColor) > 228 && luma(outsideColor) > 228 && contrast < 32;
  if (isLightCard) return null;
  const aspect = box.w / Math.max(1, box.h);
  const radiusRatio = aspect > 5 ? 0.12 : 0.08;
  const confidence = round(Math.min(0.95, 0.58 + contrast / 180 + Math.min(0.15, innerSat * 0.18)));
  return {
    box,
    shapeType: "roundRect",
    fill: rgbToHex(innerColor),
    stroke: inferContainerStroke(innerColor, outsideColor),
    strokeWidthPt: contrast < 28 ? 0.65 : 0,
    radiusRatio,
    confidence,
    textBoxCount: 1
  };
}

function dominantRegionColor(image, box, step = 2) {
  const buckets = new Map();
  const x2 = Math.min(image.width, box.x + box.w);
  const y2 = Math.min(image.height, box.y + box.h);
  for (let y = Math.max(0, box.y); y < y2; y += step) {
    for (let x = Math.max(0, box.x); x < x2; x += step) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      const key = `${Math.round(color.r / 14)},${Math.round(color.g / 14)},${Math.round(color.b / 14)}`;
      const entry = buckets.get(key) || { count: 0, r: 0, g: 0, b: 0 };
      entry.count += 1;
      entry.r += color.r;
      entry.g += color.g;
      entry.b += color.b;
      buckets.set(key, entry);
    }
  }
  const dominant = [...buckets.values()].sort((a, b) => b.count - a.count)[0];
  if (!dominant || dominant.count < 4) return { r: 255, g: 255, b: 255 };
  return {
    r: Math.round(dominant.r / dominant.count),
    g: Math.round(dominant.g / dominant.count),
    b: Math.round(dominant.b / dominant.count)
  };
}

function inferContainerStroke(innerColor, outsideColor) {
  if (colorDistance(innerColor, outsideColor) < 28) {
    return luma(innerColor) > 210 ? "#D8D8D8" : rgbToHex(innerColor);
  }
  return "none";
}

function constrainPtBox(box, bounds) {
  const x1 = clamp(Number(box.x || 0), Number(bounds.x || 0), Number(bounds.x || 0) + Number(bounds.w || 0));
  const y1 = clamp(Number(box.y || 0), Number(bounds.y || 0), Number(bounds.y || 0) + Number(bounds.h || 0));
  const x2 = clamp(Number(box.x || 0) + Number(box.w || 0), x1 + 0.1, Number(bounds.x || 0) + Number(bounds.w || 0));
  const y2 = clamp(Number(box.y || 0) + Number(box.h || 0), y1 + 0.1, Number(bounds.y || 0) + Number(bounds.h || 0));
  return { x: round(x1), y: round(y1), w: round(x2 - x1), h: round(y2 - y1) };
}

function ptBoxOverlapAreaRatio(a, b) {
  const xOverlap = Math.max(0, Math.min(a.x + a.w, b.x + b.w) - Math.max(a.x, b.x));
  const yOverlap = Math.max(0, Math.min(a.y + a.h, b.y + b.h) - Math.max(a.y, b.y));
  const overlap = xOverlap * yOverlap;
  const smaller = Math.min(Math.max(1, a.w * a.h), Math.max(1, b.w * b.h));
  return overlap / smaller;
}

function inferDenseTextGrid(imageBox, textBoxes = []) {
  const gridTextBoxes = gridCandidateTextBoxes(textBoxes);
  if (!imageBox || gridTextBoxes.length < 9) return null;
  const centers = gridTextBoxes.map((item) => ({
    x: Number(item.box?.x || 0) + Number(item.box?.w || 0) / 2,
    y: Number(item.box?.y || 0) + Number(item.box?.h || 0) / 2
  }));
  const xClusters = clusterNumericValues(centers.map((item) => item.x), Math.max(36, Number(imageBox.w || 0) * 0.07));
  const yClusters = clusterNumericValues(centers.map((item) => item.y), Math.max(26, Number(imageBox.h || 0) * 0.09));
  const columns = xClusters.length;
  const rows = yClusters.length;
  if (columns < 3 || rows < 3) return null;
  const density = gridTextBoxes.length / Math.max(1, columns * rows);
  if (density < 0.62) return null;
  const xCenters = xClusters.map((cluster) => cluster.center).sort((a, b) => a - b);
  const yCenters = yClusters.map((cluster) => cluster.center).sort((a, b) => a - b);
  const xLines = boundariesFromCenters(xCenters, imageBox.x, Number(imageBox.x || 0) + Number(imageBox.w || 0));
  const yLines = boundariesFromCenters(yCenters, imageBox.y, Number(imageBox.y || 0) + Number(imageBox.h || 0));
  if (xLines.length < 4 || yLines.length < 4) return null;
  return {
    columns,
    rows,
    density: round(density),
    xLines,
    yLines
  };
}

function gridCandidateTextBoxes(textBoxes = []) {
  return (textBoxes || []).filter((item) => {
    const text = String(item?.text || "").trim();
    const box = item?.box || {};
    if (text.length <= 1) return false;
    if (/^[+\-—–·•|/\\]+$/.test(text)) return false;
    if (Number(box.w || 0) < 28 || Number(box.h || 0) < 8) return false;
    return true;
  });
}

function clusterNumericValues(values = [], threshold = 24) {
  const clusters = [];
  for (const value of values
    .map((item) => Number(item))
    .filter(Number.isFinite)
    .sort((a, b) => a - b)) {
    const last = clusters[clusters.length - 1];
    if (!last || Math.abs(value - last.center) > threshold) {
      clusters.push({ values: [value], center: value });
    } else {
      last.values.push(value);
      last.center = last.values.reduce((sum, item) => sum + item, 0) / last.values.length;
    }
  }
  return clusters;
}

function boundariesFromCenters(centers, min, max) {
  const lines = [round(min)];
  for (let index = 0; index < centers.length - 1; index += 1) {
    lines.push(round((centers[index] + centers[index + 1]) / 2));
  }
  lines.push(round(max));
  return lines;
}

function tableGridStrokeColor(textBoxes = []) {
  const colors = textBoxes
    .map((item) => normalizeHex(item.font?.color, null))
    .filter(Boolean)
    .filter((color) => luma(parseHex(color)) < 245);
  if (colors.length === 0) return "#D2DAE4";
  const average = averageColor(colors.map(parseHex));
  const neutral = {
    r: Math.round((average.r + 210) / 2),
    g: Math.round((average.g + 218) / 2),
    b: Math.round((average.b + 228) / 2)
  };
  return rgbToHex(neutral);
}

function removesInternalEditableText(detector) {
  return [
    "kpi-evidence-crop",
    "entropy-challenge-crop",
    "illustration-card-graphic-underlay-crop",
    "mixed-diagram-graphic-underlay-crop",
    "left-illustration-panel-crop",
    "bottom-banner-crop",
    "sparse-diagram-graphic-underlay-crop",
    "visual-cluster-graphic-underlay-crop",
    "comparison-matrix-crop",
    "top-complex-diagram-crop",
    "two-panel-diagram-crop",
    "screenshot-process-underlay-crop",
    "foreground-graphic-crop"
  ].includes(detector);
}

function isCollaborationFlowInternalLabel(textBox, underlayBox) {
  const text = String(textBox?.text || "").replace(/\s+/g, "");
  const box = textBox?.box || {};
  const centerX = Number(box.x || 0) + Number(box.w || 0) / 2;
  const centerY = Number(box.y || 0) + Number(box.h || 0) / 2;
  const inside = centerX >= underlayBox.x
    && centerX <= underlayBox.x + underlayBox.w
    && centerY >= underlayBox.y
    && centerY <= underlayBox.y + underlayBox.h;
  if (!inside) return false;
  if (/^(?:PMSkills|PMSkill|处理引擎)$/i.test(text)) {
    return centerX <= underlayBox.x + underlayBox.w * 0.28
      && centerY >= underlayBox.y + underlayBox.h * 0.42
      && centerY <= underlayBox.y + underlayBox.h * 0.7;
  }
  const isRecipientText = /^(?:To后端研发BE|To前端研发FE|To测试QA)$/i.test(text)
    || /消除模糊地带|后端接口拆解|据策略读取|已关闭出库单|告别交互拉扯|阻断校验规则|界值计算公式|高保真原型|更严密的用例参考|前置暴露异常场景|发货扣减|高覆盖率测试依据/.test(text);
  if (!isRecipientText) return false;
  return centerX >= underlayBox.x + underlayBox.w * 0.48
    && centerX <= underlayBox.x + underlayBox.w * 0.98
    && centerY >= underlayBox.y + underlayBox.h * 0.04
    && centerY <= underlayBox.y + underlayBox.h * 0.95;
}

function isSaturatedDiagramInternalLabel(textBox, underlayBox) {
  const text = String(textBox?.text || "").replace(/\s+/g, "");
  if (!/(?:痛点|解决方案|文字方案|不够直观|原型与系统菜单|脱节|基于语义克隆|线上系统|文档秒变|可点击原型|路由自动接入|实现全景联动|结构化标准|文档|DOM语义|精准克隆|自动生成操作手册|证据回流|所见即所得|交互原型)/i.test(text)) {
    return false;
  }
  const box = textBox?.box || {};
  const centerX = Number(box.x || 0) + Number(box.w || 0) / 2;
  const centerY = Number(box.y || 0) + Number(box.h || 0) / 2;
  return centerX >= underlayBox.x + underlayBox.w * 0.03
    && centerX <= underlayBox.x + underlayBox.w * 0.98
    && centerY >= underlayBox.y + underlayBox.h * 0.14
    && centerY <= underlayBox.y + underlayBox.h * 0.72;
}

function isAssetCycleUnderlay(textBoxes, underlayBox) {
  if (!underlayBox) return false;
  const text = textBoxes.map((item) => String(item?.text || "").replace(/\s+/g, "")).join("\n");
  const signals = ["YH", "资产复利", "效率提速", "标准统一", "质量保障"]
    .filter((item) => text.includes(item)).length;
  const areaRatio = Number(underlayBox.w || 0) * Number(underlayBox.h || 0) / Math.max(1, DEFAULT_SLIDE.widthPt * DEFAULT_SLIDE.heightPt);
  return signals >= 5 && areaRatio >= 0.32 && areaRatio <= 0.48;
}

function isAssetCycleInternalLabel(textBox, underlayBox) {
  if (!underlayBox) return false;
  const text = String(textBox?.text || "").replace(/\s+/g, "");
  if (!/^(?:YH|资产复利|效率提速|标准统一|质量保障|\(KnowledgeAsset\)|\(Efficiency\)[）)]?|\(Standardization\)|\(Quality\)[）)]?)$/i.test(text)) {
    return false;
  }
  const box = textBox?.box || {};
  const centerX = Number(box.x || 0) + Number(box.w || 0) / 2;
  const centerY = Number(box.y || 0) + Number(box.h || 0) / 2;
  return centerX >= underlayBox.x + underlayBox.w * 0.22
    && centerX <= underlayBox.x + underlayBox.w * 0.78
    && centerY >= underlayBox.y + underlayBox.h * 0.12
    && centerY <= underlayBox.y + underlayBox.h * 0.92;
}

function isWmsRouteInternalLabel(textBox, underlayBox) {
  if (!underlayBox) return false;
  const text = String(textBox?.text || "").replace(/\s+/g, "");
  const isRouteText = /^(?:V39B|增量|WMSInbound|Tollgate[123]|越库完整性|已关闭扣减|超量公式边界)$/i.test(text)
    || /^拦截成功[:：]/.test(text);
  const isValueCardText = /^(?:挑战|AI介入|价值落地)$/.test(text)
    || /WMS高度依赖|历史版本|研发介入|增量边界|研发告别|FE\/BE\/QA|隐性规则|链路|审计|回归/.test(text)
    || /V49集单|改A坏B|最大可收量|核心逻辑防线|无死角任务清单|产出价值|文档思维|界面交互|可视化实体/.test(text);
  if (!isRouteText && !isValueCardText) return false;
  const box = textBox?.box || {};
  const centerX = Number(box.x || 0) + Number(box.w || 0) / 2;
  const centerY = Number(box.y || 0) + Number(box.h || 0) / 2;
  return centerX >= underlayBox.x
    && centerX <= underlayBox.x + underlayBox.w
    && centerY >= underlayBox.y
    && centerY <= underlayBox.y + underlayBox.h
    && underlayBox.y < DEFAULT_SLIDE.heightPt * 0.65;
}

function createEntropyChallengeCrops(image, textBoxes, slideSize, options) {
  if (!options.assetDir || !shouldUseEntropyChallengeCrops(textBoxes, slideSize)) return [];
  ensureDir(options.assetDir);
  const boxes = [
    { name: "fragment-cloud", x: 40, y: 118, w: 330, h: 294 },
    { name: "island-frame", x: 350, y: 96, w: 580, h: 356 }
  ].map((box) => ({
    name: box.name,
    x: round(clamp(box.x, 0, slideSize.widthPt - 1)),
    y: round(clamp(box.y, 0, slideSize.heightPt - 1)),
    w: round(clamp(box.w, 1, slideSize.widthPt - box.x)),
    h: round(clamp(box.h, 1, slideSize.heightPt - box.y))
  }));
  const annotationEntries = entropyChallengeAnnotationEntries(textBoxes, slideSize);
  return boxes.map((box, index) => {
    const pxBox = ptToPxBox(box, image, slideSize, 0);
    const cropSource = box.name === "fragment-cloud" && annotationEntries.length === 4
      ? eraseMasks(image, annotationEntries.map((entry) =>
        ptToPxBox(expandPtBox(entry.box, slideSize, 7, 4), image, slideSize, 0)))
      : image;
    const crop = cropPng(cropSource, pxBox);
    const file = path.join(options.assetDir, `${options.deckName || "deck"}-p${String(options.pageIndex + 1).padStart(2, "0")}-entropy-challenge-${String(index + 1).padStart(2, "0")}.png`);
    writePng(file, crop);
    return {
      id: `native-entropy-challenge-crop-${box.name || index}`,
      type: "fidelity-crop",
      assetPath: path.relative(options.irDir || options.assetDir, file).replace(/\\/g, "/"),
      box,
      source: {
        editable: false,
        nativeRebuild: true,
        // The perspective island looks grid-like, but its depth routes and
        // illustration styling are the minimum visual unit, not a data table.
        standaloneVisualAsset: true,
        expressionFamily: "pictorial-asset",
        expressionForm: "icon-or-illustration",
        expressionSubtype: box.name === "island-frame"
          ? "perspective-island-illustration"
          : "fragment-cloud-illustration",
        recommendedAction: "keep-local-crop-with-native-helper-overlays",
        intentionalMinimumUnitCrop: true,
        protectedMinimumUnit: true,
        minimumUnitPolicy: "preserve-pictorial-illustration-unit",
        minimumUnitReason: box.name === "island-frame"
          ? "perspective frame and crossing curved routes form one decorated pictorial unit"
          : "fragment cloud consists of decorative shards without independently labeled semantic nodes",
        annotationTextErasedFromCrop: box.name === "fragment-cloud" && annotationEntries.length === 4,
        componentRenderStrategy: {
          mode: box.name === "fragment-cloud" ? "preserve-crop-with-native-overlays" : "preserve-local-crop",
          implementationMode: box.name === "fragment-cloud" ? "hybrid-native-overlay" : "native-generator-safe-fallback",
          editableExpectation: box.name === "fragment-cloud"
            ? "source-faithful-fragment-illustration-with-editable-annotation-labels"
            : "standalone-perspective-illustration-preserved-as-movable-crop",
          visualFidelityBias: "fidelity-first"
        },
        layer: {
          layerType: "illustration-zone",
          detector: box.name === "island-frame" ? "entropy-challenge-island-crop" : "entropy-challenge-crop",
          expressionForm: "icon-or-illustration",
          expressionSubtype: box.name === "island-frame"
            ? "perspective-island-illustration"
            : "fragment-cloud-illustration",
          recommendedAction: "keep-local-crop-with-native-helper-overlays",
          componentRenderStrategy: {
            mode: box.name === "fragment-cloud" ? "preserve-crop-with-native-overlays" : "preserve-local-crop"
          }
        },
        // This page is deliberately retained as a fidelity-first diagram.
        // Prevent generic visual-atom reconstruction from erasing pixels in
        // the crop before a validated native replacement is available.
        skipVisualAtomRebuild: true,
        detector: box.name === "island-frame" ? "entropy-challenge-island-crop" : "entropy-challenge-crop",
        reason: box.name === "island-frame"
          ? "perspective island frame preserved as a local fidelity crop with editable helper shapes layered above"
          : "complex fragment illustration preserved as a local fidelity crop with editable helper shapes layered above",
        nonEditableReason: box.name === "island-frame"
          ? "perspective island frame and crossing routes are a decorated illustration rather than a semantic table"
          : "decorative fragment cloud remains a pictorial unit while its four annotation labels are editable"
      }
    };
  });
}

function entropyChallengeAnnotationEntries(textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const labels = ["分散的飞书材料", "过期的历史PRD", "脱节的原型设计", "滞后的评审记录"];
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  return labels.map((label, index) => {
    const textBox = (textBoxes || []).find((item) => normalizeCjkText(item?.text) === normalizeCjkText(label));
    if (!textBox?.box) return null;
    return {
      index,
      label,
      box: constrainPtBox({
        x: Number(textBox.box.x || 0),
        y: Number(textBox.box.y || 0),
        w: Number(textBox.box.w || 0),
        h: Number(textBox.box.h || 0)
      }, bounds)
    };
  }).filter(Boolean);
}

function createEntropyChallengeAnnotationObjects(textBoxes = [], images = [], slideSize = DEFAULT_SLIDE) {
  const fragment = (images || []).find((image) =>
    image?.source?.detector === "entropy-challenge-crop"
      && image?.source?.annotationTextErasedFromCrop === true
  );
  const entries = entropyChallengeAnnotationEntries(textBoxes, slideSize);
  if (!fragment || entries.length !== 4) return { shapes: [], textBoxes: [] };
  const bounds = { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt };
  const shapes = [];
  const nativeTextBoxes = [];
  entries.forEach((entry) => {
    const component = entropyChallengeNativeComponentMetadata(`annotation-${entry.index}`, "backplate");
    shapes.push({
      id: `entropy-challenge-annotation-backplate-${entry.index}`,
      type: "rect",
      box: constrainPtBox(expandPtBox(entry.box, slideSize, 7, 4), bounds),
      style: { fill: "#FFFFFF", stroke: "#FFFFFF", strokeWidthPt: 0 },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "entropy-challenge-native-annotation-backplate",
        expressionForm: "text-and-ui-chrome",
        ...component
      }
    });
    nativeTextBoxes.push({
      id: `entropy-challenge-annotation-text-${entry.index}`,
      role: "body",
      text: entry.label,
      box: entry.box,
      font: {
        family: "Microsoft YaHei",
        sizePt: entry.index === 0 ? 16 : 15,
        color: "#C56717",
        opacity: 1,
        weight: "bold",
        align: "center",
        valign: "middle"
      },
      style: {
        visibility: "visible",
        opacity: 1,
        wrap: false,
        marginLeftPt: 0,
        marginRightPt: 0,
        marginTopPt: 0,
        marginBottomPt: 0
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "entropy-challenge-native-annotation-text",
        layerSourceId: fragment.id,
        textErasedFromCrop: true,
        expressionForm: "text-and-ui-chrome",
        ...entropyChallengeNativeComponentMetadata(`annotation-${entry.index}`, "label")
      }
    });
  });
  return { shapes, textBoxes: nativeTextBoxes };
}

function entropyChallengeNativeComponentMetadata(role, part) {
  const safeRole = safeComponentToken(role || "unknown");
  return {
    nativeComponentGroupId: `entropy-challenge-${safeRole}`,
    nativeComponentParentId: "entropy-challenge",
    nativeComponentArchetype: role.startsWith("footer-") ? "bullet-label" : "illustration-annotation",
    nativeComponentInstance: true,
    nativeComponentMinimumUnit: "semantic-component",
    nativeComponentRole: role,
    nativeComponentPart: part || "detail"
  };
}

function shouldObjectifyEntropyFragmentCloud(textBoxes, slideSize = DEFAULT_SLIDE) {
  if (!shouldUseEntropyChallengeCrops(textBoxes, slideSize)) return false;
  const normalized = textBoxes.map((item) => String(item?.text || "").replace(/\s+/g, "")).join("\n");
  return ["分散的飞书材料", "过期的历史PRD", "脱节的原型设计", "滞后的评审记录"]
    .every((signal) => normalized.includes(signal));
}

function shouldObjectifyEntropyIsland(textBoxes, slideSize = DEFAULT_SLIDE) {
  return shouldObjectifyEntropyFragmentCloud(textBoxes, slideSize);
}

function shouldFullyObjectifyEntropyChallenge(textBoxes, slideSize = DEFAULT_SLIDE) {
  return shouldObjectifyEntropyFragmentCloud(textBoxes, slideSize)
    && shouldObjectifyEntropyIsland(textBoxes, slideSize);
}

function createAssetOsFlowObjects(images = [], textBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  const shapes = [];
  const iconImages = [];
  const nativeTextBoxes = [];
  for (const image of images || []) {
    if (!shouldObjectifyAssetOsFlow(image, textBoxes, slideSize)) continue;
    const flow = inferAssetOsFlowLayout(image, textBoxes, slideSize, options);
    if (!flow) continue;
    image.source = {
      ...(image.source || {}),
      assetOsFlowObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      objectifiedAssetOsFlowShapes: flow.shapes.length,
      objectifiedAssetOsFlowIconCrops: Array.isArray(flow.images) ? flow.images.length : 0,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "asset OS flow crop"}; rebuilt asset flow structure as native editable components while preserving complex icons as local crops`
    };
    shapes.push(...flow.shapes);
    iconImages.push(...(flow.images || []));
    nativeTextBoxes.push(...(flow.textBoxes || []));
  }
  return { shapes, textBoxes: nativeTextBoxes, images: iconImages };
}

function shouldObjectifyAssetOsFlow(image = {}, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  if (!box.w || !box.h || box.w < 360 || box.h < 240) return false;
  const layer = image.source?.layer || {};
  const understanding = layer.diagramUnderstanding || {};
  const detector = String(image.source?.detector || "");
  if (String(layer.layerType || "") !== "diagram-zone") return false;
  if (understanding.archetype !== "flow-card-chain" && !/sparse-diagram/.test(detector)) return false;
  const labels = normalizedTextsInsideBox(textBoxes, expandPtBox(box, slideSize, 18, 18));
  return ["标准化PRD", "交互原型", "操作手册", "业务需求", "历史文档", "飞书截图"]
    .every((label) => labels.has(normalizeCjkText(label)));
}

function inferAssetOsFlowLayout(image = {}, textBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  const b = image.box || {};
  const inside = (textBoxes || []).filter((item) =>
    item?.box && boxCenterInside(item.box, expandPtBox(b, slideSize, 20, 20)));
  const topLabels = ["标准化PRD", "交互原型", "操作手册"]
    .map((label) => ({ label, textBox: findTextBoxByNormalizedText(inside, label) }))
    .filter((item) => item.textBox?.box)
    .sort((a, bItem) => a.textBox.box.x - bItem.textBox.box.x);
  const bottomLabels = ["业务需求", "历史文档", "飞书截图"]
    .map((label) => ({ label, textBox: findTextBoxByNormalizedText(inside, label) }))
    .filter((item) => item.textBox?.box)
    .sort((a, bItem) => a.textBox.box.x - bItem.textBox.box.x);
  if (topLabels.length < 3 || bottomLabels.length < 3) return null;

  const prefix = image.id || "asset-os-flow";
  const iconImages = [];
  const nativeTextBoxes = [];
  const shield = {
    x: round(b.x + b.w * 0.405),
    y: round(b.y + b.h * 0.322),
    w: round(b.w * 0.193),
    h: round(b.h * 0.305)
  };
  const shapes = [];
  topLabels.forEach((item, index) => {
    const labelBox = item.textBox.box;
    const gemBox = constrainPtBox({
      x: round(labelBox.x - 50),
      y: round(labelBox.y - 21),
      w: 56,
      h: 54
    }, { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt });
    const gemCrop = createAssetOsFlowIconCrop({
      image,
      box: gemBox,
      options,
      slideSize,
      id: `${prefix}-input-gem-crop-${index}`,
      role: "input-gem",
      label: item.label,
      cropName: `input-gem-${index + 1}`,
      padPt: 0.5
    });
    if (gemCrop) {
      iconImages.push(gemCrop);
    } else {
      shapes.push(...createValueQuadrantGemShapes({ id: prefix }, { name: `asset-${index + 1}`, label: item.label, box: gemBox })
        .map((shape) => ({
          ...shape,
          source: { ...(shape.source || {}), detector: "asset-os-flow-native-gem", role: "input-gem", layerSourceId: image.id || null }
        })));
    }
    shapes.push(assetOsShape(`${prefix}-input-label-${index}`, "roundRect", {
      x: round(labelBox.x - 6),
      y: round(labelBox.y - 2),
      w: round(labelBox.w + 16),
      h: round(labelBox.h + 8)
    }, {
      fill: "#21AA68",
      stroke: "#21AA68",
      strokeWidthPt: 0,
      radiusRatio: 0.18
    }, image, { role: "input-label-backplate", label: item.label }));
    nativeTextBoxes.push(assetOsFlowTextBox(`${prefix}-input-label-text-${index}`, item.label, {
      x: round(labelBox.x - 1),
      y: round(labelBox.y - 1),
      w: round(labelBox.w + 4),
      h: round(labelBox.h + 3)
    }, { sizePt: 12.2, color: "#FFFFFF", weight: "regular", align: "center" }, image, { role: "input-label", label: item.label }));
    const gemBottom = { x: gemBox.x + gemBox.w * 0.5, y: gemBox.y + gemBox.h * 0.95 };
    const trunkY = b.y + b.h * 0.235;
    const shieldTargets = [shield.x + shield.w * 0.23, shield.x + shield.w * 0.50, shield.x + shield.w * 0.77];
    const turnX = index === 1 ? gemBottom.x : shieldTargets[index];
    shapes.push(assetOsShape(`${prefix}-gem-route-vertical-${index}`, "line", lineBox(gemBottom, { x: gemBottom.x, y: trunkY }), {
      stroke: "#20AA62",
      strokeWidthPt: 9,
      connectorType: "straight",
      lineCap: "round"
    }, image, { role: "input-route", label: item.label }));
    if (Math.abs(turnX - gemBottom.x) > 5) {
      shapes.push(assetOsShape(`${prefix}-gem-route-horizontal-${index}`, "line", lineBox({ x: gemBottom.x, y: trunkY }, { x: turnX, y: trunkY }), {
        stroke: "#20AA62",
        strokeWidthPt: 9,
        connectorType: "straight",
        lineCap: "round"
      }, image, { role: "input-route", label: item.label }));
    }
    shapes.push(assetOsShape(`${prefix}-gem-route-down-${index}`, "line", lineBox({ x: turnX, y: trunkY }, { x: shieldTargets[index], y: shield.y + shield.h * 0.08 }), {
      stroke: "#20AA62",
      strokeWidthPt: 9,
      connectorType: "straight",
      lineCap: "round"
    }, image, { role: "input-route", label: item.label }));
  });

  const shieldCrop = createAssetOsFlowIconCrop({
    image,
    box: shield,
    options,
    slideSize,
    id: `${prefix}-central-shield-crop`,
    role: "central-shield",
    label: "中枢盾牌",
    cropName: "central-shield",
    padPt: 1
  });
  if (shieldCrop) {
    iconImages.push(shieldCrop);
  } else {
    shapes.push(...assetOsShieldShapes(prefix, shield, image));
  }
  bottomLabels.forEach((item, index) => {
    const labelBox = item.textBox.box;
    const card = {
      x: round(labelBox.x - b.w * 0.08),
      y: round(labelBox.y - b.h * 0.21),
      w: round(b.w * 0.30),
      h: round(b.h * 0.30)
    };
    shapes.push(assetOsShape(`${prefix}-output-card-${index}`, "roundRect", card, {
      fill: "#F1F1F1",
      stroke: "#E4E4E4",
      strokeWidthPt: 0.8,
      radiusRatio: 0.06,
      shadow: { color: "#000000", alpha: 0.07, blurPt: 6, distancePt: 1.2, angle: 45 }
    }, image, { role: "output-card", label: item.label }));
    const outputIconBox = {
      x: round(card.x + card.w * 0.27),
      y: round(card.y + card.h * 0.12),
      w: round(card.w * 0.46),
      h: round(card.h * 0.48)
    };
    const outputIconCrop = createAssetOsFlowIconCrop({
      image,
      box: outputIconBox,
      options,
      slideSize,
      id: `${prefix}-output-icon-crop-${index}`,
      role: "output-icon",
      label: item.label,
      cropName: `output-icon-${index + 1}`,
      padPt: 0.5
    });
    if (outputIconCrop) iconImages.push(outputIconCrop);
    else shapes.push(...assetOsOutputIconShapes(prefix, card, image, item.label, index));
    nativeTextBoxes.push(assetOsFlowTextBox(`${prefix}-output-label-text-${index}`, item.label, {
      x: round(card.x + card.w * 0.12),
      y: round(card.y + card.h * 0.72),
      w: round(card.w * 0.76),
      h: round(card.h * 0.23)
    }, { sizePt: 14.5, color: "#111111", weight: "regular", align: "center" }, image, { role: "output-label", label: item.label }));
    shapes.push(assetOsShape(`${prefix}-shield-to-output-${index}`, "line", lineBox(
      { x: shield.x + shield.w * 0.5, y: shield.y + shield.h },
      { x: card.x + card.w * 0.5, y: card.y }
    ), {
      stroke: "#D7DBE0",
      strokeWidthPt: 1.4,
      connectorType: "straight",
      dash: "dash"
    }, image, { role: "output-guide", label: item.label }));
  });

  return { shapes, images: iconImages, textBoxes: nativeTextBoxes };
}

function createAssetOsFlowIconCrop({ image, box, options = {}, slideSize = DEFAULT_SLIDE, id, role, label, cropName, padPt = 2 } = {}) {
  if (!options.sourceImage || !options.assetDir || !box || Number(box.w || 0) <= 0 || Number(box.h || 0) <= 0) return null;
  ensureDir(options.assetDir);
  const pageIndex = Number.isFinite(Number(options.pageIndex)) ? Number(options.pageIndex) : 0;
  const base = safeIdentifier(`${options.deckName || "deck"}-p${String(pageIndex + 1).padStart(2, "0")}-${image?.id || "asset-os-flow"}-${cropName || role || "icon"}`, "asset-os-flow-icon");
  const pxBox = ptToPxBox(expandPtBox(box, slideSize, padPt, padPt), options.sourceImage, slideSize, 0);
  const refinement = refineStandaloneIconCrop(cropPng(options.sourceImage, pxBox));
  const file = path.join(options.assetDir, `${base}.png`);
  writePng(file, refinement.image);
  const refinedPxBox = { x: pxBox.x + refinement.box.x, y: pxBox.y + refinement.box.y, w: refinement.box.w, h: refinement.box.h };
  return {
    id,
    type: "fidelity-crop",
    assetPath: path.relative(options.irDir || options.assetDir, file).replace(/\\/g, "/"),
    box: pxToPtBox(refinedPxBox, options.sourceImage, slideSize, 0),
    source: {
      editable: false,
      nativeRebuild: true,
      detector: "asset-os-flow-icon-crop",
      strategy: "local-fidelity-crop",
      expressionForm: "icon-or-illustration",
      expressionSubtype: "asset-os-flow-icon",
      recommendedAction: "keep-local-crop-for-complex-icon",
      intentionalMinimumUnitCrop: true,
      protectedMinimumUnit: true,
      skipVisualAtomRebuild: true,
      iconCropRefined: refinement.refined,
      removedNeighborPixels: refinement.removedNeighborPixels,
      layerSourceId: image?.id || null,
      ...assetOsFlowNativeComponentMetadata(image, role, label, "icon-crop"),
      role,
      label,
      nonEditableReason: "complex Asset OS gem/shield icon preserved as a local crop while surrounding flow structure is rebuilt natively"
    }
  };
}

function assetOsFlowTextBox(id, text, box, font, image, extra = {}) {
  const component = assetOsFlowNativeComponentMetadata(image, extra.role, extra.label, "label");
  return {
    id,
    text,
    box,
    font: {
      family: "Microsoft YaHei",
      opacity: 1,
      valign: "middle",
      ...font
    },
    style: { wrap: false, fit: "shrink", nativeComponentGroupId: component.nativeComponentGroupId },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "asset-os-flow-native-text",
      layerSourceId: image?.id || null,
      ...component,
      ...extra
    }
  };
}

function assetOsShape(id, type, box, style, image, extra = {}) {
  const component = assetOsFlowNativeComponentMetadata(image, extra.role, extra.label, extra.part || type);
  return {
    id,
    type,
    box,
    style,
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "asset-os-flow-native-component",
      layerSourceId: image?.id || null,
      layerType: image?.source?.layer?.layerType || "diagram-zone",
      ...component,
      ...(extra.role === "input-route" ? { preserveMeasuredSegments: true } : {}),
      ...extra
    }
  };
}

function assetOsFlowNativeComponentMetadata(image, role, label, part) {
  const normalizedRole = String(role || "");
  let componentRole = null;
  let archetype = null;
  if (/^input-/.test(normalizedRole)) {
    componentRole = `input-${assetOsFlowSemanticKey(label)}`;
    archetype = "asset-os-input-stage";
  } else if (/^central-shield/.test(normalizedRole)) {
    componentRole = "core";
    archetype = "asset-os-core";
  } else if (/^output-/.test(normalizedRole)) {
    componentRole = `output-${assetOsFlowSemanticKey(label)}`;
    archetype = "asset-os-output-stage";
  }
  if (!componentRole) return {};
  const base = safeComponentToken(image?.id || "asset-os-flow");
  return {
    nativeComponentGroupId: `${base}-asset-flow-${componentRole}`,
    nativeComponentParentId: `${base}-asset-flow`,
    nativeComponentArchetype: archetype,
    nativeComponentInstance: true,
    nativeComponentMinimumUnit: "semantic-component",
    nativeComponentRole: componentRole,
    nativeComponentPart: String(part || normalizedRole || "detail")
  };
}

function assetOsFlowSemanticKey(label) {
  const normalized = normalizeCjkText(label);
  const known = [
    [/标准化PRD/i, "standard-prd"],
    [/交互原型/, "interactive-prototype"],
    [/操作手册/, "operation-manual"],
    [/业务需求/, "business-requirement"],
    [/历史文档/, "historical-document"],
    [/飞书截图/, "feishu-screenshot"]
  ].find(([pattern]) => pattern.test(normalized));
  return known ? known[1] : safeComponentToken(label || "unknown");
}

function assetOsShieldShapes(prefix, box, image) {
  const outer = assetOsShape(`${prefix}-shield-outer`, "freeform", box, {
    fill: "#1F7DD4",
    stroke: "#1266B8",
    strokeWidthPt: 1.2,
    shadow: { color: "#1F7DD4", alpha: 0.18, blurPt: 5, distancePt: 0, angle: 0 }
  }, image, { role: "central-shield" });
  outer.points = [
    { x: 0.5, y: 0.00 },
    { x: 0.94, y: 0.14 },
    { x: 0.86, y: 0.58 },
    { x: 0.70, y: 0.82 },
    { x: 0.50, y: 1.00 },
    { x: 0.30, y: 0.82 },
    { x: 0.14, y: 0.58 },
    { x: 0.06, y: 0.14 }
  ];
  const inner = assetOsShape(`${prefix}-shield-inner`, "freeform", {
    x: round(box.x + box.w * 0.27),
    y: round(box.y + box.h * 0.21),
    w: round(box.w * 0.46),
    h: round(box.h * 0.58)
  }, {
    fill: "#FFFFFF",
    stroke: "#FFFFFF",
    strokeWidthPt: 0
  }, image, { role: "central-shield-inner" });
  inner.points = [
    { x: 0.5, y: 0.00 },
    { x: 0.92, y: 0.16 },
    { x: 0.82, y: 0.62 },
    { x: 0.50, y: 1.00 },
    { x: 0.18, y: 0.62 },
    { x: 0.08, y: 0.16 }
  ];
  return [outer, inner];
}

function assetOsOutputIconShapes(prefix, card, image, label, index) {
  const cx = card.x + card.w * 0.5;
  const icon = { x: round(cx - card.w * 0.17), y: round(card.y + card.h * 0.20), w: round(card.w * 0.34), h: round(card.h * 0.30) };
  if (/历史/.test(label)) {
    const folder = assetOsShape(`${prefix}-folder-tab-${index}`, "freeform", icon, {
      fill: "#9EA7B1",
      stroke: "#9EA7B1",
      strokeWidthPt: 0
    }, image, { role: "output-icon", label, part: "folder" });
    folder.points = [
      { x: 0, y: 0.22 },
      { x: 0.30, y: 0.22 },
      { x: 0.38, y: 0.08 },
      { x: 0.66, y: 0.08 },
      { x: 0.76, y: 0.22 },
      { x: 1, y: 0.22 },
      { x: 1, y: 1 },
      { x: 0, y: 1 }
    ];
    return [folder];
  }
  if (/截图/.test(label)) {
    const mountain = assetOsShape(`${prefix}-image-mountain-${index}`, "freeform", {
      x: round(icon.x + icon.w * 0.30),
      y: round(icon.y + icon.h * 0.42),
      w: round(icon.w * 0.60),
      h: round(icon.h * 0.34)
    }, { fill: "#6F7883", stroke: "#6F7883", strokeWidthPt: 0 }, image, { role: "output-icon", label, part: "image-mountain" });
    mountain.points = [{ x: 0, y: 1 }, { x: 0.34, y: 0.28 }, { x: 0.55, y: 0.72 }, { x: 0.73, y: 0.40 }, { x: 1, y: 1 }];
    return [
      assetOsShape(`${prefix}-chat-bubble-${index}`, "ellipse", {
        x: round(icon.x - icon.w * 0.16),
        y: round(icon.y - icon.h * 0.10),
        w: round(icon.w * 0.58),
        h: round(icon.h * 0.58)
      }, { fill: "#3D83D6", stroke: "#3D83D6", strokeWidthPt: 0 }, image, { role: "output-icon", label, part: "chat" }),
      assetOsShape(`${prefix}-image-frame-${index}`, "rect", {
        x: round(icon.x + icon.w * 0.20),
        y: round(icon.y + icon.h * 0.25),
        w: round(icon.w * 0.82),
        h: round(icon.h * 0.62)
      }, { fill: "#ADB6C1", stroke: "#ADB6C1", strokeWidthPt: 0 }, image, { role: "output-icon", label, part: "image" }),
      mountain
    ];
  }
  return [
    assetOsShape(`${prefix}-doc-page-${index}`, "document", icon, {
      fill: "#B6BEC8",
      stroke: "#B6BEC8",
      strokeWidthPt: 0
    }, image, { role: "output-icon", label, part: "document" }),
    assetOsShape(`${prefix}-doc-gear-${index}`, "ellipse", {
      x: round(icon.x + icon.w * 0.58),
      y: round(icon.y + icon.h * 0.60),
      w: round(icon.w * 0.34),
      h: round(icon.w * 0.34)
    }, {
      fill: "#8F98A3",
      stroke: "#8F98A3",
      strokeWidthPt: 0
    }, image, { role: "output-icon", label, part: "gear-dot" })
  ];
}

function createPortalPlatformDiagramObjects(images = [], textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const shapes = [];
  const generatedTextBoxes = [];
  for (const image of images || []) {
    if (!shouldObjectifyPortalPlatformDiagram(image, textBoxes, slideSize)) continue;
    const diagram = inferPortalPlatformDiagramLayout(image);
    if (!diagram) continue;
    image.source = {
      ...(image.source || {}),
      portalPlatformDiagramObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      objectifiedPortalPlatformShapes: diagram.shapes.length,
      objectifiedPortalPlatformTextBoxes: diagram.textBoxes.length,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "portal platform diagram crop"}; rebuilt portal platform architecture diagram as native editable components`
    };
    shapes.push(...diagram.shapes);
    generatedTextBoxes.push(...diagram.textBoxes);
  }
  return { shapes, textBoxes: generatedTextBoxes };
}

function shouldObjectifyPortalPlatformDiagram(image = {}, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  if (!box.w || !box.h || box.w < 760 || box.h < 200) return false;
  const layer = image.source?.layer || {};
  const understanding = layer.diagramUnderstanding || {};
  if (String(layer.layerType || "") !== "table-zone") return false;
  if (understanding.archetype !== "matrix-or-grid") return false;
  const nearby = normalizedTextsInsideBox(textBoxes, {
    x: Math.max(0, box.x - 20),
    y: box.y + box.h,
    w: Math.min(slideSize.widthPt, box.w + 40),
    h: Math.max(120, slideSize.heightPt - box.y - box.h)
  });
  return nearby.has(normalizeCjkText("统一入口：跨越业务域与系统"))
    && nearby.has(normalizeCjkText("资产沉淀：打破工具孤岛，让"))
    && nearby.has(normalizeCjkText("AI协作：依托底层Skills引"));
}

function inferPortalPlatformDiagramLayout(image = {}) {
  const b = image.box || {};
  const prefix = image.id || "portal-platform";
  const shapes = [];
  const textBoxes = [];
  const leftCards = ["业务需求", "系统菜单", "历史文档"].map((label, index) => ({
    label,
    box: {
      x: round(b.x + b.w * 0.003),
      y: round(b.y + b.h * (0.011 + index * 0.356)),
      w: round(b.w * 0.149),
      h: round(b.h * 0.283)
    }
  }));
  const platform = {
    x: round(b.x + b.w * 0.323),
    y: round(b.y + b.h * 0.014),
    w: round(b.w * 0.347),
    h: round(b.h * 0.973)
  };
  const portal = {
    x: round(b.x + b.w * 0.750),
    y: round(b.y + b.h * 0.257),
    w: round(b.w * 0.246),
    h: round(b.h * 0.487)
  };
  leftCards.forEach((card, index) => {
    const component = portalPlatformComponent(image, `input-${index}`, "portal-input-card");
    shapes.push(portalShape(`${prefix}-input-card-${index}`, "rect", card.box, {
      fill: "#E9EFF6",
      stroke: "#E1E8F0",
      strokeWidthPt: 0.8
    }, image, { role: "input-card", label: card.label, ...component, nativeComponentRole: "container" }));
    textBoxes.push(portalTextBox(`${prefix}-input-label-${index}`, card.label, card.box, 17, "#111111", "regular", image, { role: "input-card-label", ...component, nativeComponentRole: "label" }));
    const start = { x: card.box.x + card.box.w, y: card.box.y + card.box.h * 0.5 };
    const midX = b.x + b.w * 0.237;
    const routing = portalPlatformComponent(image, "input-routing", "portal-routing");
    shapes.push(portalShape(`${prefix}-input-route-horizontal-${index}`, "line", lineBox(start, { x: midX, y: start.y }), {
      stroke: "#8B929A",
      strokeWidthPt: 4.2,
      connectorType: "straight"
    }, image, { role: "input-route", label: card.label, ...routing, nativeComponentRole: `branch-${index}` }));
  });
  const midX = b.x + b.w * 0.237;
  const inputRouting = portalPlatformComponent(image, "input-routing", "portal-routing");
  shapes.push(portalShape(`${prefix}-input-route-join`, "line", lineBox(
    { x: midX, y: leftCards[0].box.y + leftCards[0].box.h * 0.5 },
    { x: midX, y: leftCards[2].box.y + leftCards[2].box.h * 0.5 }
  ), {
    stroke: "#8B929A",
    strokeWidthPt: 4.2,
    connectorType: "straight"
  }, image, { role: "input-route-join", ...inputRouting, nativeComponentRole: "join" }));
  shapes.push(portalShape(`${prefix}-input-arrow`, "line", lineBox(
    { x: midX, y: b.y + b.h * 0.49 },
    { x: platform.x - 3, y: b.y + b.h * 0.49 }
  ), {
    stroke: "#8B929A",
    strokeWidthPt: 4.2,
    connectorType: "straight",
    endArrow: "triangle"
  }, image, { role: "input-arrow", ...inputRouting, nativeComponentRole: "arrow" }));

  const platformComponent = portalPlatformComponent(image, "platform", "portal-platform-core");
  shapes.push(portalShape(`${prefix}-platform-card`, "rect", platform, {
    fill: "#176BBF",
    stroke: "#176BBF",
    strokeWidthPt: 0,
    shadow: { color: "#176BBF", alpha: 0.12, blurPt: 6, distancePt: 0, angle: 0 }
  }, image, { role: "platform-card", ...platformComponent, nativeComponentRole: "container" }));
  textBoxes.push(portalTextBox(`${prefix}-platform-title`, "PM Portal Platform", {
    x: platform.x + platform.w * 0.10,
    y: platform.y + platform.h * 0.22,
    w: platform.w * 0.80,
    h: platform.h * 0.14
  }, 24, "#FFFFFF", "bold", image, { role: "platform-title", ...platformComponent, nativeComponentRole: "title" }));
  shapes.push(...portalPlatformIconShapes(prefix, platform, image, platformComponent));
  const outputRouting = portalPlatformComponent(image, "output-routing", "portal-routing");
  shapes.push(portalShape(`${prefix}-output-arrow`, "line", lineBox(
    { x: platform.x + platform.w, y: platform.y + platform.h * 0.50 },
    { x: portal.x - 3, y: portal.y + portal.h * 0.50 }
  ), {
    stroke: "#28AA65",
    strokeWidthPt: 6,
    connectorType: "straight",
    endArrow: "triangle"
  }, image, { role: "output-arrow", ...outputRouting, nativeComponentRole: "arrow" }));

  const portalComponent = portalPlatformComponent(image, "unified-portal", "unified-portal-card");
  shapes.push(portalShape(`${prefix}-portal-frame`, "roundRect", portal, {
    fill: "#FFFFFF",
    stroke: "#176BBF",
    strokeWidthPt: 3,
    radiusRatio: 0.04
  }, image, { role: "portal-frame", ...portalComponent, nativeComponentRole: "frame" }));
  textBoxes.push(portalTextBox(`${prefix}-portal-title`, "统一门户", {
    x: portal.x + portal.w * 0.12,
    y: portal.y + portal.h * 0.16,
    w: portal.w * 0.76,
    h: portal.h * 0.20
  }, 19, "#111111", "bold", image, { role: "portal-title", ...portalComponent, nativeComponentRole: "title" }));
  ["系统入口", "PRD资产", "原型资产"].forEach((label, index) => {
    const pill = {
      x: round(portal.x + portal.w * (0.06 + index * 0.31)),
      y: round(portal.y + portal.h * 0.58),
      w: round(portal.w * 0.27),
      h: round(portal.h * 0.212)
    };
    shapes.push(portalShape(`${prefix}-portal-pill-${index}`, "roundRect", pill, {
      fill: "#176BBF",
      stroke: "#176BBF",
      strokeWidthPt: 0,
      radiusRatio: 0.12
    }, image, { role: "portal-pill", label, ...portalComponent, nativeComponentRole: `pill-${index}` }));
    textBoxes.push(portalTextBox(`${prefix}-portal-pill-label-${index}`, label, pill, 9.5, "#FFFFFF", "regular", image, { role: "portal-pill-label", ...portalComponent, nativeComponentRole: `pill-label-${index}` }));
  });
  return { shapes, textBoxes };
}

function portalPlatformIconShapes(prefix, platform, image, component = {}) {
  const iconY = platform.y + platform.h * 0.53;
  const iconW = platform.w * 0.13;
  const xs = [0.22, 0.50, 0.76].map((ratio) => platform.x + platform.w * ratio - iconW / 2);
  const folder = portalShape(`${prefix}-platform-folder`, "freeform", { x: round(xs[0]), y: round(iconY), w: round(iconW), h: round(iconW * 0.72) }, {
    fill: "#FFFFFF",
    stroke: "#FFFFFF",
    strokeWidthPt: 0
  }, image, { role: "platform-icon", part: "folder", ...component, nativeComponentRole: "folder-icon" });
  folder.points = [
    { x: 0, y: 0.24 },
    { x: 0.34, y: 0.24 },
    { x: 0.42, y: 0.08 },
    { x: 0.74, y: 0.08 },
    { x: 0.82, y: 0.24 },
    { x: 1, y: 0.24 },
    { x: 1, y: 1 },
    { x: 0, y: 1 }
  ];
  return [
    folder,
    portalShape(`${prefix}-platform-document`, "document", { x: round(xs[1]), y: round(iconY - 3), w: round(iconW * 0.82), h: round(iconW * 0.90) }, {
      fill: "#FFFFFF",
      stroke: "#FFFFFF",
      strokeWidthPt: 0
    }, image, { role: "platform-icon", part: "document", ...component, nativeComponentRole: "document-icon" }),
    portalShape(`${prefix}-platform-wireframe-frame`, "rect", { x: round(xs[2]), y: round(iconY - 2), w: round(iconW), h: round(iconW * 0.86) }, {
      fill: "none",
      stroke: "#FFFFFF",
      strokeWidthPt: 2
    }, image, { role: "platform-icon", part: "wireframe", ...component, nativeComponentRole: "wireframe-frame" }),
    portalShape(`${prefix}-platform-wireframe-line-a`, "line", lineBox({ x: xs[2], y: iconY + iconW * 0.22 }, { x: xs[2] + iconW, y: iconY + iconW * 0.62 }), {
      stroke: "#FFFFFF",
      strokeWidthPt: 1.6,
      connectorType: "straight"
    }, image, { role: "platform-icon", part: "wireframe", ...component, nativeComponentRole: "wireframe-line-a" }),
    portalShape(`${prefix}-platform-wireframe-line-b`, "line", lineBox({ x: xs[2] + iconW, y: iconY + iconW * 0.22 }, { x: xs[2], y: iconY + iconW * 0.62 }), {
      stroke: "#FFFFFF",
      strokeWidthPt: 1.6,
      connectorType: "straight"
    }, image, { role: "platform-icon", part: "wireframe", ...component, nativeComponentRole: "wireframe-line-b" })
  ];
}

function portalPlatformComponent(image = {}, role = "component", archetype = "portal-platform-diagram") {
  const base = safeComponentToken(image.id || "portal-platform");
  const safeRole = safeComponentToken(role);
  return {
    nativeComponentInstance: true,
    nativeComponentGroupId: `${base}-portal-${safeRole}`,
    nativeComponentArchetype: archetype,
    componentOwnerId: `${base}-portal-${safeRole}`,
    componentOwnerKind: archetype
  };
}

function portalShape(id, type, box, style, image, extra = {}) {
  return {
    id,
    type,
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(box.w),
      h: round(box.h)
    },
    style,
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "portal-platform-native-component",
      layerSourceId: image?.id || null,
      layerType: image?.source?.layer?.layerType || "table-zone",
      ...extra
    }
  };
}

function portalTextBox(id, text, box, sizePt, color, weight, image, extra = {}) {
  return {
    id,
    text,
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(box.w),
      h: round(box.h)
    },
    font: {
      family: "Microsoft YaHei",
      sizePt,
      color,
      opacity: 1,
      weight,
      align: "center",
      valign: "middle"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "portal-platform-native-text",
      layerSourceId: image?.id || null,
      ...extra
    }
  };
}

function createSystemMapDiagramObjects(images = [], textBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  return composeSystemMapDiagram(images, textBoxes, slideSize, options, {
    shouldObjectify: shouldObjectifySystemMapDiagram,
    inferLayout: inferSystemMapDiagramLayout,
    createNetworkCrop: createSystemMapNetworkFidelityCrop,
    compactLines: compactSystemMapLineFamilies,
    boxCenterInside
  });
}

function createSystemMapNetworkFidelityCrop(target = {}, slideSize = DEFAULT_SLIDE, options = {}) {
  if (!options.sourceImage || !options.assetDir || !options.irDir) return null;
  const b = target.box || {};
  if (!b.w || !b.h) return null;
  const cropBox = clampPtBoxToSlide({
    x: Number(b.x || 0) + Number(b.w || 0) * 0.325,
    // Keep the map heading editable as a single native text box. The dense
    // network starts below it, so beginning the fidelity unit at 18% avoids
    // doubling the title while retaining micro-label topology.
    y: Number(b.y || 0) + Number(b.h || 0) * 0.18,
    w: Number(b.w || 0) * 0.455,
    h: Number(b.h || 0) * 0.7
  }, slideSize);
  const pageIndex = Number.isFinite(Number(options.pageIndex)) ? Number(options.pageIndex) : 0;
  const base = safeIdentifier(`${options.deckName || "deck"}-p${String(pageIndex + 1).padStart(2, "0")}-system-map-network`, "system-map-network");
  return materializeFidelityCrop({
    id: `${target.id || "system-map"}-network-fidelity-unit`,
    sourceImage: options.sourceImage,
    cropBox,
    slideSize,
    assetDir: options.assetDir,
    irDir: options.irDir,
    fileName: `${base}-fidelity-unit.png`,
    source: {
      nativeRebuild: true,
      detector: "system-map-network-fidelity-crop",
      strategy: "local-fidelity-crop",
      expressionFamily: "generic-structured-diagram",
      expressionForm: "complex-diagram",
      expressionSubtype: "dense-system-map-network-minimum-unit",
      recommendedAction: "preserve-local-crop",
      layerType: "diagram-zone",
      authoritativeExpressionMetadata: true,
      intentionalMinimumUnitCrop: true,
      protectedMinimumUnit: true,
      skipVisualAtomRebuild: true,
      sourceFaithfulCrop: true,
      systemMapHybridNetworkCrop: true,
      layerSourceId: target.id || null,
      largeFidelityCropApproved: true,
      largeFidelityCropApprovalReason: "the dense central system-map network and micro labels form one pictorial minimum unit; outer mapping rails, asset grid, search chrome, and external labels remain native editable components",
      componentRenderStrategy: {
        mode: "preserve-crop-with-native-overlays",
        implementationMode: "hybrid-native-overlay",
        editableExpectation: "central-network-fidelity-unit-with-native-outer-rails-grid-and-chrome",
        visualFidelityBias: "source-faithful"
      },
      nonEditableReason: "dense central topology and micro labels remain one source-faithful diagram minimum unit"
    }
  }, { ptToPxBox, pxToPtBox, cropPng, writePng, ensureDir });
}

function compactSystemMapLineFamilies(shapes = [], image = {}) {
  const denseEdgeDetectors = new Set([
    "system-map-native-network-edge",
    "system-map-native-network-detail-edge"
  ]);
  const compactionAnnotated = (shapes || []).map((shape) => {
    if (!denseEdgeDetectors.has(String(shape?.source?.detector || ""))) return shape;
    return {
      ...shape,
      source: {
        ...(shape.source || {}),
        compactionEligible: true,
        compactionPartition: String(shape.source?.axis || "") || undefined
      }
    };
  });
  return compactDenseTopologyLineFamilies(compactionAnnotated, {
    ownerId: `${image.id || "system-map"}-native-system-map-component`,
    ownerKind: "system-map-diagram",
    maxLinesPerCompound: 64
  });
}

function shouldObjectifySystemMapDiagram(image = {}, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const box = image?.box || {};
  const area = Number(box.w || 0) * Number(box.h || 0);
  const slideArea = Math.max(1, Number(slideSize.widthPt || 0) * Number(slideSize.heightPt || 0));
  if (area / slideArea < 0.35 || box.w < 700 || box.h < 300) return false;
  const source = image.source || {};
  if (source.systemMapDiagramObjectified === true) return false;
  if (!/line-diagram|graphic-underlay|dense-line/i.test(String(source.detector || ""))) return false;
  const allText = (textBoxes || []).map((item) => String(item.text || "")).join(" ");
  return /产品版图|System\s*Map/i.test(allText)
    && /数字化产品大脑|产品大脑/.test(allText);
}

function inferSystemMapDiagramLayout(image = {}, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const b = image.box || {};
  const prefix = image.id || "system-map";
  const shapes = [];
  const generatedTextBoxes = [];
  const source = {
    editable: true,
    nativeRebuild: true,
    layerSourceId: image.id || null,
    componentOwnerId: `${prefix}-native-system-map-component`,
    componentOwnerKind: "system-map-diagram",
    nativeComponentInstance: true,
    nativeComponentGroupId: `${prefix}-native-system-map-component`,
    nativeComponentArchetype: "system-map-diagram",
    nativeComponentRole: "system-map-structure",
    confidence: 0.86
  };
  let sourceImage = null;
  const sourceImageFile = findSystemMapSourceImageFile(textBoxes);
  if (sourceImageFile) {
    try {
      sourceImage = readPng(sourceImageFile);
    } catch {
      sourceImage = null;
    }
  }
  shapes.push(...systemMapDottedBackgroundShapes(prefix, b, slideSize, source));
  shapes.push(...systemMapSearchChromeShapes(prefix, textBoxes, slideSize, source));
  shapes.push(...systemMapBottomGridShapes(prefix, b, source));
  const measuredMappingLines = sourceImage
    ? detectSystemMapSourceMappingLineShapes(prefix, sourceImage, b, slideSize, source)
    : [];
  shapes.push(...(measuredMappingLines.length >= 40 ? measuredMappingLines : systemMapMappingLineShapes(prefix, b, source)));
  const sourceNetwork = systemMapSourceDetectedNetworkLayout(prefix, b, textBoxes, slideSize, source);
  const network = sourceNetwork || systemMapNetworkLayout(b);
  const rails = systemMapNetworkRailLayout(prefix, b, source);
  shapes.push(...(network.edgeShapes || systemMapOrthogonalNetworkEdgeShapes(prefix, network.edges, source)));
  shapes.push(...network.nodes.map((node, index) => systemMapShape(`${prefix}-native-network-node-${index}`, node.kind === "circle" ? "ellipse" : "rect", {
    x: node.x - node.size / 2,
    y: node.y - node.size / 2,
    w: node.size,
    h: node.size
  }, {
    fill: "#126CB4",
    stroke: "#126CB4",
    strokeWidthPt: 0.6
  }, {
    ...source,
    detector: "system-map-native-network-node",
    nodeKind: node.kind,
    sourceImageDetected: node.sourceImageDetected === true || undefined,
    detectionMethod: node.detectionMethod || undefined
  })));
  const sourceDetectedDetails = systemMapSourceDetectedNetworkDetailShapes(prefix, b, textBoxes, slideSize, source);
  shapes.push(...(sourceDetectedDetails.length ? sourceDetectedDetails : systemMapDenseNetworkDetailShapes(prefix, b, source)));
  shapes.push(...rails.shapes);
  generatedTextBoxes.push(...systemMapBottomLabelTextBoxes(prefix, b, source));
  generatedTextBoxes.push(...rails.textBoxes);
  return { shapes, textBoxes: generatedTextBoxes };
}

function systemMapDottedBackgroundShapes(prefix, b, slideSize = DEFAULT_SLIDE, source = {}) {
  const shapes = [];
  const dot = Math.max(0.55, Math.min(0.9, b.w * 0.00095));
  const xStep = b.w * 0.011;
  const yStep = b.h * 0.021;
  const startX = Math.max(6, b.x - b.w * 0.035);
  const endX = Math.min(Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) - 6, b.x + b.w * 1.035);
  const startY = Math.max(4, b.y - b.h * 0.285);
  const endY = Math.min(Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt) - 6, b.y + b.h * 1.005);
  // Dots are texture only; cap them tightly so dense maps stay responsive in PowerPoint.
  const maxDecorativeDots = 30;
  const estimatedColumns = Math.max(1, Math.floor((endX - startX) / Math.max(1, xStep)));
  const estimatedRows = Math.max(1, Math.floor((endY - startY) / Math.max(1, yStep)));
  const estimatedCandidateDots = Math.max(1, Math.ceil((estimatedColumns * estimatedRows) / 2));
  const keepEvery = Math.max(1, Math.ceil(estimatedCandidateDots / maxDecorativeDots));
  let index = 0;
  let kept = 0;
  for (let y = startY; y <= endY; y += yStep) {
    for (let x = startX; x <= endX; x += xStep) {
      if (index % 2 === 0 && kept % keepEvery === 0) {
        shapes.push(systemMapShape(`${prefix}-native-background-dot-${index}`, "ellipse", {
          x,
          y,
          w: dot,
          h: dot
        }, {
          fill: "#D9E0E7",
          stroke: "#D9E0E7",
          strokeWidthPt: 0,
          opacity: 0.88
        }, {
          ...source,
          detector: "system-map-native-background-dot",
          decorativeTexture: true,
          minimumUnitPolicy: "sampled-decorative-texture",
          dotIndex: index
        }));
      }
      if (index % 2 === 0) kept += 1;
      index += 1;
    }
  }
  return shapes;
}

function systemMapSearchChromeShapes(prefix, textBoxes = [], slideSize = DEFAULT_SLIDE, source = {}) {
  const searchText = (textBoxes || []).find((item) => /多域资产|全景搜索|全景搜素/.test(String(item.text || "")));
  const searchBox = searchText?.box
    ? {
        x: round(slideSize.widthPt - 258),
        y: round(Math.max(31, Math.min(34, searchText.box.y - 8))),
        w: 224,
        h: 31.5
      }
    : { x: slideSize.widthPt - 258, y: 33, w: 224, h: 31 };
  const lens = { x: searchBox.x + 14, y: searchBox.y + searchBox.h * 0.27, w: searchBox.h * 0.36, h: searchBox.h * 0.36 };
  return [
    systemMapShape(`${prefix}-native-search-box`, "roundRect", searchBox, {
      fill: "#FFFFFF",
      stroke: "#175D8A",
      strokeWidthPt: 1.2,
      radiusPt: 3
    }, { ...source, detector: "system-map-native-search" }),
    systemMapShape(`${prefix}-native-search-lens`, "ellipse", lens, {
      fill: "none",
      stroke: "#175D8A",
      strokeWidthPt: 1.7
    }, { ...source, detector: "system-map-native-search" }),
    systemMapLine(`${prefix}-native-search-handle`, {
      x: lens.x + lens.w * 0.78,
      y: lens.y + lens.h * 0.78
    }, {
      x: lens.x + lens.w * 1.28,
      y: lens.y + lens.h * 1.28
    }, "#175D8A", 1.8, { ...source, detector: "system-map-native-search" })
  ];
}

function systemMapBottomGridShapes(prefix, b, source = {}) {
  const shapes = [];
  const blue = "#126CB4";
  // The source is a 111 x 3 matrix of square assets, not a dashed rule. Keep
  // the individual tiles editable while packing each short run into one shape.
  const rows = 3;
  const cols = 111;
  const startX = b.x + b.w * 0.0034;
  const startY = b.y + b.h * 0.9318;
  const cellW = Math.max(4.9, Math.min(5.5, b.w * 0.00615));
  const cellH = Math.max(4.9, Math.min(5.5, b.h * 0.014));
  const gapX = Math.max(2.45, Math.min(2.8, b.w * 0.00305));
  const gapY = Math.max(2.1, Math.min(2.4, b.h * 0.006));
  const tilesPerShape = 20;
  for (let row = 0; row < rows; row += 1) {
    for (let firstColumn = 0; firstColumn < cols; firstColumn += tilesPerShape) {
      const tileCount = Math.min(tilesPerShape, cols - firstColumn);
      const x = startX + firstColumn * (cellW + gapX);
      const y = startY + row * (cellH + gapY);
      const w = tileCount * cellW + (tileCount - 1) * gapX;
      const h = cellH;
      shapes.push(systemMapShape(`${prefix}-native-asset-grid-row-${row}-part-${Math.floor(firstColumn / tilesPerShape)}`, "freeform", {
        x,
        y,
        w,
        h
      }, {
        fill: blue,
        stroke: "none",
        strokeWidthPt: 0,
        closePath: false,
        freeformSegments: systemMapAssetGridTileSegments(tileCount, cellW, gapX, w)
      }, {
        ...source,
        detector: "system-map-native-asset-grid",
        row,
        part: Math.floor(firstColumn / tilesPerShape),
        tileCount,
        decorativeTexture: true,
        nativeComponentMinimumUnit: "asset-grid-tile-run",
        minimumUnitPolicy: "source-sampled-asset-grid-tile-run"
      }));
    }
  }
  return shapes;
}

function systemMapAssetGridTileSegments(tileCount, cellW, gapX, rowWidth) {
  const segments = [];
  const safeWidth = Math.max(0.01, Number(rowWidth || 0));
  for (let index = 0; index < tileCount; index += 1) {
    const left = (index * (cellW + gapX)) / safeWidth;
    const right = (index * (cellW + gapX) + cellW) / safeWidth;
    segments.push(
      { type: "moveTo", points: [{ x: left, y: 0 }] },
      { type: "lnTo", points: [{ x: right, y: 0 }] },
      { type: "lnTo", points: [{ x: right, y: 1 }] },
      { type: "lnTo", points: [{ x: left, y: 1 }] },
      { type: "close", points: [] }
    );
  }
  return segments;
}

function systemMapMappingLineShapes(prefix, b, source = {}) {
  const shapes = [];
  const green = "#4CBF8A";
  const leftX = b.x + b.w * 0.003;
  const rightX = b.x + b.w * 0.997;
  const centerLeftX = b.x + b.w * 0.530;
  const centerRightX = b.x + b.w * 0.565;
  const bottomY = b.y + b.h * 0.925;
  const topY = b.y + b.h * 0.672;
  const sideLineCount = 31;
  for (let index = 0; index < sideLineCount; index += 1) {
    const y = b.y + b.h * (0.020 + index * 0.0198);
    const x = leftX + index * (b.w * 0.0069);
    shapes.push(systemMapLine(`${prefix}-native-left-map-horizontal-${index}`, { x: leftX, y }, { x: b.x + b.w * 0.340, y }, green, 1.15, {
      ...source,
      detector: "system-map-native-mapping-line",
      side: "left",
      index
    }));
    shapes.push(systemMapLine(`${prefix}-native-left-map-vertical-${index}`, { x, y }, { x, y: bottomY }, green, 1.15, {
      ...source,
      detector: "system-map-native-mapping-line",
      side: "left",
      index
    }));
  }
  for (let index = 0; index < sideLineCount; index += 1) {
    const y = b.y + b.h * (0.020 + index * 0.0198);
    const x = rightX - index * (b.w * 0.0069);
    shapes.push(systemMapLine(`${prefix}-native-right-map-horizontal-${index}`, { x: b.x + b.w * 0.660, y }, { x: rightX, y }, green, 1.15, {
      ...source,
      detector: "system-map-native-mapping-line",
      side: "right",
      index
    }));
    shapes.push(systemMapLine(`${prefix}-native-right-map-vertical-${index}`, { x, y }, { x, y: bottomY }, green, 1.15, {
      ...source,
      detector: "system-map-native-mapping-line",
      side: "right",
      index
    }));
  }
  for (let index = 0; index < 24; index += 1) {
    const x = centerLeftX + (centerRightX - centerLeftX) * (index / 23);
    shapes.push(systemMapLine(`${prefix}-native-center-map-vertical-${index}`, { x, y: topY }, { x, y: bottomY }, green, 0.95, {
      ...source,
      detector: "system-map-native-mapping-line",
      side: "center",
      index
    }));
  }
  return shapes;
}

function detectSystemMapSourceMappingLineShapes(prefix, image = {}, b = {}, slideSize = DEFAULT_SLIDE, source = {}) {
  const region = ptToPxBox(b, image, slideSize, 0);
  const horizontalBands = detectSystemMapGreenAxisBands(image, region, "h");
  const verticalBands = detectSystemMapGreenAxisBands(image, region, "v");
  const shapes = [];
  horizontalBands.forEach((band, bandIndex) => {
    const runs = detectSystemMapGreenRuns(image, region, "h", band.center, Math.max(40, region.w * 0.08));
    runs.forEach((run, runIndex) => {
      const start = pxToPtBox({ x: run.start, y: band.center, w: 1, h: 1 }, image, slideSize, 0);
      const end = pxToPtBox({ x: run.end, y: band.center, w: 1, h: 1 }, image, slideSize, 0);
      const midX = (start.x + end.x) / 2;
      shapes.push(systemMapLine(`${prefix}-native-source-map-horizontal-${bandIndex}-${runIndex}`, start, end, "#4CBF8A", 1.15, {
        ...source,
        detector: "system-map-native-mapping-line",
        side: midX < b.x + b.w * 0.5 ? "left" : "right",
        axis: "h",
        sourceImageDetected: true
      }));
    });
  });
  verticalBands.forEach((band, bandIndex) => {
    const runs = detectSystemMapGreenRuns(image, region, "v", band.center, Math.max(30, region.h * 0.10));
    runs.forEach((run, runIndex) => {
      const start = pxToPtBox({ x: band.center, y: run.start, w: 1, h: 1 }, image, slideSize, 0);
      const end = pxToPtBox({ x: band.center, y: run.end, w: 1, h: 1 }, image, slideSize, 0);
      const ratio = (start.x - b.x) / Math.max(1, b.w);
      const side = ratio < 0.45 ? "left" : ratio > 0.60 ? "right" : "center";
      shapes.push(systemMapLine(`${prefix}-native-source-map-vertical-${bandIndex}-${runIndex}`, start, end, "#4CBF8A", 1.15, {
        ...source,
        detector: "system-map-native-mapping-line",
        side,
        axis: "v",
        sourceImageDetected: true
      }));
    });
  });
  return shapes;
}

function detectSystemMapGreenAxisBands(image = {}, region = {}, axis = "h") {
  const length = axis === "h" ? region.h : region.w;
  const cross = axis === "h" ? region.w : region.h;
  const threshold = Math.max(8, Math.floor(cross * 0.055));
  const candidates = [];
  for (let offset = 0; offset < length; offset += 1) {
    let hits = 0;
    for (let crossOffset = 0; crossOffset < cross; crossOffset += 2) {
      const x = axis === "h" ? region.x + crossOffset : region.x + offset;
      const y = axis === "h" ? region.y + offset : region.y + crossOffset;
      if (isSystemMapGreenPixel(pixel(image, x, y))) hits += 1;
    }
    if (hits >= threshold) candidates.push((axis === "h" ? region.y : region.x) + offset);
  }
  return groupAxisPositions(candidates, 3).map((group) => ({
    start: group[0],
    end: group[group.length - 1],
    center: Math.round(group.reduce((sum, value) => sum + value, 0) / group.length)
  }));
}

function detectSystemMapGreenRuns(image = {}, region = {}, axis = "h", position = 0, minimumLength = 40) {
  const start = axis === "h" ? region.x : region.y;
  const end = start + (axis === "h" ? region.w : region.h);
  const hits = [];
  for (let value = start; value < end; value += 1) {
    let matched = false;
    for (let delta = -2; delta <= 2 && !matched; delta += 1) {
      const x = axis === "h" ? value : position + delta;
      const y = axis === "h" ? position + delta : value;
      matched = isSystemMapGreenPixel(pixel(image, x, y));
    }
    if (matched) hits.push(value);
  }
  return groupAxisPositions(hits, 4)
    .map((group) => ({ start: group[0], end: group[group.length - 1] }))
    .filter((run) => run.end - run.start >= minimumLength);
}

function groupAxisPositions(values = [], maximumGap = 1) {
  const groups = [];
  for (const value of values) {
    const current = groups[groups.length - 1];
    if (!current || value - current[current.length - 1] > maximumGap) groups.push([value]);
    else current.push(value);
  }
  return groups;
}

function isSystemMapGreenPixel(color = {}) {
  const r = Number(color.r || 0);
  const g = Number(color.g || 0);
  const b = Number(color.b || 0);
  return g >= 105 && r <= 175 && g - r >= 22 && g - b >= 8;
}

function systemMapNetworkRailLayout(prefix, b, source = {}) {
  const labels = {
    left: ["IP-PBC", "PPS-C", "需求池", "评审流", "知识库", "领域资产", "交付工单", "运营视图"],
    right: ["BPM", "MKT", "MFG", "HR", "SCM", "财务", "门户"]
  };
  const blue = "#126CB4";
  const makeRail = (side, x, yStart, gap, w, h) => labels[side].map((text, index) => {
    const y = yStart + index * gap;
    return {
      shape: systemMapShape(`${prefix}-native-${side}-rail-module-${index}`, "rect", { x, y, w, h }, {
        fill: blue,
        stroke: blue,
        strokeWidthPt: 0
      }, {
        ...source,
        detector: "system-map-native-network-rail-module",
        side,
        index
      }),
      textBox: {
        id: `${prefix}-native-${side}-rail-label-${index}`,
        text,
        box: { x: round(x + 1), y: round(y + h * 0.22), w: round(w - 2), h: round(h * 0.58) },
        font: {
          family: "Microsoft YaHei",
          sizePt: 3.6,
          color: "#FFFFFF",
          opacity: 1,
          weight: "regular",
          align: "center",
          valign: "middle"
        },
        source: {
          ...source,
          detector: "system-map-native-network-rail-label",
          side,
          index
        }
      }
    };
  });
  const left = makeRail("left", b.x + b.w * 0.335, b.y + b.h * 0.150, b.h * 0.083, b.w * 0.022, b.h * 0.050);
  const right = makeRail("right", b.x + b.w * 0.735, b.y + b.h * 0.150, b.h * 0.094, b.w * 0.024, b.h * 0.056);
  return {
    shapes: [...left, ...right].map((item) => item.shape),
    textBoxes: [...left, ...right].map((item) => item.textBox)
  };
}

function systemMapNetworkLayout(b) {
  const nodeSpecs = [
    [0.34, 0.12, "rect", 15], [0.39, 0.13, "rect", 13], [0.45, 0.12, "rect", 14], [0.53, 0.10, "rect", 16], [0.59, 0.16, "rect", 14], [0.68, 0.13, "rect", 16], [0.76, 0.14, "rect", 15],
    [0.34, 0.25, "rect", 15], [0.39, 0.25, "rect", 15], [0.42, 0.30, "circle", 15], [0.46, 0.28, "rect", 15], [0.52, 0.24, "circle", 16], [0.57, 0.26, "rect", 14], [0.64, 0.28, "rect", 14], [0.73, 0.27, "circle", 15],
    [0.35, 0.42, "circle", 16], [0.41, 0.41, "circle", 15], [0.47, 0.42, "rect", 13], [0.51, 0.40, "rect", 15], [0.56, 0.40, "rect", 13], [0.61, 0.42, "rect", 15], [0.66, 0.41, "circle", 16], [0.76, 0.42, "circle", 15],
    [0.35, 0.56, "circle", 15], [0.40, 0.57, "circle", 15], [0.45, 0.56, "rect", 14], [0.54, 0.55, "rect", 14], [0.61, 0.56, "circle", 15], [0.68, 0.56, "rect", 15], [0.77, 0.57, "circle", 15],
    [0.36, 0.71, "rect", 14], [0.46, 0.69, "rect", 15], [0.51, 0.70, "rect", 16], [0.56, 0.70, "rect", 14], [0.66, 0.72, "rect", 15], [0.72, 0.72, "rect", 15]
  ];
  const nodes = nodeSpecs.map(([rx, ry, kind, size]) => ({ x: b.x + b.w * rx, y: b.y + b.h * ry, kind, size }));
  const edgePairs = [
    [0, 1], [1, 2], [2, 10], [3, 4], [3, 11], [4, 12], [5, 6], [5, 14], [6, 14],
    [7, 8], [8, 15], [8, 9], [9, 10], [10, 17], [11, 18], [12, 19], [13, 20], [14, 21], [14, 22],
    [15, 23], [15, 16], [16, 24], [17, 25], [18, 26], [18, 19], [19, 27], [20, 21], [21, 28], [22, 29],
    [23, 30], [24, 30], [25, 31], [26, 32], [27, 33], [28, 34], [29, 35], [31, 32], [32, 33], [34, 35],
    [2, 18], [10, 19], [12, 20], [20, 28], [24, 32], [25, 33], [5, 13], [13, 21], [6, 22], [22, 35]
  ];
  return {
    nodes,
    edges: edgePairs.map(([from, to]) => ({ from: nodes[from], to: nodes[to] }))
  };
}

function systemMapSourceDetectedNetworkLayout(prefix, b, textBoxes = [], slideSize = DEFAULT_SLIDE, source = {}) {
  const sourceImageFile = findSystemMapSourceImageFile(textBoxes);
  if (!sourceImageFile) return null;
  let sourceImage = null;
  try {
    sourceImage = readPng(sourceImageFile);
  } catch {
    return null;
  }
  const nodes = detectSystemMapMainNetworkNodes(sourceImage, b, slideSize);
  if (nodes.length < 24) return null;
  const edgeShapes = detectSystemMapSourceNetworkLineShapes(prefix, sourceImage, b, slideSize, nodes, source);
  if (edgeShapes.length < 32) return null;
  return {
    nodes,
    edgeShapes
  };
}

function detectSystemMapMainNetworkNodes(image = {}, b = {}, slideSize = DEFAULT_SLIDE) {
  return detectDenseLinkedNodeAtoms(image, b, slideSize, {
    idPrefix: "system-map-main-node",
    subRegionRatios: { x: 0.335, y: 0.105, w: 0.450, h: 0.650 },
    isTargetPixel: isSystemMapBluePixel,
    maxNodes: 54,
    minConnectedNodes: 18,
    maxNodeSizePt: 25,
    outputMaxSizePt: 18
  }).map((atom) => ({
    x: round(atom.center.x),
    y: round(atom.center.y),
    size: round(Math.max(9, Math.min(18, Math.max(Number(atom.box?.w || 0), Number(atom.box?.h || 0))))),
    kind: atom.shapeHint === "ellipse" ? "circle" : "rect",
    sourceImageDetected: true,
    detectionMethod: atom.source?.method || "dense-linked-node",
    sourceAtomId: atom.id
  }));
}

function detectSystemMapSourceNetworkLineShapes(prefix, image = {}, b = {}, slideSize = DEFAULT_SLIDE, nodes = [], source = {}) {
  const pxRegion = ptToPxBox({
    x: b.x + b.w * 0.325,
    y: b.y + b.h * 0.100,
    w: b.w * 0.470,
    h: b.h * 0.680
  }, image, slideSize, 0);
  const nodeMasks = nodes.map((node) => ptToPxBox({
    x: Number(node.x || 0) - Number(node.size || 0) / 2,
    y: Number(node.y || 0) - Number(node.size || 0) / 2,
    w: Number(node.size || 0),
    h: Number(node.size || 0)
  }, image, slideSize, 2));
  const horizontalRuns = detectSystemMapSourceAxisRuns(image, pxRegion, nodeMasks, "h", slideSize)
    .map((run) => ({ ...run, axis: "h" }));
  const verticalRuns = detectSystemMapSourceAxisRuns(image, pxRegion, nodeMasks, "v", slideSize)
    .map((run) => ({ ...run, axis: "v" }));
  const filteredRuns = filterSystemMapSourceNetworkRuns([...horizontalRuns, ...verticalRuns], nodes);
  const horizontal = filteredRuns
    .filter((run) => run.axis === "h")
    .slice(0, 80)
    .map((run, index) => systemMapLine(`${prefix}-native-network-source-horizontal-${index}`, run.from, run.to, "#126CB4", 1.25, {
      ...source,
      detector: "system-map-native-network-edge",
      route: "source-orthogonal",
      sourceImageDetected: true,
      axis: "h",
      runIndex: index
    }));
  const vertical = filteredRuns
    .filter((run) => run.axis === "v")
    .slice(0, 80)
    .map((run, index) => systemMapLine(`${prefix}-native-network-source-vertical-${index}`, run.from, run.to, "#126CB4", 1.25, {
      ...source,
      detector: "system-map-native-network-edge",
      route: "source-orthogonal",
      sourceImageDetected: true,
      axis: "v",
      runIndex: index
    }));
  return mergeNearbySystemMapSourceRuns([...horizontal, ...vertical]);
}

function filterSystemMapSourceNetworkRuns(runs = [], nodes = []) {
  const nodeBoxes = (nodes || []).map((node) => ({
    x: Number(node.x || 0) - Number(node.size || 0) / 2,
    y: Number(node.y || 0) - Number(node.size || 0) / 2,
    w: Number(node.size || 0),
    h: Number(node.size || 0)
  }));
  return runs.filter((run) => {
    const length = systemMapSourceRunLength(run);
    const touchesNode = nodeBoxes.some((box) => systemMapRunTouchesBox(run, box, 3.2));
    const crossCount = runs.filter((candidate) => candidate.axis !== run.axis && systemMapRunsIntersect(run, candidate, 2.2)).length;
    if (length >= 28) return true;
    if (length >= 14 && (touchesNode || crossCount >= 2)) return true;
    if (length >= 9 && touchesNode && crossCount >= 1) return true;
    return false;
  });
}

function systemMapSourceRunLength(run = {}) {
  return Math.max(Math.abs(Number(run.to?.x || 0) - Number(run.from?.x || 0)), Math.abs(Number(run.to?.y || 0) - Number(run.from?.y || 0)));
}

function systemMapRunTouchesBox(run = {}, box = {}, pad = 0) {
  const x1 = Math.min(Number(run.from?.x || 0), Number(run.to?.x || 0));
  const x2 = Math.max(Number(run.from?.x || 0), Number(run.to?.x || 0));
  const y1 = Math.min(Number(run.from?.y || 0), Number(run.to?.y || 0));
  const y2 = Math.max(Number(run.from?.y || 0), Number(run.to?.y || 0));
  const bx1 = Number(box.x || 0) - pad;
  const bx2 = Number(box.x || 0) + Number(box.w || 0) + pad;
  const by1 = Number(box.y || 0) - pad;
  const by2 = Number(box.y || 0) + Number(box.h || 0) + pad;
  return x2 >= bx1 && x1 <= bx2 && y2 >= by1 && y1 <= by2;
}

function systemMapRunsIntersect(a = {}, b = {}, tolerance = 0) {
  if (a.axis === b.axis) return false;
  const h = a.axis === "h" ? a : b;
  const v = a.axis === "v" ? a : b;
  const hx1 = Math.min(Number(h.from?.x || 0), Number(h.to?.x || 0)) - tolerance;
  const hx2 = Math.max(Number(h.from?.x || 0), Number(h.to?.x || 0)) + tolerance;
  const hy = Number(h.from?.y || 0);
  const vx = Number(v.from?.x || 0);
  const vy1 = Math.min(Number(v.from?.y || 0), Number(v.to?.y || 0)) - tolerance;
  const vy2 = Math.max(Number(v.from?.y || 0), Number(v.to?.y || 0)) + tolerance;
  return vx >= hx1 && vx <= hx2 && hy >= vy1 && hy <= vy2;
}

function detectSystemMapSourceAxisRuns(image = {}, region = {}, nodeMasks = [], axis, slideSize = DEFAULT_SLIDE) {
  const runs = [];
  const minRunPx = Math.max(14, Math.round((axis === "h" ? image.width : image.height) / 960 * 12));
  const outer = axis === "h" ? region.h : region.w;
  const inner = axis === "h" ? region.w : region.h;
  for (let outerIndex = 0; outerIndex < outer; outerIndex += 1) {
    let start = null;
    let targetCount = 0;
    for (let innerIndex = 0; innerIndex <= inner; innerIndex += 1) {
      const x = axis === "h" ? region.x + innerIndex : region.x + outerIndex;
      const y = axis === "h" ? region.y + outerIndex : region.y + innerIndex;
      const inBounds = innerIndex < inner;
      const on = inBounds && isSystemMapBluePixel(image, x, y) && !pointInsideAnyPxBox(x, y, nodeMasks);
      if (on) {
        if (start === null) start = innerIndex;
        targetCount += 1;
        continue;
      }
      if (start !== null) {
        const length = innerIndex - start;
        if (length >= minRunPx && targetCount / Math.max(1, length) >= 0.72) {
          const pxBox = axis === "h"
            ? { x: region.x + start, y: region.y + outerIndex, w: length, h: 1 }
            : { x: region.x + outerIndex, y: region.y + start, w: 1, h: length };
          const ptBox = pxToPtBox(pxBox, image, slideSize, 0);
          runs.push(axis === "h"
            ? { from: { x: ptBox.x, y: ptBox.y }, to: { x: ptBox.x + ptBox.w, y: ptBox.y } }
            : { from: { x: ptBox.x, y: ptBox.y }, to: { x: ptBox.x, y: ptBox.y + ptBox.h } });
        }
        start = null;
        targetCount = 0;
      }
    }
  }
  return coalesceSystemMapSourceRuns(runs, axis);
}

function coalesceSystemMapSourceRuns(runs = [], axis) {
  const tolerance = 1.8;
  const groups = [];
  for (const run of runs) {
    const fixed = axis === "h" ? run.from.y : run.from.x;
    const start = axis === "h" ? Math.min(run.from.x, run.to.x) : Math.min(run.from.y, run.to.y);
    const end = axis === "h" ? Math.max(run.from.x, run.to.x) : Math.max(run.from.y, run.to.y);
    const group = groups.find((candidate) => Math.abs(candidate.fixed - fixed) <= tolerance && start <= candidate.end + 2.5 && end >= candidate.start - 2.5);
    if (group) {
      group.fixed = (group.fixed * group.count + fixed) / (group.count + 1);
      group.start = Math.min(group.start, start);
      group.end = Math.max(group.end, end);
      group.count += 1;
    } else {
      groups.push({ fixed, start, end, count: 1 });
    }
  }
  return groups
    .filter((group) => group.end - group.start >= 9)
    .sort((a, b) => (a.fixed - b.fixed) || (a.start - b.start))
    .map((group) => axis === "h"
      ? { from: { x: round(group.start), y: round(group.fixed) }, to: { x: round(group.end), y: round(group.fixed) } }
      : { from: { x: round(group.fixed), y: round(group.start) }, to: { x: round(group.fixed), y: round(group.end) } });
}

function mergeNearbySystemMapSourceRuns(shapes = []) {
  const seen = new Set();
  return shapes.filter((shape) => {
    const box = shape.box || {};
    const key = [
      Math.round(Number(box.x || 0) / 2),
      Math.round(Number(box.y || 0) / 2),
      Math.round(Number(box.w || 0) / 2),
      Math.round(Number(box.h || 0) / 2)
    ].join(":");
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function pointInsideAnyPxBox(x, y, boxes = []) {
  return (boxes || []).some((box) => pointInsidePxBox(x, y, box));
}

function systemMapOrthogonalNetworkEdgeShapes(prefix, edges = [], source = {}) {
  const shapes = [];
  edges.forEach((edge, edgeIndex) => {
    shapes.push(...systemMapOrthogonalLineSegments(`${prefix}-native-network-edge-${edgeIndex}`, edge.from, edge.to, "#126CB4", 1.25, {
        ...source,
        detector: "system-map-native-network-edge",
        route: "orthogonal",
        edgeIndex
      }));
  });
  return shapes;
}

function systemMapOrthogonalLineSegments(idBase, from = {}, to = {}, color, strokeWidthPt, source = {}) {
  const midX = round((Number(from.x || 0) + Number(to.x || 0)) / 2);
  const points = [
    { x: Number(from.x || 0), y: Number(from.y || 0) },
    { x: midX, y: Number(from.y || 0) },
    { x: midX, y: Number(to.y || 0) },
    { x: Number(to.x || 0), y: Number(to.y || 0) }
  ];
  const shapes = [];
  for (let segmentIndex = 0; segmentIndex < points.length - 1; segmentIndex += 1) {
    const start = points[segmentIndex];
    const end = points[segmentIndex + 1];
    if (Math.abs(end.x - start.x) < 0.1 && Math.abs(end.y - start.y) < 0.1) continue;
    shapes.push(systemMapLine(`${idBase}-${segmentIndex}`, start, end, color, strokeWidthPt, {
      ...source,
      route: "orthogonal",
      segmentIndex
    }));
  }
  return shapes;
}

function systemMapDenseNetworkDetailShapes(prefix, b, source = {}) {
  const blue = "#126CB4";
  const shapes = [];
  const detailNodes = [
    [0.405, 0.185, "rect", 11], [0.418, 0.242, "rect", 10], [0.432, 0.365, "rect", 10], [0.430, 0.505, "circle", 11],
    [0.485, 0.168, "rect", 10], [0.495, 0.230, "circle", 11], [0.500, 0.315, "rect", 10], [0.498, 0.455, "rect", 10], [0.500, 0.615, "rect", 11],
    [0.535, 0.160, "rect", 11], [0.545, 0.220, "rect", 10], [0.545, 0.330, "circle", 11], [0.545, 0.490, "rect", 10], [0.545, 0.635, "rect", 10],
    [0.585, 0.205, "rect", 10], [0.595, 0.305, "rect", 10], [0.595, 0.455, "circle", 11], [0.605, 0.615, "rect", 10]
  ].map(([rx, ry, kind, size]) => ({ x: b.x + b.w * rx, y: b.y + b.h * ry, kind, size }));
  const detailEdges = [
    [0, 1], [1, 2], [2, 3], [4, 5], [5, 6], [6, 7], [7, 8],
    [9, 10], [10, 11], [11, 12], [12, 13], [14, 15], [15, 16], [16, 17],
    [1, 5], [5, 10], [10, 14], [6, 11], [11, 15], [7, 12], [12, 16],
    [3, 8], [8, 13], [13, 17]
  ];
  detailEdges.forEach(([fromIndex, toIndex], index) => {
    shapes.push(...systemMapOrthogonalLineSegments(`${prefix}-native-network-detail-edge-${index}`, detailNodes[fromIndex], detailNodes[toIndex], blue, 1.0, {
      ...source,
      detector: "system-map-native-network-detail-edge",
      fromIndex,
      toIndex
    }));
  });
  detailNodes.forEach((node, index) => {
    shapes.push(systemMapShape(`${prefix}-native-network-detail-node-${index}`, node.kind === "circle" ? "ellipse" : "rect", {
      x: node.x - node.size / 2,
      y: node.y - node.size / 2,
      w: node.size,
      h: node.size
    }, {
      fill: blue,
      stroke: blue,
      strokeWidthPt: 0.4
    }, {
      ...source,
      detector: "system-map-native-network-detail-node",
      nodeKind: node.kind,
      detailIndex: index
    }));
  });
  return shapes;
}

function systemMapSourceDetectedNetworkDetailShapes(prefix, b, textBoxes = [], slideSize = DEFAULT_SLIDE, source = {}) {
  const sourceImageFile = findSystemMapSourceImageFile(textBoxes);
  if (!sourceImageFile) return [];
  let sourceImage = null;
  try {
    sourceImage = readPng(sourceImageFile);
  } catch {
    return [];
  }
  const detailNodes = detectSystemMapBlueNodeComponents(sourceImage, b, slideSize);
  if (detailNodes.length < 8) return [];
  return buildSystemMapDetailShapesFromNodes(prefix, detailNodes, {
    ...source,
    detector: "system-map-native-network-detail-node",
    sourceImageDetected: true
  });
}

function findSystemMapSourceImageFile(textBoxes = []) {
  for (const textBox of textBoxes || []) {
    const sourceImage = textBox?.source?.pageImage || textBox?.source?.sourceImage;
    if (typeof sourceImage === "string" && sourceImage && fs.existsSync(sourceImage)) return sourceImage;
  }
  return null;
}

function detectSystemMapBlueNodeComponents(image = {}, b = {}, slideSize = DEFAULT_SLIDE) {
  return detectDenseLinkedNodeAtoms(image, b, slideSize, {
    idPrefix: "system-map-detail-node",
    subRegionRatios: { x: 0.36, y: 0.09, w: 0.32, h: 0.65 },
    isTargetPixel: isSystemMapBluePixel,
    maxNodes: 28,
    minConnectedNodes: 8
  }).map((atom) => ({
    x: round(atom.center.x),
    y: round(atom.center.y),
    size: round(Math.max(Number(atom.box?.w || 0), Number(atom.box?.h || 0))),
    kind: atom.shapeHint === "ellipse" ? "circle" : "rect",
    confidence: atom.density,
    sourceAtomId: atom.id,
    detectionMethod: atom.source?.method || "dense-linked-node"
  }));
}

function isSystemMapBluePixel(image, x, y) {
  const offset = (y * image.width + x) * 4;
  const r = image.rgba[offset];
  const g = image.rgba[offset + 1];
  const b = image.rgba[offset + 2];
  const a = image.rgba[offset + 3];
  return a > 180 && b >= 95 && g >= 45 && g <= 180 && r <= 100 && b - r >= 38 && b - g >= 8;
}

function buildSystemMapDetailShapesFromNodes(prefix, detailNodes = [], source = {}) {
  const blue = "#126CB4";
  const shapes = [];
  const rows = clusterSystemMapDetailRows(detailNodes);
  const detailEdges = [];
  for (const row of rows) {
    for (let index = 0; index < row.length - 1; index += 1) {
      detailEdges.push([row[index], row[index + 1], "row"]);
    }
  }
  const columns = clusterSystemMapDetailColumns(detailNodes);
  for (const column of columns) {
    for (let index = 0; index < column.length - 1; index += 1) {
      detailEdges.push([column[index], column[index + 1], "column"]);
    }
  }
  detailEdges.slice(0, 36).forEach(([fromIndex, toIndex, axis], index) => {
    shapes.push(...systemMapOrthogonalLineSegments(`${prefix}-native-network-detail-edge-detected-${index}`, detailNodes[fromIndex], detailNodes[toIndex], blue, 0.95, {
      ...source,
      detector: "system-map-native-network-detail-edge",
      sourceImageDetected: true,
      axis,
      fromIndex,
      toIndex
    }));
  });
  detailNodes.forEach((node, index) => {
    shapes.push(systemMapShape(`${prefix}-native-network-detail-node-detected-${index}`, node.kind === "circle" ? "ellipse" : "rect", {
      x: node.x - node.size / 2,
      y: node.y - node.size / 2,
      w: node.size,
      h: node.size
    }, {
      fill: blue,
      stroke: blue,
      strokeWidthPt: 0.4
    }, {
      ...source,
      detector: "system-map-native-network-detail-node",
      nodeKind: node.kind,
      detailIndex: index,
      confidence: node.confidence,
      detectionMethod: node.detectionMethod || null,
      sourceAtomId: node.sourceAtomId || null
    }));
  });
  return shapes;
}

function clusterSystemMapDetailRows(nodes = []) {
  return clusterSystemMapDetailAxis(nodes, "y", "x", 18);
}

function clusterSystemMapDetailColumns(nodes = []) {
  return clusterSystemMapDetailAxis(nodes, "x", "y", 20);
}

function clusterSystemMapDetailAxis(nodes = [], primary, secondary, tolerance) {
  const groups = [];
  nodes.forEach((node, index) => {
    const value = Number(node[primary] || 0);
    let group = groups.find((candidate) => Math.abs(candidate.value - value) <= tolerance);
    if (!group) {
      group = { value, indexes: [] };
      groups.push(group);
    }
    group.indexes.push(index);
    group.value = group.indexes.reduce((sum, itemIndex) => sum + Number(nodes[itemIndex][primary] || 0), 0) / group.indexes.length;
  });
  return groups
    .filter((group) => group.indexes.length >= 2)
    .map((group) => group.indexes.sort((a, b) => Number(nodes[a][secondary] || 0) - Number(nodes[b][secondary] || 0)));
}

function systemMapBottomLabelTextBoxes(prefix, b, source = {}) {
  const labels = [
    { text: "物流域", x: b.x + b.w * 0.15 },
    { text: "供应链", x: b.x + b.w * 0.50 },
    { text: "ERP", x: b.x + b.w * 0.70 },
    { text: "财务", x: b.x + b.w * 0.82 }
  ];
  return labels.map((item, index) => ({
    id: `${prefix}-native-bottom-label-${index}`,
    text: item.text,
    box: { x: round(item.x), y: round(Math.min(DEFAULT_SLIDE.heightPt - 14, b.y + b.h * 1.012)), w: 48, h: 10 },
    font: {
      family: "Microsoft YaHei",
      sizePt: 5.5,
      color: "#6D8798",
      opacity: 1,
      weight: "regular",
      align: "center",
      valign: "middle"
    },
    source: {
      ...source,
      detector: "system-map-native-label",
      role: "bottom-domain-label"
    }
  }));
}

function systemMapShape(id, type, box, style, source = {}) {
  return {
    id,
    type,
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(box.w),
      h: round(box.h)
    },
    style,
    source
  };
}

function systemMapLine(id, from, to, color, strokeWidthPt, source = {}) {
  return systemMapShape(id, "line", lineBox(from, to), {
    stroke: color,
    strokeWidthPt,
    connectorType: "straight",
    lineCap: "square"
  }, source);
}

function normalizedTextsInsideBox(textBoxes = [], box = {}) {
  return new Set((textBoxes || [])
    .filter((item) => item?.box && boxCenterInside(item.box, box))
    .map((item) => normalizeCjkText(item.text))
    .filter(Boolean));
}

function findTextBoxByNormalizedText(textBoxes = [], text = "") {
  const target = normalizeCjkText(text);
  return (textBoxes || []).find((item) => normalizeCjkText(item.text) === target) || null;
}

function normalizeCjkText(value = "") {
  return String(value || "")
    .replace(/\s+/g, "")
    .replace(/[Ａ-Ｚａ-ｚ０-９]/g, (char) => String.fromCharCode(char.charCodeAt(0) - 0xFEE0))
    .replace(/Al/g, "AI")
    .trim();
}

function buildPageSemanticText(textBoxes = []) {
  return (Array.isArray(textBoxes) ? textBoxes : [])
    .map((item) => String(item?.text || "").trim())
    .filter(Boolean)
    .join(" ");
}

function enrichImagesWithPageSemanticText(images = [], pageSemanticText = "") {
  const semanticText = String(pageSemanticText || "").trim();
  if (!semanticText) return images;
  return (Array.isArray(images) ? images : []).map((image) => ({
    ...image,
    source: {
      ...(image?.source || {}),
      pageText: image?.source?.pageText || semanticText,
      allText: image?.source?.allText || semanticText
    }
  }));
}

