function eraseMasks(image, masks) {
  const next = { width: image.width, height: image.height, rgba: Buffer.from(image.rgba) };
  for (const mask of masks) {
    const fill = sampleMaskBackgroundColor(image, mask);
    const bounds = maskBounds(mask, image);
    for (let y = bounds.y; y < bounds.y + bounds.h; y += 1) {
      for (let x = bounds.x; x < bounds.x + bounds.w; x += 1) {
        if (!pointInMask(x, y, mask)) continue;
        const offset = (y * image.width + x) * 4;
        next.rgba[offset] = fill.r;
        next.rgba[offset + 1] = fill.g;
        next.rgba[offset + 2] = fill.b;
        next.rgba[offset + 3] = 255;
      }
    }
  }
  return next;
}

function sampleMaskBackgroundColor(image, mask) {
  const padding = 6;
  const bounds = maskBounds(mask, image);
  const x1 = clamp(bounds.x - padding, 0, image.width - 1);
  const y1 = clamp(bounds.y - padding, 0, image.height - 1);
  const x2 = clamp(bounds.x + bounds.w + padding, x1 + 1, image.width);
  const y2 = clamp(bounds.y + bounds.h + padding, y1 + 1, image.height);
  const buckets = new Map();
  for (let y = y1; y < y2; y += 2) {
    for (let x = x1; x < x2; x += 2) {
      const insideMask = pointInMask(x, y, mask);
      if (insideMask) continue;
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      const key = `${Math.round(color.r / 16)},${Math.round(color.g / 16)},${Math.round(color.b / 16)}`;
      const entry = buckets.get(key) || { count: 0, r: 0, g: 0, b: 0 };
      entry.count += 1;
      entry.r += color.r;
      entry.g += color.g;
      entry.b += color.b;
      buckets.set(key, entry);
    }
  }
  const dominant = [...buckets.values()].sort((a, b) => b.count - a.count)[0];
  if (!dominant || dominant.count < 4) return { r: 255, g: 255, b: 255 };
  return {
    r: Math.round(dominant.r / dominant.count),
    g: Math.round(dominant.g / dominant.count),
    b: Math.round(dominant.b / dominant.count)
  };
}

function maskBounds(mask, image) {
  if (mask?.kind === "line") {
    const half = Math.max(1, Number(mask.width || 1) / 2);
    const x1 = Math.min(mask.x1, mask.x2) - half;
    const y1 = Math.min(mask.y1, mask.y2) - half;
    const x2 = Math.max(mask.x1, mask.x2) + half;
    const y2 = Math.max(mask.y1, mask.y2) + half;
    const x = clamp(Math.floor(x1), 0, image.width - 1);
    const y = clamp(Math.floor(y1), 0, image.height - 1);
    return {
      x,
      y,
      w: clamp(Math.ceil(x2) - x, 1, image.width - x),
      h: clamp(Math.ceil(y2) - y, 1, image.height - y)
    };
  }
  const x = clamp(Math.floor(mask.x), 0, image.width - 1);
  const y = clamp(Math.floor(mask.y), 0, image.height - 1);
  return {
    x,
    y,
    w: clamp(Math.ceil(mask.w), 1, image.width - x),
    h: clamp(Math.ceil(mask.h), 1, image.height - y)
  };
}

function pointInMask(x, y, mask) {
  if (mask?.kind === "line") {
    return distanceToSegment(x, y, mask.x1, mask.y1, mask.x2, mask.y2) <= Math.max(1, Number(mask.width || 1) / 2);
  }
  return x >= mask.x && x < mask.x + mask.w && y >= mask.y && y < mask.y + mask.h;
}

function distanceToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const lenSq = dx * dx + dy * dy;
  if (lenSq === 0) return Math.hypot(px - x1, py - y1);
  const t = clamp(((px - x1) * dx + (py - y1) * dy) / lenSq, 0, 1);
  const x = x1 + t * dx;
  const y = y1 + t * dy;
  return Math.hypot(px - x, py - y);
}

function foregroundComponents(image, masks = []) {
  const visited = new Uint8Array(image.width * image.height);
  const components = [];
  for (let y = 0; y < image.height; y += 3) {
    for (let x = 0; x < image.width; x += 3) {
      const idx = y * image.width + x;
      if (visited[idx] || inAnyMask(x, y, masks)) continue;
      if (!isGraphicForeground(pixel(image, x, y))) continue;
      const queue = [[x, y]];
      visited[idx] = 1;
      let qi = 0;
      let minX = x;
      let maxX = x;
      let minY = y;
      let maxY = y;
      let count = 0;
      while (qi < queue.length && count < 300000) {
        const [cx, cy] = queue[qi++];
        count += 1;
        minX = Math.min(minX, cx);
        maxX = Math.max(maxX, cx);
        minY = Math.min(minY, cy);
        maxY = Math.max(maxY, cy);
        for (const [nx, ny] of [[cx + 3, cy], [cx - 3, cy], [cx, cy + 3], [cx, cy - 3]]) {
          if (nx < 0 || ny < 0 || nx >= image.width || ny >= image.height) continue;
          const nextIdx = ny * image.width + nx;
          if (visited[nextIdx] || inAnyMask(nx, ny, masks)) continue;
          if (!isGraphicForeground(pixel(image, nx, ny))) continue;
          visited[nextIdx] = 1;
          queue.push([nx, ny]);
        }
      }
      const box = expandPxBox({ x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 }, image, 8);
      components.push({ box, sampledCount: count });
    }
  }
  return components;
}

function mergeCloseComponent(component) {
  return component;
}

function mergeGraphicComponents(components, image) {
  const sorted = components.sort((a, b) => (b.box.w * b.box.h) - (a.box.w * a.box.h));
  const merged = [];
  for (const component of sorted) {
    const existing = merged.find((item) => boxesNear(item.box, component.box, 28));
    if (existing) {
      existing.box = expandPxBox(unionBox(existing.box, component.box), image, 0);
      existing.sampledCount += component.sampledCount;
    } else {
      merged.push({ ...component });
    }
  }
  return merged
    .filter((component) => isUsefulGraphicComponent(component, image))
    .sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
}

function aggregateForegroundComponent(image, masks = []) {
  let minX = image.width;
  let minY = image.height;
  let maxX = -1;
  let maxY = -1;
  let sampledCount = 0;
  for (let y = 0; y < image.height; y += 3) {
    for (let x = 0; x < image.width; x += 3) {
      if (inAnyMask(x, y, masks)) continue;
      if (!isGraphicForeground(pixel(image, x, y))) continue;
      sampledCount += 1;
      minX = Math.min(minX, x);
      minY = Math.min(minY, y);
      maxX = Math.max(maxX, x);
      maxY = Math.max(maxY, y);
    }
  }
  if (maxX < minX || maxY < minY) {
    return null;
  }
  return {
    box: expandPxBox({ x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 }, image, 8),
    sampledCount
  };
}

function shouldAddAggregateComponent(component, merged, image) {
  if (!component) return false;
  if (merged.length > 0) return false;
  const areaRatio = component.box.w * component.box.h / Math.max(1, image.width * image.height);
  if (areaRatio < 0.04 || areaRatio > 0.65) return false;
  if (component.box.w > image.width * 0.92 && component.box.h > image.height * 0.92) return false;
  const sampledRatio = component.sampledCount / Math.max(1, (image.width / 3) * (image.height / 3));
  return sampledRatio >= 0.0015;
}

function shouldUseGraphicUnderlay({ aggregate, image, structuralLines = [], textBoxes = [] } = {}) {
  if (!aggregate || !image) return false;
  if (textBoxes.length < 8 || structuralLines.length < 2) return false;
  const areaRatio = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (areaRatio < 0.05 || areaRatio > 0.65) return false;
  if (aggregate.box.w > image.width * 0.92 && aggregate.box.h > image.height * 0.92) return false;
  return true;
}

function shouldUseProductIllustrationSegmentCrops({ aggregate, image, structuralLines = [], textBoxes = [] } = {}) {
  if (!aggregate || !image) return false;
  if (textBoxes.length < 8 || structuralLines.length < 2) return false;
  const areaRatio = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (areaRatio < 0.38 || areaRatio > 0.68) return false;
  if (aggregate.box.w > image.width * 0.94 && aggregate.box.h > image.height * 0.88) return false;
  const segmentBoxes = productIllustrationSegmentBoxes(image, aggregate.box);
  if (looksLikeDenseTextMatrix(aggregate.box, image, textBoxes) && segmentBoxes.length < 3) return false;
  const components = mergeGraphicComponents(foregroundComponents(image, []), image)
    .filter((component) => boxOverlapArea(component.box, aggregate.box) / Math.max(1, component.box.w * component.box.h) >= 0.62);
  const meaningful = components.filter((component) => {
    const componentArea = component.box.w * component.box.h / Math.max(1, image.width * image.height);
    const ratio = component.box.w / Math.max(1, component.box.h);
    return componentArea >= 0.006
      && componentArea <= 0.26
      && component.box.w >= image.width * 0.07
      && component.box.h >= image.height * 0.06
      && ratio >= 0.42
      && ratio <= 4.8;
  });
  if ((meaningful.length < 3 || meaningful.length > 12) && segmentBoxes.length < 3) return false;
  const paletteSource = meaningful.length >= 3 ? meaningful.map((component) => component.box) : segmentBoxes;
  const palette = new Set(paletteSource.map((box) => coarseHueBucket(sampleComponentCenterColor(image, box))).filter(Boolean));
  if (palette.size < 2) return false;
  const layoutSource = meaningful.length >= 3 ? meaningful.map((component) => component.box) : segmentBoxes;
  const wideBands = layoutSource.filter((box) => box.w >= image.width * 0.2).length;
  const tallCards = layoutSource.filter((box) => box.h >= image.height * 0.18).length;
  return wideBands >= 1 && tallCards >= 1;
}

function productIllustrationSegmentBoxes(image, aggregateBox) {
  const components = mergeGraphicComponents(foregroundComponents(image, []), image)
    .filter((component) => boxOverlapArea(component.box, aggregateBox) / Math.max(1, component.box.w * component.box.h) >= 0.62)
    .filter((component) => {
      const componentArea = component.box.w * component.box.h / Math.max(1, image.width * image.height);
      return componentArea >= 0.006 && componentArea <= 0.26;
    })
    .map((component) => expandProductSegmentPxBox(component.box, image, 12, 10))
    .sort((a, b) => (a.x - b.x) || (a.y - b.y));
  return mergeNearbySegmentBoxes(components, image)
    .filter((box) => {
      const areaRatio = box.w * box.h / Math.max(1, image.width * image.height);
      return areaRatio >= 0.012 && areaRatio <= 0.24;
    })
    .concat(productIllustrationBandBoxes(image, aggregateBox))
    .sort((a, b) => (a.x - b.x) || (a.y - b.y));
}

function productIllustrationBandBoxes(image, aggregateBox) {
  const crop = cropPng(image, aggregateBox);
  const runs = significantVerticalInkRuns(crop);
  const usableRuns = runs.length >= 3 ? runs : significantVerticalInkRunsWithoutHeader(crop);
  if (usableRuns.length < 3 || usableRuns.length > 8) return [];
  const selectedRuns = runs.length >= 3 ? runs : usableRuns;
  return selectedRuns
    .map((run) => trimResidualBandBox(crop, { x: run.start, y: run.y || 0, w: run.end - run.start + 1, h: run.h || crop.height }))
    .filter(Boolean)
    .map((box) => expandProductSegmentPxBox({
      x: aggregateBox.x + box.x,
      y: aggregateBox.y + box.y,
      w: box.w,
      h: box.h
    }, image, 12, 10))
    .filter((box) => {
      const areaRatio = box.w * box.h / Math.max(1, image.width * image.height);
      return areaRatio >= 0.012 && areaRatio <= 0.24;
    });
}

function significantVerticalInkRunsWithoutHeader(crop) {
  const headerBottom = detectWideHeaderBottom(crop);
  if (!headerBottom || headerBottom > crop.height * 0.32) return [];
  const body = cropPng(crop, { x: 0, y: headerBottom, w: crop.width, h: crop.height - headerBottom });
  return significantVerticalInkRuns(body).map((run) => ({
    ...run,
    y: headerBottom,
    h: body.height
  }));
}

function detectWideHeaderBottom(crop) {
  let lastWide = -1;
  for (let y = 0; y < Math.round(crop.height * 0.34); y += 2) {
    let count = 0;
    for (let x = 0; x < crop.width; x += 4) {
      if (isTableBlockSeed(pixel(crop, x, y))) count += 1;
    }
    if (count / Math.max(1, crop.width / 4) >= 0.72) lastWide = y;
  }
  return lastWide > crop.height * 0.06 ? Math.min(crop.height - 1, lastWide + 8) : null;
}

function looksLikeDenseTextMatrix(pxBox, image, textBoxes = []) {
  const slideBox = pxToPtBox(pxBox, image, DEFAULT_SLIDE, 0);
  const inside = (textBoxes || []).filter((item) => item?.box && boxCenterInside(item.box, slideBox));
  if (inside.length < 16) return false;
  const columns = clusterCenters(inside.map((item) => item.box.x + item.box.w / 2), slideBox.w * 0.08);
  const rows = clusterCenters(inside.map((item) => item.box.y + item.box.h / 2), slideBox.h * 0.08);
  return columns.length >= 3 && rows.length >= 4 && inside.length >= columns.length * rows.length * 0.48;
}

function clusterCenters(values, tolerance) {
  const clusters = [];
  for (const value of [...values].sort((a, b) => a - b)) {
    const last = clusters[clusters.length - 1];
    if (!last || Math.abs(value - last.center) > tolerance) {
      clusters.push({ center: value, count: 1 });
    } else {
      last.center = (last.center * last.count + value) / (last.count + 1);
      last.count += 1;
    }
  }
  return clusters;
}

function mergeNearbySegmentBoxes(boxes, image) {
  const merged = [];
  for (const box of boxes) {
    const match = merged.find((item) => boxesNearPx(item, box, Math.round(image.width * 0.035), Math.round(image.height * 0.05)));
    if (match) {
      const union = unionPxBox(match, box);
      match.x = union.x;
      match.y = union.y;
      match.w = union.w;
      match.h = union.h;
    } else {
      merged.push({ ...box });
    }
  }
  return merged;
}

function boxesNearPx(a, b, padX, padY) {
  return !(a.x + a.w + padX < b.x
    || b.x + b.w + padX < a.x
    || a.y + a.h + padY < b.y
    || b.y + b.h + padY < a.y);
}

function unionPxBox(a, b) {
  const x = Math.min(a.x, b.x);
  const y = Math.min(a.y, b.y);
  const x2 = Math.max(a.x + a.w, b.x + b.w);
  const y2 = Math.max(a.y + a.h, b.y + b.h);
  return { x, y, w: x2 - x, h: y2 - y };
}

function expandProductSegmentPxBox(box, image, padX, padY) {
  const x = clamp(Math.floor(box.x - padX), 0, image.width - 1);
  const y = clamp(Math.floor(box.y - padY), 0, image.height - 1);
  const x2 = clamp(Math.ceil(box.x + box.w + padX), x + 1, image.width);
  const y2 = clamp(Math.ceil(box.y + box.h + padY), y + 1, image.height);
  return { x, y, w: x2 - x, h: y2 - y };
}

function boxOverlapArea(a, b) {
  if (!a || !b) return 0;
  const x1 = Math.max(Number(a.x || 0), Number(b.x || 0));
  const y1 = Math.max(Number(a.y || 0), Number(b.y || 0));
  const x2 = Math.min(Number(a.x || 0) + Number(a.w || 0), Number(b.x || 0) + Number(b.w || 0));
  const y2 = Math.min(Number(a.y || 0) + Number(a.h || 0), Number(b.y || 0) + Number(b.h || 0));
  return Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
}

function sampleComponentCenterColor(image, box) {
  const x1 = clamp(Math.round(box.x + box.w * 0.25), 0, image.width - 1);
  const y1 = clamp(Math.round(box.y + box.h * 0.25), 0, image.height - 1);
  const x2 = clamp(Math.round(box.x + box.w * 0.75), x1 + 1, image.width);
  const y2 = clamp(Math.round(box.y + box.h * 0.75), y1 + 1, image.height);
  const colors = [];
  for (let y = y1; y < y2; y += 6) {
    for (let x = x1; x < x2; x += 6) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      if (luma(color) > 244 && saturation(color) < 0.12) continue;
      colors.push(color);
    }
  }
  return colors.length > 0 ? averageColor(colors) : null;
}

function coarseHueBucket(color) {
  if (!color) return null;
  const hsl = rgbToHsl(color);
  if (hsl.s < 0.16 && hsl.l > 0.72) return null;
  if (hsl.s < 0.16) return "neutral";
  return String(Math.floor(hsl.h / 45));
}

function shouldUseSegmentedGraphicUnderlay({ aggregate, image, structuralLines = [], textBoxes = [] } = {}) {
  if (!aggregate || !image) return false;
  if (textBoxes.length < 12 || structuralLines.length < 4) return false;
  const areaRatio = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  const fullCanvasAggregate = aggregate.box.w > image.width * 0.96 && aggregate.box.h > image.height * 0.96;
  if (areaRatio <= 0.7) return false;
  if (areaRatio > 0.86 && !(fullCanvasAggregate && structuralLines.length >= 120)) return false;
  return true;
}

function shouldUseContentGraphicUnderlay({ aggregate, image, structuralLines = [], detectedLineCount = 0, textBoxes = [] } = {}) {
  if (!aggregate || !image) return false;
  const fullCanvasAggregate = aggregate.box.w > image.width * 0.96 && aggregate.box.h > image.height * 0.96;
  return fullCanvasAggregate && Math.max(structuralLines.length, detectedLineCount) >= 120 && textBoxes.length >= 12;
}

function shouldUseVisualClusterUnderlay({
  aggregate,
  image,
  cluster,
  components = [],
  structuralLines = [],
  detectedLineCount = 0,
  textBoxes = []
} = {}) {
  if (!aggregate || !image || !cluster) return false;
  if (textBoxes.length < 4 || textBoxes.length > 36) return false;
  const meaningfulComponents = components.filter((component) => {
    const areaRatio = component.box.w * component.box.h / Math.max(1, image.width * image.height);
    return areaRatio >= 0.004 && areaRatio <= 0.22;
  });
  if (meaningfulComponents.length < 3) return false;
  if (Math.max(structuralLines.length, detectedLineCount) < 2 && meaningfulComponents.length < 5) return false;
  const clusterArea = cluster.w * cluster.h / Math.max(1, image.width * image.height);
  if (clusterArea < 0.16 || clusterArea > 0.62) return false;
  if (cluster.w > image.width * 0.94 && cluster.h > image.height * 0.82) return false;
  const aggregateArea = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (aggregateArea > 0.78) return false;
  return true;
}

function shouldUseStructuredCaseUnderlay({ aggregate, image, structuralLines = [], textBoxes = [] } = {}) {
  if (!aggregate || !image) return false;
  if (textBoxes.length < 14 || structuralLines.length < 3) return false;
  const aggregateArea = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (aggregateArea < 0.55 || aggregateArea > 0.94) return false;
  const textArea = textBoxes
    .map((item) => item.box)
    .filter(Boolean)
    .reduce((sum, box) => sum + Math.max(0, Number(box.w || 0) * Number(box.h || 0)), 0);
  const slideArea = 960 * 540;
  return textArea / slideArea >= 0.08;
}

function shouldUseMixedDiagramUnderlay({ aggregate, image, structuralLines = [], textBoxes = [], contentBox, slideSize = DEFAULT_SLIDE } = {}) {
  if (!aggregate || !image || !contentBox) return false;
  if (textBoxes.length < 18 || textBoxes.length > 34) return false;
  if (structuralLines.length < 3) return false;
  const aggregateArea = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (aggregateArea < 0.81 || aggregateArea > 0.94) return false;
  const contentArea = contentBox.w * contentBox.h / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  if (contentArea < 0.54 || contentArea > 0.66) return false;
  return contentBox.w >= slideSize.widthPt * 0.82 && contentBox.h >= slideSize.heightPt * 0.62;
}

function shouldUseLeftIllustrationPanelUnderlay({ aggregate, image, leftBox, bannerBox, textBoxes = [], slideSize = DEFAULT_SLIDE } = {}) {
  if (!aggregate || !image || !leftBox || !bannerBox) return false;
  if (textBoxes.length < 16 || textBoxes.length > 24) return false;
  const aggregateArea = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (aggregateArea < 0.84) return false;
  const leftArea = leftBox.w * leftBox.h / Math.max(1, image.width * image.height);
  if (leftArea < 0.14 || leftArea > 0.32) return false;
  if (leftBox.x > image.width * 0.16 || leftBox.w > image.width * 0.42) return false;
  const bannerArea = bannerBox.w * bannerBox.h / Math.max(1, image.width * image.height);
  if (bannerArea < 0.05 || bannerArea > 0.18) return false;
  const rightTextCount = textBoxes.filter((item) => {
    const box = item?.box || {};
    return Number(box.x || 0) >= slideSize.widthPt * 0.45
      && Number(box.y || 0) >= slideSize.heightPt * 0.25
      && Number(box.y || 0) <= slideSize.heightPt * 0.82;
  }).length;
  return rightTextCount >= 8;
}

function shouldUseTwoPanelDiagramCrops({ panels, textBoxes = [], slideSize = DEFAULT_SLIDE } = {}) {
  if (!Array.isArray(panels) || panels.length !== 2) return false;
  const upperLeft = textBoxes.filter((item) => {
    const box = item?.box || {};
    return Number(box.x || 0) < slideSize.widthPt * 0.5
      && Number(box.y || 0) >= slideSize.heightPt * 0.18
      && Number(box.y || 0) <= slideSize.heightPt * 0.76;
  });
  const rightPanelText = textBoxes.filter((item) => {
    const box = item?.box || {};
    return Number(box.x || 0) >= slideSize.widthPt * 0.52
      && Number(box.y || 0) >= slideSize.heightPt * 0.18
      && Number(box.y || 0) <= slideSize.heightPt * 0.76;
  });
  const bottomText = textBoxes.filter((item) => Number(item?.box?.y || 0) >= slideSize.heightPt * 0.8);
  const noisyLeftLabels = upperLeft.filter((item) => /^(?:w|v\d|v\d\.\d|v\d\.\d-fix|html?|<>|error|rfcor|码表|多版本)/i.test(String(item?.text || "").trim()));
  const panelArea = panels.reduce((sum, box) => sum + box.w * box.h, 0) / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  if (upperLeft.length < 12 || noisyLeftLabels.length < 7) return false;
  if (rightPanelText.length < 5 || bottomText.length < 5) return false;
  if (panelArea < 0.42 || panelArea > 0.72) return false;
  return panels.every((box) => box.y >= slideSize.heightPt * 0.1
    && box.y <= slideSize.heightPt * 0.22
    && box.h >= slideSize.heightPt * 0.48
    && box.h <= slideSize.heightPt * 0.72
    && box.w >= slideSize.widthPt * 0.34
    && box.w <= slideSize.widthPt * 0.5);
}

function shouldUseTopComplexDiagramCrop({ panel, textBoxes = [], slideSize = DEFAULT_SLIDE } = {}) {
  if (!panel) return false;
  const topText = textBoxes.filter((item) => {
    const box = item?.box || {};
    return Number(box.y || 0) >= slideSize.heightPt * 0.08
      && Number(box.y || 0) <= slideSize.heightPt * 0.72;
  });
  const bottomText = textBoxes.filter((item) => Number(item?.box?.y || 0) >= slideSize.heightPt * 0.68);
  const signalCount = topText.filter((item) => {
    const text = String(item?.text || "").trim();
    return /debugger|prd|修复建议|前后矛盾|边界缺失|权限|阻断|^\d+$|^[+.中]$/i.test(text);
  }).length;
  const bottomLabels = bottomText.filter((item) => /痛点|能力|产出价值/.test(String(item?.text || ""))).length;
  const areaRatio = panel.w * panel.h / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  if (topText.length < 20 || signalCount < 10) return false;
  if (bottomText.length < 5 || bottomLabels < 2) return false;
  if (areaRatio < 0.52 || areaRatio > 0.76) return false;
  return panel.x >= slideSize.widthPt * 0.04
    && panel.x <= slideSize.widthPt * 0.14
    && panel.y >= slideSize.heightPt * 0.06
    && panel.y <= slideSize.heightPt * 0.16
    && panel.w >= slideSize.widthPt * 0.72
    && panel.h >= slideSize.heightPt * 0.52
    && panel.y + panel.h <= slideSize.heightPt * 0.72;
}

function inferDiagramSemanticSignals(textBoxes = []) {
  const text = (textBoxes || []).map((item) => String(item?.text || "")).join("\n");
  const groups = [
    /WMS|Tollgate|Inbound|Outbound|PRD|Debug|Debugger|HTML|API/i,
    /挑战|痛点|问题|风险|阻断|瓶颈|熵增|断层|孤岛/,
    /AI\s*介入|AI能力|AI中台|AI\s*Skill|PMSkills|AISkills/i,
    /价值落地|产出价值|收益|提效|降本|复用|资产复利/,
    /输入|输出|流转|链路|流程|闭环|协同|交互|转化/,
    /Tollgate\d+|V\d+(?:\.\d+)?|V\d+[A-Z]?|版本|码表/i,
    /修复建议|边界缺失|权限|公式|规则|状态计算/,
    /原型|截图|页面|界面|组件|按钮|表单|看板/
  ];
  return groups.filter((pattern) => pattern.test(text)).length;
}

function scoreDiagramCandidate({ panels = [], textBoxes = [], slideSize = DEFAULT_SLIDE, structuralLines = [], semanticSignals = 0 } = {}) {
  const validPanels = (Array.isArray(panels) ? panels : [panels]).filter(Boolean);
  if (validPanels.length === 0) {
    return { score: 0, reasons: ["no-panels"], metrics: {} };
  }
  const inferredSemanticSignals = inferDiagramSemanticSignals(textBoxes);
  const effectiveSemanticSignals = Math.max(Number(semanticSignals || 0), inferredSemanticSignals);
  const slideArea = Math.max(1, slideSize.widthPt * slideSize.heightPt);
  const panelArea = validPanels.reduce((sum, box) => sum + Math.max(0, Number(box.w || 0) * Number(box.h || 0)), 0);
  const panelAreaRatio = panelArea / slideArea;
  const insideText = textBoxes.filter((textBox) => validPanels.some((panel) => boxCenterInside(textBox.box, panel)));
  const textCoverage = insideText.length / Math.max(1, textBoxes.length);
  const xBuckets = new Set(insideText.map((textBox) => {
    const centerX = Number(textBox?.box?.x || 0) + Number(textBox?.box?.w || 0) / 2;
    return Math.max(0, Math.min(3, Math.floor(centerX / Math.max(1, slideSize.widthPt / 4))));
  }));
  const yBuckets = new Set(insideText.map((textBox) => {
    const centerY = Number(textBox?.box?.y || 0) + Number(textBox?.box?.h || 0) / 2;
    return Math.max(0, Math.min(2, Math.floor(centerY / Math.max(1, slideSize.heightPt / 3))));
  }));
  const relevantLines = (structuralLines || []).filter((line) =>
    validPanels.some((panel) => boxCenterInside(line.box, panel))
  );
  const reasons = [];
  let score = 0;
  if (panelAreaRatio >= 0.28 && panelAreaRatio <= 0.78) {
    score += 2;
    reasons.push("diagram-sized-region");
  }
  if (textCoverage >= 0.55) {
    score += 1;
    reasons.push("text-over-visual-region");
  }
  if (xBuckets.size >= 3 || yBuckets.size >= 2) {
    score += 1;
    reasons.push("distributed-labels");
  }
  if (validPanels.length >= 2) {
    score += 1;
    reasons.push("segmented-layout");
  }
  if (relevantLines.length >= 3) {
    score += 1;
    reasons.push("structural-line-noise");
  }
  if (effectiveSemanticSignals >= 3) {
    score += 2;
    reasons.push("semantic-diagram-signals");
  } else if (effectiveSemanticSignals >= 1) {
    score += 1;
    reasons.push("weak-semantic-signal");
  }
  const risk = {
    tooMuchRaster: panelAreaRatio > 0.74 && effectiveSemanticSignals < 5,
    weakTextAnchor: textCoverage < 0.45 && effectiveSemanticSignals < 3,
    broadSinglePanel: validPanels.length === 1 && panelAreaRatio > 0.68 && effectiveSemanticSignals < 4
  };
  if (risk.tooMuchRaster) reasons.push("risk-too-much-raster");
  if (risk.weakTextAnchor) reasons.push("risk-weak-text-anchor");
  if (risk.broadSinglePanel) reasons.push("risk-broad-single-panel");
  return {
    score,
    reasons,
    metrics: {
      panelAreaRatio: round(panelAreaRatio),
      textCoverage: round(textCoverage),
      panelCount: validPanels.length,
      textBucketColumns: xBuckets.size,
      textBucketRows: yBuckets.size,
      relevantLineCount: relevantLines.length,
      semanticSignals: effectiveSemanticSignals,
      explicitSemanticSignals: Number(semanticSignals || 0),
      inferredSemanticSignals,
      risk
    }
  };
}

function isAcceptableDiagramCandidate(candidate, minScore) {
  if (!candidate || candidate.score < minScore) return false;
  const risk = candidate.metrics?.risk || {};
  return !risk.tooMuchRaster && !risk.weakTextAnchor && !risk.broadSinglePanel;
}

function shouldUseCollaborationFlowUnderlay({ panel, textBoxes = [], slideSize = DEFAULT_SLIDE, structuralLines = [] } = {}) {
  if (!panel) return false;
  if (textBoxes.length < 12 || textBoxes.length > 18) return false;
  const text = textBoxes.map((item) => String(item?.text || "")).join("\n");
  const roleSignals = [/后端研发\s*BE/i, /前端研发\s*FE/i, /测试\s*QA/i]
    .filter((pattern) => pattern.test(text)).length;
  const hasEngine = /协同倍增器/.test(text) && /PM\s*Skills|PMSkills/i.test(text);
  const hasValueBanner = /研发返工率/.test(text) && /全链路降本/.test(text);
  const rightBodyText = textBoxes.filter((item) => {
    const box = item?.box || {};
    return Number(box.x || 0) >= slideSize.widthPt * 0.55
      && Number(box.y || 0) >= slideSize.heightPt * 0.2
      && Number(box.y || 0) <= slideSize.heightPt * 0.82;
  });
  const leftEngineText = textBoxes.filter((item) => {
    const box = item?.box || {};
    return Number(box.x || 0) <= slideSize.widthPt * 0.28
      && Number(box.y || 0) >= slideSize.heightPt * 0.45
      && Number(box.y || 0) <= slideSize.heightPt * 0.64;
  });
  const areaRatio = panel.w * panel.h / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  const candidate = scoreDiagramCandidate({
    panels: [panel],
    textBoxes,
    slideSize,
    structuralLines,
    semanticSignals: Number(hasEngine) + Number(hasValueBanner) + roleSignals
  });
  return hasEngine
    && hasValueBanner
    && roleSignals >= 3
    && rightBodyText.length >= 9
    && leftEngineText.length >= 1
    && isAcceptableDiagramCandidate(candidate, 5)
    && areaRatio >= 0.52
    && areaRatio <= 0.68
    && panel.x <= slideSize.widthPt * 0.05
    && panel.y >= slideSize.heightPt * 0.15
    && panel.y <= slideSize.heightPt * 0.23
    && panel.w >= slideSize.widthPt * 0.9
    && panel.h >= slideSize.heightPt * 0.58
    && panel.y + panel.h <= slideSize.heightPt * 0.86;
}

function shouldUseWmsChainUnderlay({ panels, textBoxes = [], slideSize = DEFAULT_SLIDE, structuralLines = [] } = {}) {
  if (!Array.isArray(panels) || panels.length !== 2) return false;
  if (textBoxes.length < 18 || textBoxes.length > 32) return false;
  const text = textBoxes.map((item) => String(item?.text || "")).join("\n");
  const hasWmsTitle = /WMS/i.test(text) && /复杂主链路|隐性风险|物流/i.test(text);
  const tollgateSignals = ["Tollgate1", "Tollgate2", "Tollgate3"]
    .filter((item) => new RegExp(item, "i").test(text)).length;
  const cardSignals = ["挑战", "AI介入", "价值落地"]
    .filter((item) => text.includes(item)).length;
  const hasValueBanner = /产出价值/.test(text) && /高效协同|可视化实体/.test(text);
  const totalArea = panels.reduce((sum, box) => sum + box.w * box.h, 0) / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  const candidate = scoreDiagramCandidate({
    panels,
    textBoxes,
    slideSize,
    structuralLines,
    semanticSignals: Number(hasWmsTitle) + tollgateSignals + cardSignals + Number(hasValueBanner)
  });
  return hasWmsTitle
    && tollgateSignals >= 3
    && cardSignals >= 3
    && hasValueBanner
    && isAcceptableDiagramCandidate(candidate, 6)
    && totalArea >= 0.56
    && totalArea <= 0.74
    && panels[0].y >= slideSize.heightPt * 0.18
    && panels[0].y <= slideSize.heightPt * 0.26
    && panels[0].h >= slideSize.heightPt * 0.34
    && panels[1].y >= slideSize.heightPt * 0.62
    && panels[1].h >= slideSize.heightPt * 0.26;
}

function shouldUseComparisonMatrixCrop({ matrixBox, textBoxes = [], slideSize = DEFAULT_SLIDE } = {}) {
  if (!matrixBox) return false;
  if (textBoxes.length < 14 || textBoxes.length > 34) return false;
  const text = textBoxes.map((item) => String(item?.text || "")).join("\n");
  const hasHeaders = /传统工作方式/.test(text)
    && /普通\s*AI\s*工具/i.test(text)
    && /PM\s*Portal\s*AI\s*Skills/i.test(text);
  const rowSignals = ["场景理解", "流程引擎", "质量控制", "资产沉淀"]
    .filter((item) => text.includes(item)).length;
  const blueColumnSignals = ["深度结合", "需求", "前置拦截", "产出自动落盘"]
    .filter((item) => text.includes(item)).length;
  const areaRatio = matrixBox.w * matrixBox.h / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  return hasHeaders
    && rowSignals >= 3
    && blueColumnSignals >= 2
    && areaRatio >= 0.58
    && areaRatio <= 0.86
    && matrixBox.x >= slideSize.widthPt * 0.02
    && matrixBox.x <= slideSize.widthPt * 0.12
    && matrixBox.y >= slideSize.heightPt * 0.04
    && matrixBox.y <= slideSize.heightPt * 0.16
    && matrixBox.w >= slideSize.widthPt * 0.78
    && matrixBox.h >= slideSize.heightPt * 0.68;
}

function lineDiagramPxBounds(lines, image, slideSize) {
  if (!image || !Array.isArray(lines) || lines.length === 0) return null;
  const contentTop = slideSize.heightPt * 0.22;
  const contentLines = lines
    .map((line) => line.box)
    .filter((box) => {
      const centerY = Number(box.y || 0) + Number(box.h || 0) / 2;
      const span = Math.max(Number(box.w || 0), Number(box.h || 0));
      return centerY >= contentTop && span >= 70;
    });
  if (contentLines.length < 24) return null;
  const ptBox = contentLines.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  return ptToPxBox(expandPtBox(ptBox, slideSize, 4, 4), image, slideSize, 0);
}

function shouldUseLineDiagramUnderlay({ pxBox, image, detectedLineCount = 0, textBoxes = [] } = {}) {
  if (!pxBox || !image) return false;
  if (detectedLineCount < 48) return false;
  const areaRatio = pxBox.w * pxBox.h / Math.max(1, image.width * image.height);
  if (areaRatio < 0.52 || areaRatio > 0.65) return false;
  if (pxBox.w > image.width * 0.94 && pxBox.h > image.height * 0.9) return false;
  return textBoxes.length <= 8;
}

function shouldUseIllustrationCardUnderlay({ image, textBoxes = [], box, slideSize = DEFAULT_SLIDE } = {}) {
  if (!image || !box) return false;
  if (textBoxes.length < 10 || textBoxes.length > 14) return false;
  const titleLike = textBoxes.filter((item) => {
    const itemBox = item?.box || {};
    const size = Number(item?.font?.sizePt || 0);
    return Number(itemBox.y || 0) < 125 && Number(itemBox.h || 0) >= 18 && size >= 17;
  });
  if (titleLike.length < 3) return false;
  const areaRatio = box.w * box.h / Math.max(1, slideSize.widthPt * slideSize.heightPt);
  if (areaRatio < 0.45 || areaRatio > 0.68) return false;
  return box.w >= slideSize.widthPt * 0.78 && box.h >= slideSize.heightPt * 0.58;
}

function shouldUseSaturatedDiagramUnderlay({ aggregate, image, pxBox, detectedLineCount = 0, textBoxes = [] } = {}) {
  if (!aggregate || !image || !pxBox) return false;
  if (textBoxes.length < 12 || textBoxes.length > 24) return false;
  if (detectedLineCount < 60) return false;
  const fullCanvasAggregate = aggregate.box.w > image.width * 0.96 && aggregate.box.h > image.height * 0.96;
  if (!fullCanvasAggregate) return false;
  const areaRatio = pxBox.w * pxBox.h / Math.max(1, image.width * image.height);
  return areaRatio >= 0.34 && areaRatio <= 0.72;
}

function decorativeBackgroundMode({ image, textBoxes = [], detectedLineCount = 0 } = {}) {
  if (shouldUseDecorativeCoverBackground({ image, textBoxes, detectedLineCount })) return "cover";
  if (shouldUseDecorativePageChromeBackground({ image, textBoxes, detectedLineCount })) return "page-chrome";
  return null;
}

function shouldUseDecorativeCoverBackground({ image, textBoxes = [], detectedLineCount = 0 } = {}) {
  if (!image || textBoxes.length < 3 || textBoxes.length > 7) return false;
  // Particle/globe covers can contain many short grid-like strokes. Keep a
  // tighter high-line exception for sparse-title edge-decorated covers, while
  // continuing to reject truly dense diagram pages.
  if (detectedLineCount > 100) return false;
  const stats = samplePageColorStats(image);
  const decoration = sampleEdgeDecorationStats(image);
  const strongTitle = textBoxes.some((item) => {
    const text = String(item?.text || "").trim();
    const box = item?.box || {};
    const fontSize = Number(item?.font?.sizePt || 0);
    const cjkCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
    return cjkCount >= 4 && (Number(box.h || 0) >= 40 || fontSize >= 28);
  });
  const compactCoverText = strongTitle && textBoxes.length <= 6;
  const darkTechnologyCover = compactCoverText
    && stats.nonWhiteRatio >= 0.68
    && stats.darkRatio >= 0.45
    && stats.saturatedRatio >= 0.28;
  const edgeDecoratedCover = compactCoverText
    && stats.nonWhiteRatio >= 0.52
    && stats.darkRatio >= 0.32
    && stats.saturatedRatio >= 0.18
    && decoration.edgeSaturatedRatio >= 0.08
    && decoration.edgeNonWhiteRatio >= 0.42;
  const particleGridCover = detectedLineCount > 80
    && textBoxes.length <= 4
    && edgeDecoratedCover;
  return (detectedLineCount <= 80 && (darkTechnologyCover || edgeDecoratedCover))
    || particleGridCover;
}

function shouldUseDecorativePageChromeBackground({ image, textBoxes = [], detectedLineCount = 0 } = {}) {
  if (!image || textBoxes.length > 70) return false;
  if (detectedLineCount > 90) return false;
  const stats = samplePageColorStats(image);
  if (textBoxes.length <= 2) {
    return stats.nonWhiteRatio >= 0.62
      && stats.darkRatio >= 0.42
      && stats.saturatedRatio >= 0.18;
  }
  if (textBoxes.length < 8) return false;
  if (stats.nonWhiteRatio < 0.62 || stats.darkRatio < 0.34 || stats.saturatedRatio < 0.18) return false;
  const strongHeader = textBoxes.some((item) => {
    const text = String(item?.text || "").trim();
    const box = item?.box || {};
    const fontSize = Number(item?.font?.sizePt || 0);
    const cjkCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
    return Number(box.y || 0) <= 125
      && cjkCount >= 6
      && (Number(box.h || 0) >= 22 || fontSize >= 20);
  });
  return strongHeader;
}

function shouldUseSparseDiagramUnderlay({ aggregate, image, detectedLineCount = 0, textBoxes = [] } = {}) {
  if (!aggregate || !image) return false;
  if (textBoxes.length < 6 || textBoxes.length > 10) return false;
  if (detectedLineCount < 48) return false;
  const areaRatio = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (areaRatio < 0.18 || areaRatio > 0.45) return false;
  if (aggregate.box.w > image.width * 0.88 && aggregate.box.h > image.height * 0.8) return false;
  return true;
}

function samplePageColorStats(image) {
  let total = 0;
  let nonWhite = 0;
  let dark = 0;
  let saturated = 0;
  const step = Math.max(1, Math.floor(Math.min(image.width, image.height) / 72));
  for (let y = 0; y < image.height; y += step) {
    for (let x = 0; x < image.width; x += step) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      total += 1;
      if (luma(color) < 238 || saturation(color) > 0.08) nonWhite += 1;
      if (luma(color) < 120) dark += 1;
      if (saturation(color) > 0.22) saturated += 1;
    }
  }
  return {
    nonWhiteRatio: total ? nonWhite / total : 0,
    darkRatio: total ? dark / total : 0,
    saturatedRatio: total ? saturated / total : 0
  };
}

function sampleEdgeDecorationStats(image) {
  if (!image) {
    return {
      edgeNonWhiteRatio: 0,
      edgeSaturatedRatio: 0
    };
  }
  let total = 0;
  let nonWhite = 0;
  let saturated = 0;
  const step = Math.max(1, Math.floor(Math.min(image.width, image.height) / 72));
  const edgeWidth = Math.max(1, Math.floor(image.width * 0.18));
  const edgeHeight = Math.max(1, Math.floor(image.height * 0.18));
  for (let y = 0; y < image.height; y += step) {
    for (let x = 0; x < image.width; x += step) {
      const nearEdge = x <= edgeWidth
        || x >= image.width - edgeWidth
        || y <= edgeHeight
        || y >= image.height - edgeHeight;
      if (!nearEdge) continue;
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      total += 1;
      if (luma(color) < 238 || saturation(color) > 0.08) nonWhite += 1;
      if (saturation(color) > 0.22) saturated += 1;
    }
  }
  return {
    edgeNonWhiteRatio: total ? nonWhite / total : 0,
    edgeSaturatedRatio: total ? saturated / total : 0
  };
}

function illustrationCardBounds(textBoxes, slideSize) {
  const boxes = textBoxes
    .filter((item) => item.box && Number(item.box.y || 0) > 55)
    .map((item) => item.box);
  if (boxes.length < 8) return null;
  const union = boxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  return expandPtBox(union, slideSize, 0, 0);
}

function saturatedGraphicBounds(image, masks = []) {
  let box = null;
  let count = 0;
  const maskList = masks || [];
  const inMask = (x, y) => maskList.some((mask) =>
    x >= mask.x && x < mask.x + mask.w && y >= mask.y && y < mask.y + mask.h
  );
  for (let y = 0; y < image.height; y += 2) {
    if (y > image.height * 0.92) continue;
    for (let x = 0; x < image.width; x += 2) {
      if (inMask(x, y)) continue;
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      if (saturation(color) <= 0.28 || luma(color) >= 230) continue;
      count += 1;
      box = box
        ? {
          x: Math.min(box.x, x),
          y: Math.min(box.y, y),
          w: Math.max(box.x + box.w, x + 1) - Math.min(box.x, x),
          h: Math.max(box.y + box.h, y + 1) - Math.min(box.y, y)
        }
        : { x, y, w: 1, h: 1 };
    }
  }
  return count >= 4000 ? box : null;
}

function visualClusterPxBounds(components, image) {
  if (!image || !Array.isArray(components) || components.length < 3) return null;
  const useful = components.filter((component) => {
    const box = component?.box || {};
    const areaRatio = Number(box.w || 0) * Number(box.h || 0) / Math.max(1, image.width * image.height);
    return areaRatio >= 0.004 && areaRatio <= 0.22;
  });
  if (useful.length < 3) return null;
  const union = useful.reduce((acc, component) => (acc ? unionBox(acc, component.box) : { ...component.box }), null);
  return expandPxBox(union, image, 10);
}

function leftIllustrationGraphicBounds(image, masks = []) {
  let box = null;
  let count = 0;
  const maxX = Math.floor(image.width * 0.42);
  const maxY = Math.floor(image.height * 0.86);
  const inMask = (x, y) => masks.some((mask) =>
    x >= mask.x && x < mask.x + mask.w && y >= mask.y && y < mask.y + mask.h
  );
  for (let y = 0; y < maxY; y += 2) {
    for (let x = 0; x < maxX; x += 2) {
      if (inMask(x, y)) continue;
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      if (luma(color) > 244 && saturation(color) < 0.12) continue;
      if (luma(color) > 230 && saturation(color) < 0.22) continue;
      count += 1;
      box = box
        ? {
          x: Math.min(box.x, x),
          y: Math.min(box.y, y),
          w: Math.max(box.x + box.w, x + 1) - Math.min(box.x, x),
          h: Math.max(box.y + box.h, y + 1) - Math.min(box.y, y)
        }
        : { x, y, w: 1, h: 1 };
    }
  }
  if (!box || count < 2500) return null;
  return expandPxBox(box, image, 14, 14);
}

function bottomBannerBounds(image) {
  let box = null;
  let count = 0;
  const startY = Math.floor(image.height * 0.84);
  for (let y = startY; y < image.height; y += 2) {
    for (let x = 0; x < image.width; x += 2) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      if (saturation(color) < 0.18 || luma(color) > 210) continue;
      count += 1;
      box = box
        ? {
          x: Math.min(box.x, x),
          y: Math.min(box.y, y),
          w: Math.max(box.x + box.w, x + 1) - Math.min(box.x, x),
          h: Math.max(box.y + box.h, y + 1) - Math.min(box.y, y)
        }
        : { x, y, w: 1, h: 1 };
    }
  }
  if (!box || count < 4000) return null;
  return expandPxBox(box, image, 0, 4);
}

function refineBottomValueBannerBoxFromText(bannerBox, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const valueText = (textBoxes || []).find((textBox) => /产出价值|核心价值|价值[:：]/.test(String(textBox?.text || "")));
  if (!valueText?.box) return bannerBox;
  const textY = Number(valueText.box.y || 0);
  if (!Number.isFinite(textY) || textY <= 0) return bannerBox;
  const refinedY = Math.max(Number(bannerBox.y || 0), Math.min(textY - 28, Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt) - 36));
  return {
    x: Math.min(Number(bannerBox.x || 0), 0),
    y: round(refinedY),
    w: Math.max(Number(bannerBox.w || 0), Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt)),
    h: round(Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt) - refinedY)
  };
}

function twoPanelDiagramBounds(textBoxes, slideSize) {
  const upperBoxes = textBoxes
    .filter((item) => {
      const box = item?.box || {};
      return Number(box.y || 0) >= slideSize.heightPt * 0.18
        && Number(box.y || 0) <= slideSize.heightPt * 0.76;
    })
    .map((item) => item.box);
  const leftBoxes = upperBoxes.filter((box) => Number(box.x || 0) < slideSize.widthPt * 0.5);
  const rightBoxes = upperBoxes.filter((box) => Number(box.x || 0) >= slideSize.widthPt * 0.5);
  if (leftBoxes.length < 8 || rightBoxes.length < 4) return [];
  const leftUnion = leftBoxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  const rightUnion = rightBoxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  return [
    fitPanelBox(expandPtBox(leftUnion, slideSize, 55, 36), slideSize, {
      minX: 18,
      maxRight: slideSize.widthPt * 0.49,
      minY: slideSize.heightPt * 0.13,
      maxBottom: slideSize.heightPt * 0.79
    }),
    fitPanelBox(expandPtBox(rightUnion, slideSize, 78, 48), slideSize, {
      minX: slideSize.widthPt * 0.5,
      maxRight: slideSize.widthPt - 22,
      minY: slideSize.heightPt * 0.13,
      maxBottom: slideSize.heightPt * 0.79
    })
  ];
}

function topComplexDiagramBounds(textBoxes, slideSize) {
  const topBoxes = textBoxes
    .filter((item) => {
      const box = item?.box || {};
      return Number(box.y || 0) >= slideSize.heightPt * 0.08
        && Number(box.y || 0) <= slideSize.heightPt * 0.72;
    })
    .map((item) => item.box);
  if (topBoxes.length < 20) return null;
  const union = topBoxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  const expanded = expandPtBox(union, slideSize, 88, 48);
  return fitPanelBox(expanded, slideSize, {
    minX: slideSize.widthPt * 0.04,
    maxRight: slideSize.widthPt * 0.96,
    minY: slideSize.heightPt * 0.06,
    maxBottom: slideSize.heightPt * 0.7
  });
}

function collaborationFlowBounds(textBoxes, slideSize) {
  const flowBoxes = textBoxes
    .filter((item) => {
      const box = item?.box || {};
      const y = Number(box.y || 0);
      return y >= slideSize.heightPt * 0.2 && y <= slideSize.heightPt * 0.82;
    })
    .map((item) => item.box);
  if (flowBoxes.length < 9) return null;
  const union = flowBoxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  const expanded = expandPtBox(union, slideSize, 118, 54);
  return fitPanelBox(expanded, slideSize, {
    minX: slideSize.widthPt * 0.02,
    maxRight: slideSize.widthPt * 0.97,
    minY: slideSize.heightPt * 0.18,
    maxBottom: slideSize.heightPt * 0.84
  });
}

function wmsChainBounds(textBoxes, slideSize) {
  const topBoxes = textBoxes
    .filter((item) => {
      const box = item?.box || {};
      const y = Number(box.y || 0);
      return y >= slideSize.heightPt * 0.2 && y <= slideSize.heightPt * 0.6;
    })
    .map((item) => item.box);
  const bottomBoxes = textBoxes
    .filter((item) => {
      const box = item?.box || {};
      const y = Number(box.y || 0);
      return y >= slideSize.heightPt * 0.64 && y <= slideSize.heightPt * 0.94;
    })
    .map((item) => item.box);
  if (topBoxes.length < 10 || bottomBoxes.length < 8) return [];
  const topUnion = topBoxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  const bottomUnion = bottomBoxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  return [
    fitPanelBox(expandPtBox(topUnion, slideSize, 34, 28), slideSize, {
      minX: slideSize.widthPt * 0.02,
      maxRight: slideSize.widthPt * 0.97,
      minY: slideSize.heightPt * 0.2,
      maxBottom: slideSize.heightPt * 0.62
    }),
    fitPanelBox(expandPtBox(bottomUnion, slideSize, 34, 24), slideSize, {
      minX: slideSize.widthPt * 0.02,
      maxRight: slideSize.widthPt * 0.97,
      minY: slideSize.heightPt * 0.62,
      maxBottom: slideSize.heightPt * 0.97
    })
  ];
}

function comparisonMatrixBounds(textBoxes, slideSize) {
  const boxes = textBoxes
    .filter((item) => item?.box)
    .map((item) => item.box);
  if (boxes.length < 12) return null;
  const union = boxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
  return fitPanelBox(expandPtBox(union, slideSize, 28, 26), slideSize, {
    minX: slideSize.widthPt * 0.02,
    maxRight: slideSize.widthPt * 0.98,
    minY: slideSize.heightPt * 0.03,
    maxBottom: slideSize.heightPt * 0.95
  });
}

function segmentComparisonMatrix(matrixBox, slideSize) {
  const splitX = round(Math.min(
    matrixBox.x + matrixBox.w * 0.69,
    slideSize.widthPt * 0.62
  ));
  const left = {
    x: matrixBox.x,
    y: matrixBox.y,
    w: round(splitX - matrixBox.x),
    h: matrixBox.h
  };
  const right = {
    x: splitX,
    y: matrixBox.y,
    w: round(matrixBox.x + matrixBox.w - splitX),
    h: matrixBox.h
  };
  return [left, right].filter((box) => box.w > 1 && box.h > 1);
}

function fitPanelBox(box, slideSize, bounds) {
  const x = Math.max(bounds.minX, box.x);
  const y = Math.max(bounds.minY, box.y);
  const right = Math.min(bounds.maxRight, box.x + box.w);
  const bottom = Math.min(bounds.maxBottom, box.y + box.h);
  return {
    x: round(x),
    y: round(y),
    w: round(Math.max(1, right - x)),
    h: round(Math.max(1, bottom - y))
  };
}

function expandPxBox(box, image, xPad, yPad) {
  const x = Math.max(0, Math.floor(box.x - xPad));
  const y = Math.max(0, Math.floor(box.y - yPad));
  const right = Math.min(image.width, Math.ceil(box.x + box.w + xPad));
  const bottom = Math.min(image.height, Math.ceil(box.y + box.h + yPad));
  return { x, y, w: Math.max(1, right - x), h: Math.max(1, bottom - y) };
}

function fitSingleUnderlayAggregate(aggregate, image) {
  if (!aggregate || !image) return null;
  const areaRatio = aggregate.box.w * aggregate.box.h / Math.max(1, image.width * image.height);
  if (areaRatio <= 0.65) return aggregate;
  if (areaRatio > 0.72) return null;
  for (let inset = 1; inset <= 80; inset += 1) {
    const box = trimPxBox(aggregate.box, image, inset);
    const fittedRatio = box.w * box.h / Math.max(1, image.width * image.height);
    if (fittedRatio <= 0.65) return { ...aggregate, box };
  }
  return null;
}

function contentTextBounds(textBoxes, slideSize) {
  const contentTop = slideSize.heightPt * 0.2;
  const boxes = textBoxes
    .filter((item) => item.box && item.box.y + item.box.h >= contentTop)
    .map((item) => item.box);
  if (boxes.length < 4) return null;
  return boxes.reduce((acc, box) => (acc ? unionPtBox(acc, box) : { ...box }), null);
}

function segmentTextBoxesForUnderlay(textBoxes, slideSize) {
  const contentTop = slideSize.heightPt * 0.2;
  const boxes = textBoxes
    .filter((item) => item.box && item.box.y + item.box.h >= contentTop)
    .map((item) => item.box)
    .sort((a, b) => (a.y + a.h / 2) - (b.y + b.h / 2));
  const rowGroups = groupBoxesByAxis(boxes, "y", 36);
  const segments = [];
  for (const row of rowGroups) {
    const columnGroups = groupBoxesByAxis(row.boxes.sort((a, b) => a.x - b.x), "x", 42);
    for (const column of columnGroups) {
      if (column.boxes.length < 2) continue;
      segments.push(expandPtBox(column.box, slideSize, 35, 30));
    }
  }
  return mergeOverlappingPtBoxes(segments, slideSize)
    .filter((box) => box.w > 90 && box.h > 55)
    .slice(0, 8);
}

function groupBoxesByAxis(boxes, axis, gapPt) {
  const groups = [];
  for (const box of boxes) {
    const start = axis === "x" ? box.x : box.y;
    const end = axis === "x" ? box.x + box.w : box.y + box.h;
    const group = groups.find((item) => start <= item.end + gapPt && end >= item.start - gapPt);
    if (group) {
      group.boxes.push(box);
      group.start = Math.min(group.start, start);
      group.end = Math.max(group.end, end);
      group.box = unionPtBox(group.box, box);
    } else {
      groups.push({ start, end, box: { ...box }, boxes: [box] });
    }
  }
  return groups;
}

function mergeOverlappingPtBoxes(boxes, slideSize) {
  const merged = [];
  for (const box of boxes) {
    const existing = merged.find((item) => boxesNearPt(item, box, 6));
    if (existing) {
      const next = unionPtBox(existing, box);
      existing.x = next.x;
      existing.y = next.y;
      existing.w = next.w;
      existing.h = next.h;
    } else {
      merged.push({ ...box });
    }
  }
  return merged.map((box) => expandPtBox(box, slideSize, 0, 0));
}

function isUsefulGraphicComponent(component, image) {
  const { w, h } = component.box;
  const area = w * h;
  if (area < image.width * image.height * 0.0025) return false;
  if (area > image.width * image.height * 0.58) return false;
  if (w < 35 || h < 35) return false;
  if (w > image.width * 0.92 && h > image.height * 0.92) return false;
  if (w > image.width * 0.88 && h > image.height * 0.68) return false;
  return true;
}

function isGraphicForeground(color) {
  if (color.a < 64) return false;
  if (luma(color) > 242 && saturation(color) < 0.12) return false;
  return true;
}

function inAnyMask(x, y, masks) {
  return masks.some((mask) => x >= mask.x && x <= mask.x + mask.w && y >= mask.y && y <= mask.y + mask.h);
}

function boxesNear(a, b, distance) {
  return !(a.x + a.w + distance < b.x
    || b.x + b.w + distance < a.x
    || a.y + a.h + distance < b.y
    || b.y + b.h + distance < a.y);
}

function unionBox(a, b) {
  const x1 = Math.min(a.x, b.x);
  const y1 = Math.min(a.y, b.y);
  const x2 = Math.max(a.x + a.w, b.x + b.w);
  const y2 = Math.max(a.y + a.h, b.y + b.h);
  return { x: x1, y: y1, w: x2 - x1, h: y2 - y1 };
}

function expandPxBox(box, image, padding) {
  const x = clamp(Math.floor(box.x - padding), 0, image.width - 1);
  const y = clamp(Math.floor(box.y - padding), 0, image.height - 1);
  const x2 = clamp(Math.ceil(box.x + box.w + padding), x + 1, image.width);
  const y2 = clamp(Math.ceil(box.y + box.h + padding), y + 1, image.height);
  return { x, y, w: x2 - x, h: y2 - y };
}

function pageImageFile(workDir, page, pageIndex) {
  const candidates = [
    page.sourceImage,
    path.join(workDir, "normalized", `${String(pageIndex + 1).padStart(3, "0")}.png`)
  ].filter(Boolean);
  for (const candidate of candidates) {
    const absolute = path.isAbsolute(candidate) ? candidate : path.resolve(path.dirname(path.join(workDir, "ir", "deck.json")), candidate);
    if (fs.existsSync(absolute)) return absolute;
    const workRelative = path.resolve(workDir, candidate);
    if (fs.existsSync(workRelative)) return workRelative;
  }
  return null;
}

function visibleTextBoxes(textBoxes, image, slideSize) {
  return textBoxes
    .filter((item) => item && item.box && typeof item.text === "string" && item.text.trim())
    .filter((item) => shouldNativeTextBox(item))
    .map((item) => {
      const next = JSON.parse(JSON.stringify(item));
      next.font = next.font || {};
      next.font.opacity = 1;
      next.font.color = image ? sampleInkColor(image, next.box, slideSize, next.font.color) : normalizeHex(next.font.color, "#111111");
      next.font.sizePt = refineFontSize(next);
      next.font.weight = inferWeight(next, next.font.weight);
      next.font.valign = next.font.valign || "middle";
      next.style = {
        ...(next.style || {}),
        visibility: "visible",
        opacity: 1,
        marginLeftPt: 0,
        marginRightPt: 0,
        marginTopPt: 0,
        marginBottomPt: 0,
        wrap: shouldDisableTextWrap(next) ? false : undefined
      };
      next.source = {
        ...(next.source || {}),
        editable: true,
        nativeRebuild: true,
        // `visibleTextBoxes` is the final rendering path for OCR text. A
        // stale overlay hint must not hide text that is no longer covered by
        // a retained fidelity crop.
        overlayVisibility: "visible"
      };
      return next;
    });
}

function createTextBackplateShapes(image, textBoxes, slideSize = DEFAULT_SLIDE) {
  return (textBoxes || [])
    .map((textBox, index) => {
      if (!shouldCreateTextBackplate(textBox, slideSize)) return null;
      const pxBox = ptToPxBox(textBox.box, image, slideSize, 5);
      const background = sampleMaskBackgroundColor(image, pxBox);
      if (!isUsefulTextBackplateColor(background)) return null;
      return {
        id: `native-text-backplate-${index}`,
        type: "roundRect",
        box: expandPtBox(textBox.box, slideSize, 6, 3),
        style: {
          fill: rgbToHex(background),
          stroke: "none",
          strokeWidthPt: 0,
          radiusRatio: 0.08
        },
        source: {
          editable: true,
          nativeRebuild: true,
          detector: "sampled-text-backplate"
        }
      };
    })
    .filter(Boolean);
}

function createValueBannerBackgroundShapes(images = [], textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE, irDir = null) {
  if (!sourceImage) return [];
  const shapes = [];
  for (const image of images || []) {
    if (!shouldObjectifyValueBanner(image, textBoxes, slideSize)) continue;
    const sampled = sampleStableValueBannerFill(sourceImage, image.box, slideSize)
      || sampleStableValueBannerFillFromAsset(image, textBoxes, slideSize, irDir)
      || sampleWideValueBannerGradientFill(sourceImage, image, slideSize)
      || sampleApproximateWideValueBannerFill(sourceImage, image, slideSize);
    if (!sampled) continue;
    image.source = {
      ...(image.source || {}),
      valueBannerObjectified: true,
      objectifiedValueBannerFill: sampled.fill,
      ...(sampled.approximate ? { objectifiedValueBannerApproximateFill: true } : {}),
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "local fidelity crop"}; replaced by native value banner background`
    };
    const gradientShape = semanticCycleValueBannerGradientShape(image, textBoxes, sampled);
    if (gradientShape) {
      image.source.objectifiedValueBannerGradientStops = gradientShape.style.gradient.stops.length;
      image.source.objectifiedValueBannerGradientNativeShape = true;
      shapes.push(gradientShape);
      continue;
    }
    if (sampled.gradientStops) {
      image.source.objectifiedValueBannerGradientStops = sampled.gradientStops.length;
      image.source.objectifiedValueBannerGradientNativeShape = true;
      image.source.objectifiedValueBannerApproximateGradient = true;
      shapes.push(wideValueBannerGradientShape(image, sampled));
      continue;
    }
    shapes.push({
      id: `${image.id || "value-banner"}-native-background`,
      type: "rect",
      box: image.box,
      style: {
        fill: sampled.fill,
        stroke: "none",
        strokeWidthPt: 0
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "value-banner-native-background",
        expressionForm: "value-banner",
        expressionSubtype: image.source?.expressionSubtype || "value-banner-strip",
        layerSourceId: image.id || null,
        colorVariance: sampled.meanDistance,
        dominantCoverage: sampled.dominantCoverage,
        ...(sampled.approximate ? { approximateFill: true } : {})
      }
    });
  }
  return shapes;
}

function wideValueBannerGradientShape(image, sampled = {}) {
  const box = image.box || {};
  return {
    id: `${image.id || "value-banner"}-native-wide-gradient`,
    type: "rect",
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(box.w),
      h: round(box.h)
    },
    style: {
      fill: sampled.fill || sampled.gradientStops?.[1]?.color || "#167E73",
      stroke: "none",
      strokeWidthPt: 0,
      gradient: {
        type: "linear",
        angleDeg: 0,
        stops: sampled.gradientStops || []
      }
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "value-banner-native-wide-gradient-background",
      expressionForm: "value-banner",
      expressionSubtype: image.source?.expressionSubtype || "value-banner-strip",
      layerSourceId: image.id || null,
      gradientStopCount: Array.isArray(sampled.gradientStops) ? sampled.gradientStops.length : 0,
      colorVariance: sampled.meanDistance,
      approximateGradient: true
    }
  };
}

function semanticCycleValueBannerGradientShape(image, textBoxes = [], sampled = {}) {
  if (!isSemanticCycleValueBanner(image, textBoxes)) return null;
  const box = image.box || {};
  const left = "#0B69A6";
  const middle = sampled.fill || "#167E73";
  const right = "#249A42";
  return {
    id: `${image.id || "value-banner"}-native-gradient`,
    type: "rect",
    box: {
      x: round(box.x),
      y: round(box.y),
      w: round(box.w),
      h: round(box.h)
    },
    style: {
      fill: middle,
      stroke: "none",
      strokeWidthPt: 0,
      gradient: {
        type: "linear",
        angleDeg: 0,
        stops: [
          { position: 0, color: left },
          { position: 0.52, color: middle },
          { position: 1, color: right }
        ]
      }
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "value-banner-native-gradient-background",
      expressionForm: "value-banner",
      expressionSubtype: image.source?.expressionSubtype || "value-banner-strip",
      layerSourceId: image.id || null,
      gradientStopCount: 3,
      colorVariance: sampled.meanDistance,
      dominantCoverage: sampled.dominantCoverage
    }
  };
}

function isSemanticCycleValueBanner(image, textBoxes = []) {
  const source = image?.source || {};
  if (source.expressionSubtype !== "value-banner-strip") return false;
  if (!/saturated-diagram-bottom-banner|semantic-cycle|value-banner/i.test(String(image?.id || ""))) return false;
  return (textBoxes || []).some((textBox) =>
    /^产出价值/.test(String(textBox?.text || "").trim())
    && boxCenterInside(textBox.box, image.box)
  );
}

function sampleStableValueBannerFillFromAsset(image, textBoxes = [], slideSize = DEFAULT_SLIDE, irDir = null) {
  const internalTextCount = (textBoxes || []).filter((textBox) => boxCenterInside(textBox.box, image.box)).length;
  if (internalTextCount <= 0) return null;
  const assetFile = resolveAssetPathForIr(image?.assetPath, irDir);
  if (!assetFile || !fs.existsSync(assetFile)) return null;
  let cropImage = null;
  try {
    cropImage = readPng(assetFile);
  } catch {
    return null;
  }
  return sampleStableValueBannerFill(
    cropImage,
    { x: 0, y: 0, w: image.box.w, h: image.box.h },
    { widthPt: image.box.w, heightPt: image.box.h }
  );
}

function shouldObjectifyValueBanner(image, textBoxes = [], slideSize = DEFAULT_SLIDE) {
  const source = image?.source || {};
  const box = image?.box || {};
  const expression = source.expressionForm || classifyImageExpressionForm(image);
  if (expression !== "value-banner") return false;
  if (!box.w || !box.h) return false;
  if (Number(box.w) / Math.max(1, slideSize.widthPt || DEFAULT_SLIDE.widthPt) < 0.45) return false;
  if (Number(box.h) < 28 || Number(box.h) > 120) return false;
  const internalTextCount = (textBoxes || []).filter((textBox) => boxCenterInside(textBox.box, box)).length;
  if (internalTextCount >= 4) return false;
  return true;
}

function sampleStableValueBannerFill(sourceImage, box, slideSize = DEFAULT_SLIDE) {
  const pxBox = trimPxBox(ptToPxBox(box, sourceImage, slideSize, 0), sourceImage, 6);
  const insetX = Math.floor(pxBox.w * 0.08);
  const insetY = Math.floor(pxBox.h * 0.18);
  const sampleBox = {
    x: clamp(pxBox.x + insetX, 0, sourceImage.width - 1),
    y: clamp(pxBox.y + insetY, 0, sourceImage.height - 1),
    w: 1,
    h: 1
  };
  sampleBox.w = clamp(pxBox.w - insetX * 2, 1, sourceImage.width - sampleBox.x);
  sampleBox.h = clamp(pxBox.h - insetY * 2, 1, sourceImage.height - sampleBox.y);
  const stride = Math.max(2, Math.floor(Math.min(sampleBox.w, sampleBox.h) / 16));
  const colors = [];
  for (let y = sampleBox.y; y < sampleBox.y + sampleBox.h; y += stride) {
    for (let x = sampleBox.x; x < sampleBox.x + sampleBox.w; x += stride) {
      const color = pixel(sourceImage, x, y);
      if (color.a >= 200) colors.push(color);
    }
  }
  if (colors.length < 12) return null;
  const average = averageColor(colors);
  const meanDistance = colors.reduce((sum, color) => sum + colorDistance(color, average), 0) / colors.length;
  if (meanDistance > 42) {
    return dominantStableValueBannerFill(colors);
  }
  if (luma(average) > 245 && saturation(average) < 0.04) return null;
  return {
    fill: rgbToHex(average),
    meanDistance: round(meanDistance)
  };
}

function sampleWideValueBannerGradientFill(sourceImage, image = {}, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage || !isApproximateWideValueBannerCandidate(image, slideSize)) return null;
  const pxBox = trimPxBox(ptToPxBox(image.box, sourceImage, slideSize, 0), sourceImage, 6);
  const insetY = Math.floor(pxBox.h * 0.22);
  const band = {
    x: pxBox.x,
    y: clamp(pxBox.y + insetY, 0, sourceImage.height - 1),
    w: pxBox.w,
    h: clamp(pxBox.h - insetY * 2, 1, sourceImage.height)
  };
  band.h = clamp(band.h, 1, sourceImage.height - band.y);
  const segments = [0.16, 0.5, 0.84].map((center) => {
    const segmentWidth = Math.max(8, Math.floor(band.w * 0.16));
    return sampleValueBannerSegment(sourceImage, {
      x: clamp(Math.floor(band.x + band.w * center - segmentWidth / 2), 0, sourceImage.width - 1),
      y: band.y,
      w: segmentWidth,
      h: band.h
    });
  });
  if (segments.some((segment) => !segment || segment.meanDistance > 74)) return null;
  if (segments.every((segment) => saturation(segment.average) < 0.10)) return null;
  const contrast = colorDistance(segments[0].average, segments[2].average);
  if (contrast < 38) return null;
  return {
    fill: rgbToHex(segments[1].average),
    meanDistance: round(Math.max(...segments.map((segment) => segment.meanDistance))),
    gradientStops: [
      { position: 0, color: rgbToHex(segments[0].average) },
      { position: 0.5, color: rgbToHex(segments[1].average) },
      { position: 1, color: rgbToHex(segments[2].average) }
    ]
  };
}

function sampleValueBannerSegment(sourceImage, box = {}) {
  const sampleBox = {
    x: clamp(Math.floor(box.x || 0), 0, sourceImage.width - 1),
    y: clamp(Math.floor(box.y || 0), 0, sourceImage.height - 1),
    w: clamp(Math.floor(box.w || 1), 1, sourceImage.width),
    h: clamp(Math.floor(box.h || 1), 1, sourceImage.height)
  };
  sampleBox.w = clamp(sampleBox.w, 1, sourceImage.width - sampleBox.x);
  sampleBox.h = clamp(sampleBox.h, 1, sourceImage.height - sampleBox.y);
  const stride = Math.max(2, Math.floor(Math.min(sampleBox.w, sampleBox.h) / 12));
  const colors = [];
  for (let y = sampleBox.y; y < sampleBox.y + sampleBox.h; y += stride) {
    for (let x = sampleBox.x; x < sampleBox.x + sampleBox.w; x += stride) {
      const color = pixel(sourceImage, x, y);
      if (color.a >= 200) colors.push(color);
    }
  }
  if (colors.length < 10) return null;
  const average = averageColor(colors);
  if (luma(average) > 242 && saturation(average) < 0.06) return null;
  const meanDistance = colors.reduce((sum, color) => sum + colorDistance(color, average), 0) / colors.length;
  return { average, meanDistance };
}

function sampleApproximateWideValueBannerFill(sourceImage, image = {}, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage || !isApproximateWideValueBannerCandidate(image, slideSize)) return null;
  const pxBox = trimPxBox(ptToPxBox(image.box, sourceImage, slideSize, 0), sourceImage, 6);
  const insetX = Math.floor(pxBox.w * 0.06);
  const insetY = Math.floor(pxBox.h * 0.22);
  const sampleBox = {
    x: clamp(pxBox.x + insetX, 0, sourceImage.width - 1),
    y: clamp(pxBox.y + insetY, 0, sourceImage.height - 1),
    w: clamp(pxBox.w - insetX * 2, 1, sourceImage.width),
    h: clamp(pxBox.h - insetY * 2, 1, sourceImage.height)
  };
  sampleBox.w = clamp(sampleBox.w, 1, sourceImage.width - sampleBox.x);
  sampleBox.h = clamp(sampleBox.h, 1, sourceImage.height - sampleBox.y);
  const stride = Math.max(2, Math.floor(Math.min(sampleBox.w, sampleBox.h) / 18));
  const colors = [];
  for (let y = sampleBox.y; y < sampleBox.y + sampleBox.h; y += stride) {
    for (let x = sampleBox.x; x < sampleBox.x + sampleBox.w; x += stride) {
      const color = pixel(sourceImage, x, y);
      if (color.a >= 200) colors.push(color);
    }
  }
  if (colors.length < 18) return null;
  const average = averageColor(colors);
  const meanDistance = colors.reduce((sum, color) => sum + colorDistance(color, average), 0) / colors.length;
  if (meanDistance > 92) return null;
  if (luma(average) > 238 && saturation(average) < 0.08) return null;
  if (saturation(average) < 0.10) return null;
  return {
    fill: rgbToHex(average),
    meanDistance: round(meanDistance),
    approximate: true
  };
}

function isApproximateWideValueBannerCandidate(image = {}, slideSize = DEFAULT_SLIDE) {
  const source = image?.source || {};
  const box = image?.box || {};
  const detector = String(source.detector || "").toLowerCase();
  if (!/bottom-banner-crop|value-banner/.test(detector)) return false;
  const widthRatio = Number(box.w || 0) / Math.max(1, slideSize.widthPt || DEFAULT_SLIDE.widthPt);
  const yRatio = Number(box.y || 0) / Math.max(1, slideSize.heightPt || DEFAULT_SLIDE.heightPt);
  if (widthRatio < 0.88 || yRatio < 0.72) return false;
  if (Number(box.h || 0) < 36 || Number(box.h || 0) > 110) return false;
  return true;
}

function dominantStableValueBannerFill(colors) {
  const buckets = new Map();
  for (const color of colors) {
    const key = quantizeColorKey(color, 32);
    const bucket = buckets.get(key) || [];
    bucket.push(color);
    buckets.set(key, bucket);
  }
  const dominant = [...buckets.values()].sort((a, b) => b.length - a.length)[0] || [];
  const coverage = dominant.length / Math.max(1, colors.length);
  if (coverage < 0.44) return null;
  const average = averageColor(dominant);
  if (luma(average) > 245 && saturation(average) < 0.04) return null;
  const meanDistance = dominant.reduce((sum, color) => sum + colorDistance(color, average), 0) / dominant.length;
  if (meanDistance > 58) return null;
  return {
    fill: rgbToHex(average),
    meanDistance: round(meanDistance),
    dominantCoverage: round(coverage)
  };
}

function quantizeColorKey(color, step = 32) {
  return [
    Math.round(color.r / step) * step,
    Math.round(color.g / step) * step,
    Math.round(color.b / step) * step
  ].join(",");
}

function shouldCreateTextBackplate(textBox, slideSize = DEFAULT_SLIDE) {
  const box = textBox?.box || {};
  const font = textBox?.font || {};
  if (!box.w || !box.h) return false;
  if (normalizeHex(font.color, "#111111").toUpperCase() !== "#FFFFFF") return false;
  if (Number(box.w) < 180 || Number(box.h) < 12) return false;
  if (Number(box.w) / Math.max(1, slideSize.widthPt || DEFAULT_SLIDE.widthPt) < 0.22) return false;
  const text = String(textBox?.text || "").trim();
  if (/^产出价值/.test(text)) return false;
  return text.length >= 8;
}

function isUsefulTextBackplateColor(color) {
  return color && luma(color) < 210 && saturation(color) > 0.18;
}

function expandPtBox(box, slideSize = DEFAULT_SLIDE, xPad = 0, yPad = 0) {
  const x = Math.max(0, Number(box.x || 0) - xPad);
  const y = Math.max(0, Number(box.y || 0) - yPad);
  const widthLimit = Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt);
  const heightLimit = Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt);
  const x2 = Math.min(widthLimit, Number(box.x || 0) + Number(box.w || 0) + xPad);
  const y2 = Math.min(heightLimit, Number(box.y || 0) + Number(box.h || 0) + yPad);
  return { x, y, w: Math.max(0.1, x2 - x), h: Math.max(0.1, y2 - y) };
}

function createAssetOsKpiBenefitObjects(page, rawTextBoxes = [], visibleTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  if (!shouldObjectifyAssetOsKpiBenefitPage(page, rawTextBoxes, slideSize)) return { shapes: [], textBoxes: [] };
  const sourceImages = page?.images || [];
  let target = null;
  for (const image of sourceImages) {
    if (!isAssetOsKpiBenefitResidual(image, slideSize)) continue;
    target ||= image;
    image.source = {
      ...(image.source || {}),
      assetOsKpiBenefitObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "asset OS KPI residual"}; rebuilt KPI benefit cards and asset scale panel as native editable objects`
    };
  }
  const base = "asset-os-kpi-benefit";
  const src = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    confidence: 0.78,
    expressionForm: "kpi-benefit-layout",
    expressionSubtype: "asset-os-benefit-card-grid",
    ...extra
  });
  const shape = (id, detector, type, box, style, extra = {}) => ({
    id: `${base}-${id}`,
    type,
    box: roundedBox(box),
    style,
    source: src(detector, extra)
  });
  const cardStyle = (stroke, fill = "#FFFFFF") => ({
    fill,
    stroke,
    strokeWidthPt: 1.6,
    radiusPt: 5.2,
    shadow: {
      type: "outer",
      color: "#B9C5D2",
      alpha: 0.06,
      blurPt: 1.4,
      distancePt: 0.6,
      angleDeg: 90
    }
  });
  const shapes = [
    shape("top-left-card", "asset-os-kpi-benefit-native-card", "roundRect", { x: 42, y: 124.5, w: 432, h: 183 }, cardStyle("#47BC7E")),
    shape("top-right-card", "asset-os-kpi-benefit-native-card", "roundRect", { x: 470, y: 124.5, w: 448, h: 183 }, cardStyle("#47BC7E")),
    shape("bottom-left-card", "asset-os-kpi-benefit-native-card", "roundRect", { x: 42, y: 320.25, w: 432, h: 183 }, cardStyle("#2A78C9")),
    shape("asset-scale-panel", "asset-os-kpi-benefit-native-scale-panel", "roundRect", { x: 470, y: 320.25, w: 448, h: 183 }, cardStyle("#1C75D8", "#1D75D8")),
    ...assetOsKpiBenefitScaleCards(shape)
  ];
  const ocrTextBoxes = assetOsKpiBenefitTextBoxes(rawTextBoxes, visibleTextBoxes, src);
  const semanticTextBoxes = assetOsKpiBenefitSemanticNodeTextBoxes(target, visibleTextBoxes, src);
  const isClaimedTitle = (item) => {
    const label = normalizeTextKey(item?.text);
    return /量化收益验证：从单点提效到规模化资产复利|显著压缩重复劳动，将“项目一次性交付”升级为“持续的知识资产运营”/.test(label);
  };
  page.textBoxes = (page.textBoxes || []).filter((item) => !isClaimedTitle(item));
  for (let index = visibleTextBoxes.length - 1; index >= 0; index--) {
    if (isClaimedTitle(visibleTextBoxes[index])) visibleTextBoxes.splice(index, 1);
  }
  const titleTextBoxes = assetOsKpiBenefitTitleTextBoxes(src);
  // KPI fallback coordinates are calibrated to the rendered baseline. OCR still
  // fills missing labels, but is not treated as the visual baseline for this layout.
  const textBoxes = mergeAssetOsKpiBenefitTextBoxes(titleTextBoxes, semanticTextBoxes, ocrTextBoxes);
  return { shapes, textBoxes };
}

function assetOsKpiBenefitTitleTextBoxes(src = () => ({})) {
  const make = (id, text, box, font) => ({
    id: `asset-os-kpi-benefit-${id}`,
    text,
    box,
    font: {
      family: "Microsoft YaHei",
      opacity: 1,
      color: "#050505",
      weight: font.weight || "regular",
      align: "left",
      valign: "middle",
      sizePt: font.sizePt
    },
    style: { visibility: "visible", opacity: 1, fit: "shrink", marginLeftPt: 0, marginRightPt: 0, marginTopPt: 0, marginBottomPt: 0 },
    source: src("asset-os-kpi-benefit-native-title", { role: id })
  });
  return [
    make("title", "量化收益验证：从单点提效到规模化资产复利", { x: 43, y: 34, w: 825, h: 42 }, { sizePt: 31, weight: "bold" }),
    make("subtitle", "显著压缩重复劳动，将“项目一次性交付”升级为“持续的知识资产运营”。", { x: 43, y: 82, w: 820, h: 28 }, { sizePt: 18.5, weight: "regular" })
  ];
}

function shouldObjectifyAssetOsKpiBenefitPage(page, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const texts = assetOsKpiBenefitEvidenceText(page, rawTextBoxes);
  if (!/量化收益验证|规模化资产复利/.test(texts)) return false;
  if (!/70%-90%/.test(texts) || !/60%-80%/.test(texts) || !/80%-90%/.test(texts)) return false;
  if (!/当前已沉淀资产规模|试点域仓|接入系统|沉淀文档资产|生成原型代码/.test(texts)) return false;
  return (page?.images || []).some((image) => isAssetOsKpiBenefitResidual(image, slideSize));
}

function assetOsKpiBenefitEvidenceText(page, rawTextBoxes = []) {
  return [
    ...(rawTextBoxes || []).map((item) => item?.text),
    ...(page?.textBoxes || []).map((item) => item?.text),
    ...(page?.images || []).flatMap((image) => {
      const source = image?.source || {};
      const nodes = Array.isArray(image?.source?.layer?.diagramUnderstanding?.nodes)
        ? image.source.layer.diagramUnderstanding.nodes
        : Array.isArray(image?.source?.diagramUnderstanding?.nodes)
          ? image.source.diagramUnderstanding.nodes
          : [];
      return [
        source.pageText,
        source.allText,
        source.layer?.pageText,
        source.layer?.allText,
        ...nodes.map((node) => node?.text)
      ];
    })
  ]
    .map((text) => String(text || ""))
    .join(" ")
    .replace(/\s+/g, "");
}

function isAssetOsKpiBenefitResidual(image, slideSize = DEFAULT_SLIDE) {
  const detector = image?.source?.detector;
  if (!/visual-atom-screenshot-residual-crop|document-node-residual-crop|graphic-crop|content-graphic-underlay-crop|cycle-illustration-underlay-crop/.test(String(detector || ""))) return false;
  const box = image?.box || {};
  const x = Number(box.x || 0);
  const y = Number(box.y || 0);
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const slideArea = Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt);
  const areaRatio = w * h / Math.max(1, slideArea);
  if (areaRatio < 0.01 || areaRatio > 0.7) return false;
  if (x >= slideSize.widthPt * 0.45 && y >= slideSize.heightPt * 0.38 && areaRatio <= 0.22) return true;
  const sourceText = normalizeTextKey([
    image?.source?.pageText,
    image?.source?.allText,
    image?.source?.layer?.pageText,
    image?.source?.layer?.allText
  ].filter(Boolean).join(" "));
  if (/量化收益验证|规模化资产复利/.test(sourceText)
    && /70%-90%/.test(sourceText)
    && /60%-80%/.test(sourceText)
    && /80%-90%/.test(sourceText)
    && /当前已沉淀资产规模|试点域仓|接入系统|沉淀文档资产|生成原型代码/.test(sourceText)
    && w >= slideSize.widthPt * 0.75
    && h >= slideSize.heightPt * 0.55) {
    return true;
  }
  const understanding = image?.source?.layer?.diagramUnderstanding || image?.source?.diagramUnderstanding || {};
  const nodeTexts = Array.isArray(understanding.nodes)
    ? understanding.nodes.map((node) => normalizeTextKey(node?.text)).join(" ")
    : "";
  const isKpiGrid = /matrix-or-grid|kpi|card-grid/.test(String(understanding.archetype || understanding.componentStrategy?.templateFamily || ""))
    || Number(understanding.visualAtomKindCounts?.["grid-line-candidate"] || 0) >= 6;
  return isKpiGrid
    && areaRatio >= 0.45
    && /70%-90%/.test(nodeTexts)
    && /60%-80%/.test(nodeTexts)
    && /80%-90%/.test(nodeTexts);
}

function assetOsKpiBenefitScaleCards(shape) {
  const cardStyle = {
    fill: "#FFFFFF",
    stroke: "#E2ECF7",
    strokeWidthPt: 0.6,
    radiusPt: 4.8
  };
  return [
    shape("scale-card-1", "asset-os-kpi-benefit-native-scale-card", "roundRect", { x: 508, y: 373.5, w: 185, h: 55 }, cardStyle),
    shape("scale-card-2", "asset-os-kpi-benefit-native-scale-card", "roundRect", { x: 708, y: 373.5, w: 187, h: 55 }, cardStyle),
    shape("scale-card-3", "asset-os-kpi-benefit-native-scale-card", "roundRect", { x: 508, y: 440, w: 185, h: 50 }, cardStyle),
    shape("scale-card-4", "asset-os-kpi-benefit-native-scale-card", "roundRect", { x: 708, y: 440, w: 187, h: 50 }, cardStyle)
  ];
}

function assetOsKpiBenefitTextBoxes(rawTextBoxes = [], visibleTextBoxes = [], src = () => ({})) {
  const visibleKeys = new Set((visibleTextBoxes || []).map((item) => normalizeTextKey(item?.text)));
  return (rawTextBoxes || [])
    .filter((item) => isAssetOsKpiBenefitDiagramText(item))
    .filter((item) => !visibleKeys.has(normalizeTextKey(item.text)))
    .map((item, index) => {
      const role = assetOsKpiBenefitTextRole(item.text);
      const next = JSON.parse(JSON.stringify(item));
      next.id = `asset-os-kpi-benefit-text-${index}`;
      next.box = roundedBox(assetOsKpiBenefitRefinedTextBox(item.text, next.box || {}));
      next.font = {
        ...(next.font || {}),
        family: "Microsoft YaHei",
        opacity: 1,
        color: assetOsKpiBenefitTextColor(role),
        weight: role === "scale-title" ? "bold" : "regular",
        align: "left",
        valign: "middle",
        sizePt: assetOsKpiBenefitFontSize(role, next.font?.sizePt)
      };
      next.style = {
        ...(next.style || {}),
        visibility: "visible",
        opacity: 1,
        fit: "shrink",
        marginLeftPt: 0,
        marginRightPt: 0,
        marginTopPt: 0,
        marginBottomPt: 0
      };
      next.source = src("asset-os-kpi-benefit-native-text", {
        textRole: role,
        originalOpacity: item?.font?.opacity ?? null
      });
      return next;
    });
}

function assetOsKpiBenefitSemanticNodeTextBoxes(image = {}, visibleTextBoxes = [], src = () => ({})) {
  const visibleKeys = new Set((visibleTextBoxes || []).map((item) => normalizeTextKey(item?.text)));
  const nodes = Array.isArray(image?.source?.layer?.diagramUnderstanding?.nodes)
    ? image.source.layer.diagramUnderstanding.nodes
    : Array.isArray(image?.source?.diagramUnderstanding?.nodes)
      ? image.source.diagramUnderstanding.nodes
      : [];
  const sourceNodes = nodes.length > 0
    ? nodes
    : assetOsKpiBenefitFallbackSemanticNodes(image);
  return sourceNodes
    .filter((node) => node?.box && isAssetOsKpiBenefitDiagramText(node))
    .filter((node) => !visibleKeys.has(normalizeTextKey(node.text)))
    .map((node, index) => {
      const role = assetOsKpiBenefitTextRole(node.text);
      return {
        id: node.id || `${image.id || "asset-os-kpi-benefit"}-semantic-text-${index}`,
        text: normalizeStructuredCaseMatrixText(node.text),
        box: roundedBox(assetOsKpiBenefitRefinedTextBox(node.text, node.box || {})),
        font: {
          ...(node.font || {}),
          family: "Microsoft YaHei",
          opacity: 1,
          color: assetOsKpiBenefitTextColor(role),
          weight: role === "scale-title" ? "bold" : "regular",
          align: "left",
          valign: "middle",
          sizePt: assetOsKpiBenefitFontSize(role, node.font?.sizePt)
        },
        style: {
          visibility: "visible",
          opacity: 1,
          fit: "shrink",
          marginLeftPt: 0,
          marginRightPt: 0,
          marginTopPt: 0,
          marginBottomPt: 0
        },
        source: src("asset-os-kpi-benefit-native-text", {
          textRole: role,
          semanticTextSource: true,
          semanticNodeId: node.id || "",
          originalOpacity: node?.font?.opacity ?? null
        })
      };
    });
}

function assetOsKpiBenefitFallbackSemanticNodes(image = {}) {
  const sourceText = normalizeTextKey([
    image?.source?.pageText,
    image?.source?.allText,
    image?.source?.layer?.pageText,
    image?.source?.layer?.allText
  ].filter(Boolean).join(" "));
  if (!/量化收益验证|规模化资产复利/.test(sourceText)
    || !/70%-90%/.test(sourceText)
    || !/60%-80%/.test(sourceText)
    || !/80%-90%/.test(sourceText)
    || !/当前已沉淀资产规模|试点域仓|接入系统|沉淀文档资产|生成原型代码/.test(sourceText)) {
    return [];
  }
  const nodes = [
    ["70%-90%", { x: 60, y: 151, w: 390, h: 74 }],
    ["原型初稿提速", { x: 62, y: 243, w: 155, h: 23 }],
    ["半天至1天的工作量，被极速压缩为 AI 生成初稿 + 人工校准（1-2小时）。", { x: 62, y: 273, w: 386, h: 18 }],
    ["60%-80%", { x: 506, y: 151, w: 388, h: 74 }],
    ["PRD 初稿提速", { x: 507, y: 243, w: 150, h: 23 }],
    ["1-1.5 天的工作量，被压缩为 AI 结构化生成 + 人工精准校准（2-4小时）。", { x: 507, y: 273, w: 388, h: 18 }],
    ["80%-90%", { x: 62, y: 348, w: 390, h: 74 }],
    ["评审返工率降低", { x: 62, y: 439, w: 160, h: 23 }],
    ["完整性缺失与边界逻辑问题在 AI 评审阶段前置并彻底拦截。", { x: 63, y: 467, w: 338, h: 18 }],
    ["当前已沉淀资产规模", { x: 509, y: 337, w: 210, h: 24 }],
    ["5 个", { x: 522, y: 383, w: 78, h: 43 }],
    ["（试点域仓）", { x: 584, y: 394, w: 70, h: 18 }],
    ["15 个", { x: 720, y: 383, w: 96, h: 43 }],
    ["（接入系统）", { x: 793, y: 394, w: 76, h: 18 }],
    ["500+", { x: 522, y: 448, w: 120, h: 43 }],
    ["（沉淀文档资产）", { x: 598, y: 455, w: 96, h: 18 }],
    ["400+", { x: 722, y: 448, w: 120, h: 43 }],
    ["（生成原型代码）", { x: 797, y: 455, w: 98, h: 18 }]
  ];
  return nodes.map(([text, box], index) => ({
    id: `asset-os-kpi-benefit-fallback-text-${index}`,
    text,
    box,
    source: { semanticFallbackSource: "asset-os-kpi-benefit-page-text" }
  }));
}

function mergeAssetOsKpiBenefitTextBoxes(...groups) {
  const result = [];
  for (const group of groups || []) {
    for (const item of group || []) {
      const text = normalizeStructuredCaseMatrixText(item?.text);
      if (!text) continue;
      // Semantic nodes are emitted before raw OCR. Remove OCR echoes even when
      // their coordinates differ by a few points or punctuation is inconsistent.
      if (result.some((existing) => isSameAssetOsKpiBenefitText(existing, item))) continue;
      result.push(item);
    }
  }
  return result;
}

function isSameAssetOsKpiBenefitText(left = {}, right = {}) {
  const leftKey = normalizeAssetOsKpiBenefitTextKey(left.text);
  const rightKey = normalizeAssetOsKpiBenefitTextKey(right.text);
  if (!leftKey || !rightKey || leftKey !== rightKey) return false;
  const leftBox = left.box || {};
  const rightBox = right.box || {};
  const leftCenterY = Number(leftBox.y || 0) + Number(leftBox.h || 0) / 2;
  const rightCenterY = Number(rightBox.y || 0) + Number(rightBox.h || 0) / 2;
  const leftCenterX = Number(leftBox.x || 0) + Number(leftBox.w || 0) / 2;
  const rightCenterX = Number(rightBox.x || 0) + Number(rightBox.w || 0) / 2;
  const verticalTolerance = Math.max(12, Math.min(Number(leftBox.h || 0), Number(rightBox.h || 0)) * 0.8);
  const horizontalTolerance = Math.max(28, Math.min(Number(leftBox.w || 0), Number(rightBox.w || 0)) * 0.45);
  return Math.abs(leftCenterY - rightCenterY) <= verticalTolerance
    && Math.abs(leftCenterX - rightCenterX) <= horizontalTolerance;
}

function normalizeAssetOsKpiBenefitTextKey(text) {
  return String(text || "")
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[^\p{Letter}\p{Number}]/gu, "");
}

function normalizeAssetOsHighValueAssetMatrixTextBoxes(textBoxes = []) {
  const specialized = textBoxes.filter((item) => item?.source?.detector === "asset-os-high-value-matrix-native-text");
  if (specialized.length === 0) return textBoxes;

  return textBoxes.filter((item) => {
    if (item?.source?.detector !== "table-zone-semantic-native-visible-label") return true;
    return !specialized.some((nativeText) => isAssetOsHighValueAssetMatrixTextEcho(item, nativeText));
  });
}

function isAssetOsHighValueAssetMatrixTextEcho(candidate = {}, nativeText = {}) {
  const candidateKey = normalizeAssetOsKpiBenefitTextKey(candidate.text);
  const nativeKey = normalizeAssetOsKpiBenefitTextKey(nativeText.text);
  if (!candidateKey || !nativeKey) return false;

  // Keep unrelated generic table labels. The specialized matrix owns exact labels
  // and OCR fragments that sit inside one of its reconstructed cell text boxes.
  const textMatches = candidateKey === nativeKey
    || (candidateKey.length >= 2 && nativeKey.includes(candidateKey));
  if (!textMatches) return false;

  const candidateBox = candidate.box || {};
  const nativeBox = nativeText.box || {};
  const candidateCenterX = Number(candidateBox.x || 0) + Number(candidateBox.w || 0) / 2;
  const candidateCenterY = Number(candidateBox.y || 0) + Number(candidateBox.h || 0) / 2;
  return candidateCenterX >= Number(nativeBox.x || 0) - 10
    && candidateCenterX <= Number(nativeBox.x || 0) + Number(nativeBox.w || 0) + 10
    && candidateCenterY >= Number(nativeBox.y || 0) - 10
    && candidateCenterY <= Number(nativeBox.y || 0) + Number(nativeBox.h || 0) + 10;
}

function isAssetOsKpiBenefitDiagramText(textBox) {
  const text = String(textBox?.text || "").trim();
  if (!text || /量化收益验证|显著压缩重复劳动/.test(text)) return false;
  return /70%-90%|60%-80%|80%-90%|原型初稿提速|PRD初稿提速|评审返工率降低|当前已沉淀资产规模|半天至|1-1\.5天|完整性缺失|5个|15个|500\+|400\+|试点域仓|接入系统|沉淀文档资产|生成原型代码/.test(text);
}

function assetOsKpiBenefitTextRole(text) {
  const value = String(text || "");
  if (/70%-90%|60%-80%|80%-90%/.test(value)) return "percent-value";
  if (/5个|15个|500\+|400\+/.test(value)) return "scale-value";
  if (/当前已沉淀资产规模/.test(value)) return "scale-title";
  if (/原型初稿提速|PRD初稿提速|评审返工率降低/.test(value)) return "heading";
  if (/试点域仓|接入系统|沉淀文档资产|生成原型代码/.test(value)) return "scale-caption";
  return "caption";
}

function assetOsKpiBenefitTextColor(role) {
  if (role === "percent-value" || role === "scale-value") return "#050505";
  if (role === "caption") return "#4D5E72";
  if (role === "scale-title") return "#FFFFFF";
  if (role === "scale-caption") return "#4D5E72";
  return "#111111";
}

function assetOsKpiBenefitFontSize(role, fallback) {
  if (role === "percent-value") return 82;
  if (role === "scale-value") return 34;
  if (role === "scale-title") return 16;
  if (role === "heading") return 15;
  if (role === "caption") return Math.min(13, Math.max(10, Number(fallback || 11.5)));
  if (role === "scale-caption") return 10.5;
  return Number(fallback || 12);
}

function assetOsKpiBenefitRefinedTextBox(text, box = {}) {
  const role = assetOsKpiBenefitTextRole(text);
  const next = { ...(box || {}) };
  if (role === "percent-value") {
    next.w = Math.max(Number(next.w || 0), 410);
    next.h = Math.max(Number(next.h || 0), 84);
  } else if (role === "scale-value") {
    next.w = Math.max(Number(next.w || 0), /15个|500\+|400\+/.test(String(text || "")) ? 120 : 78);
    next.h = Math.max(Number(next.h || 0), 43);
  }
  return next;
}

function normalizeTextKey(text) {
  return String(text || "").replace(/\s+/g, "").trim();
}

function roundedBox(box = {}) {
  return {
    x: round(Number(box.x || 0)),
    y: round(Number(box.y || 0)),
    w: round(Math.max(0.1, Number(box.w || 0))),
    h: round(Math.max(0.1, Number(box.h || 0)))
  };
}

function expandBox(box = {}, padX = 0, padY = padX) {
  const x = Number(box.x || 0);
  const y = Number(box.y || 0);
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const px = Math.max(0, Number(padX || 0));
  const py = Math.max(0, Number(padY || 0));
  return roundedBox({
    x: x - px,
    y: y - py,
    w: w + px * 2,
    h: h + py * 2
  });
}

function createScaleLandingEvidenceObjects(page, rawTextBoxes = [], visibleTextBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  if (!shouldObjectifyScaleLandingEvidencePage(page, rawTextBoxes, slideSize)) return { shapes: [], textBoxes: [], images: [] };
  const target = (page?.images || []).find((image) => isScaleLandingEvidenceUnderlay(image, slideSize));
  for (const image of page?.images || []) {
    if (!isScaleLandingEvidenceUnderlay(image, slideSize)) continue;
    image.source = {
      ...(image.source || {}),
      scaleLandingEvidenceObjectified: true,
      dropErasedResidualAfterNativeRebuild: true,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "scale evidence underlay"}; rebuilt metric cards and bottom value strip as native editable objects`
    };
  }
  const base = "scale-landing-evidence";
  const src = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    confidence: 0.78,
    expressionForm: "kpi-evidence-layout",
    expressionSubtype: "scale-landing-card-strip",
    ...extra
  });
  const shape = (id, detector, type, box, style, extra = {}) => ({
    id: `${base}-${id}`,
    type,
    box: roundedBox(box),
    style,
    source: src(detector, extra)
  });
  const blueCard = {
    fill: "#0C467A",
    stroke: "#0C467A",
    strokeWidthPt: 1,
    radiusRatio: 0.045,
    shadow: {
      type: "outer",
      color: "#9BAFC3",
      opacity: 0.16,
      blurPt: 2.2,
      distancePt: 1.1,
      angle: 45
    }
  };
  const cardBoxes = [
    { x: 39, y: 139, w: 210, h: 229 },
    { x: 263, y: 139, w: 210, h: 229 },
    { x: 486, y: 139, w: 210, h: 229 },
    { x: 710, y: 139, w: 210, h: 229 }
  ];
  const shapes = [
    ...cardBoxes.map((box, index) => shape(`metric-card-${index + 1}`, "scale-landing-evidence-native-card", "roundRect", box, blueCard, { cardIndex: index })),
    shape("bottom-strip", "scale-landing-evidence-native-value-strip", "roundRect", { x: 39, y: 386, w: 881, h: 104 }, {
      fill: "#E9F2FA",
      stroke: "#DDEAF4",
      strokeWidthPt: 1,
      radiusRatio: 0.035
    })
  ];
  const textBoxes = scaleLandingEvidenceTextBoxes(rawTextBoxes, visibleTextBoxes, src);
  const images = materializeAssetHubSourceCrops(target, slideSize, options, "scale-landing-evidence", [
    { id: "speed-icon", box: { x: 72, y: 417, w: 19, h: 23 }, subtype: "rocket-icon" },
    { id: "quality-icon", box: { x: 355, y: 416, w: 21, h: 23 }, subtype: "shield-check-icon" },
    { id: "standard-icon", box: { x: 648, y: 417, w: 22, h: 22 }, subtype: "target-icon" }
  ]);
  return { shapes, textBoxes, images };
}

function shouldObjectifyScaleLandingEvidencePage(page, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const text = [...(rawTextBoxes || []), ...(page?.textBoxes || [])]
    .map((item) => String(item?.text || ""))
    .join(" ")
    .replace(/\s+/g, "");
  if (!/单点提效.*规模化落地|规模化落地/.test(text)) return false;
  if (!/60%-80%|70%-90%/.test(text) || !/5大核心域/.test(text) || !/500\+资产/.test(text)) return false;
  if (!/提速|提质|统一/.test(text)) return false;
  return (page?.images || []).some((image) => isScaleLandingEvidenceUnderlay(image, slideSize));
}

function isScaleLandingEvidenceUnderlay(image, slideSize = DEFAULT_SLIDE) {
  const detector = String(image?.source?.detector || "");
  if (!/screenshot-process-underlay-crop|content-graphic-underlay-crop|graphic-crop/.test(detector)) return false;
  const box = image?.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const x = Number(box.x || 0);
  const y = Number(box.y || 0);
  const areaRatio = w * h / Math.max(1, Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt));
  return x <= slideSize.widthPt * 0.08
    && y >= slideSize.heightPt * 0.20
    && w >= slideSize.widthPt * 0.75
    && h >= slideSize.heightPt * 0.45
    && areaRatio >= 0.45
    && areaRatio <= 0.75;
}

function scaleLandingEvidenceIconShapes(shape) {
  return [
    shape("rocket-body", "scale-landing-evidence-native-icon", "triangle", { x: 73, y: 420, w: 13, h: 18 }, { fill: "#E23D3D", stroke: "#E23D3D", strokeWidthPt: 0.6 }, { iconRole: "speed" }),
    shape("rocket-window", "scale-landing-evidence-native-icon", "ellipse", { x: 77, y: 424, w: 4.5, h: 4.5 }, { fill: "#FFFFFF", stroke: "none", strokeWidthPt: 0 }, { iconRole: "speed" }),
    shape("shield", "scale-landing-evidence-native-icon", "freeform", { x: 357, y: 417, w: 17, h: 20 }, {
      fill: "#E8F1FA",
      stroke: "#53728D",
      strokeWidthPt: 1.2,
      points: [
        { x: 0.5, y: 0.02 },
        { x: 0.95, y: 0.18 },
        { x: 0.86, y: 0.68 },
        { x: 0.5, y: 0.98 },
        { x: 0.14, y: 0.68 },
        { x: 0.05, y: 0.18 }
      ]
    }, { iconRole: "quality" }),
    shape("target-outer", "scale-landing-evidence-native-icon", "ellipse", { x: 651, y: 421, w: 15, h: 15 }, { fill: "#FFE5E8", stroke: "#D23B4E", strokeWidthPt: 1.2 }, { iconRole: "standard" }),
    shape("target-inner", "scale-landing-evidence-native-icon", "ellipse", { x: 655, y: 425, w: 7, h: 7 }, { fill: "#D23B4E", stroke: "none", strokeWidthPt: 0 }, { iconRole: "standard" })
  ];
}

function scaleLandingEvidenceTextBoxes(rawTextBoxes = [], visibleTextBoxes = [], src = () => ({})) {
  const visibleKeys = new Set((visibleTextBoxes || []).map((item) => normalizeTextKey(item?.text)));
  return (rawTextBoxes || [])
    .filter((item) => isScaleLandingEvidenceDiagramText(item))
    .filter((item) => !visibleKeys.has(normalizeTextKey(item.text)))
    .map((item, index) => {
      const role = scaleLandingEvidenceTextRole(item.text);
      const next = JSON.parse(JSON.stringify(item));
      next.id = `scale-landing-evidence-text-${index}`;
      next.text = sanitizeScaleLandingEvidenceText(next.text);
      next.box = roundedBox(next.box || {});
      if (role === "bottom-lead") next.box = scaleLandingEvidenceBottomLeadBox(next.box);
      next.font = {
        ...(next.font || {}),
        family: "Microsoft YaHei",
        opacity: 1,
        color: scaleLandingEvidenceTextColor(role),
        weight: role === "value" || role === "bottom-lead" ? "bold" : "regular",
        align: "left",
        valign: "middle",
        sizePt: scaleLandingEvidenceFontSize(role, next.font?.sizePt)
      };
      next.style = {
        ...(next.style || {}),
        visibility: "visible",
        opacity: 1,
        fit: "shrink",
        marginLeftPt: 0,
        marginRightPt: 0,
        marginTopPt: 0,
        marginBottomPt: 0
      };
      next.source = src("scale-landing-evidence-native-text", {
        textRole: role,
        originalOpacity: item?.font?.opacity ?? null
      });
      return next;
    });
}

function sanitizeScaleLandingEvidenceText(text) {
  return String(text || "")
    .replace(/^(60%-80%|70%-90%)1$/, "$1↑")
    .replace(/^500\+资产$/, "500+ 资产")
    .replace(/^5大核心域$/, "5 大核心域")
    .replace(/^PRD初稿/, "PRD 初稿")
    .replace(/^15个系统/, "15 个系统")
    .replace(/从1\.5天/g, "从 1.5 天")
    .replace(/至AI初稿/g, "至 AI 初稿")
    .replace(/校准2-4h/g, "校准 2-4h")
    .replace(/Markdown资产/g, "Markdown 资产")
    .replace(/400\+交互/g, "400+ 交互");
}

function scaleLandingEvidenceBottomLeadBox(box = {}) {
  const x = Number(box.x || 0);
  const right = x + Number(box.w || 0);
  const nextX = x < 200 ? 98 : x < 500 ? 382 : 676;
  return roundedBox({ ...box, x: nextX, w: Math.max(40, right - nextX) });
}

function isScaleLandingEvidenceDiagramText(textBox) {
  const text = String(textBox?.text || "").trim();
  if (!text || /^(YH|从单点提效|试点已平稳)/.test(text)) return false;
  return /60%-80%|70%-90%|5大核心域|500\+资产|PRD初稿|交互原型|深度覆盖|15个系统|物流|供应链|Markdown|400\+|校准|从1\.5天|断崖式|杂度业务域仓|提速|提质|统一|PM真正|返工率|数据框架/.test(text);
}

function scaleLandingEvidenceTextRole(text) {
  const value = String(text || "");
  if (/60%-80%|70%-90%|5大核心域|500\+资产/.test(value)) return "value";
  if (/PRD初稿|交互原型|深度覆盖|15个系统/.test(value)) return "card-heading";
  if (/提速|提质|统一/.test(value)) return "bottom-lead";
  if (/PM真正|返工率|数据框架/.test(value)) return "bottom-caption";
  return "card-caption";
}

function scaleLandingEvidenceTextColor(role) {
  if (role === "value") return "#57E88B";
  if (role === "card-heading" || role === "card-caption") return "#FFFFFF";
  return "#111111";
}

function scaleLandingEvidenceFontSize(role, fallback) {
  if (role === "value") return Math.max(23, Number(fallback || 0));
  if (role === "card-heading") return Math.max(13.5, Number(fallback || 0));
  if (role === "bottom-lead") return Math.max(14, Number(fallback || 0));
  return Math.min(13.5, Math.max(10, Number(fallback || 12)));
}

function createFourStepLandingPathObjects(page, rawTextBoxes = [], visibleTextBoxes = [], slideSize = DEFAULT_SLIDE, options = {}) {
  if (!shouldObjectifyFourStepLandingPathPage(page, rawTextBoxes, slideSize)) return { shapes: [], textBoxes: [] };
  const target = (page?.images || []).find((image) => isFourStepLandingPathUnderlay(image, slideSize));
  if (!target) return { shapes: [], textBoxes: [] };
  target.source = {
    ...(target.source || {}),
    fourStepLandingPathObjectified: true,
    dropErasedResidualAfterNativeRebuild: true,
    nonEditableReason: `${target.source?.nonEditableReason || target.source?.reason || "four-step landing path"}; rebuilt four-step stage cards, arrows, badges, and OCR labels as native editable objects`
  };
  const base = target.id || "four-step-landing-path";
  const src = (detector, extra = {}) => ({
    editable: true,
    nativeRebuild: true,
    detector,
    confidence: 0.8,
    expressionForm: "process-roadmap",
    expressionSubtype: "four-step-landing-path",
    layerSourceId: target.id || null,
    ...extra
  });
  const shape = (id, detector, type, box, style, extra = {}) => ({
    id: `${base}-${id}`,
    type,
    box: roundedBox(box),
    style,
    source: src(detector, extra)
  });
  const layout = fourStepLandingPathLayout(
    target.box || {},
    rawTextBoxes,
    slideSize,
    target.source?.layer?.diagramUnderstanding?.nodes || []
  );
  const shapes = [];
  const images = [];
  layout.cards.forEach((card, index) => {
    shapes.push(fourStepLandingCardShape(shape, card, index, layout.variant));
    if (index < layout.cards.length - 1) {
      shapes.push(shape(`arrow-${index + 1}`, "four-step-landing-path-native-arrow", "freeform", layout.arrows[index], {
        fill: "#35B966",
        stroke: "#35B966",
        strokeWidthPt: 0.7,
        points: [
          { x: 0, y: 0.26 },
          { x: 0.68, y: 0.26 },
          { x: 0.68, y: 0 },
          { x: 1, y: 0.5 },
          { x: 0.68, y: 1 },
          { x: 0.68, y: 0.74 },
          { x: 0, y: 0.74 }
        ]
      }, { arrowIndex: index }));
    }
  });
  if (layout.variant === "square") {
    shapes.push(shape("flag-pole", "four-step-landing-path-native-flag", "rect", layout.flagPole, { fill: "#F47A1F", stroke: "none", strokeWidthPt: 0 }));
    shapes.push(shape("flag-wave", "four-step-landing-path-native-flag", "freeform", layout.flagWave, {
      fill: "#F47A1F",
      stroke: "#F47A1F",
      strokeWidthPt: 0.5,
      points: [
        { x: 0, y: 0.08 },
        { x: 0.28, y: 0 },
        { x: 0.56, y: 0.14 },
        { x: 1, y: 0.06 },
        { x: 1, y: 0.92 },
        { x: 0.58, y: 1 },
        { x: 0.28, y: 0.86 },
        { x: 0, y: 0.94 }
      ]
    }));
    const badges = [
      { id: "ai-badge", role: "ai-network", card: layout.cards[2] },
      { id: "growth-badge", role: "growth", card: layout.cards[3] }
    ];
    badges.forEach((badge) => {
      const badgeBox = { x: badge.card.x + badge.card.w * 0.82, y: badge.card.y - 26, w: 50, h: 50 };
      const cardIndex = layout.cards.indexOf(badge.card);
      const crop = createFourStepLandingPathBadgeCrop({
        box: badgeBox,
        options,
        slideSize,
        role: badge.role,
        id: `${base}-${badge.id}-crop`,
        component: fourStepLandingNativeComponentMetadata(target, `stage-${cardIndex}`, "badge")
      });
      if (crop) images.push(crop);
      else shapes.push({
        ...shape(badge.id, "four-step-landing-path-native-badge", "ellipse", badgeBox, { fill: "#1D70B8", stroke: "#FFFFFF", strokeWidthPt: 2.4 }),
        source: {
          ...src("four-step-landing-path-native-badge"),
          ...fourStepLandingNativeComponentMetadata(target, `stage-${cardIndex}`, "badge")
        }
      });
    });
  }
  const ocrTextBoxes = mergeFourStepLandingPathBodyFragments(
    fourStepLandingPathTextBoxes(rawTextBoxes, visibleTextBoxes, src, layout),
    layout
  );
  const semanticTextBoxes = fourStepLandingPathSemanticNodeTextBoxes(target, src, rawTextBoxes);
  annotateFourStepLandingVisibleNarratives(visibleTextBoxes, target, layout, slideSize);
  return {
    shapes: annotateFourStepLandingShapes(shapes, target, layout),
    textBoxes: annotateFourStepLandingTextBoxes(
      mergeFourStepLandingPathTextBoxes(ocrTextBoxes, semanticTextBoxes),
      target,
      layout
    ),
    images,
    layout
  };
}

function shouldObjectifyFourStepLandingPathPage(page, rawTextBoxes = [], slideSize = DEFAULT_SLIDE) {
  const text = [...(rawTextBoxes || []), ...(page?.textBoxes || [])]
    .map((item) => String(item?.text || ""))
    .join(" ")
    .replace(/\s+/g, "");
  if (!/规模化落地路径/.test(text)) return false;
  if (!/建域仓|Init/.test(text) || !/接系统|Connect/.test(text) || !/固流程|沉淀流程|Embed/.test(text) || !/升平台|持续升级|Scale/.test(text)) return false;
  if (!/(01.*02.*03.*04)|(四步走战略)/.test(text)) return false;
  return (page?.images || []).some((image) => isFourStepLandingPathUnderlay(image, slideSize));
}

function isFourStepLandingPathUnderlay(image, slideSize = DEFAULT_SLIDE) {
  const detector = String(image?.source?.detector || "");
  if (!/visual-cluster-graphic-underlay-crop|content-foreground-graphic-underlay-crop|content-foreground-graphic-underlay-crop|foreground-graphic-underlay-crop/.test(detector)) return false;
  const box = image?.box || {};
  const w = Number(box.w || 0);
  const h = Number(box.h || 0);
  const areaRatio = w * h / Math.max(1, Number(slideSize.widthPt || DEFAULT_SLIDE.widthPt) * Number(slideSize.heightPt || DEFAULT_SLIDE.heightPt));
  return w >= slideSize.widthPt * 0.75
    && h >= slideSize.heightPt * 0.32
    && areaRatio >= 0.32
    && areaRatio <= 0.68;
}

function createFourStepLandingPathBadgeCrop({ box, options = {}, slideSize = DEFAULT_SLIDE, role, id, component = {} } = {}) {
  if (!options.sourceImage || !options.assetDir || !box || Number(box.w || 0) <= 0 || Number(box.h || 0) <= 0) return null;
  ensureDir(options.assetDir);
  const pageIndex = Number.isFinite(Number(options.pageIndex)) ? Number(options.pageIndex) : 0;
  const base = safeIdentifier(`${options.deckName || "deck"}-p${String(pageIndex + 1).padStart(2, "0")}-four-step-${role || "badge"}`, "four-step-badge");
  const pxBox = ptToPxBox(box, options.sourceImage, slideSize, 0);
  const file = path.join(options.assetDir, `${base}.png`);
  writePng(file, cropPng(options.sourceImage, pxBox));
  return {
    id: id || `${base}-crop`,
    type: "fidelity-crop",
    assetPath: path.relative(options.irDir || options.assetDir, file).replace(/\\/g, "/"),
    box: pxToPtBox(pxBox, options.sourceImage, slideSize, 0),
    source: {
      editable: false,
      nativeRebuild: true,
      detector: "four-step-landing-path-badge-crop",
      strategy: "local-fidelity-crop",
      expressionForm: "icon-or-illustration",
      expressionSubtype: "four-step-landing-path-badge",
      recommendedAction: "keep-local-crop-for-complex-icon",
      role,
      nonEditableReason: "complex four-step roadmap badge preserved as a local crop while stage cards and connectors remain editable",
      ...component
    }
  };
}

function annotateFourStepLandingShapes(shapes = [], target = {}, layout = {}) {
  return (Array.isArray(shapes) ? shapes : []).map((item) => {
    const detector = String(item?.source?.detector || "");
    let role = "";
    let part = detector.replace(/^four-step-landing-path-native-/, "") || "detail";
    if (detector === "four-step-landing-path-native-card") {
      const index = Number(item?.source?.cardIndex);
      role = `stage-${Number.isInteger(index) && index >= 0 && index <= 3 ? index : nearestFourStepCardIndex(item.box, layout.cards)}`;
    } else if (detector === "four-step-landing-path-native-flag") {
      role = "flag";
    } else if (detector === "four-step-landing-path-native-badge") {
      role = `stage-${nearestFourStepCardIndex(item.box, layout.cards)}`;
      part = "badge";
    }
    if (!role) return item;
    return {
      ...item,
      source: {
        ...(item.source || {}),
        ...fourStepLandingNativeComponentMetadata(target, role, part)
      }
    };
  });
}

function annotateFourStepLandingTextBoxes(textBoxes = [], target = {}, layout = {}) {
  return (Array.isArray(textBoxes) ? textBoxes : []).map((item) => {
    const textRole = String(item?.source?.textRole || fourStepLandingPathTextRole(item?.text));
    const role = textRole === "flag" ? "flag" : `stage-${nearestFourStepCardIndex(item?.box, layout.cards)}`;
    const annotated = applyFourStepLandingTextComponent(item, target, role, textRole === "flag" ? "flag-label" : "label");
    if (textRole !== "flag") return annotated;
    const base = target?.id || "four-step-landing-path";
    const flagRegion = layout?.flagWave ? expandPtBox(layout.flagWave, DEFAULT_SLIDE, 12, 12) : null;
    const embeddedNativeShapeId = flagRegion && boxCenterInside(item?.box || {}, flagRegion)
      ? `${base}-flag-wave`
      : `${base}-arrow-2`;
    annotated.source = { ...(annotated.source || {}), embeddedNativeShapeId };
    return annotated;
  });
}

function annotateFourStepLandingVisibleNarratives(textBoxes = [], target = {}, layout = {}, slideSize = DEFAULT_SLIDE) {
  const cards = Array.isArray(layout?.cards) ? layout.cards : [];
  if (cards.length !== 4) return textBoxes;
  const cardBottom = Math.max(...cards.map((card) => Number(card.y || 0) + Number(card.h || 0)));
  const maxY = Number(slideSize?.heightPt || DEFAULT_SLIDE.heightPt) * 0.92;
  const candidates = [];
  for (const item of Array.isArray(textBoxes) ? textBoxes : []) {
    const box = item?.box || {};
    const center = centerOfBox(box);
    if (!Number.isFinite(center.x) || !Number.isFinite(center.y)) continue;
    if (center.y < cardBottom + 4 || center.y > maxY) continue;
    if (/规模化落地路径/.test(String(item?.text || ""))) continue;
    const stageIndex = nearestFourStepCardIndex(box, cards);
    const card = cards[stageIndex];
    if (center.x < Number(card.x || 0) - 28 || center.x > Number(card.x || 0) + Number(card.w || 0) + 28) continue;
    applyFourStepLandingTextComponent(item, target, `stage-${stageIndex}`, "narrative");
    candidates.push({ item, stageIndex });
  }
  const removed = new Set();
  for (let stageIndex = 0; stageIndex < cards.length; stageIndex += 1) {
    const group = candidates
      .filter((candidate) => candidate.stageIndex === stageIndex)
      .map((candidate) => candidate.item)
      .sort((left, right) => Number(left.box?.y || 0) - Number(right.box?.y || 0)
        || Number(left.box?.x || 0) - Number(right.box?.x || 0));
    if (group.length < 2) continue;
    const targetBox = group[0];
    const left = Math.min(...group.map((item) => Number(item.box?.x || 0)));
    const top = Math.min(...group.map((item) => Number(item.box?.y || 0)));
    const right = Math.max(...group.map((item) => Number(item.box?.x || 0) + Number(item.box?.w || 0)));
    const bottom = Math.max(...group.map((item) => Number(item.box?.y || 0) + Number(item.box?.h || 0)));
    const text = mergeFourStepNarrativeFragments(group.map((item) => item.text));
    const splitAt = text.indexOf("：");
    const evidenceBox = roundedBox({ x: left, y: top, w: right - left, h: bottom - top });
    targetBox.text = text;
    targetBox.box = evidenceBox;
    targetBox.font = {
      ...(targetBox.font || {}),
      family: "SimSun",
      sizePt: 13.5,
      weight: "regular",
      color: "#1F1F1F",
      align: "left",
      valign: "top",
      lineHeightMultiple: 1.32
    };
    targetBox.style = {
      ...(targetBox.style || {}),
      wrap: true,
      fit: "shrink",
      preserveTypography: true,
      marginLeftPt: 0,
      marginRightPt: 0,
      marginTopPt: 0,
      marginBottomPt: 0
    };
    targetBox.runs = splitAt > 0
      ? [
        { text: text.slice(0, splitAt + 1), font: { family: "SimHei", weight: "bold" } },
        { text: text.slice(splitAt + 1), font: { family: "SimSun", weight: "regular" } }
      ]
      : null;
    targetBox.source = {
      ...(targetBox.source || {}),
      detector: "four-step-landing-path-native-narrative",
      mergedOcrFragments: group.length,
      evidenceBox,
      preserveTypography: true
    };
    group.slice(1).forEach((item) => removed.add(item));
  }
  if (removed.size > 0) {
    const retained = textBoxes.filter((item) => !removed.has(item));
    textBoxes.splice(0, textBoxes.length, ...retained);
  }
  return textBoxes;
}

function mergeFourStepNarrativeFragments(fragments = []) {
  return fragments
    .map((fragment) => String(fragment || "").trim())
    .filter(Boolean)
    .join("")
    .replace(/([\u3400-\u9FFF])([A-Za-z])/g, "$1 $2")
    .replace(/([A-Za-z])([\u3400-\u9FFF])/g, "$1 $2")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function applyFourStepLandingTextComponent(item, target, role, part) {
  const component = fourStepLandingNativeComponentMetadata(target, role, part);
  item.style = { ...(item.style || {}), nativeComponentGroupId: component.nativeComponentGroupId };
  item.source = { ...(item.source || {}), ...component };
  return item;
}

function nearestFourStepCardIndex(box, cards = []) {
  const x = centerOfBox(box || {}).x;
  const centers = (Array.isArray(cards) ? cards : []).map((card) => centerOfBox(card).x);
  return nearestNumericIndex(x, centers);
}

function fourStepLandingNativeComponentMetadata(target, role, part) {
  const base = safeComponentToken(target?.id || "four-step-landing-path");
  const safeRole = safeComponentToken(role);
  return {
    nativeComponentGroupId: `${base}-four-step-${safeRole}`,
    nativeComponentInstance: true,
    nativeComponentMinimumUnit: "semantic-component",
    nativeComponentArchetype: "four-step-roadmap",
    nativeComponentRole: safeRole,
    nativeComponentPart: safeComponentToken(part)
  };
}

function fourStepLandingPathLayout(box = {}, rawTextBoxes = [], slideSize = DEFAULT_SLIDE, semanticNodes = []) {
  const normalizedBox = {
    x: Number(box.x || slideSize.widthPt * 0.08),
    y: Number(box.y || slideSize.heightPt * 0.25),
    w: Number(box.w || slideSize.widthPt * 0.84),
    h: Number(box.h || slideSize.heightPt * 0.52)
  };
  const variant = normalizedBox.h >= slideSize.heightPt * 0.55 ? "chevron" : "square";
  if (variant === "square") {
    // Square-stage roadmaps reserve a wider, labelled midpoint between steps 02 and 03.
    // Treating all gaps uniformly turns that label into an unrelated cycle-shaped atom.
    const cardW = normalizedBox.w * 0.163;
    const cardH = normalizedBox.h * 0.73;
    const cardY = normalizedBox.y + normalizedBox.h * 0.23;
    const xRatios = [0.008, 0.251, 0.566, 0.811];
    const cards = xRatios.map((ratio, index) => ({
      x: normalizedBox.x + normalizedBox.w * ratio,
      y: cardY,
      w: cardW,
      h: cardH,
      semanticNode: semanticNodes.find((node) => String(node?.text || "") === `0${index + 1}`) || null
    }));
    const gapBoxes = [
      { x: normalizedBox.x + normalizedBox.w * 0.181, w: normalizedBox.w * 0.055 },
      { x: normalizedBox.x + normalizedBox.w * 0.423, w: normalizedBox.w * 0.137 },
      { x: normalizedBox.x + normalizedBox.w * 0.737, w: normalizedBox.w * 0.055 }
    ];
    const arrows = gapBoxes.map((gap) => ({
      x: gap.x,
      y: cardY + cardH * 0.38,
      w: gap.w,
      h: Math.max(34, cardH * 0.24)
    }));
    const flagLabel = [...(rawTextBoxes || []), ...(semanticNodes || [])]
      .filter((item) => /克服标准缺口/.test(String(item?.text || "")))
      .filter((item) => Number(item?.box?.y || 0) < cardY + cardH * 0.45)
      .sort((left, right) => Number(left?.box?.y || 0) - Number(right?.box?.y || 0))[0];
    const flagWave = flagLabel?.box
      ? {
        x: Number(flagLabel.box.x || 0) - 8,
        y: Number(flagLabel.box.y || 0) - 15,
        w: Math.max(92, Number(flagLabel.box.w || 0) + 16),
        h: 58
      }
      : { x: normalizedBox.x + normalizedBox.w * 0.515, y: normalizedBox.y + normalizedBox.h * 0.08, w: 92, h: 58 };
    const flagPole = { x: flagWave.x - 7, y: flagWave.y, w: 5, h: 102 };
    return { box: normalizedBox, cards, arrows, variant, flagWave, flagPole };
  }
  if (variant === "chevron") {
    // This source family uses uneven stage widths and a cropped left contour.
    // The OCR labels are good anchors; uniform division shifts stage one by
    // about 40pt and makes every native label look detached from its card.
    const cards = [
      { x: normalizedBox.x + slideSize.widthPt * 0.044, w: slideSize.widthPt * 0.188 },
      { x: normalizedBox.x + slideSize.widthPt * 0.246, w: slideSize.widthPt * 0.205 },
      { x: normalizedBox.x + slideSize.widthPt * 0.479, w: slideSize.widthPt * 0.207 },
      { x: normalizedBox.x + slideSize.widthPt * 0.716, w: slideSize.widthPt * 0.21 }
    ].map((item) => ({
      ...item,
      y: normalizedBox.y + normalizedBox.h * 0.12,
      h: normalizedBox.h * 0.76
    }));
    const arrows = cards.slice(0, 3).map((card, index) => {
      const next = cards[index + 1];
      const gap = Math.max(8, Number(next.x) - (Number(card.x) + Number(card.w)));
      return {
        x: card.x + card.w + gap * 0.14,
        y: card.y + card.h * 0.42,
        w: Math.max(24, gap * 0.9),
        h: Math.max(34, card.h * 0.24)
      };
    });
    return { box: normalizedBox, cards, arrows, variant };
  }
  const gap = 74;
  const cardY = variant === "chevron" ? normalizedBox.y + normalizedBox.h * 0.12 : normalizedBox.y + normalizedBox.h * 0.20;
  const cardH = variant === "chevron" ? normalizedBox.h * 0.76 : normalizedBox.h * 0.56;
  const cardW = (normalizedBox.w - gap * 3) / 4;
  const cards = [0, 1, 2, 3].map((index) => ({
    x: normalizedBox.x + index * (cardW + gap),
    y: cardY,
    w: cardW,
    h: cardH
  }));
  const arrows = cards.slice(0, 3).map((card, index) => ({
    x: card.x + card.w + gap * 0.16,
    y: card.y + card.h * (variant === "chevron" ? 0.42 : 0.38),
    w: Math.max(24, gap * 0.68),
    h: Math.max(34, card.h * 0.24)
  }));
  return { box: normalizedBox, cards, arrows, variant };
}

function fourStepLandingCardShape(shape, card, index, variant) {
  const fill = variant === "square"
    ? "#1D70B8"
    : index === 0 ? "#1E75BD" : index === 1 ? "#1B66A7" : index === 2 ? "#185891" : "#124A7D";
  if (variant === "chevron") {
    return shape(`card-${index + 1}`, "four-step-landing-path-native-card", "freeform", card, {
      fill,
      stroke: "#DFF4F7",
      strokeWidthPt: 1.2,
      shadow: { type: "outer", color: "#7EAFC3", opacity: 0.18, blurPt: 2.2, distancePt: 1.2, angle: 45 },
      points: [
        { x: 0.03, y: 0 },
        { x: 0.94, y: 0 },
        { x: 1, y: 0.5 },
        { x: 0.94, y: 1 },
        { x: 0, y: 1 },
        { x: 0.07, y: 0.5 }
      ]
    }, { cardIndex: index, variant });
  }
  return shape(`card-${index + 1}`, "four-step-landing-path-native-card", "rect", card, {
    fill,
    stroke: fill,
    strokeWidthPt: 0.8,
    shadow: { type: "outer", color: "#6E9DBE", opacity: 0.12, blurPt: 1.6, distancePt: 0.8, angle: 45 }
  }, { cardIndex: index, variant });
}

function fourStepLandingPathTextBoxes(rawTextBoxes = [], visibleTextBoxes = [], src = () => ({}), layout = {}) {
  const pageText = (rawTextBoxes || []).map((item) => String(item?.text || "")).join(" ");
  const squareVariant = /四步走战略/.test(pageText);
  return (rawTextBoxes || [])
    .filter((item) => isFourStepLandingPathDiagramText(item) || isFourStepLandingPathCardText(item, layout))
    .map((item, index) => {
      const role = fourStepLandingPathTextRole(item.text);
      const next = JSON.parse(JSON.stringify(item));
      next.id = `four-step-landing-path-text-${index}`;
      next.box = roundedBox(next.box || {});
      const card = layout?.cards?.[nearestFourStepCardIndex(next.box, layout.cards)];
      if ((role === "heading" || role === "subheading") && card) {
        next.box = roundedBox({
          ...next.box,
          x: card.x + 14,
          w: Math.max(40, card.w - 28),
          h: Math.max(next.box.h, role === "heading" ? 27 : 22)
        });
      }
      next.font = {
        ...(next.font || {}),
        family: "Microsoft YaHei",
        opacity: 1,
        color: fourStepLandingPathTextColor(role, next.box, squareVariant),
        weight: role === "number" || role === "heading" || role === "subheading" ? "bold" : "regular",
        align: role === "number" || role === "heading" || role === "subheading" ? "center" : "left",
        valign: "middle",
        sizePt: fourStepLandingPathFontSize(role, next.font?.sizePt)
      };
      next.style = {
        ...(next.style || {}),
        visibility: "visible",
        opacity: 1,
        fit: "shrink",
        marginLeftPt: 0,
        marginRightPt: 0,
        marginTopPt: 0,
        marginBottomPt: 0
      };
      next.source = src("four-step-landing-path-native-text", {
        textRole: role,
        originalOpacity: item?.font?.opacity ?? null
      });
      return next;
    });
}

function fourStepLandingPathSemanticNodeTextBoxes(image = {}, src = () => ({}), rawTextBoxes = []) {
  const nodes = Array.isArray(image?.source?.layer?.diagramUnderstanding?.nodes)
    ? image.source.layer.diagramUnderstanding.nodes
    : [];
  return nodes
    .filter((node) => node?.box && isFourStepLandingPathDiagramText(node))
    .map((node, index) => {
      const role = fourStepLandingPathTextRole(node.text);
      const evidence = findFourStepLandingPathTextEvidence(node, rawTextBoxes);
      if (evidence) return null;
      return {
        id: node.id || `${image.id || "four-step-landing-path"}-semantic-text-${index}`,
        text: normalizeStructuredCaseMatrixText(node.text),
        box: roundedBox(node.box || {}),
        font: {
          family: role === "number" ? "Microsoft YaHei" : "SimHei",
          opacity: 1,
          color: fourStepLandingPathTextColor(role, node.box, true),
          weight: role === "number" || role === "heading" ? "bold" : "regular",
          align: "center",
          valign: "middle",
          sizePt: fourStepLandingPathFontSize(role, evidence?.font?.sizePt ?? node.font?.sizePt)
        },
        style: {
          visibility: "visible",
          opacity: 1,
          fit: "shrink",
          marginLeftPt: 0,
          marginRightPt: 0,
          marginTopPt: 0,
          marginBottomPt: 0
        },
        source: src("four-step-landing-path-native-text", {
          textRole: role,
          semanticTextSource: true,
          semanticNodeId: node.id || "",
          originalOpacity: node?.font?.opacity ?? null
        })
      };
    })
    .filter(Boolean);
}

function findFourStepLandingPathTextEvidence(node = {}, rawTextBoxes = []) {
  const targetText = normalizeTextKey(node?.text);
  const targetBox = node?.box || {};
  return (Array.isArray(rawTextBoxes) ? rawTextBoxes : [])
    .filter((item) => normalizeTextKey(item?.text) === targetText)
    .sort((left, right) => {
      const leftDistance = distanceBetweenBoxCenters(left?.box, targetBox);
      const rightDistance = distanceBetweenBoxCenters(right?.box, targetBox);
      return leftDistance - rightDistance;
    })[0] || null;
}

function distanceBetweenBoxCenters(left = {}, right = {}) {
  const leftCenter = centerOfBox(left);
  const rightCenter = centerOfBox(right);
  return Math.hypot(leftCenter.x - rightCenter.x, leftCenter.y - rightCenter.y);
}

function isFourStepLandingPathCardText(textBox = {}, layout = {}) {
  const cards = Array.isArray(layout?.cards) ? layout.cards : [];
  if (cards.length !== 4) return false;
  const box = textBox?.box || {};
  const center = centerOfBox(box);
  return cards.some((card) => center.x >= Number(card.x || 0) - 20
    && center.x <= Number(card.x || 0) + Number(card.w || 0) + 20
    && center.y >= Number(card.y || 0) + 6
    && center.y <= Number(card.y || 0) + Number(card.h || 0) + 8);
}

function filterTextBoxesClaimedByFourStepLandingPath(textBoxes = [], layout = {}) {
  return (Array.isArray(textBoxes) ? textBoxes : [])
    .filter((item) => !isFourStepLandingPathDiagramText(item) && !isFourStepLandingPathCardText(item, layout));
}

function mergeFourStepLandingPathTextBoxes(...groups) {
  const result = [];
  for (const group of groups || []) {
    for (const item of group || []) {
      const text = normalizeStructuredCaseMatrixText(item?.text);
      if (!text) continue;
      const box = item?.box || {};
      const alreadyClaimed = result.some((existing) =>
        normalizeStructuredCaseMatrixText(existing?.text) === text
        && fourStepLandingPathTextBoxesOverlap(existing?.box, box)
      );
      if (alreadyClaimed) continue;
      result.push(item);
    }
  }
  return result;
}

function mergeFourStepLandingPathBodyFragments(textBoxes = [], layout = {}) {
  const cards = Array.isArray(layout?.cards) ? layout.cards : [];
  if (cards.length !== 4) return textBoxes;
  const retained = [];
  for (let cardIndex = 0; cardIndex < cards.length; cardIndex += 1) {
    const card = cards[cardIndex];
    const body = (Array.isArray(textBoxes) ? textBoxes : [])
      .filter((item) => fourStepLandingPathTextRole(item?.text) === "body")
      .filter((item) => nearestFourStepCardIndex(item?.box, cards) === cardIndex)
      .filter((item) => centerOfBox(item?.box || {}).y >= Number(card.y || 0) + Number(card.h || 0) * 0.62)
      .sort((left, right) => Number(left?.box?.y || 0) - Number(right?.box?.y || 0)
        || Number(left?.box?.x || 0) - Number(right?.box?.x || 0));
    const bodySet = new Set(body);
    retained.push(...(Array.isArray(textBoxes) ? textBoxes : []).filter((item) => !bodySet.has(item) && nearestFourStepCardIndex(item?.box, cards) === cardIndex));
    if (body.length === 0) continue;
    const first = JSON.parse(JSON.stringify(body[0]));
    const top = Math.min(...body.map((item) => Number(item?.box?.y || 0)));
    const bottom = Math.max(...body.map((item) => Number(item?.box?.y || 0) + Number(item?.box?.h || 0)));
    const innerLeft = Number(card.x || 0) + 26;
    const sourceLeft = Math.min(...body.map((item) => Number(item?.box?.x || 0)));
    const x = Math.max(innerLeft, sourceLeft);
    first.id = `${first.id}-merged-card-body`;
    first.text = body.map((item) => String(item?.text || "").trim()).filter(Boolean).join("\n");
    first.box = roundedBox({ x, y: top, w: Math.max(36, Number(card.x || 0) + Number(card.w || 0) - x - 16), h: Math.max(20, bottom - top) });
    first.font = {
      ...(first.font || {}),
      family: "Microsoft YaHei",
      sizePt: 13,
      weight: "regular",
      align: "left",
      valign: "top",
      lineHeightMultiple: 1.16
    };
    first.style = {
      ...(first.style || {}),
      wrap: true,
      fit: "shrink",
      marginLeftPt: 0,
      marginRightPt: 0,
      marginTopPt: 0,
      marginBottomPt: 0
    };
    first.source = {
      ...(first.source || {}),
      mergedOcrFragments: body.length,
      textRole: "body",
      semanticCardIndex: cardIndex
    };
    retained.push(first);
  }
  return retained;
}

function fourStepLandingPathTextBoxesOverlap(left = {}, right = {}) {
  const leftCenter = centerOfBox(left);
  const rightCenter = centerOfBox(right);
  const maxHorizontalDistance = Math.max(Number(left.w || 0), Number(right.w || 0)) * 0.55 + 8;
  const maxVerticalDistance = Math.max(Number(left.h || 0), Number(right.h || 0)) * 0.55 + 6;
  return Math.abs(leftCenter.x - rightCenter.x) <= maxHorizontalDistance
    && Math.abs(leftCenter.y - rightCenter.y) <= maxVerticalDistance;
}

function isFourStepLandingPathDiagramText(textBox) {
  const text = String(textBox?.text || "").trim();
  if (!text || /^(TheDigitalArchitect|规模化落地路径)/.test(text)) return false;
  return /^(01|02|03|04)$|建域仓|接系统|固流程|升平台|统一资产容器|扩展业务入口|AI链路固化|集中演进|一键初始化|先建域仓|再接系统|沉淀流程|持续升级|选择高价值|连接现有系统|技能|sync-prds|骨架|常工作流|能力|仓库|业务域|域内|深度嵌入|运行时|初始化|入口|菜单|链路|边际成本|克服标准缺口/.test(text);
}

function fourStepLandingPathTextRole(text) {
  const value = String(text || "");
  if (/^(01|02|03|04)$/.test(value)) return "number";
  if (/建域仓|接系统|固流程|升平台/.test(value)) return "heading";
  if (/统一资产容器|扩展业务入口|AI链路固化|固化AI链路|集中演进|一键初始化/.test(value)) return "subheading";
  if (/克服标准缺口/.test(value)) return "flag";
  return "body";
}

function fourStepLandingPathTextColor(role, box = {}, squareVariant = false) {
  if (role === "flag") return "#FFFFFF";
  if (squareVariant && (role === "body" || Number(box.y || 0) >= 340)) return "#111111";
  return "#FFFFFF";
}

function fourStepLandingPathFontSize(role, fallback) {
  if (role === "number") return Math.max(26, Number(fallback || 0));
  if (role === "heading") return Math.min(16, Math.max(13.5, Number(fallback || 0)));
  if (role === "subheading") return Math.min(16, Math.max(13, Number(fallback || 0)));
  if (role === "flag") return Math.max(11, Number(fallback || 0));
  return Math.min(14, Math.max(10.5, Number(fallback || 12)));
}

function createKpiEvidenceShapes(textBoxes, slideSize = DEFAULT_SLIDE) {
  const layout = kpiEvidenceLayoutBounds(textBoxes, slideSize);
  if (!layout) return [];
  const cardShapes = layout.cards.map((box, index) => ({
    id: `native-kpi-card-${index}`,
    type: "roundRect",
    box,
    style: {
      fill: "#FFFFFF",
      stroke: "#D8D8D8",
      strokeWidthPt: 1,
      radiusRatio: 0.04
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "kpi-evidence-card-container"
    }
  }));
  return [
    {
      id: "native-kpi-title-accent",
      type: "rect",
      box: layout.titleAccent,
      style: {
        fill: "#0D70C8",
        stroke: "none",
        strokeWidthPt: 0
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "kpi-evidence-title-accent"
      }
    },
    ...cardShapes,
    {
      id: "native-kpi-conclusion-banner",
      type: "roundRect",
      box: layout.banner,
      style: {
        fill: "#F6FBFF",
        stroke: "#1269A4",
        strokeWidthPt: 1.5,
        radiusRatio: 0.08
      },
      source: {
        editable: true,
        nativeRebuild: true,
        detector: "kpi-evidence-conclusion-banner"
      }
    }
  ];
}

function createKpiEvidenceCrops(image, textBoxes, slideSize = DEFAULT_SLIDE, options = {}) {
  if (!options.assetDir) return [];
  const layout = kpiEvidenceLayoutBounds(textBoxes, slideSize);
  if (!layout) return [];
  ensureDir(options.assetDir);
  const row1 = expandPtBox(unionPtBox(layout.cards[0], layout.cards[1]), slideSize, 3, 3);
  const row2 = expandPtBox(unionPtBox(layout.cards[2], layout.cards[3]), slideSize, 3, 3);
  const banner = expandPtBox(layout.banner, slideSize, 3, 3);
  return [row1, row2, banner].map((box, index) => {
    const pxBox = ptToPxBox(box, image, slideSize, 0);
    const crop = cropPng(image, pxBox);
    const file = path.join(options.assetDir, `${options.deckName || "deck"}-p${String(options.pageIndex + 1).padStart(2, "0")}-kpi-evidence-${String(index + 1).padStart(2, "0")}.png`);
    writePng(file, crop);
    return {
      id: `native-kpi-evidence-crop-${index}`,
      type: "fidelity-crop",
      assetPath: path.relative(options.irDir || options.assetDir, file).replace(/\\/g, "/"),
      box,
      source: {
        editable: false,
        nativeRebuild: true,
        detector: "kpi-evidence-crop",
        reason: "kpi-card-figure-preserved-as-local-crops-to-avoid-font-rendering-drift"
      }
    };
  });
}

function createKpiEvidenceTextShapes(images = [], textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE, irDir = null) {
  if (!sourceImage) return [];
  for (const image of images || []) {
    if (image?.source?.detector !== "kpi-evidence-crop") continue;
    const nativeTextBoxes = maybeEraseKpiEvidenceText({
      image,
      textBoxes: kpiEvidenceNativeTextBoxes(image, textBoxes),
      sourceImage,
      slideSize,
      irDir
    });
    if (nativeTextBoxes.length === 0) continue;
    image.source = {
      ...(image.source || {}),
      kpiEvidenceTextObjectified: true,
      kpiEvidenceNativeTextBoxes: nativeTextBoxes,
      objectifiedKpiEvidenceTextBoxes: nativeTextBoxes.length,
      preserveKpiEvidenceCropUnderNativeText: true,
      dropErasedResidualAfterNativeRebuild: false,
      nonEditableReason: `${image.source?.nonEditableReason || image.source?.reason || "local fidelity crop"}; KPI labels erased from crop and rebuilt as editable native text`
    };
  }
  return [];
}

function kpiEvidenceNativeTextBoxes(image, textBoxes = []) {
  const box = image?.box || {};
  return (textBoxes || [])
    .filter((textBox) => textBox?.box && boxCenterInside(textBox.box, box))
    .filter((textBox) => isKpiEvidenceInternalLabel(textBox))
    .map((textBox, index) => kpiEvidenceTextBox(image, textBox, index));
}

function isKpiEvidenceInternalLabel(textBox) {
  const text = String(textBox?.text || "").trim();
  if (!text) return false;
  return looksLikeLargeKpiValue(text)
    || /PRD|UI|组件|系统|底座|深度接入|沉淀|回流|AISkills|企业级|基础设施/.test(text);
}

function kpiEvidenceTextBox(image, textBox, index) {
  const next = JSON.parse(JSON.stringify(textBox));
  const role = looksLikeLargeKpiValue(next.text)
    ? "kpi-value"
    : /AISkills|企业级|基础设施/.test(String(next.text || ""))
      ? "kpi-conclusion"
      : "kpi-caption";
  next.id = next.id || `${image.id || "kpi-evidence"}-native-text-${index}`;
  const fallbackColor = role === "kpi-caption" ? "#132037" : "#0D70C8";
  next.font = {
    ...(next.font || {}),
    color: normalizeHex(next.font?.color, fallbackColor),
    opacity: 1,
    weight: role === "kpi-value" ? "bold" : (next.font?.weight || "regular")
  };
  next.source = {
    ...(next.source || {}),
    editable: true,
    nativeRebuild: true,
    detector: "kpi-evidence-native-visible-label",
    expressionForm: "chart-snapshot",
    expressionSubtype: "kpi-chart-snapshot",
    layerSourceId: image.id || null,
    overlayVisibility: "visible",
    role,
    textErasedFromCrop: true
  };
  return next;
}

function maybeEraseKpiEvidenceText({ image, textBoxes = [], sourceImage = null, slideSize = DEFAULT_SLIDE, irDir = null }) {
  if (!sourceImage || textBoxes.length === 0) return [];
  const assetFile = resolveAssetPathForIr(image.assetPath, irDir);
  if (!assetFile) return [];
  const masks = textBoxes.map((item) => ptToPxBox(item.box, sourceImage, slideSize, 5));
  if (masks.length === 0) return [];
  const erased = eraseMasks(sourceImage, masks);
  const crop = cropPng(erased, ptToPxBox(image.box, sourceImage, slideSize, 0));
  ensureDir(path.dirname(assetFile));
  writePng(assetFile, crop);
  return textBoxes;
}

function createTitleChromeShapes(textBoxes, slideSize = DEFAULT_SLIDE, sourceImage = null) {
  const title = textBoxes.find((item) => looksLikeTopTitle(item));
  if (!title) return [];
  if (/Skill\s*4.*智能评审/i.test(String(title.text || ""))) return [];
  if (/临时问答.*专业\s*AI\s*工作流/.test(String(title.text || ""))) return [];
  if (/破局重构.*A[Iil1]\s*Skills.*工作流/i.test(String(title.text || ""))) return [];
  if (/真实案例证明/.test(String(title.text || ""))) return [];
  if (/量化收益验证|规模化资产复利/.test(String(title.text || ""))) return [];
  if (/终局视野|企业级数字化产品大脑/.test(String(title.text || ""))) return [];
  const box = title.box || {};
  if (Number(box.x || 0) > slideSize.widthPt * 0.14) return [];
  if (sourceImage && !hasTitleAccentEvidence(sourceImage, box, slideSize)) return [];
  const shapes = [{
    id: "native-title-accent",
    type: "rect",
    box: {
      x: round(clamp(Number(box.x || 0) - 13, 24, 56)),
      y: round(clamp(Number(box.y || 0) - 2, 36, 48)),
      w: 3.4,
      h: round(clamp(Number(box.h || 0) + 10, 34, 48))
    },
    style: {
      fill: "#0D70C8",
      stroke: "none",
      strokeWidthPt: 0
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "title-accent"
    }
  }];
  return shapes;
}

function hasTitleAccentEvidence(sourceImage, titleBox, slideSize = DEFAULT_SLIDE) {
  if (!sourceImage || !titleBox) return false;
  const accentX = clamp(Number(titleBox.x || 0) - 13, 24, 56);
  const search = ptToPxBox({
    x: accentX - 3,
    y: clamp(Number(titleBox.y || 0) - 4, 0, slideSize.heightPt),
    w: 9.4,
    h: clamp(Number(titleBox.h || 0) + 12, 24, 60)
  }, sourceImage, slideSize, 0);
  const xEnd = Math.min(sourceImage.width, search.x + search.w);
  const yEnd = Math.min(sourceImage.height, search.y + search.h);
  const height = Math.max(1, yEnd - Math.max(0, search.y));
  let strongColumns = 0;
  let maxCoverage = 0;
  for (let x = Math.max(0, search.x); x < xEnd; x += 1) {
    let foreground = 0;
    for (let y = Math.max(0, search.y); y < yEnd; y += 1) {
      if (isGraphicForeground(pixel(sourceImage, x, y))) foreground += 1;
    }
    const coverage = foreground / height;
    maxCoverage = Math.max(maxCoverage, coverage);
    if (coverage >= 0.45) strongColumns += 1;
  }
  return maxCoverage >= 0.62 && strongColumns >= 2;
}

function kpiEvidenceLayoutBounds(textBoxes, slideSize = DEFAULT_SLIDE) {
  const values = textBoxes
    .filter((item) => looksLikeLargeKpiValue(item.text) && Number(item?.box?.h || 0) >= 48)
    .sort((a, b) => (a.box.y - b.box.y) || (a.box.x - b.box.x));
  if (values.length !== 4) return null;
  const title = textBoxes.find((item) => looksLikeTopTitle(item));
  const conclusion = textBoxes.find((item) => {
    const text = String(item?.text || "");
    const box = item?.box || {};
    return /AI\s*Skills|AISkills/i.test(text)
      && /企业级|基础设施|验证/.test(text)
      && Number(box.y || 0) >= slideSize.heightPt * 0.78;
  });
  if (!title || !conclusion) return null;
  const captions = textBoxes.filter((item) => {
    const box = item?.box || {};
    const text = String(item?.text || "").trim();
    return !looksLikeLargeKpiValue(text)
      && !looksLikeTopTitle(item)
      && item !== conclusion
      && Number(box.y || 0) >= slideSize.heightPt * 0.36
      && Number(box.y || 0) <= slideSize.heightPt * 0.8;
  });
  if (captions.length < 4) return null;
  const columns = values.map((item) => Number(item.box.x || 0) + Number(item.box.w || 0) / 2);
  const leftValues = values.filter((item) => Number(item.box.x || 0) + Number(item.box.w || 0) / 2 < slideSize.widthPt / 2);
  const rightValues = values.filter((item) => Number(item.box.x || 0) + Number(item.box.w || 0) / 2 >= slideSize.widthPt / 2);
  if (leftValues.length !== 2 || rightValues.length !== 2) return null;
  const topValues = values.slice(0, 2);
  const bottomValues = values.slice(2, 4);
  if (Math.abs(topValues[0].box.y - topValues[1].box.y) > 14) return null;
  if (Math.abs(bottomValues[0].box.y - bottomValues[1].box.y) > 14) return null;
  if (Math.min(...columns) < slideSize.widthPt * 0.12 || Math.max(...columns) > slideSize.widthPt * 0.9) return null;
  const marginX = round(clamp(Math.min(...values.map((item) => item.box.x)) - 72, 36, 70));
  const gap = round(clamp(slideSize.widthPt * 0.018, 12, 20));
  const cardW = round((slideSize.widthPt - marginX * 2 - gap) / 2);
  const row1Y = round(clamp(Math.min(...topValues.map((item) => item.box.y)) - 27, 96, 118));
  const row2Y = round(clamp(Math.min(...bottomValues.map((item) => item.box.y)) - 29, 270, 292));
  const row1Bottom = Math.max(...captions
    .filter((item) => Number(item.box.y || 0) < (row2Y - 10))
    .map((item) => Number(item.box.y || 0) + Number(item.box.h || 0)));
  const row2Bottom = Math.max(...captions
    .filter((item) => Number(item.box.y || 0) >= (row2Y - 10))
    .map((item) => Number(item.box.y || 0) + Number(item.box.h || 0)));
  if (!Number.isFinite(row1Bottom) || !Number.isFinite(row2Bottom)) return null;
  const cardH1 = round(clamp(row1Bottom - row1Y + 18, 148, 166));
  const cardH2 = round(clamp(row2Bottom - row2Y + 18, 148, 166));
  const rightX = round(slideSize.widthPt - marginX - cardW);
  return {
    titleAccent: {
      x: round(clamp((title.box.x || 0) - 12.5, 42, 54)),
      y: round(clamp((title.box.y || 0) - 1.5, 38, 48)),
      w: 3.4,
      h: round(clamp((title.box.h || 0) + 10, 34, 44))
    },
    cards: [
      { x: marginX, y: row1Y, w: cardW, h: cardH1 },
      { x: rightX, y: row1Y, w: cardW, h: cardH1 },
      { x: marginX, y: row2Y, w: cardW, h: cardH2 },
      { x: rightX, y: row2Y, w: cardW, h: cardH2 }
    ],
    banner: {
      x: round(clamp((conclusion.box.x || 0) - 17, 92, 104)),
      y: round(clamp((conclusion.box.y || 0) - 13, 460, 468)),
      w: round(clamp((conclusion.box.w || 0) + 52, 758, 770)),
      h: round(clamp((conclusion.box.h || 0) + 29, 46, 54))
    }
  };
}

function shouldNativeTextBox(item) {
  const box = item?.box || {};
  const font = item?.font || {};
  const text = String(item?.text || "").trim();
  const width = Number(box.w || 0);
  const height = Number(box.h || 0);
  const sizePt = Number(font.sizePt || 0);
  const ratio = width / Math.max(1, height);
  const cjkCount = (text.match(/[\u3400-\u9fff]/g) || []).length;

  // Rotated/slanted labels inside diagrams often OCR as tall narrow boxes.
  // Keeping them in the graphic crop is more faithful than making huge wrapped text.
  if (height >= 72 && ratio <= 0.95 && sizePt >= 22 && cjkCount >= 4) {
    return false;
  }
  return true;
}

function inferWeight(item, currentWeight = null) {
  const role = String(item.role || "").toLowerCase();
  const size = Number(item.font?.sizePt || 0);
  const text = String(item.text || "").trim();
  const box = item.box || {};
  const cjkCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
  const current = normalizeFontWeightForOpenXml(currentWeight, "");
  if (current && current !== "regular") return current;
  if (role === "title" || size >= 18) return "bold";
  if (looksLikeLargeMetric(text) && size >= 24) return "bold";
  if (looksLikeLargeKpiValue(text) && size >= 24) return "bold";
  if (looksLikeShortCardHeading(item)) return "bold";
  if (Number(box.y || 0) < 105 && size >= 15.5 && cjkCount >= 6) return "bold";
  if (Number(box.h || 0) >= 20 && size >= 14.5 && cjkCount >= 5 && text.length <= 24) return "bold";
  return "regular";
}

function normalizeTextBoxFontWeights(textBoxes = []) {
  return (textBoxes || []).map((textBox) => {
    if (!textBox?.font || textBox.font.weight === undefined || textBox.font.weight === null) return textBox;
    const normalizedWeight = normalizeFontWeightForOpenXml(textBox.font.weight, "regular");
    if (textBox.font.weight === normalizedWeight) return textBox;
    return {
      ...textBox,
      font: {
        ...textBox.font,
        weight: normalizedWeight
      }
    };
  });
}

function normalizeFontWeightForOpenXml(value, fallback = "regular") {
  if (value === undefined || value === null || value === "") return fallback;
  if (typeof value === "number") return Number(value) >= 600 ? "bold" : "regular";
  const text = String(value).trim().toLowerCase();
  if (!text) return fallback;
  if (/^\d+(?:\.\d+)?$/.test(text)) return Number(text) >= 600 ? "bold" : "regular";
  if (/^(bold|bolder|heavy|semibold|semi-bold|demibold|demi-bold)$/.test(text)) return "bold";
  if (/^(regular|normal|book|light|lighter)$/.test(text)) return "regular";
  return text;
}

function refineFontSize(item) {
  const font = item.font || {};
  const box = item.box || {};
  const size = Number(font.sizePt || 0);
  const height = Number(box.h || 0);
  const text = String(item.text || "").trim();
  if (!size || !height) return font.sizePt;
  let nextSize = size;
  if (looksLikeLargeMetric(text) && height >= 44) {
    nextSize = round(clamp(height * 1.08, size, 76));
  } else if (looksLikeLargeKpiValue(text) && height >= 44) {
    nextSize = round(clamp(height * 0.95, size, 76));
  } else if (looksLikeTopTitle(item) && height >= 20) {
    nextSize = round(clamp(height * 1.05, size, 52));
  } else if (looksLikeShortCardHeading(item) && height >= 18) {
    nextSize = round(clamp(height * 0.95, size, 30));
  }
  return fitSingleLineFontSize(item, nextSize);
}

function looksLikeLargeMetric(text) {
  return /^[0-9０-９]+(?:[.%％]|[%-－–—][0-9０-９]+[%％]?)+$/.test(String(text || "").trim());
}

function looksLikeLargeKpiValue(text) {
  return /^[0-9０-９]+(?:\+|＋)?\s*[\u4e00-\u9fff]{1,2}$/.test(String(text || "").trim());
}

function looksLikeTopTitle(item) {
  const text = String(item?.text || "").trim();
  const box = item?.box || {};
  const cjkCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
  return Number(box.y || 0) < 95 && cjkCount >= 8 && text.length <= 34;
}

function looksLikeShortCardHeading(item) {
  const text = String(item?.text || "").trim();
  const box = item?.box || {};
  const cjkCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
  if (cjkCount < 4 || cjkCount > 12) return false;
  if (/[。；，,.;:：]/.test(text)) return false;
  return Number(box.w || 0) <= 220 && Number(box.h || 0) >= 18;
}

function shouldDisableTextWrap(item) {
  const text = String(item?.text || "").trim();
  const box = item?.box || {};
  if (!text || text.includes("\n")) return false;
  const height = Number(box.h || 0);
  const width = Number(box.w || 0);
  const size = Number(item?.font?.sizePt || 0);
  if (!height || !width || !size) return false;
  if (height <= Math.max(24, size * 1.75)) return true;
  if (looksLikeLargeMetric(text) && height <= size * 2.3) return true;
  return false;
}

function fitSingleLineFontSize(item, currentSize) {
  const text = String(item?.text || "").trim();
  const box = item?.box || {};
  const width = Number(box.w || 0);
  const height = Number(box.h || 0);
  const size = Number(currentSize || 0);
  if (!text || text.includes("\n") || !width || !height || !size) return currentSize;
  if (!shouldDisableTextWrap({ ...item, font: { ...(item.font || {}), sizePt: size } })) return currentSize;
  if (Number(box.y || 0) < 110 && text.length <= 36) return currentSize;
  const units = estimatedTextUnits(text);
  if (units <= 0) return currentSize;
  const maxSize = (width * 0.94) / units;
  if (maxSize >= size) return currentSize;
  return round(clamp(maxSize, Math.max(7.5, size * 0.62), size));
}

function estimatedTextUnits(text) {
  let units = 0;
  for (const char of String(text || "")) {
    if (/[\u3400-\u9fff\uff00-\uffef]/.test(char)) units += 0.86;
    else if (/[A-Z]/.test(char)) units += 0.68;
    else if (/[a-z0-9]/.test(char)) units += 0.56;
    else if (/\s/.test(char)) units += 0.32;
    else units += 0.44;
  }
  return units;
}

function sampleInkColor(image, ptBox, slideSize, fallback = "#111111") {
  const box = ptToPxBox(ptBox, image, slideSize, 2);
  const samples = [];
  const sampleStep = Math.max(1, Math.ceil(Math.sqrt((box.w * box.h) / 9000)));
  for (let y = box.y; y < box.y + box.h; y += sampleStep) {
    for (let x = box.x; x < box.x + box.w; x += sampleStep) {
      const color = pixel(image, x, y);
      if (color.a < 64) continue;
      samples.push(color);
    }
  }
  if (samples.length < 8) return normalizeHex(fallback, "#111111");
  const background = sampleMaskBackgroundColor(image, box);
  const contrastSorted = samples
    .map((color) => ({ color, distance: colorDistance(color, background) }))
    .sort((a, b) => b.distance - a.distance);
  const topDistance = contrastSorted[0]?.distance || 0;
  const highContrast = contrastSorted
    .filter((item) => item.distance >= Math.max(32, topDistance * 0.65))
    .map((item) => item.color);
  const chosen = highContrast.length >= 8
    ? highContrast
    : samples.slice().sort((a, b) => luma(a) - luma(b)).slice(0, Math.max(8, Math.floor(samples.length * 0.45)));
  const averaged = averageColor(chosen);
  if (luma(background) < 205 && saturation(background) > 0.18 && luma(averaged) > 190) {
    return "#FFFFFF";
  }
  const lightNeutralRatio = samples.filter((color) => luma(color) > 235 && saturation(color) < 0.12).length / samples.length;
  if (luma(averaged) > 220 && lightNeutralRatio > 0.45) {
    const darkInk = samples
      .filter((color) => luma(color) < 190)
      .sort((a, b) => luma(a) - luma(b))
      .slice(0, Math.max(8, Math.floor(samples.length * 0.22)));
    if (darkInk.length >= 8) return rgbToHex(averageColor(darkInk));
  }
  return rgbToHex(averaged);
}

function detectLongLines(image, slideSize) {
  const horizontal = detectAxisLines(image, slideSize, "h");
  const vertical = detectAxisLines(image, slideSize, "v");
  return [...horizontal, ...vertical].map((line, index) => ({
    id: `native-line-${line.axis}-${index}`,
    type: "line",
    box: line.axis === "h"
      ? { x: line.x1, y: line.y, w: Math.max(0.1, line.x2 - line.x1), h: 0 }
      : { x: line.x, y: line.y1, w: 0, h: Math.max(0.1, line.y2 - line.y1) },
    style: {
      stroke: line.color,
      strokeWidthPt: Math.max(0.5, line.thicknessPt),
      connectorType: "straight"
    },
    source: {
      editable: true,
      nativeRebuild: true,
      detector: "long-axis-line"
    }
  }));
}

function keepStructuralLines(lines, textBoxes) {
  const horizontal = lines.filter((line) => Math.abs(line.box.h || 0) < 0.01);
  const vertical = lines.filter((line) => Math.abs(line.box.w || 0) < 0.01);
  const tableLike = textBoxes.length >= 10 && horizontal.length >= 2 && vertical.length >= 2;
  if (tableLike) {
    return [...horizontal.slice(0, 16), ...vertical.slice(0, 16)];
  }
  if (lines.length <= 8) return lines;
  return [];
}

function detectAxisLines(image, slideSize, axis) {
  const raw = [];
  const outer = axis === "h" ? image.height : image.width;
  const inner = axis === "h" ? image.width : image.height;
  const minRun = axis === "h" ? image.width * 0.18 : image.height * 0.16;
  for (let a = 0; a < outer; a += 1) {
    let start = null;
    let colors = [];
    for (let b = 0; b <= inner; b += 1) {
      const color = b < inner ? (axis === "h" ? pixel(image, b, a) : pixel(image, a, b)) : null;
      const on = color && isLinePixel(color);
      if (on && start === null) {
        start = b;
        colors = [color];
      } else if (on) {
        if (colors.length < 200) colors.push(color);
      } else if (start !== null) {
        const len = b - start;
        if (len >= minRun) raw.push({ axis, a, b1: start, b2: b, color: rgbToHex(averageColor(colors)) });
        start = null;
      }
    }
  }
  return mergeAxisRuns(raw, image, slideSize, axis);
}

function mergeAxisRuns(raw, image, slideSize, axis) {
  const groups = [];
  for (const run of raw) {
    const existing = groups.find((group) =>
      Math.abs(group.a - run.a) <= 4
      && overlapRatio(group.b1, group.b2, run.b1, run.b2) >= 0.7
    );
    if (existing) {
      existing.aValues.push(run.a);
      existing.a = median(existing.aValues);
      existing.b1 = Math.min(existing.b1, run.b1);
      existing.b2 = Math.max(existing.b2, run.b2);
      existing.colors.push(run.color);
    } else {
      groups.push({ ...run, aValues: [run.a], colors: [run.color] });
    }
  }
  const sx = slideSize.widthPt / image.width;
  const sy = slideSize.heightPt / image.height;
  return groups
    .filter((group) => group.aValues.length <= 12)
    .map((group) => {
      const thicknessPx = Math.max(1, group.aValues.length);
      if (axis === "h") {
        return {
          axis,
          x1: round(group.b1 * sx),
          x2: round(group.b2 * sx),
          y: round(group.a * sy),
          thicknessPt: round(thicknessPx * sy),
          color: dominantHex(group.colors)
        };
      }
      return {
        axis,
        x: round(group.a * sx),
        y1: round(group.b1 * sy),
        y2: round(group.b2 * sy),
        thicknessPt: round(thicknessPx * sx),
        color: dominantHex(group.colors)
      };
    })
    .filter((line) => {
      if (axis === "h") return line.x2 - line.x1 >= 120;
      return line.y2 - line.y1 >= 80;
    });
}

function detectSimpleStatusIcons(image, slideSize, existingTextBoxes = []) {
  const components = connectedColorComponents(image);
  const shapes = [];
  const iconTextBoxes = [];
  let index = 0;
  for (const component of components) {
    const kind = classifyIconComponent(component);
    if (!kind) continue;
    const box = pxToPtBox(component.box, image, slideSize, 1.5);
    if (overlapsAnyTextBox(box, existingTextBoxes)) continue;
    const id = `native-icon-${index++}`;
    shapes.push({
      id,
      type: kind.shape,
      box,
      style: { fill: component.color, stroke: component.color, strokeWidthPt: 0 },
      source: { editable: true, nativeRebuild: true, detector: "simple-status-icon", component: kind.name }
    });
    if (kind.mark) {
      iconTextBoxes.push({
        id: `${id}-mark`,
        text: kind.mark,
        box: insetBox(box, kind.shape === "triangle" ? 0.22 : 0.12),
        font: {
          family: "Arial",
          sizePt: kind.shape === "triangle" ? Math.max(12, box.h * 0.56) : Math.max(14, box.h * 0.72),
          weight: "bold",
          color: "#FFFFFF",
          align: "center",
          valign: "middle"
        },
        style: { marginLeftPt: 0, marginRightPt: 0, marginTopPt: 0, marginBottomPt: 0 },
        source: { editable: true, nativeRebuild: true, detector: "simple-status-icon-mark" }
      });
    }
  }
  return { shapes, textBoxes: iconTextBoxes };
}

function overlapsAnyTextBox(box, textBoxes) {
  return textBoxes.some((textBox) => boxOverlapRatio(box, textBox.box || {}) > 0.08);
}

function boxOverlapRatio(a, b) {
  if (!a || !b) return 0;
  const x1 = Math.max(Number(a.x), Number(b.x));
  const y1 = Math.max(Number(a.y), Number(b.y));
  const x2 = Math.min(Number(a.x) + Number(a.w), Number(b.x) + Number(b.w));
  const y2 = Math.min(Number(a.y) + Number(a.h), Number(b.y) + Number(b.h));
  const area = Math.max(0, x2 - x1) * Math.max(0, y2 - y1);
  return area / Math.max(1, Number(a.w) * Number(a.h));
}

function detectEntropyMicroComponents(image, slideSize, options = {}) {
  if (!image?.rgba || !options.region || typeof options.predicate !== "function") return [];
  const crop = ptToPxBox(options.region, image, slideSize, 0);
  const visited = new Uint8Array(crop.w * crop.h);
  const textBoxes = (options.textBoxes || [])
    .filter((item) => item?.box && Number.isFinite(Number(item.box.x)) && Number.isFinite(Number(item.box.y)))
    .map((item) => expandPtBox(item.box, slideSize, 3, 3));
  const components = [];
  for (let localY = 0; localY < crop.h; localY += 1) {
    for (let localX = 0; localX < crop.w; localX += 1) {
      const start = localY * crop.w + localX;
      if (visited[start]) continue;
      const x = crop.x + localX;
      const y = crop.y + localY;
      const seed = pixel(image, x, y);
      if (!options.predicate(seed)) {
        visited[start] = 1;
        continue;
      }
      const queue = [[localX, localY]];
      visited[start] = 1;
      let qi = 0;
      let count = 0;
      let minX = x;
      let minY = y;
      let maxX = x;
      let maxY = y;
      const colors = [];
      while (qi < queue.length) {
        const [cx, cy] = queue[qi++];
        const px = crop.x + cx;
        const py = crop.y + cy;
        const color = pixel(image, px, py);
        count += 1;
        if (colors.length < 60) colors.push(color);
        minX = Math.min(minX, px);
        minY = Math.min(minY, py);
        maxX = Math.max(maxX, px);
        maxY = Math.max(maxY, py);
        for (const [nx, ny] of [[cx + 1, cy], [cx - 1, cy], [cx, cy + 1], [cx, cy - 1]]) {
          if (nx < 0 || ny < 0 || nx >= crop.w || ny >= crop.h) continue;
          const next = ny * crop.w + nx;
          if (visited[next]) continue;
          const nextColor = pixel(image, crop.x + nx, crop.y + ny);
          if (!options.predicate(nextColor)) {
            visited[next] = 1;
            continue;
          }
          visited[next] = 1;
          queue.push([nx, ny]);
        }
      }
      const pxBox = { x: minX, y: minY, w: maxX - minX + 1, h: maxY - minY + 1 };
      const ptBox = pxToPtBox(pxBox, image, slideSize, 0);
      const minAreaPx = options.minAreaPx ?? 4;
      const maxAreaPx = options.maxAreaPx ?? 150;
      if (count < minAreaPx || count > maxAreaPx) continue;
      if (ptBox.w > (options.maxWPt ?? 14) || ptBox.h > (options.maxHPt ?? 12)) continue;
      if (textBoxes.some((box) => boxCenterInside(ptBox, box) || boxOverlapRatio(ptBox, box) > 0.12)) continue;
      const pad = options.padPt ?? 1.2;
      components.push({
        box: constrainPtBox(expandPtBox(ptBox, slideSize, pad, pad), { x: 0, y: 0, w: slideSize.widthPt, h: slideSize.heightPt }),
        fill: rgbToHex(averageColor(colors)),
        areaPx: count,
        imageEvidence: true
      });
    }
  }
  return components
    .sort((a, b) => b.areaPx - a.areaPx)
    .slice(0, options.maxCount ?? 10);
}

function isEntropyOrangePixel(color) {
  if (!color || color.a < 64) return false;
  const hsl = rgbToHsl(color);
  return hsl.h >= 8 && hsl.h <= 48 && hsl.s >= 0.35 && hsl.l >= 0.30 && hsl.l <= 0.78;
}

function isEntropyIslandMicroPixel(color) {
  if (!color || color.a < 64) return false;
  const hsl = rgbToHsl(color);
  if (hsl.l > 0.86 || hsl.l < 0.20 || hsl.s < 0.22) return false;
  return (hsl.h >= 8 && hsl.h <= 48) || (hsl.h >= 190 && hsl.h <= 220);
}

function connectedColorComponents(image) {
  const visited = new Uint8Array(image.width * image.height);
  const components = [];
  const maxPixels = image.width * image.height;
  for (let y = 0; y < image.height; y += 2) {
    for (let x = 0; x < image.width; x += 2) {
      const seedIndex = y * image.width + x;
      if (visited[seedIndex]) continue;
      const seed = pixel(image, x, y);
      if (!isIconSeed(seed)) continue;
      const queue = [[x, y]];
      visited[seedIndex] = 1;
      let qi = 0;
      let minX = x;
      let maxX = x;
      let minY = y;
      let maxY = y;
      const colors = [];
      let count = 0;
      while (qi < queue.length && count < maxPixels) {
        const [cx, cy] = queue[qi++];
        const color = pixel(image, cx, cy);
        colors.push(color);
        count += 1;
        minX = Math.min(minX, cx);
        maxX = Math.max(maxX, cx);
        minY = Math.min(minY, cy);
        maxY = Math.max(maxY, cy);
        for (const [nx, ny] of [[cx + 2, cy], [cx - 2, cy], [cx, cy + 2], [cx, cy - 2]]) {
          if (nx < 0 || ny < 0 || nx >= image.width || ny >= image.height) continue;
          const idx = ny * image.width + nx;
          if (visited[idx]) continue;
          const next = pixel(image, nx, ny);
          if (!isSimilarIconPixel(seed, next)) continue;
          visited[idx] = 1;
          queue.push([nx, ny]);
        }
      }
      const width = maxX - minX + 1;
      const height = maxY - minY + 1;
      if (count >= 120 && width >= 35 && height >= 35 && width <= 160 && height <= 160) {
        components.push({
          box: { x: minX, y: minY, w: width, h: height },
          area: count * 4,
          density: (count * 4) / Math.max(1, width * height),
          color: rgbToHex(averageColor(colors))
        });
      }
    }
  }
  return components;
}

function classifyIconComponent(component) {
  const color = parseHex(component.color);
  const hsl = rgbToHsl(color);
  const ratio = component.box.w / Math.max(1, component.box.h);
  if (ratio < 0.55 || ratio > 1.65) return null;
  if (component.density < 0.28) return null;
  if (hsl.h >= 18 && hsl.h <= 48 && hsl.s > 0.55) {
    return { name: "warning", shape: "triangle", mark: "!" };
  }
  if (hsl.s < 0.16 && hsl.l < 0.65) {
    return { name: "negative", shape: "ellipse", mark: "×" };
  }
  if ((hsl.h >= 95 && hsl.h <= 170 && hsl.s > 0.35) || (hsl.h >= 190 && hsl.h <= 220 && hsl.s > 0.35)) {
    return { name: "positive", shape: "ellipse", mark: "✓" };
  }
  return null;
}

function isLinePixel(color) {
  if (color.a < 64) return false;
  if (luma(color) > 238 && saturation(color) < 0.16) return false;
  if (luma(color) < 45) return false;
  return true;
}

function isIconSeed(color) {
  if (color.a < 64) return false;
  const hsl = rgbToHsl(color);
  if (hsl.l > 0.82 || hsl.l < 0.18) return false;
  return hsl.s > 0.22 || hsl.l < 0.58;
}

function isSimilarIconPixel(seed, next) {
  if (!isIconSeed(next)) return false;
  return colorDistance(seed, next) <= 55;
}

function ptToPxBox(box, image, slideSize, paddingPt = 0) {
  const sx = image.width / slideSize.widthPt;
  const sy = image.height / slideSize.heightPt;
  const x = clamp(Math.floor((box.x - paddingPt) * sx), 0, image.width - 1);
  const y = clamp(Math.floor((box.y - paddingPt) * sy), 0, image.height - 1);
  const w = clamp(Math.ceil((box.w + paddingPt * 2) * sx), 1, image.width - x);
  const h = clamp(Math.ceil((box.h + paddingPt * 2) * sy), 1, image.height - y);
  return { x, y, w, h };
}

function ptLineToPxMask(box, image, slideSize, widthPt = 4) {
  const sx = image.width / slideSize.widthPt;
  const sy = image.height / slideSize.heightPt;
  return {
    kind: "line",
    x1: clamp(Math.round(box.x * sx), 0, image.width - 1),
    y1: clamp(Math.round(box.y * sy), 0, image.height - 1),
    x2: clamp(Math.round((box.x + box.w) * sx), 0, image.width - 1),
    y2: clamp(Math.round((box.y + box.h) * sy), 0, image.height - 1),
    width: Math.max(1, Math.round(widthPt * (sx + sy) / 2))
  };
}

function pxToPtBox(box, image, slideSize, paddingPt = 0) {
  const sx = slideSize.widthPt / image.width;
  const sy = slideSize.heightPt / image.height;
  return {
    x: round(box.x * sx - paddingPt),
    y: round(box.y * sy - paddingPt),
    w: round(box.w * sx + paddingPt * 2),
    h: round(box.h * sy + paddingPt * 2)
  };
}

function insetBox(box, ratio) {
  const dx = box.w * ratio;
  const dy = box.h * ratio;
  return {
    x: round(box.x + dx),
    y: round(box.y + dy * 0.8),
    w: round(Math.max(1, box.w - dx * 2)),
    h: round(Math.max(1, box.h - dy * 1.6))
  };
}

function trimPxBox(box, image, inset) {
  const x = clamp(box.x + inset, 0, image.width - 1);
  const y = clamp(box.y + inset, 0, image.height - 1);
  const x2 = clamp(box.x + box.w - inset, x + 1, image.width);
  const y2 = clamp(box.y + box.h - inset, y + 1, image.height);
  return { x, y, w: x2 - x, h: y2 - y };
}

function unionPtBox(a, b) {
  const x = Math.min(a.x, b.x);
  const y = Math.min(a.y, b.y);
  const x2 = Math.max(a.x + a.w, b.x + b.w);
  const y2 = Math.max(a.y + a.h, b.y + b.h);
  return { x, y, w: x2 - x, h: y2 - y };
}

function expandPtBox(box, slideSize, padX, padY) {
  const x = clamp(box.x - padX, 0, slideSize.widthPt);
  const y = clamp(box.y - padY, 0, slideSize.heightPt);
  const x2 = clamp(box.x + box.w + padX, x + 1, slideSize.widthPt);
  const y2 = clamp(box.y + box.h + padY, y + 1, slideSize.heightPt);
  return { x: round(x), y: round(y), w: round(x2 - x), h: round(y2 - y) };
}

function boxesNearPt(a, b, distance) {
  return !(a.x + a.w + distance < b.x
    || b.x + b.w + distance < a.x
    || a.y + a.h + distance < b.y
    || b.y + b.h + distance < a.y);
}

function pixel(image, x, y) {
  const offset = (Math.floor(y) * image.width + Math.floor(x)) * 4;
  return {
    r: image.rgba[offset],
    g: image.rgba[offset + 1],
    b: image.rgba[offset + 2],
    a: image.rgba[offset + 3]
  };
}

function averageColor(colors) {
  const total = colors.reduce((acc, color) => ({
    r: acc.r + color.r,
    g: acc.g + color.g,
    b: acc.b + color.b
  }), { r: 0, g: 0, b: 0 });
  const count = Math.max(1, colors.length);
  return {
    r: Math.round(total.r / count),
    g: Math.round(total.g / count),
    b: Math.round(total.b / count)
  };
}

function luma(color) {
  return color.r * 0.2126 + color.g * 0.7152 + color.b * 0.0722;
}

function saturation(color) {
  const max = Math.max(color.r, color.g, color.b) / 255;
  const min = Math.min(color.r, color.g, color.b) / 255;
  return max === 0 ? 0 : (max - min) / max;
}

function rgbToHsl(color) {
  const r = color.r / 255;
  const g = color.g / 255;
  const b = color.b / 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0;
  let s = 0;
  const l = (max + min) / 2;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) * 60;
    else if (max === g) h = ((b - r) / d + 2) * 60;
    else h = ((r - g) / d + 4) * 60;
  }
  return { h, s, l };
}

function colorDistance(a, b) {
  return Math.sqrt((a.r - b.r) ** 2 + (a.g - b.g) ** 2 + (a.b - b.b) ** 2);
}

function rgbToHex(color) {
  return `#${toHex(color.r)}${toHex(color.g)}${toHex(color.b)}`;
}

function parseHex(value) {
  const normalized = normalizeHex(value, "#000000").slice(1);
  return {
    r: parseInt(normalized.slice(0, 2), 16),
    g: parseInt(normalized.slice(2, 4), 16),
    b: parseInt(normalized.slice(4, 6), 16)
  };
}

function darkerHex(value, ratio = 0.45) {
  const color = parseHex(normalizeHex(value, "#000000"));
  const factor = clamp(1 - Number(ratio || 0), 0, 1);
  return rgbToHex({
    r: Math.round(color.r * factor),
    g: Math.round(color.g * factor),
    b: Math.round(color.b * factor)
  });
}

function normalizeHex(value, fallback) {
  const raw = String(value || "").trim().replace(/^#/, "");
  return /^[0-9a-f]{6}$/i.test(raw) ? `#${raw.toUpperCase()}` : fallback;
}

function dominantHex(values) {
  const counts = new Map();
  for (const value of values) counts.set(value, (counts.get(value) || 0) + 1);
  return [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] || "#666666";
}

function overlapRatio(a1, a2, b1, b2) {
  const overlap = Math.max(0, Math.min(a2, b2) - Math.max(a1, b1));
  return overlap / Math.max(1, Math.min(a2 - a1, b2 - b1));
}

function median(values) {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

function centerOfBox(box = {}) {
  return {
    x: Number(box.x || 0) + Number(box.w || 0) / 2,
    y: Number(box.y || 0) + Number(box.h || 0) / 2
  };
}

function toHex(value) {
  return clamp(Math.round(value), 0, 255).toString(16).padStart(2, "0").toUpperCase();
}

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function round(value) {
  return Math.round(Number(value) * 100) / 100;
}

function roundRatio(value) {
  return Math.round(Number(value) * 10000) / 10000;
}

function buildPptx(irFile, outFile, options) {
  if (resolvePptxBuildMode(options).engine === "openxml") {
    buildPptxBatch([{ irFile, outFile }], options);
    return;
  }
  const python = resolvePython(options.python);
  const script = path.resolve(__dirname, "python", "build_pptx.py");
  const result = spawnSync(python, [script, "--ir", irFile, "--out", outFile], {
    cwd: path.resolve(__dirname, "..", "..", ".."),
    encoding: "utf8"
  });
  if (result.status !== 0) {
    const details = [
      result.error?.message,
      result.stderr,
      result.stdout
    ].filter(Boolean).join("\n").trim();
    throw new Error(`build_pptx failed for ${irFile}: ${details || `exit status ${result.status}`}`);
  }
}

function buildPptxBatch(jobs, options = {}) {
  const normalizedJobs = normalizePptxBuildJobs(jobs);
  if (normalizedJobs.length === 0) return [];
  const mode = resolvePptxBuildMode(options);
  if (mode.engine === "openxml") {
    const { buildOpenXmlDecksSync } = require("./adapters/pptx-openxml-dotnet");
    const skillRoot = path.resolve(__dirname, "..");
    const context = {
      skillRoot,
      outputDir: path.dirname(normalizedJobs[0].outFile),
      config: {
        openXmlBuilder: {
          ...(mode.openXmlBuilderExe ? { exePath: mode.openXmlBuilderExe } : {}),
          ...(mode.openXmlBuilderConfiguration ? { configuration: mode.openXmlBuilderConfiguration } : {}),
          ...(mode.openXmlBuilderTargetFramework ? { targetFramework: mode.openXmlBuilderTargetFramework } : {}),
          cache: mode.openXmlBuildCache,
          cacheDir: mode.openXmlBuildCacheDir,
          cacheMaxBytes: Number(mode.openXmlBuildCacheMaxBytes) || undefined
        }
      },
      configFile: path.join(process.cwd(), "slideclone.config.json")
    };
    return buildOpenXmlDecksSync(normalizedJobs, context, path.join(skillRoot, "dotnet", "OpenXmlDeckBuilder"), mode);
  }

  for (const job of normalizedJobs) {
    buildPptx(job.irFile, job.outFile, { ...options, "pptx-engine": "python" });
  }
  return normalizedJobs.map((job) => job.outFile);
}

function normalizePptxBuildJobs(jobs) {
  if (!Array.isArray(jobs)) return [];
  return jobs.map((job, index) => {
    const irFile = typeof job?.irFile === "string" ? job.irFile.trim() : "";
    const outFile = typeof job?.outFile === "string" ? job.outFile.trim() : "";
    if (!irFile || !outFile) {
      throw new Error(`PPTX build job ${index + 1} requires irFile and outFile`);
    }
    return {
      ...job,
      irFile: path.resolve(irFile),
      outFile: path.resolve(outFile),
      templatePptx: normalizeBuildTemplatePptx(job?.templatePptx, index)
    };
  });
}

function normalizeBuildTemplatePptx(value, index) {
  if (value == null || value === "") return "";
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`PPTX build job ${index + 1} has an invalid templatePptx`);
  }
  const templatePptx = path.resolve(value.trim());
  if (!fs.existsSync(templatePptx) || !fs.statSync(templatePptx).isFile()) {
    throw new Error(`PPTX build job ${index + 1} template PPTX was not found: ${templatePptx}`);
  }
  return templatePptx;
}

function shouldRunPowerPointOpenGate(options = {}, buildMode = resolvePptxBuildMode(options)) {
  const configured = options["powerpoint-open-gate"] ?? options.powerPointOpenGate;
  if (configured !== undefined) return !isFlagDisabled(configured);
  // OpenXML is the delivery engine. Make a real PowerPoint open mandatory
  // unless a diagnostic caller explicitly opts out.
  return buildMode.engine === "openxml";
}

function isFlagDisabled(value) {
  return value === false
    || String(value ?? "").trim().toLowerCase() === "false"
    || String(value ?? "").trim() === "0";
}

function resolvePython(explicit) {
  const bundled = path.join(process.env.USERPROFILE || "", ".cache", "codex-runtimes", "codex-primary-runtime", "dependencies", "python", "python.exe");
  return [
    explicit,
    process.env.SLIDECLONE_PYTHON,
    process.env.PYTHON,
    bundled,
    "python"
  ].filter(Boolean).find((candidate) => !path.isAbsolute(candidate) || fs.existsSync(candidate)) || "python";
}

function shouldVectorizeStatusIcons(options = {}) {
  return options.vectorizeStatusIcons === true;
}

function isFlagEnabled(value) {
  return value === true || value === "true" || value === "1" || value === "yes";
}

function resolveSmartNativeRebuildOptions(args = {}) {
  const smartNativeLayers = isFlagEnabled(args["smart-native-layers"]);
  const componentStrategyIndex = resolveComponentStrategyIndex(args["component-strategy-report"]);
  const componentAssetIndex = resolveComponentAssetIndex(args["component-asset-manifest"]);
  return {
    preserveGraphics: smartNativeLayers || isFlagEnabled(args["preserve-graphics"]),
    vectorizeStatusIcons: isFlagEnabled(args["vectorize-status-icons"]),
    objectifyLayerText: isFlagEnabled(args["objectify-layer-text"]),
    objectifyStructuredVisualAtomText: smartNativeLayers || isFlagEnabled(args["objectify-structured-visual-atom-text"]),
    objectifyLayerContainers: smartNativeLayers || isFlagEnabled(args["objectify-layer-containers"]),
    objectifyLayerConnectors: smartNativeLayers || isFlagEnabled(args["objectify-layer-connectors"]),
    eraseObjectifiedLayerPrimitives: smartNativeLayers || isFlagEnabled(args["erase-objectified-layer-primitives"]),
    splitErasedResidualCrops: smartNativeLayers || isFlagEnabled(args["split-erased-residual-crops"]),
    objectifyTableGrid: smartNativeLayers || isFlagEnabled(args["objectify-table-grid"]),
    objectifyValueBanners: smartNativeLayers || isFlagEnabled(args["objectify-value-banners"]),
    objectifyToolGapPlatform: isFlagEnabled(args["objectify-tool-gap-platform"]),
    objectifyAssetHubInputIcons: smartNativeLayers || isFlagEnabled(args["objectify-asset-hub-input-icons"]),
    objectifySmartReviewSegmented: isFlagEnabled(args["objectify-smart-review-segmented"]),
    ...(isFlagEnabled(args["force-preserve-wms-route-graphic"])
      ? { forcePreserveWmsRouteGraphic: true }
      : {}),
    objectifyComponentGroupMatches: isFlagEnabled(args["objectify-component-group-matches"]),
    componentGroupMatchMinScore: Number(args["component-group-match-min-score"] || 58),
    replaceSafeComponentTemplateCrops: isFlagEnabled(args["replace-safe-component-template-crops"]),
    allowUnverifiedAppliedPluginPrototypeReplay: isFlagEnabled(args["allow-unverified-applied-plugin-prototype-replay"]),
    ...(isFlagEnabled(args["hybrid-component-template-residuals"])
      ? { hybridComponentTemplateResiduals: true }
      : {}),
    ...(isFlagEnabled(args["erase-specialized-hybrid-residual-text"])
      ? { eraseSpecializedHybridResidualText: true }
      : {}),
    ...(isFlagEnabled(args["allow-asset-os-demand-understanding-native-approximation"])
      ? { allowAssetOsDemandUnderstandingNativeApproximation: true }
      : {}),
    objectifyProductBrainVision: isFlagEnabled(args["objectify-product-brain-vision"]),
    sampleProductBrainVisionColors: isFlagEnabled(args["sample-product-brain-vision-colors"]),
    allowEntropyChallengeNativeApproximation: isFlagEnabled(args["allow-entropy-challenge-native-approximation"]),
    allowProductCollaborationChallengeNativeApproximation: isFlagEnabled(args["allow-product-collaboration-challenge-native-approximation"]),
    ...(componentStrategyIndex ? { componentStrategyIndex } : {}),
    ...(componentAssetIndex ? { componentAssetIndex } : {})
  };
}

function resolveComponentStrategyIndex(reportFile) {
  if (!reportFile || reportFile === true) return null;
  const resolved = path.resolve(String(reportFile));
  if (!fs.existsSync(resolved)) throw new Error(`component strategy report not found: ${resolved}`);
  return buildComponentStrategyIndex(readJson(resolved));
}

function resolveComponentAssetIndex(manifestFile) {
  if (!manifestFile || manifestFile === true) return null;
  const resolved = path.resolve(String(manifestFile));
  if (!fs.existsSync(resolved)) throw new Error(`component asset manifest not found: ${resolved}`);
  return buildComponentAssetIndex(readJson(resolved));
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help === true || args.h === true) {
    console.log(rebuildRealPptxNativeUsage());
    return;
  }
  const workRoot = path.resolve(args["work-root"] || "ppt文档/可编辑版本");
  const outRoot = path.resolve(args.out || "ppt文档/真可编辑版本");
  const only = args.only || null;
  ensureDir(outRoot);
  const rebuildOptions = resolveSmartNativeRebuildOptions(args);
  const finalPageCacheEnabled = !isFlagEnabled(args["no-final-page-cache"]);
  const finalPageCacheStats = { hits: 0, misses: 0, writes: 0 };
  if (finalPageCacheEnabled) {
    rebuildOptions.finalPageCacheDir = path.resolve(args["final-page-cache-dir"] || resolveDefaultFinalPageCacheDir());
    rebuildOptions.reuseFinalPageCache = String(args["reuse-final-page-cache"] ?? "true").toLowerCase() !== "false";
    rebuildOptions.pageCacheSalt = typeof args["page-cache-salt"] === "string" ? args["page-cache-salt"] : "";
    rebuildOptions.finalPageCacheStats = finalPageCacheStats;
  }
  const pptxBuildMode = resolvePptxBuildMode(args);
  // Keep source-authored native slides intact in mixed decks. The OpenXML
  // builder receives the source PPTX as its template, while raster-only pages
  // continue through the visual reconstruction path.
  rebuildOptions.preserveSourceNativeSlides = pptxBuildMode.engine === "openxml"
    && String(args["preserve-source-native-slides"] ?? "true").toLowerCase() !== "false";
  const powerPointOpenGate = shouldRunPowerPointOpenGate(args, pptxBuildMode);
  const progressReporter = createProgressReporter({
    enabled: String(args.progress ?? "true").toLowerCase() !== "false",
    context: { scope: "native-rebuild" }
  });
  const workDirs = listWorkDirs(workRoot, only);
  const deferredPptxJobs = [];
  const report = {
    provider: "rebuild-real-pptx-native",
    workRoot,
    outRoot,
    generatedAt: new Date().toISOString(),
    strategy: hybridRebuildStrategyProfile(rebuildOptions),
    pptxBuild: {
      engine: pptxBuildMode.engine,
      batch: pptxBuildMode.engine === "openxml",
      // This makes the delivery report auditable: every OpenXML batch deck is
      // normalized before delivery unless an explicit diagnostic override opts out.
      powerPointSafe: pptxBuildMode.engine === "openxml" ? pptxBuildMode.powerPointSafe : null
    },
    powerPointOpenGate: {
      enabled: powerPointOpenGate,
      status: powerPointOpenGate ? "pending" : "not-requested"
    },
    command: sanitizeCommandArgs(process.argv.slice(2)),
    finalPageCache: {
      enabled: finalPageCacheEnabled,
      reuse: rebuildOptions.reuseFinalPageCache === true,
      dir: rebuildOptions.finalPageCacheDir || null,
      stats: finalPageCacheStats
    },
    totals: { files: 0, pages: 0, images: 0, shapes: 0, textBoxes: 0, failed: 0 },
    results: []
  };
  progressReporter.emit({ phase: "run", status: "start", deckTotal: workDirs.length });
  for (let workIndex = 0; workIndex < workDirs.length; workIndex += 1) {
    const workDir = workDirs[workIndex];
    const baseName = path.basename(workDir, ".work");
    const deckProgress = progressReporter.child({
      deck: baseName,
      deckIndex: workIndex + 1,
      deckTotal: workDirs.length
    });
    const irFile = path.join(outRoot, `${baseName}.native.ir.json`);
    const outFile = path.join(outRoot, `${baseName}.native-editable.pptx`);
    try {
      const deckStartedAt = Date.now();
      const pageTimings = [];
      deckProgress.emit({ phase: "deck", status: "start" });
      const assetDir = path.join(outRoot, `${baseName}.assets`);
      const rebuiltDeck = rebuildDeckFromWorkDir(workDir, {
        ...rebuildOptions,
        assetDir,
        irDir: outRoot,
        deckName: baseName,
        pages: args.pages || args.page || args["only-pages"] || "",
        pageTimings,
        progressReporter: deckProgress
      });
      const deck = enrichReconstructionContracts(rebuiltDeck, { baseDir: outRoot });
      const irBuildMs = Date.now() - deckStartedAt;
      fs.writeFileSync(irFile, `${JSON.stringify(deck, null, 2)}\n`, "utf8");
      if (pptxBuildMode.engine === "openxml") {
        const sourceTemplate = path.join(workDir, "input", `${baseName}.pptx`);
        deferredPptxJobs.push({
          irFile,
          outFile,
          baseName,
          // Reuse the source deck's Office-authored package skeleton so the
          // output keeps compatible masters, layouts, and presentation props.
          templatePptx: fs.existsSync(sourceTemplate) ? sourceTemplate : ""
        });
      } else {
        buildPptx(irFile, outFile, { python: args.python });
      }
      const result = {
        inputWorkDir: workDir,
        outputPptx: outFile,
        outputIr: irFile,
        pages: deck.pages.length,
        images: deck.pages.reduce((sum, page) => sum + (page.images || []).length, 0),
        shapes: deck.pages.reduce((sum, page) => sum + (page.shapes || []).length, 0),
        textBoxes: deck.pages.reduce((sum, page) => sum + (page.textBoxes || []).length, 0),
        composition: summarizeDeckComposition(deck),
        timings: { irBuildMs, pageTimings },
        status: pptxBuildMode.engine === "openxml" ? "ir-built" : "converted"
      };
      report.results.push(result);
      report.totals.files += 1;
      report.totals.pages += result.pages;
      report.totals.images += result.images;
      report.totals.shapes += result.shapes;
      report.totals.textBoxes += result.textBoxes;
      deckProgress.emit({
        phase: "deck",
        status: pptxBuildMode.engine === "openxml" ? "ir-done" : "done",
        elapsedMs: Date.now() - deckStartedAt,
        images: result.images,
        shapes: result.shapes,
        textBoxes: result.textBoxes
      });
    } catch (error) {
      report.totals.failed += 1;
      report.results.push({
        inputWorkDir: workDir,
        status: "failed",
        error: error.message
      });
      deckProgress.emit({ phase: "deck", status: "failed" });
    }
  }
  if (deferredPptxJobs.length > 0) {
    try {
      const pptxStartedAt = Date.now();
      progressReporter.emit({ phase: "pptx-build", status: "start", jobs: deferredPptxJobs.length });
      buildPptxBatch(deferredPptxJobs, args);
      for (const result of report.results) {
        if (result.status === "ir-built") result.status = "converted";
      }
      progressReporter.emit({
        phase: "pptx-build",
        status: "done",
        jobs: deferredPptxJobs.length,
        elapsedMs: Date.now() - pptxStartedAt
      });
      report.pptxBuild.elapsedMs = Date.now() - pptxStartedAt;
    } catch (error) {
      for (const job of deferredPptxJobs) {
        const result = report.results.find((item) => item.outputIr === job.irFile);
        if (result && result.status === "ir-built") {
          result.status = "failed";
          result.error = error.message;
          report.totals.failed += 1;
          report.totals.files = Math.max(0, report.totals.files - 1);
          report.totals.pages = Math.max(0, report.totals.pages - Number(result.pages || 0));
          report.totals.images = Math.max(0, report.totals.images - Number(result.images || 0));
          report.totals.shapes = Math.max(0, report.totals.shapes - Number(result.shapes || 0));
          report.totals.textBoxes = Math.max(0, report.totals.textBoxes - Number(result.textBoxes || 0));
        }
      }
      progressReporter.emit({ phase: "pptx-build", status: "failed", jobs: deferredPptxJobs.length });
    }
  }
  if (powerPointOpenGate && report.totals.failed === 0) {
    try {
      const { validatePowerPointOpen } = require("./adapters/validate-powerpoint-com");
      const files = report.results.filter((result) => result.status === "converted").map((result) => result.outputPptx);
      progressReporter.emit({ phase: "powerpoint-open-gate", status: "start", jobs: files.length });
      const gateReport = await validatePowerPointOpen(files, {
        outputDir: path.join(outRoot, "powerpoint-open-gate"),
        timeoutMs: Number(args["powerpoint-open-timeout-ms"] || 170000),
        // PowerPoint is the final compatibility authority. If it silently
        // rewrites a generated package, finalize that generated copy once and
        // require a second clean open before delivery.
        repairInPlace: !isFlagDisabled(args["powerpoint-repair-in-place"] ?? args.powerPointRepairInPlace)
      });
      report.powerPointOpenGate = { enabled: true, status: "passed", ...gateReport };
      progressReporter.emit({ phase: "powerpoint-open-gate", status: "done", jobs: files.length });
    } catch (error) {
      report.powerPointOpenGate = { enabled: true, status: "failed", error: error.message };
      for (const result of report.results) {
        if (result.status !== "converted") continue;
        result.status = "failed";
        result.error = `PowerPoint open gate failed: ${error.message}`;
        report.totals.failed += 1;
      }
      progressReporter.emit({ phase: "powerpoint-open-gate", status: "failed" });
    }
  }
  const reportFile = path.resolve(args["report-file"] || path.join(outRoot, "native-rebuild-report.json"));
  ensureDir(path.dirname(reportFile));
  fs.writeFileSync(reportFile, `${JSON.stringify(report, null, 2)}\n`, "utf8");
  progressReporter.emit({ phase: "run", status: report.totals.failed > 0 ? "failed" : "done", deckTotal: workDirs.length });
  console.log(JSON.stringify(report, null, 2));
  if (report.totals.failed > 0) process.exitCode = 1;
}

function rebuildRealPptxNativeUsage() {
  return [
    "Usage: node rebuild-real-pptx-native.js [options]",
    "  --work-root <dir>       Source .work directories (default: ppt文档/可编辑版本)",
    "  --only <deck>           Rebuild one deck only",
    "  --pages <selection>     Rebuild selected 1-based pages, for example: 4,8,13",
    "  --out <dir>             Output directory (default: ppt文档/真可编辑版本)",
    "  --smart-native-layers true",
    "  --force-preserve-wms-route-graphic true  Preserve matching WMS pictorial routes as protected local crops",
    "  --pptx-engine openxml",
    "  --powerpoint-open-gate true  Open every generated PPTX in PowerPoint before delivery",
    "  --final-page-cache-dir <dir>  Override the shared safe page-cache directory",
    "  --reuse-final-page-cache [true|false]  Reuse unchanged cached pages (default: true)",
    "  --no-final-page-cache         Disable writing and reading page cache",
    "  --page-cache-salt <value>      Explicitly invalidate otherwise matching cache entries",
    "  --progress false         Disable safe per-page progress events on stderr",
    "  --help, -h              Print this help without creating output"
  ].join("\n");
}

function summarizeDeckComposition(deck) {
  return summarizeDeckCompositionCore(deck, {
    classifyEditableExpressionForm,
    classifyImageExpressionForm,
    classifyImageExpressionSubtype,
    recommendExpressionHandling
  });
}

function addCount(target, key) {
  const safeKey = String(key || "unknown");
  target[safeKey] = (target[safeKey] || 0) + 1;
}

function sanitizeCommandArgs(argv = []) {
  const secretPattern = /(?:token|key|secret|password|license|bearer|cookie)/i;
  const result = [];
  for (let index = 0; index < argv.length; index += 1) {
    const item = String(argv[index] || "");
    result.push(item);
    if (item.startsWith("--") && secretPattern.test(item)) {
      if (argv[index + 1] && !String(argv[index + 1]).startsWith("--")) {
        result.push("[redacted]");
        index += 1;
      }
    }
  }
  return result;
}

if (require.main === module) {
  main().catch((error) => {
    console.error(error.stack || error.message || String(error));
    process.exitCode = 1;
  });
}

